pub(crate) fn cmd_author_work_packages(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    let game_root = author_work_packages_game_root(&map)?;
    let blueprint_path = large_mod_blueprint_path_from_args(&map, Some(&mod_root))?;
    let blueprint = read_large_mod_blueprint(&blueprint_path)?;
    let packages = split_large_mod_work_packages(&blueprint);
    let (request_path, request_source, generated_request_file, auto_dispatched) =
        author_work_packages_request_path_from_args(&map, &mod_root, &packages)?;
    let requests = parse_author_work_packages_requests(&read_utf8_lossy(&request_path)?)?;
    if requests.is_empty() {
        return Err(
            "no filled package requests found; provide --text <request> or keep `## package_id` sections and replace TODO lines with user content"
                .to_string(),
        );
    }
    let valid_packages = packages
        .iter()
        .map(|package| package.id.clone())
        .collect::<BTreeSet<_>>();
    let author_dir = mod_root.join(".hoi4skill").join("author_queue");
    fs::create_dir_all(&author_dir).map_err(|e| format!("create {}: {e}", author_dir.display()))?;
    let mut entries = Vec::new();
    let mut ok_count = 0usize;
    let mut planned_count = 0usize;
    let mut failed_count = 0usize;
    let mut blocked_count = 0usize;
    let dispatch_lane_matrix =
        author_work_packages_dispatch_lane_matrix_json(&requests, &valid_packages);
    let six_lane_dispatch_ready =
        author_work_packages_six_lane_dispatch_ready(&requests, &valid_packages);
    for request in requests {
        let output = author_dir.join(format!("{}.json", request.package));
        if !valid_packages.contains(&request.package) {
            blocked_count += 1;
            entries.push(author_work_packages_entry_json(
                &request.package,
                "unknown_package",
                &output,
                None,
                Some("package is not present in the large-mod blueprint"),
            ));
            if map.flags.contains("stop-on-failure") {
                break;
            }
            continue;
        }
        let mut author_args = vec![
            "--mod-root".to_string(),
            mod_root.display().to_string(),
            "--package".to_string(),
            request.package.clone(),
            "--text".to_string(),
            request.text.clone(),
            "--output".to_string(),
            output.display().to_string(),
            "--allow-failure".to_string(),
        ];
        if map.flags.contains("execute") {
            author_args.push("--execute".to_string());
        }
        if map.flags.contains("plan-only") {
            author_args.push("--plan-only".to_string());
        }
        if map.flags.contains("append") {
            author_args.push("--append".to_string());
        }
        if map.flags.contains("allow-blocked") {
            author_args.push("--allow-blocked".to_string());
        }
        if map.flags.contains("apply-localisation") {
            author_args.push("--apply-localisation".to_string());
        }
        if let Some(game_root) = game_root.as_ref() {
            author_args.push("--game-root".to_string());
            author_args.push(game_root.display().to_string());
        }
        for mod_path in repeated_values(&map, "mod-path") {
            author_args.push("--mod-path".to_string());
            author_args.push(mod_path.to_string());
        }
        let result = cmd_author_work_package(&author_args);
        let (status, repair_bundle, error) = match result {
            Ok(()) => {
                let text = read_utf8_lossy(&output).unwrap_or_default();
                let status =
                    json_string_field(&text, "status").unwrap_or_else(|| "unknown".to_string());
                let repair_bundle = json_string_field(&text, "repair_bundle");
                (status, repair_bundle, None::<String>)
            }
            Err(err) => {
                failed_count += 1;
                entries.push(author_work_packages_entry_json(
                    &request.package,
                    "command_failed",
                    &output,
                    None,
                    Some(&err),
                ));
                if map.flags.contains("stop-on-failure") {
                    break;
                }
                continue;
            }
        };
        match status.as_str() {
            "ok" => ok_count += 1,
            "planned" => planned_count += 1,
            "failed_repair_ready" => failed_count += 1,
            _ => blocked_count += 1,
        }
        entries.push(author_work_packages_entry_json(
            &request.package,
            &status,
            &output,
            repair_bundle.as_deref(),
            error.as_deref(),
        ));
        if status == "failed_repair_ready" && map.flags.contains("stop-on-failure") {
            break;
        }
    }
    let status = if failed_count > 0 {
        "needs_repair"
    } else if blocked_count > 0 {
        "needs_review"
    } else if planned_count > 0 {
        "planned"
    } else {
        "ok"
    };
    let refreshed_artifacts = large_mod_author_work_package_artifact_paths(&mod_root);
    let project_author_queue = refreshed_artifacts[0].clone();
    let refreshed_artifact_paths = refreshed_artifacts
        .iter()
        .map(|path| path.display().to_string())
        .collect::<Vec<_>>();
    let request_sources_report = if request_source == "input_sources" {
        let path = if let Some(output) = value(&map, "request-sources-output") {
            Some(normalize_path(output)?)
        } else {
            Some(
                mod_root
                    .join(".hoi4skill")
                    .join("package_request_sources.json"),
            )
        };
        path.map(|path| path.display().to_string())
    } else {
        None
    };
    let next_commands = vec![
        format!(
            "inspect {}",
            mod_root
                .join(".hoi4skill")
                .join("authoring_gate.json")
                .display()
        ),
        format!(
            "inspect {}",
            mod_root
                .join(".hoi4skill")
                .join("input_repair_queue.json")
                .display()
        ),
        format!(
            "hoi4skill large-mod-repair-cycle --mod-root {} --output .hoi4skill/repair_cycle.json",
            mod_root.display()
        ),
    ];
    let manifest = format!(
        "{{\n  \"schema\": \"hoi4skill.author_work_packages.v1\",\n  \"status\": {},\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"blueprint\": {},\n  \"request_source\": {},\n  \"auto_dispatched\": {},\n  \"request_file\": {},\n  \"generated_request_file\": {},\n  \"request_sources_report\": {},\n  \"request_count\": {},\n  \"required_content_lanes\": {},\n  \"six_lane_dispatch_ready\": {},\n  \"dispatch_lane_matrix\": [\n{}\n  ],\n  \"ok_count\": {},\n  \"planned_count\": {},\n  \"failed_repair_ready_count\": {},\n  \"blocked_count\": {},\n  \"project_author_queue\": {},\n  \"refreshed_artifacts\": {},\n  \"entries\": [\n{}\n  ],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&mod_root.display().to_string()),
        json_str(&blueprint_path.display().to_string()),
        json_str(request_source),
        json_bool(auto_dispatched),
        json_str(&request_path.display().to_string()),
        json_optional_str(generated_request_file.as_deref()),
        json_optional_str(request_sources_report.as_deref()),
        entries.len(),
        json_array(&large_mod_content_family_ids()),
        json_bool(six_lane_dispatch_ready),
        dispatch_lane_matrix,
        ok_count,
        planned_count,
        failed_count,
        blocked_count,
        json_str(&project_author_queue.display().to_string()),
        json_array(&refreshed_artifact_paths),
        entries.join(",\n"),
        json_array(&next_commands),
        json_array(&author_work_packages_stop_conditions()),
    );
    refresh_large_mod_author_work_package_artifacts(
        &blueprint,
        &packages,
        &blueprint_path,
        &mod_root,
        &manifest,
    )?;
    let output = value(&map, "output")
        .map(str::to_string)
        .unwrap_or_else(|| project_author_queue.display().to_string());
    write_or_print(&manifest, Some(&output))?;
    if failed_count > 0 && !map.flags.contains("allow-failure") {
        return Err(format!(
            "author-work-packages finished with {failed_count} package(s) needing repair"
        ));
    }
    Ok(())
}

fn author_work_packages_game_root(map: &ArgMap) -> Result<Option<PathBuf>, String> {
    if let Some(path) = value(map, "game-root").or_else(|| value(map, "hoi4-path")) {
        return normalize_path(path).map(Some);
    }
    if map.flags.contains("execute") || map.flags.contains("auto-game-root") {
        return detect_selected_hoi4_path(&[]).map(Some).ok_or_else(|| {
            "author-work-packages execution requires --game-root <Hearts of Iron IV>; detect-hoi4-path found no valid selected path".to_string()
        });
    }
    Ok(None)
}

fn large_mod_author_work_package_artifact_paths(mod_root: &Path) -> Vec<PathBuf> {
    let hoi4skill_dir = mod_root.join(".hoi4skill");
    vec![
        hoi4skill_dir.join("author_queue.json"),
        hoi4skill_dir.join("run_summary.json"),
        hoi4skill_dir.join("input_repair_queue.json"),
        hoi4skill_dir.join("authoring_gate.json"),
        hoi4skill_dir.join("execution_queue.json"),
    ]
}

fn refresh_large_mod_author_work_package_artifacts(
    blueprint: &LargeModBlueprint,
    packages: &[WorkPackage],
    blueprint_path: &Path,
    mod_root: &Path,
    author_queue_manifest: &str,
) -> Result<(), String> {
    let hoi4skill_dir = mod_root.join(".hoi4skill");
    fs::create_dir_all(&hoi4skill_dir)
        .map_err(|e| format!("create {}: {e}", hoi4skill_dir.display()))?;
    let artifacts = large_mod_author_work_package_artifact_paths(mod_root);
    let author_queue = &artifacts[0];
    fs::write(&author_queue, author_queue_manifest)
        .map_err(|e| format!("write {}: {e}", author_queue.display()))?;

    let run_summary = &artifacts[1];
    let run_summary_json =
        large_mod_run_summary_json(blueprint, packages, blueprint_path, mod_root)?;
    fs::write(&run_summary, run_summary_json)
        .map_err(|e| format!("write {}: {e}", run_summary.display()))?;

    let input_repair_queue = &artifacts[2];
    let repair_queue_json =
        large_mod_input_repair_queue_json(blueprint, packages, blueprint_path, mod_root)?;
    fs::write(&input_repair_queue, repair_queue_json)
        .map_err(|e| format!("write {}: {e}", input_repair_queue.display()))?;

    let authoring_gate = &artifacts[3];
    let gate_json = large_mod_authoring_gate_json(blueprint, packages, blueprint_path, mod_root)?;
    fs::write(&authoring_gate, gate_json)
        .map_err(|e| format!("write {}: {e}", authoring_gate.display()))?;

    let execution_queue = &artifacts[4];
    let execution_queue_json =
        large_mod_execution_queue_json(blueprint, packages, blueprint_path, Some(mod_root));
    fs::write(&execution_queue, execution_queue_json)
        .map_err(|e| format!("write {}: {e}", execution_queue.display()))?;

    Ok(())
}

fn author_work_packages_request_path_from_args(
    map: &ArgMap,
    mod_root: &Path,
    packages: &[WorkPackage],
) -> Result<(PathBuf, &'static str, Option<String>, bool), String> {
    if value(map, "input-dir").is_some()
        || repeated_values(map, "input").len() > 1
        || repeated_values(map, "request-file").len() > 1
    {
        let (sources, ignored_sources) = author_work_packages_collect_source_inputs(map)?;
        if sources.is_empty() {
            return Err("author-work-packages found no supported files in --input-dir".to_string());
        }
        if map.flags.contains("strict-input-sources") && !ignored_sources.is_empty() {
            return Err(format!(
                "author-work-packages --strict-input-sources found unsupported files: {}",
                ignored_sources
                    .iter()
                    .map(|path| path.display().to_string())
                    .collect::<Vec<_>>()
                    .join(", ")
            ));
        }
        let package_override = value(map, "package");
        let mut source_entries = Vec::new();
        let mut merged = BTreeMap::<String, Vec<String>>::new();
        for source in &sources {
            let text = read_text_document(source)?;
            if text.trim().is_empty() {
                continue;
            }
            let source_markdown = author_work_packages_source_request_markdown(
                packages,
                source,
                &text,
                package_override,
            )?;
            let requests = parse_author_work_packages_requests(&source_markdown)?;
            let source_packages = requests
                .iter()
                .map(|request| request.package.clone())
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let source_lanes = requests
                .iter()
                .flat_map(|request| author_work_package_lanes_in_text(&request.text))
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            for request in requests {
                merged.entry(request.package).or_default().push(format!(
                    "# source: {}\n{}",
                    source.display(),
                    request.text.trim()
                ));
            }
            source_entries.push(author_work_packages_source_entry_json(
                source,
                &text,
                author_work_packages_source_kind(source),
                &source_packages,
                &source_lanes,
            ));
        }
        if merged.is_empty() {
            return Err("author-work-packages input sources contain no readable text".to_string());
        }
        let markdown = author_work_packages_requests_markdown(
            merged
                .into_iter()
                .map(|(package, chunks)| (package, chunks.join("\n")))
                .collect(),
        );
        let request_path = if let Some(output) = value(map, "request-output") {
            normalize_path(output)?
        } else {
            mod_root
                .join(".hoi4skill")
                .join("package_requests_from_sources.md")
        };
        write_author_work_packages_request_file(&request_path, &markdown)?;
        let source_manifest = if let Some(output) = value(map, "request-sources-output") {
            normalize_path(output)?
        } else {
            mod_root
                .join(".hoi4skill")
                .join("package_request_sources.json")
        };
        let manifest = author_work_packages_sources_manifest_json(
            mod_root,
            &request_path,
            package_override,
            &source_entries,
            &ignored_sources,
        );
        write_author_work_packages_request_file(&source_manifest, &manifest)?;
        return Ok((
            request_path.clone(),
            "input_sources",
            Some(request_path.display().to_string()),
            true,
        ));
    }
    if let Some(input) = value(map, "input").or_else(|| value(map, "request-file")) {
        let input_path = normalize_path(input)?;
        let extension = input_path
            .extension()
            .and_then(OsStr::to_str)
            .unwrap_or("")
            .to_ascii_lowercase();
        if author_work_packages_text_input_extension(&extension) {
            let text = read_text_document(&input_path)?;
            if author_work_package_text_has_explicit_package_sections(&text)
                && value(map, "package").is_none()
            {
                return Ok((input_path, "input_file", None, false));
            }
            let package_override = value(map, "package");
            let markdown = author_work_packages_requests_markdown_from_text(
                packages,
                &text,
                package_override,
            )?;
            let request_path = if let Some(output) = value(map, "request-output") {
                normalize_path(output)?
            } else {
                mod_root
                    .join(".hoi4skill")
                    .join("package_requests_from_input.md")
            };
            write_author_work_packages_request_file(&request_path, &markdown)?;
            return Ok((
                request_path.clone(),
                "input_document",
                Some(request_path.display().to_string()),
                true,
            ));
        }
        if matches!(
            extension.as_str(),
            "docx" | "xlsx" | "xls" | "xlsm" | "xlsb" | "ods"
        ) {
            let text = read_text_document(&input_path)?;
            let package_override = value(map, "package");
            let markdown = author_work_packages_requests_markdown_from_text(
                packages,
                &text,
                package_override,
            )?;
            let request_path = if let Some(output) = value(map, "request-output") {
                normalize_path(output)?
            } else {
                mod_root
                    .join(".hoi4skill")
                    .join("package_requests_from_input.md")
            };
            write_author_work_packages_request_file(&request_path, &markdown)?;
            return Ok((
                request_path.clone(),
                "input_document",
                Some(request_path.display().to_string()),
                true,
            ));
        }
        return Ok((input_path, "input_file", None, false));
    }
    let Some(text) = value(map, "text").or_else(|| value(map, "request")) else {
        return Err(
            "author-work-packages requires --input <package_requests.md> or --text <user request>"
                .to_string(),
        );
    };
    let package_override = value(map, "package");
    let markdown =
        author_work_packages_requests_markdown_from_text(packages, text, package_override)?;
    let request_path = if let Some(output) = value(map, "request-output") {
        normalize_path(output)?
    } else {
        mod_root
            .join(".hoi4skill")
            .join("package_requests_from_text.md")
    };
    write_author_work_packages_request_file(&request_path, &markdown)?;
    Ok((
        request_path.clone(),
        "text",
        Some(request_path.display().to_string()),
        true,
    ))
}

fn write_author_work_packages_request_file(path: &Path, text: &str) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
    }
    fs::write(path, text).map_err(|e| format!("write {}: {e}", path.display()))
}

fn author_work_packages_text_input_extension(extension: &str) -> bool {
    matches!(extension, "md" | "markdown" | "txt" | "csv" | "tsv")
}

fn author_work_packages_supported_source_extension(extension: &str) -> bool {
    author_work_packages_text_input_extension(extension)
        || matches!(extension, "docx" | "xlsx" | "xls" | "xlsm" | "xlsb" | "ods")
}

fn author_work_packages_collect_source_inputs(
    map: &ArgMap,
) -> Result<(Vec<PathBuf>, Vec<PathBuf>), String> {
    let mut sources = BTreeSet::new();
    let mut ignored = BTreeSet::new();
    for input in repeated_values(map, "input")
        .into_iter()
        .chain(repeated_values(map, "request-file"))
    {
        let path = normalize_path(input)?;
        let extension = path
            .extension()
            .and_then(OsStr::to_str)
            .unwrap_or("")
            .to_ascii_lowercase();
        if author_work_packages_supported_source_extension(&extension) {
            sources.insert(path);
        } else {
            ignored.insert(path);
        }
    }
    for input_dir in repeated_values(map, "input-dir") {
        let dir = normalize_path(input_dir)?;
        author_work_packages_collect_source_dir(&dir, &mut sources, &mut ignored)?;
    }
    Ok((sources.into_iter().collect(), ignored.into_iter().collect()))
}

fn author_work_packages_collect_source_dir(
    dir: &Path,
    sources: &mut BTreeSet<PathBuf>,
    ignored: &mut BTreeSet<PathBuf>,
) -> Result<(), String> {
    if !dir.is_dir() {
        return Err(format!("--input-dir is not a directory: {}", dir.display()));
    }
    let mut entries = fs::read_dir(dir)
        .map_err(|e| format!("read {}: {e}", dir.display()))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|e| format!("read {} entry: {e}", dir.display()))?;
    entries.sort_by_key(|entry| entry.path());
    for entry in entries {
        let path = entry.path();
        let name = path.file_name().and_then(OsStr::to_str).unwrap_or("");
        if name.starts_with('.') || name.starts_with('~') {
            continue;
        }
        if path.is_dir() {
            author_work_packages_collect_source_dir(&path, sources, ignored)?;
            continue;
        }
        let extension = path
            .extension()
            .and_then(OsStr::to_str)
            .unwrap_or("")
            .to_ascii_lowercase();
        if author_work_packages_supported_source_extension(&extension) {
            sources.insert(path);
        } else {
            ignored.insert(path);
        }
    }
    Ok(())
}

fn author_work_packages_source_request_markdown(
    packages: &[WorkPackage],
    source: &Path,
    text: &str,
    package_override: Option<&str>,
) -> Result<String, String> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return Ok(String::new());
    }
    if package_override.is_none() && author_work_package_text_has_explicit_package_sections(trimmed)
    {
        let requests = parse_author_work_packages_requests(trimmed)?;
        if !requests.is_empty() {
            for request in &requests {
                if !packages.iter().any(|package| package.id == request.package) {
                    return Err(format!(
                        "package `{}` from {} is not present in the large-mod blueprint",
                        request.package,
                        source.display()
                    ));
                }
            }
            return Ok(author_work_packages_requests_markdown(
                requests
                    .into_iter()
                    .map(|request| (request.package, request.text))
                    .collect(),
            ));
        }
    }
    author_work_packages_requests_markdown_from_text(packages, trimmed, package_override)
}

fn author_work_packages_source_kind(path: &Path) -> &'static str {
    match path
        .extension()
        .and_then(OsStr::to_str)
        .unwrap_or("")
        .to_ascii_lowercase()
        .as_str()
    {
        "docx" => "docx_word",
        "xlsx" | "xls" | "xlsm" | "xlsb" | "ods" => "xlsx_excel",
        "csv" | "tsv" => "table_text",
        "md" | "markdown" => "markdown",
        "txt" => "plain_text",
        _ => "unknown",
    }
}

fn author_work_packages_source_entry_json(
    path: &Path,
    text: &str,
    kind: &str,
    packages: &[String],
    lanes: &[String],
) -> String {
    format!(
        "    {{\"path\": {}, \"kind\": {}, \"char_count\": {}, \"line_count\": {}, \"packages\": {}, \"lanes\": {}}}",
        json_str(&path.display().to_string()),
        json_str(kind),
        text.chars().count(),
        text.lines().count(),
        json_array(&packages.to_vec()),
        json_array(&lanes.to_vec())
    )
}

fn author_work_package_lanes_in_text(text: &str) -> Vec<String> {
    let mut lanes = BTreeSet::new();
    for line in normalise_work_package_request_lane_lines(text).lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let lower = trimmed.to_ascii_lowercase();
        if request_line_is_focus_text(trimmed, &lower) {
            lanes.insert("focus".to_string());
        }
        if request_line_is_event_text(trimmed, &lower) {
            lanes.insert("event".to_string());
        }
        if request_mentions_decision(trimmed, &lower) {
            lanes.insert("decision".to_string());
        }
        if request_mentions_national_spirit(trimmed, &lower) {
            lanes.insert("national_spirit".to_string());
        }
        if request_line_is_dynamic_modifier_start(trimmed, &lower) {
            lanes.insert("dynamic_modifier".to_string());
        }
        if request_line_is_localisation_text(trimmed, &lower) || trimmed.contains('【') {
            lanes.insert("localisation".to_string());
        }
        if request_line_is_intent_effect_text(trimmed, &lower) {
            lanes.insert("intent".to_string());
        }
    }
    lanes.into_iter().collect()
}

fn author_work_packages_sources_manifest_json(
    mod_root: &Path,
    request_path: &Path,
    package_override: Option<&str>,
    source_entries: &[String],
    ignored_sources: &[PathBuf],
) -> String {
    let ignored = ignored_sources
        .iter()
        .map(|path| path.display().to_string())
        .collect::<Vec<_>>();
    let source_kinds = source_entries
        .iter()
        .flat_map(|entry| status_json_string_field_values(entry, "kind"))
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let source_lanes = source_entries
        .iter()
        .flat_map(|entry| status_json_string_array_values(entry, "lanes"))
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let required_lanes = large_mod_required_semiauto_lanes();
    let missing_lanes = required_lanes
        .iter()
        .filter(|lane| !source_lanes.contains(lane))
        .cloned()
        .collect::<Vec<_>>();
    let source_lane_coverage_percent = percentage(
        required_lanes.len().saturating_sub(missing_lanes.len()),
        required_lanes.len(),
    );
    format!(
        "{{\n  \"schema\": \"hoi4skill.author_work_package_sources.v1\",\n  \"status\": \"ok\",\n  \"mod_root\": {},\n  \"request_file\": {},\n  \"package_override\": {},\n  \"source_count\": {},\n  \"ignored_source_count\": {},\n  \"source_kinds\": {},\n  \"has_word_input\": {},\n  \"has_excel_input\": {},\n  \"has_plain_text_input\": {},\n  \"has_table_text_input\": {},\n  \"source_lanes\": {},\n  \"required_content_lanes\": {},\n  \"missing_source_lanes\": {},\n  \"source_lane_coverage_percent\": {},\n  \"six_lane_source_coverage\": {},\n  \"ignored_sources\": {},\n  \"sources\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_str(&mod_root.display().to_string()),
        json_str(&request_path.display().to_string()),
        json_optional_str(package_override),
        source_entries.len(),
        ignored.len(),
        json_array(&source_kinds),
        json_bool(source_kinds.iter().any(|kind| kind == "docx_word")),
        json_bool(source_kinds.iter().any(|kind| kind == "xlsx_excel")),
        json_bool(source_kinds.iter().any(|kind| kind == "plain_text")),
        json_bool(source_kinds.iter().any(|kind| kind == "table_text")),
        json_array(&source_lanes),
        json_array(&required_lanes),
        json_array(&missing_lanes),
        source_lane_coverage_percent,
        json_bool(missing_lanes.is_empty()),
        json_array(&ignored),
        source_entries.join(",\n"),
        json_array(&[
            "Do not delete or reorder source files when debugging user-visible text alignment.".to_string(),
            "Use --strict-input-sources when unsupported files in an input directory must block generation instead of being ignored.".to_string(),
            "If a generated request is wrong, inspect this manifest before asking the AI to repair content.".to_string(),
        ])
    )
}

fn large_mod_required_semiauto_lanes() -> Vec<String> {
    vec![
        "focus".to_string(),
        "event".to_string(),
        "decision".to_string(),
        "national_spirit".to_string(),
        "dynamic_modifier".to_string(),
        "localisation".to_string(),
    ]
}

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
enum AuthorWorkPackageLane {
    Focus,
    Event,
    Decision,
    NationalSpirit,
    DynamicModifier,
    Localisation,
    Intent,
}

impl AuthorWorkPackageLane {
    fn heading(self) -> &'static str {
        match self {
            AuthorWorkPackageLane::Focus => "国策",
            AuthorWorkPackageLane::Event => "事件",
            AuthorWorkPackageLane::Decision => "决议",
            AuthorWorkPackageLane::NationalSpirit => "民族精神",
            AuthorWorkPackageLane::DynamicModifier => "动态修正",
            AuthorWorkPackageLane::Localisation => "本地化",
            AuthorWorkPackageLane::Intent => "效果",
        }
    }

    fn audit_key(self) -> &'static str {
        match self {
            AuthorWorkPackageLane::Focus => "focus",
            AuthorWorkPackageLane::Event => "event_chain",
            AuthorWorkPackageLane::Decision | AuthorWorkPackageLane::NationalSpirit => {
                "decisions_or_national_spirits"
            }
            AuthorWorkPackageLane::DynamicModifier => "dynamic_modifiers",
            AuthorWorkPackageLane::Localisation => "localisation",
            AuthorWorkPackageLane::Intent => "intent",
        }
    }

    fn keywords(self) -> &'static [&'static str] {
        match self {
            AuthorWorkPackageLane::Focus => &[
                "focus",
                "national_focus",
                "national focus",
                "political_paths",
                "political paths",
                "国策",
            ],
            AuthorWorkPackageLane::Event => &[
                "event",
                "events",
                "event_chain",
                "event chain",
                "event text",
                "事件",
                "事件链",
                "事件文案",
            ],
            AuthorWorkPackageLane::Decision => &["decision", "decisions", "决议"],
            AuthorWorkPackageLane::NationalSpirit => &[
                "national_spirit",
                "national spirit",
                "national_idea",
                "national idea",
                "idea",
                "ideas",
                "民族精神",
            ],
            AuthorWorkPackageLane::DynamicModifier => &[
                "dynamic_modifier",
                "dynamic modifiers",
                "dynamic modifier",
                "dynamic_modifiers",
                "scripted_effect",
                "scripted effects",
                "动态修正",
                "动态修饰",
            ],
            AuthorWorkPackageLane::Localisation => &[
                "localisation",
                "localization",
                "localisation_assets",
                "localisation content",
                "localization content",
                "loc",
                "本地化",
            ],
            AuthorWorkPackageLane::Intent => &["intent", "effect", "effects", "效果"],
        }
    }
}

fn author_work_packages_requests_markdown_from_text(
    packages: &[WorkPackage],
    text: &str,
    package_override: Option<&str>,
) -> Result<String, String> {
    if packages.is_empty() {
        return Err("large-mod blueprint has no work packages to receive --text".to_string());
    }
    if let Some(package) = package_override {
        if !packages.iter().any(|candidate| candidate.id == package) {
            return Err(format!(
                "--package {package} is not present in the large-mod blueprint"
            ));
        }
        let text = single_work_package_tabular_text(text, Some(package))
            .unwrap_or_else(|| normalise_work_package_request_lane_lines(text));
        return Ok(author_work_packages_requests_markdown(vec![(
            package.to_string(),
            text,
        )]));
    }

    if let Some(sections) = author_work_package_tabular_sections(packages, text)? {
        return Ok(author_work_packages_requests_markdown(sections));
    }
    if author_work_package_text_has_explicit_package_sections(text) {
        let requests = parse_author_work_packages_requests(text)?;
        if !requests.is_empty() {
            for request in &requests {
                if !packages.iter().any(|package| package.id == request.package) {
                    return Err(format!(
                        "package `{}` from request document is not present in the large-mod blueprint",
                        request.package
                    ));
                }
            }
            return Ok(author_work_packages_requests_markdown(
                requests
                    .into_iter()
                    .map(|request| (request.package, request.text))
                    .collect(),
            ));
        }
    }

    let mut grouped = BTreeMap::<String, Vec<String>>::new();
    for (lane, lane_text) in author_work_package_lane_sections(text) {
        let package = author_work_package_route_package(packages, lane)
            .ok_or_else(|| format!("no package can receive {} request text", lane.heading()))?;
        grouped.entry(package).or_default().push(lane_text);
    }
    if grouped.is_empty() {
        let fallback = packages
            .iter()
            .find(|package| package.kind == "country")
            .or_else(|| packages.first())
            .expect("packages is not empty");
        grouped
            .entry(fallback.id.clone())
            .or_default()
            .push(text.trim().to_string());
    }

    let sections = grouped
        .into_iter()
        .map(|(package, chunks)| {
            (
                package,
                chunks
                    .into_iter()
                    .map(|chunk| chunk.trim().to_string())
                    .filter(|chunk| !chunk.is_empty())
                    .collect::<Vec<_>>()
                    .join("\n"),
            )
        })
        .filter(|(_, body)| !body.trim().is_empty())
        .collect::<Vec<_>>();
    Ok(author_work_packages_requests_markdown(sections))
}

fn author_work_package_text_has_explicit_package_sections(text: &str) -> bool {
    text.lines().any(|line| {
        parse_author_work_packages_heading(line)
            .or_else(|| parse_author_work_packages_package_line(line))
            .is_some()
    })
}

fn author_work_package_tabular_sections(
    packages: &[WorkPackage],
    text: &str,
) -> Result<Option<Vec<(String, String)>>, String> {
    let mut header: Option<Vec<String>> = None;
    let mut grouped = BTreeMap::<String, Vec<String>>::new();
    let mut current_package: Option<String> = None;
    let mut current_lane: Option<AuthorWorkPackageLane> = None;
    for line in author_work_package_table_records(text) {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        if line.starts_with("# sheet:") {
            continue;
        }
        let mut cells = split_author_work_package_table_row(line);
        if cells.len() < 2 {
            continue;
        }
        if author_work_package_table_separator_row(&cells) {
            continue;
        }
        if header.is_none() && author_work_package_table_header_score(&cells) >= 2 {
            header = Some(cells);
            continue;
        }
        let Some(header_cells) = header.as_ref() else {
            continue;
        };
        let Some(package_idx) = author_work_package_table_column(
            header_cells,
            AUTHOR_WORK_PACKAGE_TABLE_PACKAGE_COLUMNS,
        ) else {
            continue;
        };
        let text_idx =
            author_work_package_table_column(header_cells, AUTHOR_WORK_PACKAGE_TABLE_TEXT_COLUMNS);
        let lane_idx =
            author_work_package_table_column(header_cells, AUTHOR_WORK_PACKAGE_TABLE_LANE_COLUMNS);
        if package_idx >= cells.len() {
            continue;
        }
        let package_cell = cells[package_idx].trim();
        if !package_cell.is_empty()
            && current_package.is_some()
            && !packages
                .iter()
                .any(|candidate| candidate.id == package_cell)
            && author_work_package_lane_from_table_value(package_cell).is_some()
        {
            cells.insert(package_idx, String::new());
        } else if !package_cell.is_empty()
            && current_package.is_some()
            && current_lane.is_some()
            && !packages
                .iter()
                .any(|candidate| candidate.id == package_cell)
            && !is_work_package_id_like(package_cell)
        {
            cells.insert(package_idx, String::new());
            cells.insert(package_idx + 1, String::new());
        }
        let raw_package = cells[package_idx].trim().trim_matches('`');
        if !raw_package.is_empty() {
            current_package = Some(raw_package.to_string());
        }
        let Some(package) = current_package.clone() else {
            continue;
        };
        if let Some(idx) = lane_idx {
            if let Some(value) = cells.get(idx) {
                if let Some(lane) = author_work_package_lane_from_table_value(value) {
                    current_lane = Some(lane);
                }
            }
        }
        if !packages.iter().any(|candidate| candidate.id == package) {
            return Err(format!(
                "package `{package}` from tabular request input is not present in the large-mod blueprint"
            ));
        }
        let lane = current_lane;
        let Some(line) =
            author_work_package_table_request_line(header_cells, &cells, text_idx, lane)
        else {
            continue;
        };
        grouped.entry(package).or_default().push(line);
    }
    if grouped.is_empty() {
        return Ok(None);
    }
    Ok(Some(
        grouped
            .into_iter()
            .map(|(package, chunks)| {
                (
                    package,
                    chunks
                        .into_iter()
                        .map(|chunk| chunk.trim().to_string())
                        .filter(|chunk| !chunk.is_empty())
                        .collect::<Vec<_>>()
                        .join("\n"),
                )
            })
            .collect(),
    ))
}

pub(crate) fn normalise_single_work_package_request_text(
    text: &str,
    package_id: Option<&str>,
) -> String {
    single_work_package_tabular_text(text, package_id).unwrap_or_else(|| text.to_string())
}

fn single_work_package_tabular_text(text: &str, package_id: Option<&str>) -> Option<String> {
    let mut header: Option<Vec<String>> = None;
    let mut current_package: Option<String> = None;
    let mut current_lane: Option<AuthorWorkPackageLane> = None;
    let mut lines = Vec::new();
    for line in author_work_package_table_records(text) {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        if line.starts_with("# sheet:") {
            continue;
        }
        let cells = split_author_work_package_table_row(line);
        if cells.len() < 2 {
            continue;
        }
        if author_work_package_table_separator_row(&cells) {
            continue;
        }
        if header.is_none() && author_work_package_table_header_score(&cells) >= 2 {
            header = Some(cells);
            continue;
        }
        let Some(header_cells) = header.as_ref() else {
            continue;
        };
        let package_idx = author_work_package_table_column(
            header_cells,
            AUTHOR_WORK_PACKAGE_TABLE_PACKAGE_COLUMNS,
        );
        let text_idx =
            author_work_package_table_column(header_cells, AUTHOR_WORK_PACKAGE_TABLE_TEXT_COLUMNS);
        let lane_idx =
            author_work_package_table_column(header_cells, AUTHOR_WORK_PACKAGE_TABLE_LANE_COLUMNS);
        if let Some(idx) = package_idx {
            let raw_package = cells
                .get(idx)
                .map(|cell| cell.trim().trim_matches('`'))
                .unwrap_or("");
            if !raw_package.is_empty() {
                current_package = Some(raw_package.to_string());
            }
            if let Some(target) = package_id {
                if current_package
                    .as_deref()
                    .is_some_and(|current| current != target)
                {
                    continue;
                }
            }
        }
        if let Some(idx) = lane_idx {
            if let Some(value) = cells.get(idx) {
                if let Some(lane) = author_work_package_lane_from_table_value(value) {
                    current_lane = Some(lane);
                }
            }
        }
        let Some(line) =
            author_work_package_table_request_line(header_cells, &cells, text_idx, current_lane)
        else {
            continue;
        };
        lines.push(line);
    }
    if lines.is_empty() {
        None
    } else {
        Some(lines.join("\n"))
    }
}

pub(crate) fn author_work_package_table_records(text: &str) -> Vec<String> {
    let mut records = Vec::new();
    let mut csv_buffer = String::new();
    for raw in text.lines() {
        let trimmed = raw.trim();
        if csv_buffer.is_empty() && trimmed.is_empty() {
            continue;
        }
        if !csv_buffer.is_empty() {
            csv_buffer.push('\n');
            csv_buffer.push_str(raw);
            if author_work_package_csv_record_complete(&csv_buffer) {
                records.push(csv_buffer.trim().to_string());
                csv_buffer.clear();
            }
            continue;
        }
        if author_work_package_csv_row_candidate(raw)
            && !author_work_package_csv_record_complete(raw)
        {
            csv_buffer.push_str(raw);
            continue;
        }
        records.push(trimmed.to_string());
    }
    if !csv_buffer.trim().is_empty() {
        records.push(csv_buffer.trim().to_string());
    }
    records
}

pub(crate) fn split_author_work_package_table_row(line: &str) -> Vec<String> {
    if line.contains('\t') {
        return line
            .split('\t')
            .map(|cell| cell.trim().to_string())
            .collect();
    }
    if line.contains('|') {
        return line
            .trim_matches('|')
            .split('|')
            .map(|cell| cell.trim().to_string())
            .collect();
    }
    if author_work_package_csv_row_candidate(line) {
        let delimiter = author_work_package_delimited_row_separator(line).unwrap_or(',');
        let cells = split_author_work_package_delimited_row(line, delimiter);
        if cells.len() >= 2 {
            return cells;
        }
    }
    Vec::new()
}

fn author_work_package_csv_row_candidate(line: &str) -> bool {
    author_work_package_delimited_row_separator(line).is_some()
        && !line.trim_start().starts_with('#')
        && !line.trim_start().starts_with("//")
}

fn author_work_package_delimited_row_separator(line: &str) -> Option<char> {
    [',', ';', '，']
        .into_iter()
        .filter_map(|delimiter| {
            let count = author_work_package_delimiter_count(line, delimiter);
            (count > 0).then_some((delimiter, count))
        })
        .max_by_key(|(_, count)| *count)
        .map(|(delimiter, _)| delimiter)
}

fn author_work_package_delimiter_count(line: &str, delimiter: char) -> usize {
    let mut count = 0usize;
    let mut chars = line.chars().peekable();
    let mut in_quotes = false;
    while let Some(ch) = chars.next() {
        match ch {
            '"' if in_quotes && chars.peek() == Some(&'"') => {
                chars.next();
            }
            '"' => in_quotes = !in_quotes,
            _ if ch == delimiter && !in_quotes => count += 1,
            _ => {}
        }
    }
    count
}

fn split_author_work_package_delimited_row(line: &str, delimiter: char) -> Vec<String> {
    let mut cells = Vec::new();
    let mut current = String::new();
    let mut chars = line.chars().peekable();
    let mut in_quotes = false;
    while let Some(ch) = chars.next() {
        match ch {
            '"' if in_quotes && chars.peek() == Some(&'"') => {
                current.push('"');
                chars.next();
            }
            '"' => {
                in_quotes = !in_quotes;
            }
            _ if ch == delimiter && !in_quotes => {
                cells.push(cleanup_author_work_package_csv_cell(&current));
                current.clear();
            }
            _ => current.push(ch),
        }
    }
    cells.push(cleanup_author_work_package_csv_cell(&current));
    cells
}

fn author_work_package_csv_record_complete(line: &str) -> bool {
    let mut chars = line.chars().peekable();
    let mut in_quotes = false;
    while let Some(ch) = chars.next() {
        match ch {
            '"' if in_quotes && chars.peek() == Some(&'"') => {
                chars.next();
            }
            '"' => in_quotes = !in_quotes,
            _ => {}
        }
    }
    !in_quotes
}

fn cleanup_author_work_package_csv_cell(cell: &str) -> String {
    cell.trim().to_string()
}

