fn author_work_package_table_separator_row(cells: &[String]) -> bool {
    cells.len() >= 2
        && cells.iter().all(|cell| {
            let trimmed = cell.trim();
            !trimmed.is_empty()
                && trimmed.chars().any(|ch| ch == '-')
                && trimmed
                    .chars()
                    .all(|ch| matches!(ch, '-' | ':' | '：' | ' '))
        })
}

fn normalise_author_work_package_table_header_cell(cell: &str) -> String {
    cell.trim()
        .trim_matches('`')
        .trim()
        .trim_end_matches(|ch| ch == ':' || ch == '：')
        .trim()
        .chars()
        .filter(|ch| {
            !matches!(
                ch,
                ' ' | '\t' | '_' | '-' | '－' | '—' | '.' | '/' | '\\' | '(' | ')' | '（' | '）'
            )
        })
        .collect::<String>()
        .to_ascii_lowercase()
}

fn author_work_package_table_header_score(cells: &[String]) -> usize {
    let lower = cells
        .iter()
        .map(|cell| normalise_author_work_package_table_header_cell(cell))
        .collect::<Vec<_>>();
    let has_package = lower.iter().any(|cell| {
        AUTHOR_WORK_PACKAGE_TABLE_PACKAGE_COLUMNS
            .iter()
            .any(|name| cell == &normalise_author_work_package_table_header_cell(name))
    });
    let has_text = lower.iter().any(|cell| {
        AUTHOR_WORK_PACKAGE_TABLE_TEXT_COLUMNS
            .iter()
            .any(|name| cell == &normalise_author_work_package_table_header_cell(name))
    });
    let has_structured_body = lower.iter().any(|cell| {
        author_work_package_table_header_matches(
            cell,
            &[
                "title",
                "name",
                "标题",
                "名称",
                "题目",
                "effect",
                "effects",
                "reward",
                "效果",
                "奖励",
                "收益",
                "description",
                "desc",
                "描述",
                "说明",
                "id",
                "focus_id",
                "国策ID",
                "国策编号",
                "event_key",
                "事件ID",
                "事件编号",
                "namespace",
                "命名空间",
                "icon",
                "GFX",
                "图标",
                "x",
                "y",
                "prerequisite",
                "前置国策",
                "relative_position_id",
                "target",
                "category",
                "visible",
                "available",
                "cooldown",
                "remove",
                "option_a",
                "选项A",
                "选项一",
                "选项1",
                "effect_a",
                "效果A",
                "效果一",
                "效果1",
                "next_a",
                "delay_a",
                "option_b",
                "effect_b",
                "next_b",
                "delay_b",
                "option_a_condition",
                "hidden_effect_a",
                "effect_preview_a",
                "immediate_effect",
                "modifier",
                "dynamic_modifier",
                "custom_effect_tooltip",
                "temp_variable",
                "change_effect",
                "key",
                "value",
                "localisation_key",
                "localisation_value",
            ],
        )
    });
    let has_lane = lower.iter().any(|cell| {
        AUTHOR_WORK_PACKAGE_TABLE_LANE_COLUMNS
            .iter()
            .any(|name| cell == &normalise_author_work_package_table_header_cell(name))
    });
    usize::from(has_package) + usize::from(has_text || has_structured_body) + usize::from(has_lane)
}

fn author_work_package_table_column(cells: &[String], names: &[&str]) -> Option<usize> {
    cells.iter().position(|cell| {
        let lower = normalise_author_work_package_table_header_cell(cell);
        author_work_package_table_header_matches(&lower, names)
    })
}

fn author_work_package_table_header_matches(cell: &str, names: &[&str]) -> bool {
    names
        .iter()
        .any(|name| cell == normalise_author_work_package_table_header_cell(name))
}

fn author_work_package_lane_from_table_value(value: &str) -> Option<AuthorWorkPackageLane> {
    let lower = value.trim().to_ascii_lowercase();
    author_work_package_explicit_lane(value.trim(), &lower).or_else(|| {
        [
            AuthorWorkPackageLane::Focus,
            AuthorWorkPackageLane::Event,
            AuthorWorkPackageLane::Decision,
            AuthorWorkPackageLane::NationalSpirit,
            AuthorWorkPackageLane::DynamicModifier,
            AuthorWorkPackageLane::Localisation,
            AuthorWorkPackageLane::Intent,
        ]
        .into_iter()
        .find(|lane| {
            lane.keywords()
                .iter()
                .any(|keyword| lower == keyword.to_ascii_lowercase())
        })
    })
}

fn author_work_package_table_lane_line(lane: AuthorWorkPackageLane, body: &str) -> String {
    let body = body.trim();
    let lower = body.to_ascii_lowercase();
    if author_work_package_explicit_lane(body, &lower).is_some() {
        return normalise_work_package_request_lane_lines(body);
    }
    format!("{}：{}", lane.heading(), body)
}

