fn large_mod_apply_repair_queue_json(
    blueprint: &LargeModBlueprint,
    blueprint_path: &Path,
    mod_root: &Path,
    input_dir: &Path,
    status: &str,
    executed: bool,
    selected_count: usize,
    applied_count: usize,
    executed_count: usize,
    failed_rerun_count: usize,
    missing_input_count: usize,
    missing_bundle_count: usize,
    context_blocked_count: usize,
    error_count: usize,
    entries: &[String],
    run_summary_path: &Path,
    repair_queue_path: &Path,
    repair_cycle_path: &Path,
) -> String {
    let root = mod_root.display().to_string();
    let next_commands = vec![
        format!("hoi4skill large-mod-repair-cycle --mod-root {root} --output .hoi4skill/repair_cycle.json"),
        format!("hoi4skill run-work-packages --mod-root {root} --ready-only --execute --game-root <HOI4 root>"),
        format!("hoi4skill large-mod-batch-acceptance --mod-root {root} --execute --game-root <HOI4 root> --require-accepted --output .hoi4skill/batch_acceptance.json"),
        format!("hoi4skill large-mod-production-gate --mod-root {root} --require-semiauto-ready --output .hoi4skill/production_gate.json"),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_repair_queue_apply.v1\",\n  \"status\": {},\n  \"executed\": {},\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"blueprint\": {},\n  \"input_dir\": {},\n  \"selected_package_count\": {},\n  \"applied_count\": {},\n  \"executed_count\": {},\n  \"failed_rerun_count\": {},\n  \"missing_input_count\": {},\n  \"missing_repair_bundle_count\": {},\n  \"context_blocked_count\": {},\n  \"error_count\": {},\n  \"run_summary\": {},\n  \"input_repair_queue\": {},\n  \"repair_cycle\": {},\n  \"packages\": [\n{}\n  ],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(executed),
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&root),
        json_str(&blueprint_path.display().to_string()),
        json_str(&input_dir.display().to_string()),
        selected_count,
        applied_count,
        executed_count,
        failed_rerun_count,
        missing_input_count,
        missing_bundle_count,
        context_blocked_count,
        error_count,
        json_str(&run_summary_path.display().to_string()),
        json_str(&repair_queue_path.display().to_string()),
        json_str(&repair_cycle_path.display().to_string()),
        entries.join(",\n"),
        json_array(&next_commands),
        json_array(&large_mod_apply_repair_queue_stop_conditions()),
    )
}

fn large_mod_apply_repair_queue_stop_conditions() -> Vec<String> {
    vec![
        "Batch repair apply only writes work-package input templates; final Clausewitz remains Rust-writer-owned.".to_string(),
        "Do not apply repair bundles whose retrieval_status is not ok unless explicit human evidence has been verified or --allow-unverified-context is intentionally used.".to_string(),
        "After applying repairs, rerun repair-cycle, batch acceptance, strict validation, and production-gate before claiming semiauto readiness.".to_string(),
    ]
}

#[derive(Debug)]
struct WorkPackageRepairInputPatch {
    kind: String,
    text: String,
}

fn parse_work_package_repair_input_patches(
    text: &str,
) -> Result<Vec<WorkPackageRepairInputPatch>, String> {
    let mut patches = Vec::new();
    let mut active_kind: Option<String> = None;
    let mut active_text = String::new();
    for line in text.lines() {
        if let Some(info) = line.trim_start().strip_prefix("```") {
            if let Some(kind) = active_kind.take() {
                patches.push(WorkPackageRepairInputPatch {
                    kind,
                    text: trim_repair_input_text(&active_text),
                });
                active_text.clear();
                continue;
            }
            let info = info.trim();
            if info.is_empty() {
                continue;
            }
            if let Some(kind) = parse_work_package_repair_input_kind(info)? {
                active_kind = Some(kind);
                active_text.clear();
            }
            continue;
        }
        if active_kind.is_some() {
            active_text.push_str(line);
            active_text.push('\n');
        }
    }
    if active_kind.is_some() {
        return Err("unterminated hoi4skill-input fenced block in repair input".to_string());
    }
    Ok(patches)
}

fn parse_work_package_repair_input_kind(info: &str) -> Result<Option<String>, String> {
    let raw = info
        .strip_prefix("hoi4skill-input:")
        .or_else(|| info.strip_prefix("hoi4skill-input "))
        .or_else(|| info.strip_prefix("hoi4skill_input:"))
        .or_else(|| info.strip_prefix("hoi4skill_input "));
    let Some(raw) = raw else {
        return Ok(None);
    };
    let requested = raw
        .split_whitespace()
        .next()
        .unwrap_or("")
        .trim_matches(['`', '"', '\'']);
    canonical_work_package_repair_input_kind(requested)
        .map(Some)
        .ok_or_else(|| {
            format!(
                "unsupported repair input kind `{requested}`; expected focus_layout, event_cards, feature_cards, intent, dynamic_modifier_intent, localisation_placeholders, or translated_localisation"
            )
        })
}

fn canonical_work_package_repair_input_kind(kind: &str) -> Option<String> {
    match kind {
        "focus_layout" | "focus" | "focuses" | "national_focus" | "national_focuses" => {
            Some("focus_layout".to_string())
        }
        "event_cards" | "event" | "events" | "event_chain" => Some("event_cards".to_string()),
        "feature_cards" | "feature" | "features" | "decision" | "decisions" | "national_spirit"
        | "national_spirits" | "idea" | "ideas" => Some("feature_cards".to_string()),
        "intent" | "effect_intent" | "effects" => Some("intent".to_string()),
        "dynamic_modifier_intent" | "dynamic_modifier" | "dynamic_modifiers" | "dynamic" => {
            Some("dynamic_modifier_intent".to_string())
        }
        "localisation_placeholders"
        | "localization_placeholders"
        | "localisation"
        | "localization"
        | "loc"
        | "loc_tokens" => Some("localisation_placeholders".to_string()),
        "translated_localisation"
        | "translated_localization"
        | "translated_l_simp_chinese"
        | "translation" => Some("translated_localisation".to_string()),
        _ => None,
    }
}

fn work_package_repair_input_filename(kind: &str) -> &'static str {
    match kind {
        "focus_layout" => "focus_layout.txt",
        "event_cards" => "event_cards.txt",
        "feature_cards" => "feature_cards.txt",
        "intent" => "intent.txt",
        "dynamic_modifier_intent" => "dynamic_modifier_intent.txt",
        "localisation_placeholders" => "localisation_placeholders.txt",
        "translated_localisation" => "translated_l_simp_chinese.yml",
        _ => "unsupported.txt",
    }
}

fn trim_repair_input_text(text: &str) -> String {
    let mut out = text.trim_matches(|ch| ch == '\r' || ch == '\n').to_string();
    out.push('\n');
    out
}

fn parse_work_package_failed_output_dir(path: &Path) -> Option<PathBuf> {
    let text = read_utf8_lossy(path).ok()?;
    for line in text.lines() {
        let Some(rest) = line.trim().strip_prefix("- output_dir: `") else {
            continue;
        };
        let Some((value, _)) = rest.split_once('`') else {
            continue;
        };
        if !value.trim().is_empty() {
            return Some(PathBuf::from(value.trim()));
        }
    }
    None
}

fn work_package_repair_apply_report_json(
    mod_root: &Path,
    package_id: &str,
    repair_bundle: &Path,
    repair_input: &Path,
    output_dir: &Path,
    written: &[PathBuf],
    executed: bool,
    execution_status: &str,
    execution_repair_bundle: Option<&str>,
) -> String {
    let written_json = written
        .iter()
        .map(|path| {
            format!(
                "{{\"path\": {}, \"kind\": \"work_package_input\"}}",
                json_str(&path.display().to_string())
            )
        })
        .collect::<Vec<_>>()
        .join(", ");
    let next_commands = vec![
        format!(
            "hoi4skill run-work-package --mod-root {} --package {} --execute --game-root <HOI4 root>",
            mod_root.display(),
            package_id
        ),
        format!(
            "hoi4skill large-mod-run-summary --mod-root {} --output .hoi4skill/run_summary.json",
            mod_root.display()
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.work_package_repair_apply.v1\",\n  \"status\": {},\n  \"final_files_written\": false,\n  \"executed\": {},\n  \"execution_status\": {},\n  \"mod_root\": {},\n  \"package\": {},\n  \"repair_bundle\": {},\n  \"repair_input\": {},\n  \"output_dir\": {},\n  \"written_inputs\": [{}],\n  \"execution_report\": {},\n  \"execution_repair_bundle\": {},\n  \"anti_hallucination_rule\": {},\n  \"next_commands\": {}\n}}\n",
        json_str(if executed { execution_status } else { "applied" }),
        json_bool(executed),
        json_str(execution_status),
        json_str(&mod_root.display().to_string()),
        json_str(package_id),
        json_str(&repair_bundle.display().to_string()),
        json_str(&repair_input.display().to_string()),
        json_str(&output_dir.display().to_string()),
        written_json,
        json_str(&output_dir.join("execution_report.json").display().to_string()),
        json_optional_str(execution_repair_bundle),
        json_str("AI repair output may update only work-package input templates; final HOI4 files remain writer-owned and must pass strict validation."),
        json_array(&next_commands),
    )
}

pub(crate) fn cmd_work_package_start_brief(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let package_id = require_value(&map, "package")?;
    let mod_root = if let Some(root) = value(&map, "mod-root") {
        Some(normalize_path(root)?)
    } else {
        None
    };
    let blueprint_path = large_mod_blueprint_path_from_args(&map, mod_root.as_deref())?;
    let blueprint = read_large_mod_blueprint(&blueprint_path)?;
    let packages = split_large_mod_work_packages(&blueprint);
    let package = packages
        .iter()
        .find(|package| package.id == package_id)
        .ok_or_else(|| {
            format!(
                "unknown package `{}`; available packages: {}",
                package_id,
                packages
                    .iter()
                    .map(|package| package.id.as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            )
        })?;
    let markdown = work_package_start_brief_markdown(
        &blueprint,
        package,
        &packages,
        &blueprint_path,
        mod_root.as_deref(),
    );
    write_or_print(&markdown, value(&map, "output"))
}

