pub(crate) fn cmd_check_work_package_boundary(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let package_id = require_value(&map, "package")?;
    let mod_root = if let Some(root) = value(&map, "mod-root") {
        Some(normalize_path(root)?)
    } else {
        None
    };
    let blueprint_path = large_mod_blueprint_path_from_args(&map, mod_root.as_deref())?;
    let blueprint = read_large_mod_blueprint(&blueprint_path)?;
    let packages = split_large_mod_work_packages(&blueprint);
    let package = packages
        .iter()
        .find(|package| package.id == package_id)
        .ok_or_else(|| {
            format!(
                "unknown package `{}`; available packages: {}",
                package_id,
                packages
                    .iter()
                    .map(|package| package.id.as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            )
        })?;
    let changed = collect_boundary_changed_paths(&map, mod_root.as_deref())?;
    let report = work_package_boundary_report(
        &blueprint,
        package,
        &blueprint_path,
        mod_root.as_deref(),
        &changed,
        map.flags.contains("strict-names"),
    );
    write_or_print(&report.json, value(&map, "output"))?;
    if !report.ok
        && (map.flags.contains("fail-on-violation")
            || map.flags.contains("gate")
            || map.flags.contains("strict-gate"))
    {
        return Err(format!(
            "work-package boundary gate failed: {} changed file(s) outside package `{}`",
            report.violation_count, package.id
        ));
    }
    Ok(())
}

