fn collect_large_mod_production_workflow_changed_files(
    mod_root: &Path,
    package_filter: Option<&str>,
) -> Result<Vec<String>, String> {
    let hoi4skill_dir = mod_root.join(".hoi4skill");
    let mut changed = BTreeSet::new();
    if let Some(package) = package_filter {
        let path = hoi4skill_dir.join(format!("changed_{package}.txt"));
        if path.exists() {
            for item in read_changed_paths_file(&path)? {
                changed.insert(item);
            }
        }
    } else if hoi4skill_dir.is_dir() {
        for entry in fs::read_dir(&hoi4skill_dir)
            .map_err(|e| format!("read {}: {e}", hoi4skill_dir.display()))?
        {
            let entry =
                entry.map_err(|e| format!("read {} entry: {e}", hoi4skill_dir.display()))?;
            let path = entry.path();
            let Some(name) = path.file_name().and_then(OsStr::to_str) else {
                continue;
            };
            if name.starts_with("changed_") && name.ends_with(".txt") {
                for item in read_changed_paths_file(&path)? {
                    changed.insert(item);
                }
            }
        }
    }
    Ok(changed.into_iter().collect())
}

fn large_mod_production_workflow_report(
    mod_root: &Path,
    game_root: Option<&Path>,
    run_output: &Path,
    changed_output: &Path,
    evidence_output: &Path,
    gate_output: &Path,
    changed_files: &[String],
    run_error: Option<&str>,
    evidence_error: Option<&str>,
    gate_error: Option<&str>,
) -> String {
    let run_text = read_utf8_lossy(run_output).ok();
    let evidence_text = read_utf8_lossy(evidence_output).ok();
    let gate_text = read_utf8_lossy(gate_output).ok();
    let release_ready = gate_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "release_ready", true));
    let semiauto_ready = gate_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "semiauto_ready", true));
    let status = if run_error.is_some() {
        "run_failed"
    } else if evidence_error.is_some() {
        "evidence_failed"
    } else if gate_error.is_some() {
        "gate_failed"
    } else if release_ready {
        "release_ready"
    } else if semiauto_ready {
        "semiauto_ready"
    } else {
        "needs_review"
    };
    let artifacts = vec![
        run_output.display().to_string(),
        changed_output.display().to_string(),
        evidence_output.display().to_string(),
        gate_output.display().to_string(),
    ];
    let next_commands = vec![
        format!(
            "hoi4skill run-work-packages --mod-root {} --ready-only --execute --game-root <HOI4 root> --max-packages 1 --allow-failure",
            mod_root.display()
        ),
        format!(
            "hoi4skill large-mod-production-evidence-refresh --mod-root {} --game-root <HOI4 root> --changed-list {} --output {}",
            mod_root.display(),
            changed_output.display(),
            evidence_output.display()
        ),
        format!(
            "hoi4skill large-mod-production-gate --mod-root {} --output {}",
            mod_root.display(),
            gate_output.display()
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_production_workflow.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"mod_root\": {},\n  \"game_root\": {},\n  \"run_status\": {},\n  \"evidence_status\": {},\n  \"gate_status\": {},\n  \"semiauto_ready\": {},\n  \"release_ready\": {},\n  \"changed_count\": {},\n  \"changed_files\": {},\n  \"run_report\": {},\n  \"changed_list\": {},\n  \"evidence_report\": {},\n  \"production_gate_report\": {},\n  \"delivery_artifacts\": {},\n  \"run_error\": {},\n  \"evidence_error\": {},\n  \"gate_error\": {},\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(run_error.is_none() && evidence_error.is_none() && gate_error.is_none()),
        json_str(&mod_root.display().to_string()),
        json_optional_str(game_root.map(|path| path.display().to_string()).as_deref()),
        json_optional_str(run_text.as_deref().and_then(|text| status_json_string_field(text, "status")).as_deref()),
        json_optional_str(evidence_text.as_deref().and_then(|text| status_json_string_field(text, "status")).as_deref()),
        json_optional_str(gate_text.as_deref().and_then(|text| status_json_string_field(text, "status")).as_deref()),
        json_bool(semiauto_ready),
        json_bool(release_ready),
        changed_files.len(),
        json_array(&changed_files.to_vec()),
        json_str(&run_output.display().to_string()),
        json_str(&changed_output.display().to_string()),
        json_str(&evidence_output.display().to_string()),
        json_str(&gate_output.display().to_string()),
        json_array(&artifacts),
        json_optional_str(run_error),
        json_optional_str(evidence_error),
        json_optional_str(gate_error),
        json_array(&next_commands),
        json_array(&[
            "Do not claim release_ready unless production_gate_report has release_ready=true.".to_string(),
            "If evidence_failed, open evidence_report and repair_bundle artifacts before rerunning execution.".to_string(),
            "Changed-only validation must use changed_list so old large-mod errors do not mask new authoring bugs.".to_string()
        ])
    )
}

fn large_mod_repair_workflow_report(
    mod_root: &Path,
    game_root: Option<&Path>,
    executed: bool,
    repair_queue_output: &Path,
    apply_output: &Path,
    repair_cycle_output: &Path,
    production_output: &Path,
    repair_queue_error: Option<&str>,
    apply_error: Option<&str>,
    repair_cycle_error: Option<&str>,
    production_error: Option<&str>,
) -> String {
    let repair_queue_text = read_utf8_lossy(repair_queue_output).ok();
    let apply_text = read_utf8_lossy(apply_output).ok();
    let repair_cycle_text = read_utf8_lossy(repair_cycle_output).ok();
    let production_text = read_utf8_lossy(production_output).ok();
    let repair_queue_status = repair_queue_text
        .as_deref()
        .and_then(|text| status_json_string_field(text, "status"));
    let apply_status = apply_text
        .as_deref()
        .and_then(|text| status_json_string_field(text, "status"));
    let repair_cycle_status = repair_cycle_text
        .as_deref()
        .and_then(|text| status_json_string_field(text, "status"));
    let production_status = production_text
        .as_deref()
        .and_then(|text| status_json_string_field(text, "status"));
    let semiauto_ready = production_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "semiauto_ready", true));
    let release_ready = production_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "release_ready", true));
    let status = if repair_queue_error.is_some() {
        "repair_queue_failed"
    } else if apply_error.is_some() {
        "repair_apply_failed"
    } else if repair_cycle_error.is_some() {
        "repair_cycle_failed"
    } else if production_error.is_some() {
        "production_failed"
    } else if release_ready {
        "release_ready"
    } else if semiauto_ready {
        "semiauto_ready"
    } else if let Some(cycle) = repair_cycle_status.as_deref() {
        cycle
    } else if let Some(apply) = apply_status.as_deref() {
        apply
    } else {
        "needs_review"
    };
    let ok = repair_queue_error.is_none()
        && apply_error.is_none()
        && repair_cycle_error.is_none()
        && production_error.is_none()
        && (release_ready || semiauto_ready || status == "ready_for_next_batch");
    let artifacts = vec![
        repair_queue_output.display().to_string(),
        apply_output.display().to_string(),
        repair_cycle_output.display().to_string(),
        production_output.display().to_string(),
    ];
    let next_commands = vec![
        format!(
            "hoi4skill large-mod-input-repair-queue --mod-root {} --output {}",
            mod_root.display(),
            repair_queue_output.display()
        ),
        format!(
            "hoi4skill large-mod-apply-repair-queue --mod-root {} --input-dir .hoi4skill/ai_repair_inputs --execute --game-root <HOI4 root> --allow-failure --output {}",
            mod_root.display(),
            apply_output.display()
        ),
        format!(
            "hoi4skill large-mod-repair-cycle --mod-root {} --output {}",
            mod_root.display(),
            repair_cycle_output.display()
        ),
        format!(
            "hoi4skill large-mod-production-workflow --mod-root {} --ready-only --execute --game-root <HOI4 root> --output {}",
            mod_root.display(),
            production_output.display()
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_repair_workflow.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"executed\": {},\n  \"mod_root\": {},\n  \"game_root\": {},\n  \"repair_queue_status\": {},\n  \"repair_apply_status\": {},\n  \"repair_cycle_status\": {},\n  \"production_status\": {},\n  \"semiauto_ready\": {},\n  \"release_ready\": {},\n  \"input_repair_queue\": {},\n  \"repair_queue_apply\": {},\n  \"repair_cycle\": {},\n  \"production_workflow\": {},\n  \"delivery_artifacts\": {},\n  \"repair_queue_error\": {},\n  \"repair_apply_error\": {},\n  \"repair_cycle_error\": {},\n  \"production_error\": {},\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(ok),
        json_bool(executed),
        json_str(&mod_root.display().to_string()),
        json_optional_str(game_root.map(|path| path.display().to_string()).as_deref()),
        json_optional_str(repair_queue_status.as_deref()),
        json_optional_str(apply_status.as_deref()),
        json_optional_str(repair_cycle_status.as_deref()),
        json_optional_str(production_status.as_deref()),
        json_bool(semiauto_ready),
        json_bool(release_ready),
        json_str(&repair_queue_output.display().to_string()),
        json_str(&apply_output.display().to_string()),
        json_str(&repair_cycle_output.display().to_string()),
        json_str(&production_output.display().to_string()),
        json_array(&artifacts),
        json_optional_str(repair_queue_error),
        json_optional_str(apply_error),
        json_optional_str(repair_cycle_error),
        json_optional_str(production_error),
        json_array(&next_commands),
        json_array(&[
            "Do not accept direct Clausewitz patches from AI repair output; only hoi4skill-input fenced blocks are allowed.".to_string(),
            "If repair_apply_status is needs_context_evidence, run context evidence verification before asking the AI to write repair input.".to_string(),
            "If production_status is needs_review, inspect production_workflow and production_gate before claiming KXC-scale readiness.".to_string(),
        ])
    )
}

fn large_mod_build_workflow_report(
    mod_root: &Path,
    author_output: &Path,
    repair_output: &Path,
    production_output: &Path,
    acceptance_output: &Path,
    author_error: Option<&str>,
    repair_error: Option<&str>,
    acceptance_error: Option<&str>,
    repair_skipped_for_production_only: bool,
) -> String {
    let author_text = read_utf8_lossy(author_output).ok();
    let repair_text = read_utf8_lossy(repair_output).ok();
    let production_text = read_utf8_lossy(production_output).ok();
    let acceptance_text = read_utf8_lossy(acceptance_output).ok();
    let author_status = author_text
        .as_deref()
        .and_then(|text| status_json_string_field(text, "status"));
    let repair_status = repair_text
        .as_deref()
        .and_then(|text| status_json_string_field(text, "status"));
    let production_status = production_text
        .as_deref()
        .and_then(|text| status_json_string_field(text, "status"));
    let acceptance_status = acceptance_text
        .as_deref()
        .and_then(|text| status_json_string_field(text, "status"));
    let author_ready = author_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "semiauto_ready", true));
    let repair_ready = repair_text.as_deref().is_some_and(|text| {
        status_json_bool_field_has_value(text, "semiauto_ready", true)
            || status_json_bool_field_has_value(text, "release_ready", true)
    });
    let semiauto_ready = production_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "semiauto_ready", true));
    let release_ready = production_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "release_ready", true));
    let status = if author_error.is_some() {
        "author_failed"
    } else if repair_error.is_some() {
        "repair_or_production_failed"
    } else if acceptance_error.is_some() {
        "acceptance_failed"
    } else if release_ready {
        "release_ready"
    } else if semiauto_ready {
        "semiauto_ready"
    } else if repair_skipped_for_production_only {
        production_status.as_deref().unwrap_or("production_only")
    } else if let Some(repair) = repair_status.as_deref() {
        repair
    } else if let Some(author) = author_status.as_deref() {
        author
    } else {
        "needs_review"
    };
    let artifacts = vec![
        author_output.display().to_string(),
        repair_output.display().to_string(),
        production_output.display().to_string(),
        acceptance_output.display().to_string(),
        mod_root
            .join(".hoi4skill")
            .join("package_request_sources.json")
            .display()
            .to_string(),
        mod_root
            .join(".hoi4skill")
            .join("production_gate.json")
            .display()
            .to_string(),
    ];
    let next_commands = vec![
        format!(
            "hoi4skill large-mod-author-workflow --mod-root {} --input-dir <request_docs> --plan-only --output {}",
            mod_root.display(),
            author_output.display()
        ),
        format!(
            "hoi4skill large-mod-repair-workflow --mod-root {} --repair-input-dir <ai_repair_inputs> --skip-evidence-refresh --output {}",
            mod_root.display(),
            repair_output.display()
        ),
        format!(
            "hoi4skill large-mod-production-workflow --mod-root {} --ready-only --execute --game-root <HOI4 root> --output {}",
            mod_root.display(),
            production_output.display()
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_build_workflow.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"mod_root\": {},\n  \"author_status\": {},\n  \"repair_status\": {},\n  \"production_status\": {},\n  \"acceptance_status\": {},\n  \"author_semiauto_ready\": {},\n  \"repair_ready\": {},\n  \"semiauto_ready\": {},\n  \"release_ready\": {},\n  \"author_workflow\": {},\n  \"repair_workflow\": {},\n  \"production_workflow\": {},\n  \"acceptance_report\": {},\n  \"delivery_artifacts\": {},\n  \"author_error\": {},\n  \"repair_or_production_error\": {},\n  \"acceptance_error\": {},\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(author_error.is_none() && repair_error.is_none() && acceptance_error.is_none()),
        json_str(&mod_root.display().to_string()),
        json_optional_str(author_status.as_deref()),
        json_optional_str(repair_status.as_deref()),
        json_optional_str(production_status.as_deref()),
        json_optional_str(acceptance_status.as_deref()),
        json_bool(author_ready),
        json_bool(repair_ready),
        json_bool(semiauto_ready),
        json_bool(release_ready),
        json_str(&author_output.display().to_string()),
        json_str(&repair_output.display().to_string()),
        json_str(&production_output.display().to_string()),
        json_str(&acceptance_output.display().to_string()),
        json_array(&artifacts),
        json_optional_str(author_error),
        json_optional_str(repair_error),
        json_optional_str(acceptance_error),
        json_array(&next_commands),
        json_array(&[
            "Do not treat build_workflow ok=true as release readiness; require semiauto_ready or release_ready for acceptance.".to_string(),
            "Use repair-input-dir only for AI repair fenced blocks; user Word/Excel/txt sources belong to input-dir or repeated input.".to_string(),
            "If production_status is needs_review, inspect production_workflow and production_gate before continuing.".to_string(),
        ])
    )
}

fn large_mod_build_acceptance_json(
    mod_root: &Path,
    build_report: &Path,
    author_report: &Path,
    repair_report: &Path,
    production_report: &Path,
    source_report: &Path,
    validation_report: &Path,
    text_alignment_report: &Path,
    required_input_kinds: &[String],
    require_six_lanes: bool,
    require_ready: bool,
    require_final_validation: bool,
) -> String {
    let build_text = read_utf8_lossy(build_report).ok();
    let author_text = read_utf8_lossy(author_report).ok();
    let repair_text = read_utf8_lossy(repair_report).ok();
    let production_text = read_utf8_lossy(production_report).ok();
    let source_text = read_utf8_lossy(source_report).ok();
    let validation_text = read_utf8_lossy(validation_report).ok();
    let text_alignment_text = read_utf8_lossy(text_alignment_report).ok();
    let request_file = source_text
        .as_deref()
        .and_then(|text| status_json_string_field(text, "request_file"))
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            mod_root
                .join(".hoi4skill")
                .join("package_requests_from_sources.md")
        });
    let request_text = read_utf8_lossy(&request_file).ok();
    let source_kinds = source_text
        .as_deref()
        .map(|text| status_json_string_field_values(text, "kind"))
        .unwrap_or_default()
        .into_iter()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let source_lanes = source_text
        .as_deref()
        .map(|text| status_json_string_array_values(text, "lanes"))
        .unwrap_or_default()
        .into_iter()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let required_lanes = large_mod_required_semiauto_lanes();
    let missing_lanes = required_lanes
        .iter()
        .filter(|lane| !source_lanes.contains(lane))
        .cloned()
        .collect::<Vec<_>>();
    let missing_input_kinds = required_input_kinds
        .iter()
        .filter(|kind| !source_kinds.contains(kind))
        .cloned()
        .collect::<Vec<_>>();
    let semiauto_ready = production_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "semiauto_ready", true));
    let release_ready = production_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "release_ready", true));
    let validation_present = validation_text.is_some();
    let text_alignment_present = text_alignment_text.is_some();
    let strict_code_index = validation_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "strict_code_index", true));
    let validation_schema_ok = validation_text
        .as_deref()
        .is_some_and(large_mod_acceptance_validation_schema_ok);
    let validation_issue_fields = validation_text
        .as_deref()
        .map(large_mod_acceptance_validation_issue_fields)
        .unwrap_or_default();
    let validation_ok = validation_text.as_deref().is_some_and(|text| {
        validation_schema_ok
            && strict_code_index
            && status_json_bool_field_has_value(text, "ok", true)
            && validation_issue_fields.is_empty()
    });
    let text_alignment_schema_ok = text_alignment_text
        .as_deref()
        .is_some_and(large_mod_acceptance_text_alignment_schema_ok);
    let text_alignment_issue_fields = text_alignment_text
        .as_deref()
        .map(large_mod_acceptance_text_alignment_issue_fields)
        .unwrap_or_default();
    let text_alignment_ok = text_alignment_text.as_deref().is_some_and(|text| {
        text_alignment_schema_ok
            && status_json_bool_field_has_value(text, "ok", true)
            && text_alignment_issue_fields.is_empty()
    });
    let raw_table_leak = request_text.as_deref().is_some_and(|text| {
        text.contains("package,lane,title")
            || text.contains("package, lane, title")
            || text.contains("content_type,")
            || text.contains("localisation_key,localisation_value")
    });
    let mut blockers = Vec::new();
    large_mod_acceptance_require_schema(
        build_report,
        build_text.as_deref(),
        "hoi4skill.large_mod_build_workflow.v1",
        false,
        &mut blockers,
    );
    large_mod_acceptance_require_schema(
        author_report,
        author_text.as_deref(),
        "hoi4skill.large_mod_author_workflow.v1",
        true,
        &mut blockers,
    );
    large_mod_acceptance_require_schema(
        repair_report,
        repair_text.as_deref(),
        "hoi4skill.large_mod_repair_workflow.v1",
        true,
        &mut blockers,
    );
    large_mod_acceptance_require_schema(
        production_report,
        production_text.as_deref(),
        "hoi4skill.large_mod_production_workflow.v1",
        true,
        &mut blockers,
    );
    large_mod_acceptance_require_schema(
        source_report,
        source_text.as_deref(),
        "hoi4skill.author_work_package_sources.v1",
        true,
        &mut blockers,
    );
    if request_text.is_none() {
        blockers.push(format!("missing_request_file:{}", request_file.display()));
    }
    if raw_table_leak {
        blockers.push("request_file_contains_raw_table_header".to_string());
    }
    if source_kinds.is_empty() {
        blockers.push("no_input_sources_recorded".to_string());
    }
    if require_six_lanes && !missing_lanes.is_empty() {
        blockers.push(format!(
            "missing_required_lanes:{}",
            missing_lanes.join(",")
        ));
    }
    if !missing_input_kinds.is_empty() {
        blockers.push(format!(
            "missing_required_input_kinds:{}",
            missing_input_kinds.join(",")
        ));
    }
    if require_ready && !semiauto_ready && !release_ready {
        blockers.push("not_semiauto_or_release_ready".to_string());
    }
    if require_final_validation && !validation_present {
        blockers.push(format!(
            "missing_validation_report:{}",
            validation_report.display()
        ));
    }
    if validation_present {
        if !validation_schema_ok {
            blockers.push(format!(
                "validation_bad_schema:{}:expected:hoi4skill.validation.v1|hoi4skill.validation_report.v1",
                validation_report.display()
            ));
        }
        if !strict_code_index {
            blockers.push(format!(
                "strict_code_index_missing_or_false:{}",
                validation_report.display()
            ));
        }
        if !validation_text
            .as_deref()
            .is_some_and(|text| status_json_bool_field_has_value(text, "ok", true))
        {
            blockers.push(format!("validation_not_ok:{}", validation_report.display()));
        }
        if !validation_issue_fields.is_empty() {
            blockers.push(format!(
                "validation_errors_present:{}:{}",
                validation_report.display(),
                validation_issue_fields.join(",")
            ));
        }
    }
    if require_final_validation && !text_alignment_present {
        blockers.push(format!(
            "missing_text_alignment_report:{}",
            text_alignment_report.display()
        ));
    }
    if text_alignment_present {
        if !text_alignment_schema_ok {
            blockers.push(format!(
                "text_alignment_bad_schema:{}:expected:hoi4skill.text_alignment.v1",
                text_alignment_report.display()
            ));
        }
        if !text_alignment_text
            .as_deref()
            .is_some_and(|text| status_json_bool_field_has_value(text, "ok", true))
        {
            blockers.push(format!(
                "text_alignment_not_ok:{}",
                text_alignment_report.display()
            ));
        }
        if !text_alignment_issue_fields.is_empty() {
            blockers.push(format!(
                "text_alignment_issues_present:{}:{}",
                text_alignment_report.display(),
                text_alignment_issue_fields.join(",")
            ));
        }
    }
    let lane_completion_percent = percentage(
        required_lanes.len().saturating_sub(missing_lanes.len()),
        required_lanes.len(),
    );
    let input_mode_completion_percent = percentage(
        required_input_kinds
            .len()
            .saturating_sub(missing_input_kinds.len()),
        required_input_kinds.len(),
    );
    let mut gate_done = 0usize;
    let mut gate_total = 2usize;
    if !raw_table_leak {
        gate_done += 1;
    }
    if !source_kinds.is_empty() {
        gate_done += 1;
    }
    if require_ready {
        gate_total += 1;
        if semiauto_ready || release_ready {
            gate_done += 1;
        }
    }
    if require_final_validation || validation_present {
        gate_total += 1;
        if validation_ok {
            gate_done += 1;
        }
    }
    if require_final_validation || text_alignment_present {
        gate_total += 1;
        if text_alignment_ok {
            gate_done += 1;
        }
    }
    let gate_completion_percent = percentage(gate_done, gate_total);
    let overall_completion_percent =
        (lane_completion_percent + gate_completion_percent + input_mode_completion_percent) / 3;
    let next_required_action = blockers
        .first()
        .cloned()
        .unwrap_or_else(|| "ready_for_next_large_mod_gate".to_string());
    let ok = blockers.is_empty();
    let status = if ok { "ok" } else { "blocked" };
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_build_acceptance.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"mod_root\": {},\n  \"require_six_lanes\": {},\n  \"require_ready\": {},\n  \"require_final_validation\": {},\n  \"semiauto_ready\": {},\n  \"release_ready\": {},\n  \"lane_completion_percent\": {},\n  \"input_mode_completion_percent\": {},\n  \"gate_completion_percent\": {},\n  \"overall_completion_percent\": {},\n  \"next_required_action\": {},\n  \"validation_present\": {},\n  \"validation_ok\": {},\n  \"strict_code_index\": {},\n  \"validation_report\": {},\n  \"validation_issue_fields\": {},\n  \"text_alignment_present\": {},\n  \"text_alignment_ok\": {},\n  \"text_alignment_report\": {},\n  \"text_alignment_issue_fields\": {},\n  \"build_report\": {},\n  \"author_report\": {},\n  \"repair_report\": {},\n  \"production_report\": {},\n  \"request_sources_report\": {},\n  \"request_file\": {},\n  \"source_kinds\": {},\n  \"required_input_kinds\": {},\n  \"missing_required_input_kinds\": {},\n  \"has_word_input\": {},\n  \"has_excel_input\": {},\n  \"has_plain_text_input\": {},\n  \"has_table_text_input\": {},\n  \"source_lanes\": {},\n  \"required_lanes\": {},\n  \"missing_required_lanes\": {},\n  \"raw_table_leak\": {},\n  \"blocking_count\": {},\n  \"blockers\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(ok),
        json_str(&mod_root.display().to_string()),
        json_bool(require_six_lanes),
        json_bool(require_ready),
        json_bool(require_final_validation),
        json_bool(semiauto_ready),
        json_bool(release_ready),
        lane_completion_percent,
        input_mode_completion_percent,
        gate_completion_percent,
        overall_completion_percent,
        json_str(&next_required_action),
        json_bool(validation_present),
        json_bool(validation_ok),
        json_bool(strict_code_index),
        json_str(&validation_report.display().to_string()),
        json_array(&validation_issue_fields),
        json_bool(text_alignment_present),
        json_bool(text_alignment_ok),
        json_str(&text_alignment_report.display().to_string()),
        json_array(&text_alignment_issue_fields),
        json_str(&build_report.display().to_string()),
        json_str(&author_report.display().to_string()),
        json_str(&repair_report.display().to_string()),
        json_str(&production_report.display().to_string()),
        json_str(&source_report.display().to_string()),
        json_str(&request_file.display().to_string()),
        json_array(&source_kinds),
        json_array(&required_input_kinds.to_vec()),
        json_array(&missing_input_kinds),
        json_bool(source_kinds.iter().any(|kind| kind == "docx_word")),
        json_bool(source_kinds.iter().any(|kind| kind == "xlsx_excel")),
        json_bool(source_kinds.iter().any(|kind| kind == "plain_text")),
        json_bool(source_kinds.iter().any(|kind| kind == "table_text")),
        json_array(&source_lanes),
        json_array(&required_lanes),
        json_array(&missing_lanes),
        json_bool(raw_table_leak),
        blockers.len(),
        json_array(&blockers),
        json_array(&[
            "Do not accept a build if raw_table_leak=true; table inputs must be converted into lane text before authoring.".to_string(),
            "Use --require-six-lanes for KXC/MDARD-scale content acceptance across focus, event, decision, national_spirit, dynamic_modifier, and localisation.".to_string(),
            "Use --require-large-mod-inputs when acceptance must prove Word, Excel, and plain-text source ingestion were exercised.".to_string(),
            "Use --require-ready only when production_gate semiauto_ready or release_ready is required.".to_string(),
            "Use --require-final-validation when generated code must prove strict_code_index validation and text alignment before acceptance.".to_string(),
        ])
    )
}

fn percentage(done: usize, total: usize) -> usize {
    if total == 0 {
        100
    } else {
        done.saturating_mul(100) / total
    }
}

fn large_mod_acceptance_required_input_kinds(map: &ArgMap) -> Vec<String> {
    let mut kinds = BTreeSet::new();
    let require_all = map.flags.contains("require-large-mod-inputs")
        || map.flags.contains("require-kxc-scale-inputs")
        || map.flags.contains("require-office-text-inputs");
    if require_all || map.flags.contains("require-word-input") {
        kinds.insert("docx_word".to_string());
    }
    if require_all || map.flags.contains("require-excel-input") {
        kinds.insert("xlsx_excel".to_string());
    }
    if require_all || map.flags.contains("require-plain-text-input") {
        kinds.insert("plain_text".to_string());
    }
    if map.flags.contains("require-table-text-input") {
        kinds.insert("table_text".to_string());
    }
    for value in repeated_values(map, "require-input-kind") {
        let value = value.trim();
        if !value.is_empty() {
            kinds.insert(value.to_string());
        }
    }
    kinds.into_iter().collect()
}

fn write_large_mod_build_acceptance_repair_pack(
    mod_root: &Path,
    acceptance_report: &Path,
    output_dir: &Path,
    acceptance_json: &str,
    map: &ArgMap,
) -> Result<(), String> {
    fs::create_dir_all(output_dir).map_err(|e| format!("create {}: {e}", output_dir.display()))?;
    let blockers = status_json_string_array_values(acceptance_json, "blockers");
    let queries = large_mod_build_acceptance_repair_queries(acceptance_json);
    let package = WorkPackage {
        id: "large_mod_build_acceptance".to_string(),
        kind: "acceptance".to_string(),
        title: "Large Mod Build Acceptance Repair".to_string(),
        allowed_paths: vec![
            "common/national_focus".to_string(),
            "events".to_string(),
            "common/decisions".to_string(),
            "common/ideas".to_string(),
            "common/dynamic_modifiers".to_string(),
            "common/scripted_effects".to_string(),
            "localisation".to_string(),
            ".hoi4skill".to_string(),
        ],
        deliverables: vec![
            "repair structured package inputs".to_string(),
            "rerun strict validation and text alignment".to_string(),
        ],
        validation_steps: vec![
            "large-mod-build-acceptance --require-final-validation --fail-on-blockers".to_string(),
            "validate --strict-code-index".to_string(),
            "check-text-alignment".to_string(),
        ],
    };
    let retrieved = build_work_package_run_retrieved_repair_context(
        &package,
        mod_root,
        value(map, "game-root"),
        &queries,
        map,
    );
    let context_json = output_dir.join("acceptance_repair_context.json");
    let context_markdown = output_dir.join("acceptance_repair_context.md");
    let prompt_markdown = output_dir.join("acceptance_repair_prompt.md");
    let manifest_path = output_dir.join("manifest.json");
    fs::write(&context_json, &retrieved.json)
        .map_err(|e| format!("write {}: {e}", context_json.display()))?;
    fs::write(&context_markdown, &retrieved.markdown)
        .map_err(|e| format!("write {}: {e}", context_markdown.display()))?;
    let prompt = large_mod_build_acceptance_repair_prompt_markdown(
        mod_root,
        acceptance_report,
        &blockers,
        &queries,
        &context_markdown,
    );
    fs::write(&prompt_markdown, prompt)
        .map_err(|e| format!("write {}: {e}", prompt_markdown.display()))?;
    let manifest = large_mod_build_acceptance_repair_manifest_json(
        mod_root,
        acceptance_report,
        output_dir,
        &context_json,
        &context_markdown,
        &prompt_markdown,
        &blockers,
        &queries,
        &retrieved.status,
    );
    fs::write(&manifest_path, manifest)
        .map_err(|e| format!("write {}: {e}", manifest_path.display()))
}

fn large_mod_build_acceptance_repair_queries(acceptance_json: &str) -> Vec<String> {
    let mut queries = Vec::new();
    push_work_package_repair_query(&mut queries, "large-mod-build-acceptance strict validation");
    push_work_package_repair_query(&mut queries, "compile-intent strict-code-index repair");
    push_work_package_repair_query(&mut queries, "check-text-alignment missing user text");
    for blocker in status_json_string_array_values(acceptance_json, "blockers") {
        push_work_package_repair_query(&mut queries, &blocker);
        if blocker.contains("strict_code_index") || blocker.contains("validation") {
            push_work_package_repair_query(
                &mut queries,
                "unknown effect trigger modifier indexed code",
            );
            push_work_package_repair_query(&mut queries, "validate --strict-code-index");
        }
        if blocker.contains("text_alignment") {
            push_work_package_repair_query(
                &mut queries,
                "localisation placeholder scripted localisation icon flag leader",
            );
            push_work_package_repair_query(
                &mut queries,
                "text alignment expected user visible text",
            );
        }
        if blocker.contains("dynamic_modifier") {
            push_work_package_repair_query(
                &mut queries,
                "dynamic modifier scripted_effect custom_effect_tooltip set_temp_variable",
            );
        }
        if blocker.contains("raw_table") || blocker.contains("input_sources") {
            push_work_package_repair_query(
                &mut queries,
                "author-work-packages Word Excel CSV plain text lane routing",
            );
        }
    }
    for key in [
        "validation_issue_fields",
        "text_alignment_issue_fields",
        "missing_required_lanes",
        "source_lanes",
    ] {
        for value in status_json_string_array_values(acceptance_json, key) {
            push_work_package_repair_query(&mut queries, &value);
        }
    }
    queries.truncate(60);
    queries
}

fn large_mod_build_acceptance_repair_prompt_markdown(
    mod_root: &Path,
    acceptance_report: &Path,
    blockers: &[String],
    queries: &[String],
    context_markdown: &Path,
) -> String {
    let mut out = String::new();
    out.push_str("# Large Mod Build Acceptance Repair Prompt\n\n");
    out.push_str("- schema: `hoi4skill.large_mod_build_acceptance_repair_prompt.v1`\n");
    out.push_str(&format!("- mod_root: `{}`\n", mod_root.display()));
    out.push_str(&format!(
        "- acceptance_report: `{}`\n",
        acceptance_report.display()
    ));
    out.push_str(&format!(
        "- retrieved_context: `{}`\n",
        context_markdown.display()
    ));
    out.push_str("\n## Blockers\n\n");
    for blocker in blockers {
        out.push_str(&format!("- `{}`\n", blocker.replace('`', "'")));
    }
    out.push_str("\n## AI Repair Rules\n\n");
    out.push_str("- Repair structured inputs or user-facing text only; do not emit raw Clausewitz final code.\n");
    out.push_str("- Use only symbols, syntax, tags, sprites, pictures, modifiers, and examples found in the retrieved local context or strict code index.\n");
    out.push_str("- If the related context is empty, ask the user for the missing tag/icon/cosmetic-tag/leader evidence instead of inventing it.\n");
    out.push_str(
        "- Do not bypass build acceptance, strict validation, text alignment, or six-lane checks.\n",
    );
    out.push_str("- Dynamic modifiers must stay on the scripted_effect/custom_effect_tooltip/temp-variable path, not national spirits.\n");
    out.push_str(
        "- Preserve every user-provided title and prose line; rerun text alignment after repair.\n",
    );
    out.push_str("\n## Retrieval Queries\n\n");
    for query in queries.iter().take(30) {
        out.push_str(&format!("- `{}`\n", query.replace('`', "'")));
    }
    out.push_str("\n## Rerun Commands\n\n");
    out.push_str(&format!(
        "- `hoi4skill large-mod-build-acceptance --mod-root {} --require-six-lanes --require-ready --require-final-validation --write-repair-context --fail-on-blockers`\n",
        mod_root.display()
    ));
    out.push_str(&format!(
        "- `hoi4skill validate {} --game-root <HOI4 root> --strict-code-index --output .hoi4skill/validation.json`\n",
        mod_root.display()
    ));
    out.push_str(&format!(
        "- `hoi4skill check-text-alignment --mod-root {} --input <request-or-workbook> --output .hoi4skill/text_alignment.json`\n",
        mod_root.display()
    ));
    out
}

fn large_mod_build_acceptance_repair_manifest_json(
    mod_root: &Path,
    acceptance_report: &Path,
    output_dir: &Path,
    context_json: &Path,
    context_markdown: &Path,
    prompt_markdown: &Path,
    blockers: &[String],
    queries: &[String],
    retrieval_status: &str,
) -> String {
    let status = if retrieval_status == "ok" {
        "repair_context_ready"
    } else {
        "needs_context_evidence"
    };
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_build_acceptance_repair.v1\",\n  \"status\": {},\n  \"mod_root\": {},\n  \"acceptance_report\": {},\n  \"output_dir\": {},\n  \"retrieval_status\": {},\n  \"blocking_count\": {},\n  \"blockers\": {},\n  \"queries\": {},\n  \"artifacts\": [\n    {{\"name\": \"retrieved_context_json\", \"path\": {}}},\n    {{\"name\": \"retrieved_context_markdown\", \"path\": {}}},\n    {{\"name\": \"ai_repair_prompt\", \"path\": {}}}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_str(&mod_root.display().to_string()),
        json_str(&acceptance_report.display().to_string()),
        json_str(&output_dir.display().to_string()),
        json_str(retrieval_status),
        blockers.len(),
        json_array(&blockers.to_vec()),
        json_array(&queries.to_vec()),
        json_str(&context_json.display().to_string()),
        json_str(&context_markdown.display().to_string()),
        json_str(&prompt_markdown.display().to_string()),
        json_array(&[
            "Do not repair acceptance blockers without local code evidence or explicit user evidence.".to_string(),
            "Do not bypass build acceptance by disabling strict validation, text alignment, or six-lane checks.".to_string(),
            "After AI repair, rerun build acceptance with --fail-on-blockers.".to_string(),
        ])
    )
}

