fn large_mod_acceptance_positive_counter_fields(text: &str, keys: &[&str]) -> Vec<String> {
    keys.iter()
        .filter_map(|key| match status_json_i64_field(text, key) {
            Some(value) if value > 0 => Some(format!("{key}={value}")),
            _ => None,
        })
        .collect()
}

fn large_mod_acceptance_require_schema(
    path: &Path,
    text: Option<&str>,
    expected_schema: &str,
    required: bool,
    blockers: &mut Vec<String>,
) {
    let Some(text) = text else {
        if required {
            blockers.push(format!("missing_report:{}", path.display()));
        }
        return;
    };
    if status_json_string_field(text, "schema").as_deref() != Some(expected_schema) {
        blockers.push(format!(
            "bad_schema:{}:expected:{expected_schema}",
            path.display()
        ));
    }
}

fn large_mod_author_workflow_forward_args(
    args: &[String],
    skip_value_keys: &[&str],
    skip_flag_keys: &[&str],
) -> Vec<String> {
    let skip_values = skip_value_keys.iter().copied().collect::<BTreeSet<_>>();
    let skip_flags = skip_flag_keys.iter().copied().collect::<BTreeSet<_>>();
    let mut out = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if let Some(key) = arg.strip_prefix("--") {
            let has_value = i + 1 < args.len() && !args[i + 1].starts_with("--");
            if skip_values.contains(key) {
                i += if has_value { 2 } else { 1 };
                continue;
            }
            if skip_flags.contains(key) {
                i += 1;
                continue;
            }
            out.push(arg.clone());
            if has_value {
                out.push(args[i + 1].clone());
                i += 2;
            } else {
                i += 1;
            }
        } else {
            out.push(arg.clone());
            i += 1;
        }
    }
    out
}

fn large_mod_author_workflow_report(
    mod_root: &Path,
    author_output: &Path,
    gate_output: &Path,
    gate_markdown: &Path,
    author_error: Option<&str>,
    gate_error: Option<&str>,
) -> String {
    let author_text = read_utf8_lossy(author_output).ok();
    let gate_text = read_utf8_lossy(gate_output).ok();
    let author_status = author_text
        .as_deref()
        .and_then(|text| status_json_string_field(text, "status"));
    let gate_status = gate_text
        .as_deref()
        .and_then(|text| status_json_string_field(text, "status"));
    let semiauto_ready = gate_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "semiauto_ready", true));
    let six_lane_ready = author_text.as_deref().is_some_and(|text| {
        status_json_bool_field_has_value(text, "six_lane_dispatch_ready", true)
    });
    let status = if author_error.is_some() {
        "author_failed"
    } else if gate_error.is_some() {
        "gate_failed"
    } else if semiauto_ready {
        "semiauto_ready"
    } else {
        "needs_repair"
    };
    let artifacts = vec![
        author_output.display().to_string(),
        gate_output.display().to_string(),
        gate_markdown.display().to_string(),
        mod_root
            .join(".hoi4skill")
            .join("input_repair_queue.json")
            .display()
            .to_string(),
        mod_root
            .join(".hoi4skill")
            .join("execution_queue.json")
            .display()
            .to_string(),
    ];
    let next_commands = vec![
        format!(
            "hoi4skill large-mod-semi-auto-gate --mod-root {} --output {} --markdown-output {}",
            mod_root.display(),
            gate_output.display(),
            gate_markdown.display()
        ),
        format!(
            "hoi4skill run-work-packages --mod-root {} --ready-only --max-packages 4 --output .hoi4skill/run_queue.json",
            mod_root.display()
        ),
        format!(
            "hoi4skill large-mod-input-repair-queue --mod-root {} --output .hoi4skill/input_repair_queue.json",
            mod_root.display()
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_author_workflow.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"mod_root\": {},\n  \"supported_input_modes\": {},\n  \"required_content_lanes\": {},\n  \"six_lane_dispatch_ready\": {},\n  \"semiauto_ready\": {},\n  \"author_status\": {},\n  \"gate_status\": {},\n  \"author_report\": {},\n  \"semiauto_gate_report\": {},\n  \"semiauto_gate_markdown\": {},\n  \"delivery_artifacts\": {},\n  \"author_error\": {},\n  \"gate_error\": {},\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(author_error.is_none() && gate_error.is_none()),
        json_str(&mod_root.display().to_string()),
        json_array(&[
            "plain_text".to_string(),
            "docx_word".to_string(),
            "xlsx_excel".to_string(),
            "csv_table".to_string(),
            "input_directory".to_string(),
            "multi_file_bundle".to_string()
        ]),
        json_array(&large_mod_content_family_ids()),
        json_bool(six_lane_ready),
        json_bool(semiauto_ready),
        json_optional_str(author_status.as_deref()),
        json_optional_str(gate_status.as_deref()),
        json_str(&author_output.display().to_string()),
        json_str(&gate_output.display().to_string()),
        json_str(&gate_markdown.display().to_string()),
        json_array(&artifacts),
        json_optional_str(author_error),
        json_optional_str(gate_error),
        json_array(&next_commands),
        json_array(&[
            "Do not run large-mod batch execution until semiauto_ready is true or the input_repair_queue has been handled.".to_string(),
            "Word, Excel, CSV, and plain-text requests must preserve user-visible titles and localisation text through text-alignment validation.".to_string(),
            "Every generated package must keep changed-file evidence before strict validation or repair bundle application.".to_string()
        ])
    )
}

