pub(crate) fn cmd_author_intent_workflow(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    let game_root = author_intent_workflow_game_root(&map)?;
    let hoi4skill_dir = mod_root.join(".hoi4skill");
    fs::create_dir_all(&hoi4skill_dir)
        .map_err(|e| format!("create {}: {e}", hoi4skill_dir.display()))?;

    let output = workflow_output_path(&map, &mod_root, "output", "author_intent_workflow.json")?;
    let author_output = workflow_output_path(
        &map,
        &mod_root,
        "author-output",
        "author_intent_workflow_author.json",
    )?;
    let evidence_output = workflow_output_path(
        &map,
        &mod_root,
        "evidence-output",
        "author_intent_workflow_evidence.json",
    )?;
    let changed_output = workflow_output_path(
        &map,
        &mod_root,
        "changed-output",
        "author_intent_workflow_changed.txt",
    )?;
    let baseline_output = workflow_output_path(
        &map,
        &mod_root,
        "baseline-output",
        "validation_baseline.json",
    )?;
    let repair_context_output = workflow_output_path(
        &map,
        &mod_root,
        "repair-context-output",
        "author_intent_workflow_repair_context.json",
    )?;
    let repair_context_markdown = workflow_output_path(
        &map,
        &mod_root,
        "repair-context-markdown-output",
        "author_intent_workflow_repair_context.md",
    )?;
    let repair_bundle_output = workflow_output_path(
        &map,
        &mod_root,
        "repair-bundle-output",
        "author_intent_workflow_repair_bundle.json",
    )?;
    let repair_bundle_dir = workflow_output_path(
        &map,
        &mod_root,
        "repair-bundle-output-dir",
        "author_intent_workflow_repair_bundle",
    )?;
    let retrieved_context_output = workflow_output_path(
        &map,
        &mod_root,
        "retrieved-context-output",
        "author_intent_workflow_retrieved_code_context.json",
    )?;
    let retrieved_context_markdown = workflow_output_path(
        &map,
        &mod_root,
        "retrieved-context-markdown-output",
        "author_intent_workflow_retrieved_code_context.md",
    )?;
    let request_text_source = workflow_request_text_source(&map, &mod_root)?;

    let mut baseline_args = vec![
        mod_root.display().to_string(),
        "--game-root".to_string(),
        game_root.display().to_string(),
        "--strict-code-index".to_string(),
        "--output".to_string(),
        baseline_output.display().to_string(),
    ];
    append_validation_dependency_args(&map, &mut baseline_args);
    let baseline_result = cmd_validation_baseline(&baseline_args);

    let author_run = if baseline_result.is_ok() {
        run_author_intent_workflow_authoring(args, &map, &mod_root, &game_root, &author_output)
    } else {
        AuthorIntentWorkflowRun {
            changed_files: Vec::new(),
            result: Err(
                "author-intent workflow skipped write because validation baseline failed"
                    .to_string(),
            ),
        }
    };
    let author_result = author_run.result;

    let mut changed_files = author_run.changed_files;
    if author_result.is_ok() {
        changed_files.sort();
        changed_files.dedup();
        write_author_intent_workflow_changed_file(&changed_output, &changed_files)?;
    }

    let evidence_result = if author_result.is_ok() && !changed_files.is_empty() {
        let mut evidence_args = vec![
            "--mod-root".to_string(),
            mod_root.display().to_string(),
            "--game-root".to_string(),
            game_root.display().to_string(),
            "--changed-file".to_string(),
            changed_output.display().to_string(),
            "--output".to_string(),
            evidence_output.display().to_string(),
        ];
        append_validation_dependency_args(&map, &mut evidence_args);
        append_author_intent_workflow_text_alignment_args(
            &map,
            request_text_source.as_deref(),
            &mut evidence_args,
        );
        if map.flags.contains("skip-audits") {
            evidence_args.push("--skip-audits".to_string());
        }
        cmd_large_mod_production_evidence_refresh(&evidence_args)
    } else if author_result.is_ok() {
        Err("author-intent workflow produced no changed files; evidence refresh cannot prove the write".to_string())
    } else {
        Err(
            "author-intent workflow skipped evidence refresh because author-intent failed"
                .to_string(),
        )
    };
    let repair_context_result = run_author_intent_workflow_repair_context_if_needed(
        &map,
        &mod_root,
        &game_root,
        &baseline_output,
        &changed_files,
        request_text_source.as_deref(),
        &evidence_output,
        evidence_result.as_ref().err().map(String::as_str),
        &repair_context_output,
        &repair_context_markdown,
    );
    let repair_bundle_result = run_author_intent_workflow_repair_bundle_if_needed(
        &map,
        &mod_root,
        &game_root,
        &baseline_output,
        &changed_output,
        &changed_files,
        request_text_source.as_deref(),
        &evidence_output,
        evidence_result.as_ref().err().map(String::as_str),
        &repair_context_output,
        &repair_context_markdown,
        &repair_bundle_output,
        &repair_bundle_dir,
    );
    let retrieved_context_result = run_author_intent_workflow_retrieved_context_if_needed(
        &map,
        &mod_root,
        &game_root,
        request_text_source.as_deref(),
        &author_output,
        author_result.as_ref().err().map(String::as_str),
        &retrieved_context_output,
        &retrieved_context_markdown,
    );

    let report = author_intent_workflow_report(
        &mod_root,
        &game_root,
        &baseline_output,
        &author_output,
        &evidence_output,
        &changed_output,
        &repair_context_output,
        &repair_context_markdown,
        &repair_bundle_output,
        &repair_bundle_dir,
        &retrieved_context_output,
        &retrieved_context_markdown,
        &changed_files,
        baseline_result.as_ref().err().map(String::as_str),
        author_result.as_ref().err().map(String::as_str),
        evidence_result.as_ref().err().map(String::as_str),
        repair_context_result.as_ref().err().map(String::as_str),
        repair_bundle_result.as_ref().err().map(String::as_str),
        retrieved_context_result.as_ref().err().map(String::as_str),
    );
    write_or_print(&report, Some(&output.display().to_string()))?;

    let status =
        status_json_string_field(&report, "status").unwrap_or_else(|| "failed".to_string());
    if matches!(
        status.as_str(),
        "release_ready" | "semiauto_ready" | "written_validated"
    ) {
        Ok(())
    } else {
        Err(format!("author-intent workflow blocked: {status}"))
    }
}

fn author_intent_workflow_game_root(map: &ArgMap) -> Result<PathBuf, String> {
    if let Some(path) = value(map, "game-root").or_else(|| value(map, "hoi4-path")) {
        return normalize_path(path);
    }
    detect_selected_hoi4_path(&[]).ok_or_else(|| {
        "author-intent-workflow requires --game-root <Hearts of Iron IV> because detect-hoi4-path found no valid selected path".to_string()
    })
}

