pub(crate) fn cmd_large_mod_capability_audit(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    let blueprint_path = large_mod_blueprint_path_from_args(&map, Some(&mod_root))?;
    let blueprint = read_large_mod_blueprint(&blueprint_path)?;
    let packages = split_large_mod_work_packages(&blueprint);
    let selected_package = value(&map, "package");
    let selected = packages
        .iter()
        .filter(|package| selected_package.map(|id| id == package.id).unwrap_or(true))
        .collect::<Vec<_>>();
    if selected.is_empty() {
        return Err(format!(
            "unknown work package `{}`",
            selected_package.unwrap_or("<missing>")
        ));
    }
    let json = large_mod_capability_audit_json(
        &blueprint,
        &packages,
        &selected,
        &blueprint_path,
        &mod_root,
        map.flags.contains("require-style-context"),
    )?;
    let output = value(&map, "output")
        .map(str::to_string)
        .unwrap_or_else(|| {
            mod_root
                .join(".hoi4skill")
                .join("capability_audit.json")
                .display()
                .to_string()
        });
    write_or_print(&json, Some(&output))
}

