pub(crate) fn cmd_large_mod_ai_output_insurance(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    let source = large_mod_source_text(&map)?;
    let Some(package_id) = value(&map, "package") else {
        return cmd_generic_ai_output_insurance(&map, &mod_root, &source);
    };
    let blueprint_path = large_mod_blueprint_path_from_args(&map, Some(&mod_root))?;
    let blueprint = read_large_mod_blueprint(&blueprint_path)?;
    let packages = split_large_mod_work_packages(&blueprint);
    let package = packages
        .iter()
        .find(|package| package.id == package_id)
        .ok_or_else(|| format!("unknown work package `{package_id}`"))?;
    let queries = ai_output_insurance_queries(package, &source, &map);
    let payload = build_work_package_run_retrieved_repair_context(
        package,
        &mod_root,
        value(&map, "game-root"),
        &queries,
        &map,
    );
    let markdown = large_mod_ai_output_insurance_markdown(
        &blueprint,
        package,
        &mod_root,
        value(&map, "game-root"),
        &source,
        &payload,
    );
    let markdown_output = value(&map, "markdown-output")
        .map(str::to_string)
        .unwrap_or_else(|| {
            mod_root
                .join(".hoi4skill")
                .join(format!("ai_output_insurance_{}.md", package.id))
                .display()
                .to_string()
        });
    write_or_print(&markdown, Some(&markdown_output))?;
    let json = large_mod_ai_output_insurance_json(
        &blueprint,
        package,
        &mod_root,
        value(&map, "game-root"),
        &source,
        &queries,
        &payload,
    );
    let output = value(&map, "output")
        .map(str::to_string)
        .unwrap_or_else(|| {
            mod_root
                .join(".hoi4skill")
                .join(format!("ai_output_insurance_{}.json", package.id))
                .display()
                .to_string()
        });
    write_or_print(&json, Some(&output))
}

fn cmd_generic_ai_output_insurance(
    map: &ArgMap,
    mod_root: &Path,
    source: &str,
) -> Result<(), String> {
    let game_root = value(map, "game-root")
        .map(normalize_path)
        .transpose()?
        .ok_or_else(|| {
            "large-mod-ai-output-insurance without --package requires --game-root".to_string()
        })?;
    let dependency_mods = dependency_mod_roots_for_optional_edited_mod(map, Some(mod_root), true)?;
    let index = build_game_index_with_mod_paths(&game_root, &dependency_mods)?;
    let findings = generic_ai_output_findings(source, &index);
    let ok = findings.is_empty();
    let json = generic_ai_output_insurance_json(
        mod_root,
        &game_root,
        &dependency_mods,
        source,
        &findings,
        ok,
    );
    if let Some(markdown_output) = value(map, "markdown-output") {
        let markdown = generic_ai_output_insurance_markdown(&findings, ok);
        write_or_print(&markdown, Some(markdown_output))?;
    }
    write_or_print(&json, value(map, "output"))?;
    if map.flags.contains("require-passed") && !ok {
        return Err(
            "AI output insurance found unknown symbols or scope/container errors".to_string(),
        );
    }
    Ok(())
}

#[derive(Clone)]
struct GenericAiOutputFinding {
    line: usize,
    kind: String,
    token: String,
    message: String,
    candidates: Vec<String>,
}

fn generic_ai_output_findings(source: &str, index: &GameIndex) -> Vec<GenericAiOutputFinding> {
    let mut findings = Vec::new();
    let mut seen = BTreeSet::new();
    let lower_source = source.to_ascii_lowercase();
    for (line_index, line) in source.lines().enumerate() {
        let line_no = line_index + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        if let Some(token) = clausewitz_lhs_token(trimmed) {
            if !generic_ai_known_container_key(&token)
                && !generic_ai_symbol_registered(&token, index)
                && generic_ai_symbol_like(&token)
            {
                let kind = generic_ai_expected_kind(trimmed, &lower_source);
                let candidates = generic_ai_nearest_candidates(&token, kind, index, 5);
                push_generic_ai_finding(
                    &mut findings,
                    &mut seen,
                    GenericAiOutputFinding {
                        line: line_no,
                        kind: format!("unknown_{kind}"),
                        token: token.clone(),
                        message: format!(
                            "`{token}` is not registered in the local game/dependency/target code index"
                        ),
                        candidates,
                    },
                );
            }
            if generic_ai_modifier_wrong_scope(&token, &lower_source) {
                push_generic_ai_finding(
                    &mut findings,
                    &mut seen,
                    GenericAiOutputFinding {
                        line: line_no,
                        kind: "scope_error".to_string(),
                        token: token.clone(),
                        message: format!(
                            "`{token}` looks like a MIO/state/province scoped modifier and cannot be used as tag-wide national-spirit code without scope evidence"
                        ),
                        candidates: generic_ai_nearest_candidates(&token, "modifier", index, 5),
                    },
                );
            }
        }
        for token in generic_ai_line_tokens(trimmed) {
            if generic_ai_modifier_wrong_scope(&token, &lower_source) {
                push_generic_ai_finding(
                    &mut findings,
                    &mut seen,
                    GenericAiOutputFinding {
                        line: line_no,
                        kind: "scope_error".to_string(),
                        token: token.clone(),
                        message: format!(
                            "`{token}` looks like a MIO/state/province scoped modifier and cannot be used as tag-wide national-spirit code without scope evidence"
                        ),
                        candidates: generic_ai_nearest_candidates(&token, "modifier", index, 5),
                    },
                );
            } else if generic_ai_symbol_like(&token)
                && !generic_ai_known_container_key(&token)
                && !generic_ai_symbol_registered(&token, index)
            {
                let kind = generic_ai_expected_kind(&token, &lower_source);
                push_generic_ai_finding(
                    &mut findings,
                    &mut seen,
                    GenericAiOutputFinding {
                        line: line_no,
                        kind: format!("unknown_{kind}"),
                        token: token.clone(),
                        message: format!(
                            "`{token}` is not registered in the local game/dependency/target code index"
                        ),
                        candidates: generic_ai_nearest_candidates(&token, kind, index, 5),
                    },
                );
            }
        }
        if generic_ai_container_pollution(trimmed, &lower_source) {
            push_generic_ai_finding(
                &mut findings,
                &mut seen,
                GenericAiOutputFinding {
                    line: line_no,
                    kind: "container_error".to_string(),
                    token: trimmed.to_string(),
                    message:
                        "GUI/GFX/localisation-looking content appears inside gameplay effect output"
                            .to_string(),
                    candidates: Vec::new(),
                },
            );
        }
    }
    findings
}

fn push_generic_ai_finding(
    findings: &mut Vec<GenericAiOutputFinding>,
    seen: &mut BTreeSet<String>,
    finding: GenericAiOutputFinding,
) {
    let key = format!("{}:{}:{}", finding.line, finding.kind, finding.token);
    if seen.insert(key) {
        findings.push(finding);
    }
}

fn generic_ai_line_tokens(line: &str) -> Vec<String> {
    line.split(|ch: char| !(ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' || ch == '.'))
        .filter(|token| !token.is_empty())
        .map(str::to_string)
        .collect()
}

fn clausewitz_lhs_token(line: &str) -> Option<String> {
    let (lhs, _) = line.split_once('=')?;
    let token = lhs.trim();
    if token.is_empty() {
        return None;
    }
    if token
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' || ch == '.')
    {
        Some(token.to_string())
    } else {
        None
    }
}

fn generic_ai_known_container_key(token: &str) -> bool {
    matches!(
        token,
        "id" | "title"
            | "desc"
            | "picture"
            | "major"
            | "is_triggered_only"
            | "trigger"
            | "immediate"
            | "option"
            | "name"
            | "ai_chance"
            | "hidden_effect"
            | "completion_reward"
            | "available"
            | "visible"
            | "cancel_trigger"
            | "modifier"
            | "national_spirit"
            | "idea"
            | "ideas"
            | "allowed"
            | "limit"
            | "if"
            | "else"
            | "else_if"
            | "ROOT"
            | "PREV"
            | "FROM"
    )
}

fn generic_ai_symbol_like(token: &str) -> bool {
    if token.parse::<f64>().is_ok() {
        return false;
    }
    token.contains('_')
        || token.contains('.')
        || token.starts_with("add")
        || token.starts_with("set")
        || token.starts_with("remove")
        || token.starts_with("has")
}

fn generic_ai_symbol_registered(token: &str, index: &GameIndex) -> bool {
    index.effects.contains(token)
        || index.triggers.contains(token)
        || index.modifiers.contains(token)
        || index.dynamic_modifiers.contains(token)
        || index.sprites.contains(token)
        || index.ideas.contains(token)
        || index.country_tags.contains(token)
        || index.technologies.contains(token)
}

fn generic_ai_expected_kind(line: &str, source_lower: &str) -> &'static str {
    let lower = line.to_ascii_lowercase();
    if line.starts_with("GFX_") {
        "sprite"
    } else if source_lower.contains("modifier")
        || lower.contains("factor")
        || lower.contains("gain")
    {
        "modifier"
    } else if source_lower.contains("trigger") || source_lower.contains("limit") {
        "trigger"
    } else {
        "effect"
    }
}

fn generic_ai_modifier_wrong_scope(token: &str, source_lower: &str) -> bool {
    let looks_wrong_scope = token.starts_with("mio")
        || token.contains("_mio_")
        || token.starts_with("state_")
        || token.starts_with("province_")
        || token.contains("_state_")
        || token.contains("_province_");
    looks_wrong_scope
        && (source_lower.contains("national_spirit")
            || source_lower.contains("common/ideas")
            || source_lower.contains("add_ideas")
            || source_lower.contains("民族精神"))
}

fn generic_ai_container_pollution(line: &str, source_lower: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    let looks_visual_or_loc = lower.contains("spritetype")
        || line.contains("GFX_")
        || lower.contains("localisation")
        || lower.contains("l_simp_chinese:")
        || lower.contains("_desc:");
    looks_visual_or_loc
        && (source_lower.contains("completion_reward")
            || source_lower.contains("effect")
            || source_lower.contains("效果"))
}

fn generic_ai_nearest_candidates(
    token: &str,
    kind: &str,
    index: &GameIndex,
    limit: usize,
) -> Vec<String> {
    let catalog = match kind {
        "trigger" => &index.triggers,
        "modifier" => &index.modifiers,
        "dynamic_modifier" => &index.dynamic_modifiers,
        "sprite" => &index.sprites,
        _ => &index.effects,
    };
    let mut scored = catalog
        .iter()
        .map(|candidate| (generic_ai_levenshtein(token, candidate), candidate.clone()))
        .collect::<Vec<_>>();
    scored.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
    scored
        .into_iter()
        .take(limit)
        .filter(|(distance, _)| *distance <= token.len().max(8))
        .map(|(_, candidate)| candidate)
        .collect()
}

fn generic_ai_levenshtein(a: &str, b: &str) -> usize {
    let mut costs = (0..=b.len()).collect::<Vec<_>>();
    for (i, ca) in a.chars().enumerate() {
        let mut last = i;
        costs[0] = i + 1;
        for (j, cb) in b.chars().enumerate() {
            let old = costs[j + 1];
            costs[j + 1] = if ca == cb {
                last
            } else {
                1 + last.min(old).min(costs[j])
            };
            last = old;
        }
    }
    costs[b.len()]
}

fn generic_ai_output_insurance_json(
    mod_root: &Path,
    game_root: &Path,
    dependency_mods: &[PathBuf],
    source: &str,
    findings: &[GenericAiOutputFinding],
    ok: bool,
) -> String {
    let mut map = BTreeMap::new();
    map.insert(
        "schema".to_string(),
        json_str("hoi4skill.generic_ai_output_insurance.v1"),
    );
    map.insert("ok".to_string(), json_bool(ok).to_string());
    map.insert(
        "status".to_string(),
        json_str(if ok {
            "ai_output_indexed"
        } else {
            "repair_context_required"
        }),
    );
    map.insert(
        "mod_root".to_string(),
        json_str(&mod_root.display().to_string()),
    );
    map.insert(
        "game_root".to_string(),
        json_str(&game_root.display().to_string()),
    );
    map.insert(
        "dependency_mods".to_string(),
        json_array(
            &dependency_mods
                .iter()
                .map(|path| path.display().to_string())
                .collect::<Vec<_>>(),
        ),
    );
    map.insert(
        "source_line_count".to_string(),
        source.lines().count().to_string(),
    );
    map.insert("finding_count".to_string(), findings.len().to_string());
    map.insert("findings".to_string(), generic_ai_findings_json(findings));
    map.insert(
        "rules".to_string(),
        json_array(&[
            "unknown trigger, effect, modifier, sprite, tag, or technology is a hard error".to_string(),
            "MIO/state/province scoped modifiers cannot be used as tag-wide national-spirit effects without indexed scope evidence".to_string(),
            "GUI, GFX, and localisation text cannot be assembled inside gameplay effect containers".to_string(),
            "repair context may use indexed candidates and summaries only, not official code snippets".to_string(),
        ]),
    );
    map.insert(
        "next_commands".to_string(),
        json_array(&[
            "fix the AI output by choosing indexed candidates or asking the user for missing registration".to_string(),
            "rerun large-mod-ai-output-insurance --require-passed".to_string(),
            "rerun validate --strict-code-index after writing any repaired patch".to_string(),
        ]),
    );
    json_raw_object(&map)
}

fn generic_ai_findings_json(findings: &[GenericAiOutputFinding]) -> String {
    format!(
        "[{}]",
        findings
            .iter()
            .map(|finding| {
                let mut map = BTreeMap::new();
                map.insert("line".to_string(), finding.line.to_string());
                map.insert("kind".to_string(), json_str(&finding.kind));
                map.insert("token".to_string(), json_str(&finding.token));
                map.insert("message".to_string(), json_str(&finding.message));
                map.insert("candidates".to_string(), json_array(&finding.candidates));
                json_raw_object(&map)
            })
            .collect::<Vec<_>>()
            .join(", ")
    )
}

fn generic_ai_output_insurance_markdown(findings: &[GenericAiOutputFinding], ok: bool) -> String {
    let mut out = String::new();
    out.push_str("# AI Output Insurance\n\n");
    out.push_str(&format!("- ok: `{}`\n", ok));
    out.push_str(&format!("- finding_count: `{}`\n\n", findings.len()));
    if findings.is_empty() {
        out.push_str("No unknown symbols or scope/container errors were detected.\n");
        return out;
    }
    for finding in findings {
        out.push_str(&format!(
            "- line {} `{}`: {}\n",
            finding.line, finding.kind, finding.message
        ));
        if !finding.candidates.is_empty() {
            out.push_str(&format!(
                "  candidates: `{}`\n",
                finding.candidates.join("`, `")
            ));
        }
    }
    out
}

pub(crate) fn cmd_large_mod_country_dry_run(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    let package_id = require_value(&map, "package")?;
    let blueprint_path = large_mod_blueprint_path_from_args(&map, Some(&mod_root))?;
    let blueprint = read_large_mod_blueprint(&blueprint_path)?;
    let packages = split_large_mod_work_packages(&blueprint);
    let package = packages
        .iter()
        .find(|package| package.id == package_id)
        .ok_or_else(|| format!("unknown work package `{package_id}`"))?;
    if package.kind != "country" {
        return Err(format!(
            "large-mod-country-dry-run requires a country package, got `{}` ({})",
            package.id, package.kind
        ));
    }
    let output_dir = value(&map, "output-dir")
        .map(normalize_path)
        .transpose()?
        .unwrap_or_else(|| {
            mod_root
                .join(".hoi4skill")
                .join("work_package_runs")
                .join(&package.id)
        });
    let request = value(&map, "request").unwrap_or(
        "生成一个完整国家包 dry-run：国策、事件链、决议、民族精神、动态修正、本地化全部具备，并保留严格校验保险。",
    );
    let mut run_args = vec![
        "--mod-root".to_string(),
        mod_root.display().to_string(),
        "--package".to_string(),
        package.id.clone(),
        "--request".to_string(),
        request.to_string(),
        "--output-dir".to_string(),
        output_dir.display().to_string(),
        "--output".to_string(),
        output_dir.join("run.json").display().to_string(),
    ];
    if let Some(game_root) = value(&map, "game-root") {
        run_args.push("--game-root".to_string());
        run_args.push(game_root.to_string());
    }
    for style_mod in repeated_values(&map, "style-mod") {
        run_args.push("--style-mod".to_string());
        run_args.push(style_mod.to_string());
    }
    cmd_run_work_package(&run_args)?;
    let style_mods = repeated_values(&map, "style-mod")
        .iter()
        .map(|value| value.to_string())
        .collect::<Vec<_>>();
    if !style_mods.is_empty() {
        let mut style_args = Vec::new();
        for style_mod in &style_mods {
            style_args.push("--style-mod".to_string());
            style_args.push(style_mod.clone());
        }
        style_args.extend([
            "--language".to_string(),
            "all".to_string(),
            "--template".to_string(),
            "auto".to_string(),
            "--output".to_string(),
            output_dir
                .join("inputs")
                .join("style_context.md")
                .display()
                .to_string(),
        ]);
        cmd_work_package_style_context(&style_args)?;
    }
    write_large_mod_country_dry_run_inputs(package, &blueprint, &output_dir)?;
    let capability_path = mod_root
        .join(".hoi4skill")
        .join(format!("capability_{}.json", package.id));
    let mut audit_args = vec![
        "--mod-root".to_string(),
        mod_root.display().to_string(),
        "--package".to_string(),
        package.id.clone(),
        "--output".to_string(),
        capability_path.display().to_string(),
    ];
    if !repeated_values(&map, "style-mod").is_empty() {
        audit_args.push("--require-style-context".to_string());
    }
    cmd_large_mod_capability_audit(&audit_args)?;
    let report = large_mod_country_dry_run_json(
        &blueprint,
        package,
        &mod_root,
        &output_dir,
        &capability_path,
        value(&map, "game-root"),
        &style_mods,
    );
    let output = value(&map, "output")
        .map(str::to_string)
        .unwrap_or_else(|| {
            mod_root
                .join(".hoi4skill")
                .join(format!("country_dry_run_{}.json", package.id))
                .display()
                .to_string()
        });
    write_or_print(&report, Some(&output))
}

pub(crate) fn cmd_large_mod_sample_acceptance(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    let package_id = require_value(&map, "package")?;
    let blueprint_path = large_mod_blueprint_path_from_args(&map, Some(&mod_root))?;
    let blueprint = read_large_mod_blueprint(&blueprint_path)?;
    let packages = split_large_mod_work_packages(&blueprint);
    let package = packages
        .iter()
        .find(|package| package.id == package_id)
        .ok_or_else(|| format!("unknown work package `{package_id}`"))?;
    if package.kind != "country" {
        return Err(format!(
            "large-mod-sample-acceptance requires a country package, got `{}` ({})",
            package.id, package.kind
        ));
    }
    let output_dir = value(&map, "output-dir")
        .map(normalize_path)
        .transpose()?
        .unwrap_or_else(|| {
            mod_root
                .join(".hoi4skill")
                .join("work_package_runs")
                .join(&package.id)
        });
    let dry_run_path = mod_root
        .join(".hoi4skill")
        .join(format!("country_dry_run_{}.json", package.id));
    let mut dry_args = vec![
        "--mod-root".to_string(),
        mod_root.display().to_string(),
        "--package".to_string(),
        package.id.clone(),
        "--output-dir".to_string(),
        output_dir.display().to_string(),
        "--output".to_string(),
        dry_run_path.display().to_string(),
    ];
    if let Some(game_root) = value(&map, "game-root") {
        dry_args.push("--game-root".to_string());
        dry_args.push(game_root.to_string());
    }
    for style_mod in repeated_values(&map, "style-mod") {
        dry_args.push("--style-mod".to_string());
        dry_args.push(style_mod.to_string());
    }
    cmd_large_mod_country_dry_run(&dry_args)?;
    let mut execution_error = None;
    if map.flags.contains("execute") {
        let Some(game_root) = value(&map, "game-root") else {
            return Err("large-mod-sample-acceptance --execute requires --game-root".to_string());
        };
        let mut run_args = vec![
            "--mod-root".to_string(),
            mod_root.display().to_string(),
            "--package".to_string(),
            package.id.clone(),
            "--game-root".to_string(),
            game_root.to_string(),
            "--output-dir".to_string(),
            output_dir.display().to_string(),
            "--execute".to_string(),
            "--allow-blocked".to_string(),
            "--allow-failure".to_string(),
        ];
        for mod_path in repeated_values(&map, "mod-path") {
            run_args.push("--mod-path".to_string());
            run_args.push(mod_path.to_string());
        }
        for style_mod in repeated_values(&map, "style-mod") {
            run_args.push("--style-mod".to_string());
            run_args.push(style_mod.to_string());
        }
        if let Err(err) = cmd_run_work_package(&run_args) {
            execution_error = Some(err);
        }
    }
    let content_audit_path = mod_root
        .join(".hoi4skill")
        .join(format!("content_{}.json", package.id));
    let content_args = vec![
        "--mod-root".to_string(),
        mod_root.display().to_string(),
        "--package".to_string(),
        package.id.clone(),
        "--output".to_string(),
        content_audit_path.display().to_string(),
    ];
    cmd_large_mod_content_audit(&content_args)?;
    let execution_report = output_dir.join("execution_report.json");
    let check_written = map.flags.contains("check-written")
        || map.flags.contains("accept-written")
        || map.flags.contains("written-content");
    let execution_status = if check_written && !execution_report.exists() {
        "written_content_checked".to_string()
    } else {
        top_status_from_optional_report(&execution_report)?
    };
    let content_text = read_utf8_lossy(&content_audit_path)?;
    let content_ready = status_json_bool_field_has_value(&content_text, "content_ready", true);
    let content_family_matrix = large_mod_sample_content_family_matrix_json(&content_text);
    let six_content_families_ok = large_mod_sample_content_families_ok(&content_text);
    let report = large_mod_sample_acceptance_json(
        &blueprint,
        package,
        &mod_root,
        &output_dir,
        &dry_run_path,
        &execution_report,
        &content_audit_path,
        &execution_status,
        content_ready,
        six_content_families_ok,
        &content_family_matrix,
        map.flags.contains("execute"),
        check_written,
        execution_error.as_deref(),
        value(&map, "game-root"),
    );
    let output = value(&map, "output")
        .map(str::to_string)
        .unwrap_or_else(|| {
            mod_root
                .join(".hoi4skill")
                .join(format!("sample_acceptance_{}.json", package.id))
                .display()
                .to_string()
        });
    write_or_print(&report, Some(&output))?;
    let accepted_by_sample = ((map.flags.contains("execute") && execution_status == "ok")
        || check_written)
        && content_ready
        && six_content_families_ok
        && execution_error.is_none();
    if map.flags.contains("require-accepted") && !accepted_by_sample {
        return Err("large-mod-sample-acceptance did not accept the selected package".to_string());
    }
    Ok(())
}

pub(crate) fn cmd_large_mod_batch_acceptance(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    let blueprint_path = large_mod_blueprint_path_from_args(&map, Some(&mod_root))?;
    let blueprint = read_large_mod_blueprint(&blueprint_path)?;
    let mut packages = split_large_mod_work_packages(&blueprint)
        .into_iter()
        .filter(|package| package.kind == "country")
        .collect::<Vec<_>>();
    if let Some(package_id) = value(&map, "package") {
        packages.retain(|package| package.id == package_id);
        if packages.is_empty() {
            return Err(format!("unknown country package `{package_id}`"));
        }
    }
    packages.sort_by(|left, right| left.id.cmp(&right.id));
    let max_packages = parse_usize_option(&map, "max-packages", usize::MAX)?;
    if packages.len() > max_packages {
        packages.truncate(max_packages);
    }
    if packages.is_empty() {
        return Err("large-mod-batch-acceptance found no country packages".to_string());
    }
    let check_written = map.flags.contains("check-written")
        || map.flags.contains("accept-written")
        || map.flags.contains("written-content");
    if map.flags.contains("execute") && value(&map, "game-root").is_none() {
        return Err("large-mod-batch-acceptance --execute requires --game-root".to_string());
    }

    let report_dir = value(&map, "report-dir")
        .map(normalize_path)
        .transpose()?
        .unwrap_or_else(|| mod_root.join(".hoi4skill").join("batch_acceptance_reports"));
    fs::create_dir_all(&report_dir).map_err(|e| format!("create {}: {e}", report_dir.display()))?;

    let mut items = Vec::new();
    let mut accepted_count = 0usize;
    let mut content_ready_count = 0usize;
    let mut six_content_families_ok_count = 0usize;
    let mut execution_ok_count = 0usize;
    let mut needs_repair_count = 0usize;
    let mut execution_error_count = 0usize;
    for package in &packages {
        let output_dir = mod_root
            .join(".hoi4skill")
            .join("work_package_runs")
            .join(&package.id);
        let report_path = report_dir.join(format!("sample_acceptance_{}.json", package.id));
        let mut sample_args = vec![
            "--mod-root".to_string(),
            mod_root.display().to_string(),
            "--package".to_string(),
            package.id.clone(),
            "--output-dir".to_string(),
            output_dir.display().to_string(),
            "--output".to_string(),
            report_path.display().to_string(),
        ];
        if map.flags.contains("execute") {
            sample_args.push("--execute".to_string());
        }
        if check_written {
            sample_args.push("--check-written".to_string());
        }
        if let Some(game_root) = value(&map, "game-root") {
            sample_args.push("--game-root".to_string());
            sample_args.push(game_root.to_string());
        }
        for mod_path in repeated_values(&map, "mod-path") {
            sample_args.push("--mod-path".to_string());
            sample_args.push(mod_path.to_string());
        }
        for style_mod in repeated_values(&map, "style-mod") {
            sample_args.push("--style-mod".to_string());
            sample_args.push(style_mod.to_string());
        }

        let execution_error = cmd_large_mod_sample_acceptance(&sample_args).err();
        if execution_error.is_some() {
            execution_error_count += 1;
        }
        let report_text = if report_path.exists() {
            read_utf8_lossy(&report_path).unwrap_or_default()
        } else {
            String::new()
        };
        let accepted = status_json_bool_field_has_value(&report_text, "accepted", true);
        let content_ready = status_json_bool_field_has_value(&report_text, "content_ready", true);
        let six_content_families_ok =
            status_json_bool_field_has_value(&report_text, "six_content_families_ok", true);
        let execution_status = status_json_string_field(&report_text, "execution_status")
            .unwrap_or_else(|| {
                if execution_error.is_some() {
                    "failed".to_string()
                } else {
                    "missing".to_string()
                }
            });
        if accepted {
            accepted_count += 1;
        }
        if content_ready {
            content_ready_count += 1;
        }
        if six_content_families_ok {
            six_content_families_ok_count += 1;
        }
        if execution_status == "ok" {
            execution_ok_count += 1;
        } else if map.flags.contains("execute") {
            needs_repair_count += 1;
        }
        items.push(large_mod_batch_acceptance_item_json(
            package,
            &report_path,
            &output_dir,
            accepted,
            content_ready,
            six_content_families_ok,
            &execution_status,
            execution_error.as_deref(),
        ));
    }

    let selected_count = packages.len();
    let accepted = (map.flags.contains("execute") || check_written)
        && accepted_count == selected_count
        && execution_error_count == 0;
    let status = if accepted {
        "accepted"
    } else if check_written {
        "needs_content"
    } else if !map.flags.contains("execute") {
        "sample_inputs_ready"
    } else if needs_repair_count > 0 || execution_error_count > 0 {
        "needs_repair"
    } else {
        "needs_content"
    };
    let report = large_mod_batch_acceptance_json(
        &blueprint,
        &blueprint_path,
        &mod_root,
        value(&map, "game-root"),
        map.flags.contains("execute"),
        check_written,
        status,
        selected_count,
        accepted_count,
        content_ready_count,
        six_content_families_ok_count,
        execution_ok_count,
        needs_repair_count,
        execution_error_count,
        &items,
    );
    let output = value(&map, "output")
        .map(str::to_string)
        .unwrap_or_else(|| {
            mod_root
                .join(".hoi4skill")
                .join("batch_acceptance.json")
                .display()
                .to_string()
        });
    write_or_print(&report, Some(&output))?;
    if map.flags.contains("require-accepted") && status != "accepted" {
        return Err("large-mod-batch-acceptance did not accept every selected package".to_string());
    }
    Ok(())
}

pub(crate) fn cmd_large_mod_capability_smoke(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let output_dir = value(&map, "output-dir")
        .map(normalize_path)
        .transpose()?
        .unwrap_or_else(|| {
            std::env::temp_dir().join(format!(
                "hoi4skill-large-mod-capability-smoke-{}",
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|duration| duration.as_nanos())
                    .unwrap_or(0)
            ))
        });
    fs::create_dir_all(&output_dir).map_err(|e| format!("create {}: {e}", output_dir.display()))?;
    let blueprint = output_dir.join("blueprint.yml");
    let mod_root = output_dir.join("mod");
    let input_dir = output_dir.join("requests");
    let author_report = output_dir.join("large_mod_author_workflow.json");
    let acceptance_report = output_dir.join("large_mod_build_acceptance.json");
    let sources_report = mod_root
        .join(".hoi4skill")
        .join("package_request_sources.json");
    let target_mod_root = value(&map, "target-mod-root")
        .or_else(|| value(&map, "mod-root"))
        .or_else(|| value(&map, "real-mod-root"))
        .or_else(|| value(&map, "target"))
        .map(normalize_path)
        .transpose()?;
    let target_mod_exists = target_mod_root.as_deref().is_some_and(Path::is_dir);
    let target_descriptor_exists = target_mod_root
        .as_deref()
        .is_some_and(|root| root.join("descriptor.mod").exists());
    let target_profile = large_mod_capability_smoke_target_profile(target_mod_root.as_deref());
    let target_profile_required = map.flags.contains("require-kxc-target-profile")
        || map.flags.contains("require-mdard-target-profile")
        || map.flags.contains("require-large-target-profile");
    let target_mod_required = map.flags.contains("require-target-mod") || target_profile_required;
    fs::create_dir_all(&input_dir).map_err(|e| format!("create {}: {e}", input_dir.display()))?;

    let mut steps = Vec::new();
    steps.push(large_mod_capability_smoke_step_json(
        "plan_blueprint",
        &blueprint,
        cmd_plan_large_mod(&[
            "--text".to_string(),
            "name: Capability Smoke Mod\ncountries: CHI\nregions: east asia\nsystems: industrial recovery, political reform".to_string(),
            "--name".to_string(),
            "Capability Smoke Mod".to_string(),
            "--acronym".to_string(),
            "CSM".to_string(),
            "--output".to_string(),
            blueprint.display().to_string(),
        ]),
    ));
    steps.push(large_mod_capability_smoke_step_json(
        "init_large_mod",
        &mod_root,
        cmd_init_large_mod(&[
            "--blueprint".to_string(),
            blueprint.display().to_string(),
            "--output".to_string(),
            mod_root.display().to_string(),
        ]),
    ));

    let docx = input_dir.join("01_focus_spirits.docx");
    let xlsx = input_dir.join("02_events_decisions.xlsx");
    let text = input_dir.join("03_dynamic_localisation.txt");
    steps.push(large_mod_capability_smoke_step_json(
        "write_word_excel_text_inputs",
        &input_dir,
        write_large_mod_capability_smoke_inputs(&docx, &xlsx, &text),
    ));

    let mut author_args = vec![
        "--mod-root".to_string(),
        mod_root.display().to_string(),
        "--input-dir".to_string(),
        input_dir.display().to_string(),
        "--package".to_string(),
        "country_chi".to_string(),
        "--plan-only".to_string(),
        "--strict-input-sources".to_string(),
        "--request-sources-output".to_string(),
        sources_report.display().to_string(),
        "--output".to_string(),
        author_report.display().to_string(),
    ];
    if let Some(game_root) = value(&map, "game-root") {
        author_args.push("--game-root".to_string());
        author_args.push(game_root.to_string());
    }
    steps.push(large_mod_capability_smoke_step_json(
        "author_workflow",
        &author_report,
        cmd_large_mod_author_workflow(&author_args),
    ));

    let hoi4skill_dir = mod_root.join(".hoi4skill");
    let repair_report = hoi4skill_dir.join("large_mod_repair_workflow.json");
    let production_report = hoi4skill_dir.join("large_mod_production_workflow.json");
    let validation_report = hoi4skill_dir.join("validation.json");
    let text_alignment_report = hoi4skill_dir.join("text_alignment.json");
    steps.push(large_mod_capability_smoke_step_json(
        "write_clean_gate_reports",
        &hoi4skill_dir,
        write_large_mod_capability_smoke_gate_reports(
            &mod_root,
            &repair_report,
            &production_report,
            &validation_report,
            &text_alignment_report,
        ),
    ));

    let acceptance_args = vec![
        "--mod-root".to_string(),
        mod_root.display().to_string(),
        "--author-report".to_string(),
        author_report.display().to_string(),
        "--repair-report".to_string(),
        repair_report.display().to_string(),
        "--production-report".to_string(),
        production_report.display().to_string(),
        "--request-sources-report".to_string(),
        sources_report.display().to_string(),
        "--validation-report".to_string(),
        validation_report.display().to_string(),
        "--text-alignment-report".to_string(),
        text_alignment_report.display().to_string(),
        "--require-six-lanes".to_string(),
        "--require-large-mod-inputs".to_string(),
        "--require-ready".to_string(),
        "--require-final-validation".to_string(),
        "--fail-on-blockers".to_string(),
        "--output".to_string(),
        acceptance_report.display().to_string(),
    ];
    steps.push(large_mod_capability_smoke_step_json(
        "build_acceptance",
        &acceptance_report,
        cmd_large_mod_build_acceptance(&acceptance_args),
    ));

    let acceptance_text = read_utf8_lossy(&acceptance_report).ok();
    let sources_text = read_utf8_lossy(&sources_report).ok();
    let accepted = acceptance_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "ok", true));
    let has_word_input = sources_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "has_word_input", true));
    let has_excel_input = sources_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "has_excel_input", true));
    let has_plain_text_input = sources_text
        .as_deref()
        .is_some_and(|text| status_json_bool_field_has_value(text, "has_plain_text_input", true));
    let six_lane_source_coverage = sources_text.as_deref().is_some_and(|text| {
        status_json_bool_field_has_value(text, "six_lane_source_coverage", true)
    });
    let target_root_requirement_ok =
        !target_mod_required || (target_mod_exists && target_descriptor_exists);
    let target_requirement_ok =
        target_root_requirement_ok && (!target_profile_required || target_profile.ready());
    let smoke_passed = accepted
        && has_word_input
        && has_excel_input
        && has_plain_text_input
        && six_lane_source_coverage
        && target_requirement_ok
        && steps.iter().all(|step| step.contains("\"ok\": true"));
    let report = large_mod_capability_smoke_report_json(
        target_mod_root.as_deref(),
        target_mod_exists,
        target_descriptor_exists,
        &target_profile,
        target_profile_required,
        &output_dir,
        &mod_root,
        &input_dir,
        &author_report,
        &sources_report,
        &acceptance_report,
        &steps,
        smoke_passed,
        accepted,
        has_word_input,
        has_excel_input,
        has_plain_text_input,
        six_lane_source_coverage,
        target_requirement_ok,
        target_root_requirement_ok,
    );
    let output = value(&map, "output")
        .map(str::to_string)
        .unwrap_or_else(|| {
            output_dir
                .join("capability_smoke.json")
                .display()
                .to_string()
        });
    write_or_print(&report, Some(&output))?;
    if map.flags.contains("require-passed") && !smoke_passed {
        return Err("large-mod-capability-smoke did not pass".to_string());
    }
    Ok(())
}

pub(crate) fn cmd_large_mod_real_readiness_smoke(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let output_dir = value(&map, "output-dir")
        .map(normalize_path)
        .transpose()?
        .unwrap_or_else(|| {
            std::env::temp_dir().join(format!(
                "hoi4skill-large-mod-real-readiness-smoke-{}",
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|duration| duration.as_nanos())
                    .unwrap_or(0)
            ))
        });
    fs::create_dir_all(&output_dir).map_err(|e| format!("create {}: {e}", output_dir.display()))?;
    let target_mod_root = value(&map, "target-mod-root")
        .or_else(|| value(&map, "mod-root"))
        .or_else(|| value(&map, "real-mod-root"))
        .or_else(|| value(&map, "target"))
        .ok_or_else(|| "missing --target-mod-root for real readiness smoke".to_string())
        .and_then(normalize_path)?;
    let explicit_game_root = value(&map, "game-root")
        .or_else(|| value(&map, "hoi4-path"))
        .map(normalize_path)
        .transpose()?;
    let game_root_detected = explicit_game_root.is_none();
    let game_root = if let Some(root) = explicit_game_root {
        root
    } else {
        detect_selected_hoi4_path(&[]).ok_or_else(|| {
            "could not detect Hearts of Iron IV install path; rerun with --game-root <HOI4 root>"
                .to_string()
        })?
    };
    if !game_root.is_dir() {
        return Err(format!("game root does not exist: {}", game_root.display()));
    }

    let capability_dir = output_dir.join("capability");
    let capability_report = output_dir.join("capability_smoke.json");
    let validation_report = output_dir.join("validation_strict_code_index.json");
    let mut capability_args = vec![
        "--output-dir".to_string(),
        capability_dir.display().to_string(),
        "--target-mod-root".to_string(),
        target_mod_root.display().to_string(),
        "--require-target-mod".to_string(),
        "--require-kxc-target-profile".to_string(),
        "--require-passed".to_string(),
        "--game-root".to_string(),
        game_root.display().to_string(),
        "--output".to_string(),
        capability_report.display().to_string(),
    ];
    if map.flags.contains("require-mdard-target-profile") {
        capability_args.push("--require-mdard-target-profile".to_string());
    }
    let capability_result = cmd_large_mod_capability_smoke(&capability_args);
    let capability_text = read_utf8_lossy(&capability_report).unwrap_or_default();
    let capability_smoke_passed =
        status_json_bool_field_has_value(&capability_text, "smoke_passed", true);
    let target_profile_ready =
        status_json_bool_field_has_value(&capability_text, "target_profile_ready", true);

    let generated_mod_root = capability_dir.join("mod");
    let validation_result = if capability_result.is_ok() {
        cmd_validate(&[
            generated_mod_root.display().to_string(),
            "--game-root".to_string(),
            game_root.display().to_string(),
            "--strict-code-index".to_string(),
            "--output".to_string(),
            validation_report.display().to_string(),
        ])
    } else {
        Err("capability smoke failed before final validation".to_string())
    };
    let validation_text = read_utf8_lossy(&validation_report).unwrap_or_default();
    let final_validation_ok = validation_result.is_ok()
        && status_json_bool_field_has_value(&validation_text, "ok", true)
        && status_json_bool_field_has_value(&validation_text, "strict_code_index", true);
    let ok = capability_result.is_ok()
        && capability_smoke_passed
        && target_profile_ready
        && final_validation_ok;
    let report = large_mod_real_readiness_smoke_report_json(
        &output_dir,
        &target_mod_root,
        &game_root,
        game_root_detected,
        &capability_report,
        &validation_report,
        &generated_mod_root,
        capability_smoke_passed,
        target_profile_ready,
        final_validation_ok,
        capability_result.as_ref().err().map(String::as_str),
        validation_result.as_ref().err().map(String::as_str),
    );
    let output = value(&map, "output")
        .map(str::to_string)
        .unwrap_or_else(|| {
            output_dir
                .join("real_readiness_smoke.json")
                .display()
                .to_string()
        });
    write_or_print(&report, Some(&output))?;
    if let Some(markdown_output) = value(&map, "markdown-output") {
        let markdown = large_mod_real_readiness_smoke_report_markdown(
            &target_mod_root,
            &game_root,
            &capability_report,
            &validation_report,
            capability_smoke_passed,
            target_profile_ready,
            final_validation_ok,
            capability_result.as_ref().err().map(String::as_str),
            validation_result.as_ref().err().map(String::as_str),
        );
        write_or_print(&markdown, Some(markdown_output))?;
    }
    if map.flags.contains("require-passed") && !ok {
        return Err("large-mod-real-readiness-smoke did not pass".to_string());
    }
    Ok(())
}

pub(crate) fn cmd_large_mod_user_request_smoke(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let output_dir = value(&map, "output-dir")
        .map(normalize_path)
        .transpose()?
        .unwrap_or_else(|| {
            std::env::temp_dir().join(format!(
                "hoi4skill-large-mod-user-request-smoke-{}",
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|duration| duration.as_nanos())
                    .unwrap_or(0)
            ))
        });
    fs::create_dir_all(&output_dir).map_err(|e| format!("create {}: {e}", output_dir.display()))?;
    let target_mod_root = value(&map, "target-mod-root")
        .or_else(|| value(&map, "real-mod-root"))
        .or_else(|| value(&map, "target"))
        .ok_or_else(|| "missing --target-mod-root for user request smoke".to_string())
        .and_then(normalize_path)?;
    let explicit_game_root = value(&map, "game-root")
        .or_else(|| value(&map, "hoi4-path"))
        .map(normalize_path)
        .transpose()?;
    let game_root_detected = explicit_game_root.is_none();
    let game_root = explicit_game_root
        .or_else(|| detect_selected_hoi4_path(&[]))
        .ok_or_else(|| {
            "could not detect Hearts of Iron IV install path; rerun with --game-root <HOI4 root>"
                .to_string()
        })?;
    if !game_root.is_dir() {
        return Err(format!("game root does not exist: {}", game_root.display()));
    }

    let target_profile = large_mod_capability_smoke_target_profile(Some(&target_mod_root));
    let mod_root = output_dir.join("mod");
    let input_dir = output_dir.join("inputs");
    let reports_dir = output_dir.join("reports");
    fs::create_dir_all(&input_dir).map_err(|e| format!("create {}: {e}", input_dir.display()))?;
    fs::create_dir_all(&reports_dir)
        .map_err(|e| format!("create {}: {e}", reports_dir.display()))?;
    let request_text = require_value(&map, "text")?;
    let tag = require_value(&map, "tag")?;
    let generated_prefix = format!("{}_smoke", tag.to_ascii_lowercase());
    let prefix = value(&map, "prefix").unwrap_or(&generated_prefix);
    let request_input = input_dir.join("user_request.txt");
    let focus_input = input_dir.join("focus_layout.txt");
    let event_input = input_dir.join("event_cards.txt");
    let feature_input = input_dir.join("feature_cards.txt");
    let dynamic_input = input_dir.join("dynamic_modifier.txt");
    write_large_mod_user_request_smoke_inputs(
        &request_input,
        &focus_input,
        &event_input,
        &feature_input,
        &dynamic_input,
        &request_text,
        &tag,
        prefix,
    )?;

    let mut steps = Vec::new();
    steps.push(large_mod_capability_smoke_step_json(
        "init_temp_mod",
        &mod_root,
        init_large_mod_user_request_smoke_mod(&mod_root),
    ));
    let focus_report = reports_dir.join("apply_focus.json");
    steps.push(large_mod_capability_smoke_step_json(
        "apply_focus_layout_final_check",
        &focus_report,
        cmd_apply_focus_layout(&[
            "--input".to_string(),
            focus_input.display().to_string(),
            "--mod-root".to_string(),
            mod_root.display().to_string(),
            "--tag".to_string(),
            tag.to_string(),
            "--prefix".to_string(),
            prefix.to_string(),
            "--game-root".to_string(),
            game_root.display().to_string(),
            "--final-check".to_string(),
            "--output".to_string(),
            focus_report.display().to_string(),
        ]),
    ));
    let event_report = reports_dir.join("apply_events.json");
    steps.push(large_mod_capability_smoke_step_json(
        "apply_event_cards_final_check",
        &event_report,
        cmd_apply_event_cards(&[
            "--input".to_string(),
            event_input.display().to_string(),
            "--mod-root".to_string(),
            mod_root.display().to_string(),
            "--tag".to_string(),
            tag.to_string(),
            "--prefix".to_string(),
            prefix.to_string(),
            "--game-root".to_string(),
            game_root.display().to_string(),
            "--final-check".to_string(),
            "--output".to_string(),
            event_report.display().to_string(),
        ]),
    ));
    let feature_report = reports_dir.join("apply_features.json");
    steps.push(large_mod_capability_smoke_step_json(
        "apply_feature_cards_final_check",
        &feature_report,
        cmd_apply_feature_cards(&[
            "--input".to_string(),
            feature_input.display().to_string(),
            "--mod-root".to_string(),
            mod_root.display().to_string(),
            "--tag".to_string(),
            tag.to_string(),
            "--prefix".to_string(),
            prefix.to_string(),
            "--game-root".to_string(),
            game_root.display().to_string(),
            "--final-check".to_string(),
            "--output".to_string(),
            feature_report.display().to_string(),
        ]),
    ));
    let dynamic_report = reports_dir.join("dynamic_modifier_change.json");
    steps.push(large_mod_capability_smoke_step_json(
        "apply_dynamic_modifier_final_check",
        &dynamic_report,
        cmd_plan_dynamic_modifier_change(&[
            "--input".to_string(),
            dynamic_input.display().to_string(),
            "--execute".to_string(),
            "--mod-root".to_string(),
            mod_root.display().to_string(),
            "--tag".to_string(),
            tag.to_string(),
            "--prefix".to_string(),
            prefix.to_string(),
            "--game-root".to_string(),
            game_root.display().to_string(),
            "--final-check".to_string(),
            "--output".to_string(),
            dynamic_report.display().to_string(),
        ]),
    ));
    let text_alignment_report = reports_dir.join("text_alignment.json");
    steps.push(large_mod_capability_smoke_step_json(
        "check_text_alignment",
        &text_alignment_report,
        cmd_check_text_alignment(&[
            "--mod-root".to_string(),
            mod_root.display().to_string(),
            "--tag".to_string(),
            tag.to_string(),
            "--prefix".to_string(),
            prefix.to_string(),
            "--expect-title".to_string(),
            "没收资本家".to_string(),
            "--expect-title".to_string(),
            "建国宣言".to_string(),
            "--expect-title".to_string(),
            "镇压资本家".to_string(),
            "--expect-title".to_string(),
            "资本家的反抗".to_string(),
            "--expect-title".to_string(),
            "中国制造".to_string(),
            "--output".to_string(),
            text_alignment_report.display().to_string(),
        ]),
    ));
    let validation_report = reports_dir.join("validation_strict_code_index.json");
    steps.push(large_mod_capability_smoke_step_json(
        "validate_strict_code_index",
        &validation_report,
        cmd_validate(&[
            mod_root.display().to_string(),
            "--game-root".to_string(),
            game_root.display().to_string(),
            "--strict-code-index".to_string(),
            "--request".to_string(),
            request_text.clone(),
            "--output".to_string(),
            validation_report.display().to_string(),
        ]),
    ));

    let generated_profile = large_mod_capability_smoke_target_profile(Some(&mod_root));
    let final_validation_ok = read_utf8_lossy(&validation_report)
        .ok()
        .is_some_and(|text| {
            status_json_bool_field_has_value(&text, "ok", true)
                && status_json_bool_field_has_value(&text, "strict_code_index", true)
        });
    let text_alignment_ok = read_utf8_lossy(&text_alignment_report)
        .ok()
        .is_some_and(|text| status_json_bool_field_has_value(&text, "ok", true));
    let ok = target_profile.ready()
        && generated_profile.ready()
        && final_validation_ok
        && text_alignment_ok
        && steps.iter().all(|step| step.contains("\"ok\": true"));
    let report = large_mod_user_request_smoke_report_json(
        &output_dir,
        &mod_root,
        &target_mod_root,
        &game_root,
        game_root_detected,
        &tag,
        prefix,
        &request_input,
        &focus_report,
        &event_report,
        &feature_report,
        &dynamic_report,
        &text_alignment_report,
        &validation_report,
        &target_profile,
        &generated_profile,
        text_alignment_ok,
        final_validation_ok,
        &steps,
    );
    let output = value(&map, "output")
        .map(str::to_string)
        .unwrap_or_else(|| {
            output_dir
                .join("user_request_smoke.json")
                .display()
                .to_string()
        });
    write_or_print(&report, Some(&output))?;
    if map.flags.contains("require-passed") && !ok {
        return Err("large-mod-user-request-smoke did not pass".to_string());
    }
    Ok(())
}

