fn gui_one_shot_required_sidecar_status(
    output_dir: &Path,
    spec: &GuiOneShotRequiredSidecarSpec,
) -> (PathBuf, bool, String, String, bool, bool) {
    let path = output_dir.join(spec.file);
    let text = read_utf8_lossy(&path).unwrap_or_default();
    let exists = path.is_file();
    let is_markdown_sidecar = spec.schema == "markdown";
    let schema = if is_markdown_sidecar && exists {
        "markdown".to_string()
    } else {
        status_json_string_field(&text, "schema").unwrap_or_else(|| "missing".to_string())
    };
    let status = if is_markdown_sidecar && exists {
        "written".to_string()
    } else {
        top_level_json_string_field(&text, "status").unwrap_or_else(|| "missing".to_string())
    };
    let schema_ok = exists && schema == spec.schema;
    let gate_ready = match spec.id {
        "ai_context_contract" => gui_ai_context_contract_ready(&text),
        "related_code_context" => gui_related_code_context_ready(&text),
        "repair_context" => gui_repair_context_safety_ready(&text),
        _ => match spec.ready_field {
            Some("ok") => status_json_top_level_bool_field_has_value(&text, "ok", true),
            Some(field) => status_json_top_level_bool_field_has_value(&text, field, true),
            None => true,
        },
    };
    (path, exists, schema, status, schema_ok, gate_ready)
}

pub(crate) fn gui_one_shot_required_sidecar_audit_json(output_dir: &Path) -> String {
    let mut missing = Vec::new();
    let mut invalid = Vec::new();
    let mut gate_failed = Vec::new();
    let mut blocking_gate_failed = Vec::new();
    let entries = gui_one_shot_required_sidecar_specs()
        .iter()
        .map(|spec| {
            let (path, exists, schema, status, schema_ready, gate_ready) =
                gui_one_shot_required_sidecar_status(output_dir, spec);
            if !exists {
                missing.push(spec.file.to_string());
            } else if !schema_ready {
                invalid.push(spec.file.to_string());
            } else if !gate_ready {
                gate_failed.push(spec.file.to_string());
                if gui_one_shot_sidecar_gate_failure_blocks_integrity(spec.id) {
                    blocking_gate_failed.push(spec.file.to_string());
                }
            }
            format!(
                "    {{\"id\": {}, \"file\": {}, \"path\": {}, \"required_schema\": {}, \"schema\": {}, \"status\": {}, \"exists\": {}, \"schema_ready\": {}, \"gate_ready\": {}, \"ready_field\": {}}}",
                json_str(spec.id),
                json_str(spec.file),
                json_str(&path.display().to_string()),
                json_str(spec.schema),
                json_str(&schema),
                json_str(&status),
                json_bool(exists),
                json_bool(schema_ready),
                json_bool(gate_ready),
                json_optional_str(spec.ready_field),
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    format!(
        "{{\"ready\": {}, \"required_count\": {}, \"missing_count\": {}, \"invalid_count\": {}, \"gate_failed_count\": {}, \"blocking_gate_failed_count\": {}, \"missing\": {}, \"invalid\": {}, \"gate_failed\": {}, \"blocking_gate_failed\": {}, \"sidecars\": [\n{}\n  ]}}",
        json_bool(missing.is_empty() && invalid.is_empty() && blocking_gate_failed.is_empty()),
        gui_one_shot_required_sidecar_specs().len(),
        missing.len(),
        invalid.len(),
        gate_failed.len(),
        blocking_gate_failed.len(),
        json_array(&missing),
        json_array(&invalid),
        json_array(&gate_failed),
        json_array(&blocking_gate_failed),
        entries,
    )
}

fn gui_one_shot_missing_required_sidecars(output_dir: &Path) -> Vec<String> {
    let mut missing = Vec::new();
    for spec in gui_one_shot_required_sidecar_specs() {
        let (_, exists, _, _, _, _) = gui_one_shot_required_sidecar_status(output_dir, spec);
        if !exists {
            missing.push(spec.file.to_string());
        }
    }
    missing
}

pub(crate) fn gui_one_shot_invalid_required_sidecars(output_dir: &Path) -> Vec<String> {
    let mut invalid = Vec::new();
    for spec in gui_one_shot_required_sidecar_specs() {
        let (_, exists, _, _, schema_ready, gate_ready) =
            gui_one_shot_required_sidecar_status(output_dir, spec);
        if exists
            && (!schema_ready
                || !gate_ready && gui_one_shot_sidecar_gate_failure_blocks_integrity(spec.id))
        {
            invalid.push(spec.file.to_string());
        }
    }
    invalid
}

fn gui_one_shot_sidecar_gate_failure_blocks_integrity(id: &str) -> bool {
    matches!(
        id,
        "ai_context_contract" | "related_code_context" | "repair_context"
    )
}

fn gui_one_shot_blockers(
    workflow_error: Option<&str>,
    workflow_exists: bool,
    goal_ok: bool,
    generated_ready: bool,
    safe_blocked: bool,
    require_generated: bool,
    output_dir: &Path,
) -> Vec<String> {
    let mut blockers = Vec::new();
    if let Some(error) = workflow_error {
        blockers.push(format!("workflow_command_failed:{error}"));
    }
    if !workflow_exists {
        blockers.push("workflow_report_missing".to_string());
    }
    if !goal_ok {
        blockers.push("goal_gate_not_ok".to_string());
    }
    if require_generated && !generated_ready {
        blockers.push("generated_ready_required".to_string());
    }
    if !require_generated && !generated_ready && !safe_blocked {
        blockers.push("neither_generated_ready_nor_safe_blocked".to_string());
    }
    for file in gui_one_shot_missing_required_sidecars(output_dir) {
        blockers.push(format!("missing_sidecar:{file}"));
    }
    for file in gui_one_shot_invalid_required_sidecars(output_dir) {
        blockers.push(format!("invalid_sidecar:{file}"));
    }
    blockers
}

fn gui_request_workflow_code_index_roots(mod_root: &Path, style_roots: &[PathBuf]) -> Vec<PathBuf> {
    let mut roots = style_roots.to_vec();
    if !roots.iter().any(|root| root == mod_root) {
        roots.push(mod_root.to_path_buf());
    }
    roots.sort();
    roots.dedup();
    roots
}

#[derive(Clone, Debug)]
struct GuiRequestStyleTemplatePackage {
    manifest: PathBuf,
    style_tokens: PathBuf,
    control_examples: PathBuf,
    mount_examples: PathBuf,
    resource_index: PathBuf,
    visual_template_examples: Option<PathBuf>,
    source_status: String,
    source_manifest: Option<PathBuf>,
}

fn resolve_gui_request_style_template_package(
    map: &ArgMap,
    output_dir: &Path,
    style_roots: &[PathBuf],
    reports: &[LargeModGuiPatternProfile],
    tokens: &GuiStyleTemplateTokens,
) -> Result<GuiRequestStyleTemplatePackage, String> {
    fs::create_dir_all(output_dir).map_err(|e| format!("create {}: {e}", output_dir.display()))?;
    let manifest = output_dir.join("gui_style_template_package.json");
    let style_tokens_path = output_dir.join("style_tokens.json");
    let control_examples_path = output_dir.join("control_examples.json");
    let mount_examples_path = output_dir.join("mount_examples.json");
    let resource_index_path = output_dir.join("resource_index.json");
    let visual_template_examples_path = output_dir.join("visual_template_examples.json");
    if let Some(source) = value(map, "style-template-package")
        .or_else(|| value(map, "gui-style-template-package"))
        .or_else(|| value(map, "style-package"))
    {
        let source_manifest = normalize_path(source)?;
        let source = read_gui_style_template_package(&source_manifest)?;
        let source_manifest_text = read_utf8_lossy(&source_manifest)?;
        let source_parent_mods =
            status_json_string_array_values(&source_manifest_text, "parent_mods");
        let requested_style_roots = style_roots
            .iter()
            .map(|path| path.display().to_string())
            .collect::<Vec<_>>();
        if !gui_one_shot_path_sets_match(&requested_style_roots, &source_parent_mods) {
            return Err(format!(
                "style-template-package parent_mods do not match requested parent/style sources: package={} requested={}",
                json_array(&source_parent_mods),
                json_array(&requested_style_roots)
            ));
        }
        fs::write(&style_tokens_path, read_utf8_lossy(&source.style_tokens)?)
            .map_err(|e| format!("write {}: {e}", style_tokens_path.display()))?;
        fs::write(
            &control_examples_path,
            read_utf8_lossy(&source.control_examples)?,
        )
        .map_err(|e| format!("write {}: {e}", control_examples_path.display()))?;
        fs::write(
            &mount_examples_path,
            read_utf8_lossy(&source.mount_examples)?,
        )
        .map_err(|e| format!("write {}: {e}", mount_examples_path.display()))?;
        fs::write(
            &resource_index_path,
            read_utf8_lossy(&source.resource_index)?,
        )
        .map_err(|e| format!("write {}: {e}", resource_index_path.display()))?;
        if let Some(source_visual_examples) = &source.visual_template_examples {
            fs::write(
                &visual_template_examples_path,
                read_utf8_lossy(source_visual_examples)?,
            )
            .map_err(|e| format!("write {}: {e}", visual_template_examples_path.display()))?;
        } else {
            fs::write(
                &visual_template_examples_path,
                gui_style_template_package_visual_template_examples_json(style_roots, tokens),
            )
            .map_err(|e| format!("write {}: {e}", visual_template_examples_path.display()))?;
        }
        fs::write(
            &manifest,
            gui_request_style_template_package_manifest_json(
                style_roots,
                &style_tokens_path,
                &control_examples_path,
                &mount_examples_path,
                &resource_index_path,
                Some(&visual_template_examples_path),
            ),
        )
        .map_err(|e| format!("write {}: {e}", manifest.display()))?;
        return Ok(GuiRequestStyleTemplatePackage {
            manifest,
            style_tokens: style_tokens_path,
            control_examples: control_examples_path,
            mount_examples: mount_examples_path,
            resource_index: resource_index_path,
            visual_template_examples: Some(visual_template_examples_path),
            source_status: "provided_package_reused".to_string(),
            source_manifest: Some(source_manifest),
        });
    }
    write_gui_request_style_template_package(output_dir, &manifest, style_roots, reports, tokens)?;
    Ok(GuiRequestStyleTemplatePackage {
        manifest,
        style_tokens: style_tokens_path,
        control_examples: control_examples_path,
        mount_examples: mount_examples_path,
        resource_index: resource_index_path,
        visual_template_examples: Some(visual_template_examples_path),
        source_status: "generated_from_style_mod".to_string(),
        source_manifest: None,
    })
}

fn read_gui_style_template_package(
    manifest: &Path,
) -> Result<GuiRequestStyleTemplatePackage, String> {
    if !manifest.is_file() {
        return Err(format!(
            "style-template-package does not exist: {}",
            manifest.display()
        ));
    }
    let text = read_utf8_lossy(manifest)?;
    if !text.contains("\"schema\": \"hoi4skill.gui_style_template_package.v1\"") {
        return Err(format!(
            "style-template-package has unsupported schema: {}",
            manifest.display()
        ));
    }
    let parent = manifest.parent().unwrap_or_else(|| Path::new("."));
    let style_tokens = gui_style_package_field_path(parent, &text, "style_tokens")?;
    let control_examples = gui_style_package_field_path(parent, &text, "control_examples")?;
    let mount_examples = gui_style_package_field_path(parent, &text, "mount_examples")?;
    let resource_index = gui_style_package_field_path(parent, &text, "resource_index")?;
    let visual_template_examples = root_json_string_field(&text, "visual_template_examples")
        .map(|_| gui_style_package_field_path(parent, &text, "visual_template_examples"))
        .transpose()?;
    validate_gui_style_package_file(&style_tokens, "hoi4skill.gui_style_tokens.v1")?;
    validate_gui_style_package_file(&control_examples, "hoi4skill.gui_control_examples.v1")?;
    validate_gui_style_package_file(&mount_examples, "hoi4skill.gui_mount_examples.v1")?;
    validate_gui_style_package_file(&resource_index, "hoi4skill.gui_resource_index.v1")?;
    if let Some(path) = &visual_template_examples {
        validate_gui_style_package_file(path, "hoi4skill.gui_visual_template_examples.v1")?;
    }
    Ok(GuiRequestStyleTemplatePackage {
        manifest: manifest.to_path_buf(),
        style_tokens,
        control_examples,
        mount_examples,
        resource_index,
        visual_template_examples,
        source_status: "provided_package_validated".to_string(),
        source_manifest: Some(manifest.to_path_buf()),
    })
}

fn gui_style_package_field_path(parent: &Path, text: &str, key: &str) -> Result<PathBuf, String> {
    let value = root_json_string_field(text, key)
        .ok_or_else(|| format!("style-template-package missing `{key}` path"))?;
    let raw = Path::new(&value);
    let path = if raw.is_absolute() {
        raw.to_path_buf()
    } else {
        parent.join(raw)
    };
    if !path.is_file() {
        return Err(format!(
            "style-template-package `{key}` file does not exist: {}",
            path.display()
        ));
    }
    Ok(path)
}

fn validate_gui_style_package_file(path: &Path, schema: &str) -> Result<(), String> {
    let text = read_utf8_lossy(path)?;
    let expected = format!("\"schema\": \"{schema}\"");
    if !text.contains(&expected) {
        return Err(format!(
            "style-template-package file {} missing schema {}",
            path.display(),
            schema
        ));
    }
    Ok(())
}

fn write_gui_request_style_template_package(
    output_dir: &Path,
    manifest: &Path,
    style_roots: &[PathBuf],
    reports: &[LargeModGuiPatternProfile],
    tokens: &GuiStyleTemplateTokens,
) -> Result<(), String> {
    fs::create_dir_all(output_dir).map_err(|e| format!("create {}: {e}", output_dir.display()))?;
    let style_tokens_path = output_dir.join("style_tokens.json");
    let control_examples_path = output_dir.join("control_examples.json");
    let mount_examples_path = output_dir.join("mount_examples.json");
    let resource_index_path = output_dir.join("resource_index.json");
    let visual_template_examples_path = output_dir.join("visual_template_examples.json");
    fs::write(
        &style_tokens_path,
        gui_style_template_package_style_tokens_json(style_roots, tokens),
    )
    .map_err(|e| format!("write {}: {e}", style_tokens_path.display()))?;
    fs::write(
        &control_examples_path,
        gui_style_template_package_control_examples_json(style_roots, tokens),
    )
    .map_err(|e| format!("write {}: {e}", control_examples_path.display()))?;
    fs::write(
        &mount_examples_path,
        gui_style_template_package_mount_examples_json(style_roots, reports),
    )
    .map_err(|e| format!("write {}: {e}", mount_examples_path.display()))?;
    fs::write(
        &resource_index_path,
        gui_style_template_package_resource_index_json(style_roots, tokens),
    )
    .map_err(|e| format!("write {}: {e}", resource_index_path.display()))?;
    fs::write(
        &visual_template_examples_path,
        gui_style_template_package_visual_template_examples_json(style_roots, tokens),
    )
    .map_err(|e| format!("write {}: {e}", visual_template_examples_path.display()))?;
    fs::write(
        manifest,
        gui_request_style_template_package_manifest_json(
            style_roots,
            &style_tokens_path,
            &control_examples_path,
            &mount_examples_path,
            &resource_index_path,
            Some(&visual_template_examples_path),
        ),
    )
    .map_err(|e| format!("write {}: {e}", manifest.display()))?;
    Ok(())
}

fn gui_request_style_template_package_manifest_json(
    style_roots: &[PathBuf],
    style_tokens_path: &Path,
    control_examples_path: &Path,
    mount_examples_path: &Path,
    resource_index_path: &Path,
    visual_template_examples_path: Option<&Path>,
) -> String {
    let roots = style_roots
        .iter()
        .map(|root| root.display().to_string())
        .collect::<Vec<_>>();
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_style_template_package.v1\",\n  \"status\": \"written\",\n  \"parent_mods\": {},\n  \"style_tokens\": {},\n  \"control_examples\": {},\n  \"mount_examples\": {},\n  \"resource_index\": {},\n  \"visual_template_examples\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_array(&roots),
        json_str(&style_tokens_path.display().to_string()),
        json_str(&control_examples_path.display().to_string()),
        json_str(&mount_examples_path.display().to_string()),
        json_str(&resource_index_path.display().to_string()),
        json_optional_str(
            visual_template_examples_path
                .map(|path| path.display().to_string())
                .as_deref()
        ),
        json_array(&[
            "Reuse this package as evidence; do not copy whole parent-mod GUI implementations.".to_string(),
            "A generated control, mount, sprite, or font still must resolve through final-check before write.".to_string(),
        ]),
    )
}

fn gui_request_style_template_package_ready(manifest: &Path) -> bool {
    let Some(dir) = manifest.parent() else {
        return false;
    };
    manifest.is_file()
        && dir.join("style_tokens.json").is_file()
        && dir.join("control_examples.json").is_file()
        && dir.join("mount_examples.json").is_file()
        && dir.join("resource_index.json").is_file()
        && dir.join("visual_template_examples.json").is_file()
}

fn gui_style_package_validate_report_json(
    manifest: &Path,
    package: Option<&GuiRequestStyleTemplatePackage>,
    error: Option<&str>,
) -> String {
    let ok = package.is_some();
    let status = if ok { "passed" } else { "blocked" };
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_style_package_validate.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"manifest\": {},\n  \"style_tokens\": {},\n  \"control_examples\": {},\n  \"mount_examples\": {},\n  \"resource_index\": {},\n  \"visual_template_examples\": {},\n  \"visual_template_examples_ready\": {},\n  \"error\": {},\n  \"objective_acceptance\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(ok),
        json_str(&manifest.display().to_string()),
        json_optional_str(package.map(|pkg| pkg.style_tokens.display().to_string()).as_deref()),
        json_optional_str(
            package
                .map(|pkg| pkg.control_examples.display().to_string())
                .as_deref()
        ),
        json_optional_str(package.map(|pkg| pkg.mount_examples.display().to_string()).as_deref()),
        json_optional_str(package.map(|pkg| pkg.resource_index.display().to_string()).as_deref()),
        json_optional_str(
            package
                .and_then(|pkg| {
                    pkg.visual_template_examples
                        .as_ref()
                        .map(|path| path.display().to_string())
                })
                .as_deref()
        ),
        json_bool(
            package
                .and_then(|pkg| pkg.visual_template_examples.as_ref())
                .is_some_and(|path| path.is_file())
        ),
        json_optional_str(error),
        vec![
            gui_request_acceptance_item_json(
                "manifest_schema",
                "Style package manifest has hoi4skill.gui_style_template_package.v1 schema.",
                ok,
                "gui_style_template_package.json",
            ),
            gui_request_acceptance_item_json(
                "package_files",
                "Style package references valid style token, control example, mount example, resource index, and optional visual template files.",
                ok,
                "style_tokens/control_examples/mount_examples/resource_index/visual_template_examples",
            ),
            gui_request_acceptance_item_json(
                "visual_template_examples",
                "New GUI style packages expose visual component templates for runtime style matching.",
                package
                    .and_then(|pkg| pkg.visual_template_examples.as_ref())
                    .is_some_and(|path| path.is_file()),
                "visual_template_examples",
            ),
        ]
        .join(",\n"),
        json_array(&[
            "Do not reuse a GUI style package unless this validation report has ok=true."
                .to_string(),
            "A valid style package is evidence only; final GUI code still needs apply-gui-intent --final-check."
                .to_string(),
        ]),
    )
}

pub(crate) fn cmd_gui_output_audit(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let mut changed = repeated_values(&map, "changed")
        .into_iter()
        .map(|value| value.replace('\\', "/"))
        .collect::<Vec<_>>();
    if let Some(path) = value(&map, "changed-file") {
        let changed_file = normalize_path(path)?;
        let text = read_utf8_lossy(&changed_file)?;
        changed.extend(
            text.lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(|line| line.replace('\\', "/")),
        );
    }
    let apply_report_path = value(&map, "apply-report")
        .or_else(|| value(&map, "applied-gui-intent"))
        .map(normalize_path)
        .transpose()?;
    let apply_report_text = apply_report_path
        .as_ref()
        .map(|path| read_utf8_lossy(path))
        .transpose()?;
    if let Some(text) = apply_report_text.as_deref() {
        changed.extend(
            parse_json_string_array_field(text, "changed_files")
                .into_iter()
                .map(|value| value.replace('\\', "/")),
        );
    }
    changed.sort();
    changed.dedup();
    let runtime_open_plan_path = value(&map, "runtime-open-plan")
        .or_else(|| value(&map, "open-plan"))
        .map(normalize_path)
        .transpose()?;
    let runtime_open_plan_text = runtime_open_plan_path
        .as_ref()
        .map(|path| read_utf8_lossy(path))
        .transpose()?;
    let expected = gui_output_expected_from_reports(
        apply_report_path.as_deref(),
        apply_report_text.as_deref(),
        runtime_open_plan_path.as_deref(),
        runtime_open_plan_text.as_deref(),
    );
    let strict_index = if map.flags.contains("strict-code-index") {
        let Some(game_root) = value(&map, "game-root").or_else(|| value(&map, "hoi4-path")) else {
            return Err(
                "gui-output-audit --strict-code-index requires --game-root <HOI4 root>".to_string(),
            );
        };
        let game_root = normalize_path(game_root)?;
        let style_roots = gui_output_audit_style_roots(&map, &mod_root)?;
        let code_index_roots = gui_request_workflow_code_index_roots(&mod_root, &style_roots);
        Some(build_game_index_with_mod_paths(
            &game_root,
            &code_index_roots,
        )?)
    } else {
        None
    };
    let style_template = gui_output_audit_style_template_from_args(&map, &mod_root)?;
    let audit = gui_output_audit_for_paths_with_index(
        &mod_root,
        &changed,
        strict_index.as_ref(),
        style_template.as_ref(),
        Some(&expected),
    )?;
    write_or_print(
        &gui_output_audit_json(&mod_root, &audit),
        value(&map, "output"),
    )?;
    if map.flags.contains("require-passed") && !audit.ok {
        return Err("gui-output-audit did not pass".to_string());
    }
    Ok(())
}

pub(crate) fn cmd_gui_error_regression(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let input = value(&map, "input")
        .or_else(|| value(&map, "error-log"))
        .or_else(|| value(&map, "error-log-input"))
        .ok_or_else(|| "gui-error-regression requires --input <error.log>".to_string())?;
    let input = normalize_path(input)?;
    let changed = gui_command_changed_files(&map)?;
    let output_path = value(&map, "output")
        .map(normalize_path)
        .transpose()?
        .unwrap_or_else(|| {
            mod_root
                .join(".hoi4skill")
                .join("gui_error_regression.json")
        });
    if let Some(parent) = output_path.parent() {
        fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
    }
    let analysis_report = output_path.with_file_name(format!(
        "{}_error_log_report.json",
        output_path
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or("gui_error_regression")
    ));
    let mut analyze_args = vec![
        "--input".to_string(),
        input.display().to_string(),
        "--mod-root".to_string(),
        mod_root.display().to_string(),
        "--output".to_string(),
        analysis_report.display().to_string(),
    ];
    if let Some(baseline) = value(&map, "baseline").or_else(|| value(&map, "error-log-baseline")) {
        analyze_args.push("--baseline".to_string());
        analyze_args.push(baseline.to_string());
    }
    if !changed.is_empty() || map.flags.contains("changed-only") {
        analyze_args.push("--changed-only".to_string());
    }
    for changed_file in &changed {
        analyze_args.push("--changed".to_string());
        analyze_args.push(changed_file.clone());
    }
    let analyze_result = cmd_analyze_error_log(&analyze_args);
    let analysis_text = read_utf8_lossy(&analysis_report).unwrap_or_default();
    let gui_diagnostic_count = gui_error_regression_diagnostic_objects(&analysis_text).len();
    let ok = analyze_result.is_ok() && gui_diagnostic_count == 0;
    let report = gui_error_regression_report_json(
        &mod_root,
        &input,
        &analysis_report,
        &analysis_text,
        &changed,
        value(&map, "baseline").or_else(|| value(&map, "error-log-baseline")),
        analyze_result.as_ref().err().map(String::as_str),
    );
    write_or_print(&report, Some(&output_path.display().to_string()))?;
    if map.flags.contains("require-passed") && !ok {
        return Err("gui-error-regression did not pass".to_string());
    }
    Ok(())
}

fn gui_output_audit_style_roots(map: &ArgMap, mod_root: &Path) -> Result<Vec<PathBuf>, String> {
    let mut style_roots = repeated_values(map, "style-mod")
        .into_iter()
        .chain(repeated_values(map, "parent-mod"))
        .map(normalize_path)
        .collect::<Result<Vec<_>, _>>()?;
    if style_roots.is_empty() {
        style_roots.push(mod_root.to_path_buf());
    }
    style_roots.sort();
    style_roots.dedup();
    Ok(style_roots)
}

fn gui_output_audit_style_template_from_args(
    map: &ArgMap,
    mod_root: &Path,
) -> Result<Option<GuiStyleRuntimeTemplate>, String> {
    if let Some(package) = value(map, "style-template-package")
        .or_else(|| value(map, "gui-style-template-package"))
        .or_else(|| value(map, "style-package"))
    {
        let package = read_gui_style_template_package(&normalize_path(package)?)?;
        return load_gui_style_runtime_template(Some(&package.style_tokens.display().to_string()));
    }
    let style_template_path = value(map, "style-template");
    let has_style_roots = !repeated_values(map, "style-mod").is_empty()
        || !repeated_values(map, "parent-mod").is_empty();
    if style_template_path.is_none() && !has_style_roots {
        return Ok(None);
    }
    let style_roots = gui_output_audit_style_roots(map, mod_root)?;
    let reports = style_roots
        .iter()
        .map(|root| large_mod_gui_pattern_profile(root))
        .collect::<Result<Vec<_>, _>>()?;
    load_or_learn_gui_style_runtime_template(style_template_path, &reports)
}

pub(crate) fn cmd_gui_visual_smoke(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let game_root = value(&map, "game-root")
        .or_else(|| value(&map, "hoi4-path"))
        .map(normalize_path)
        .transpose()?
        .ok_or_else(|| "gui-visual-smoke requires --game-root <HOI4 root>".to_string())?;
    if !game_root.is_dir() {
        return Err(format!("game root does not exist: {}", game_root.display()));
    }
    let apply_report = normalize_path(&require_value(&map, "apply-report")?)?;
    let apply_text = read_utf8_lossy(&apply_report)?;
    let code_passed = status_json_top_level_bool_field_has_value(&apply_text, "ok", true)
        && status_json_top_level_bool_field_has_value(&apply_text, "final_check_ok", true)
        && status_json_bool_field_has_value(&apply_text, "strict_validation_ok", true);
    let window_name = value(&map, "window-name").or_else(|| value(&map, "window"));
    let evidence_log = value(&map, "evidence-log")
        .or_else(|| value(&map, "log-evidence"))
        .map(normalize_path)
        .transpose()?;
    let evidence_log_ok = evidence_log
        .as_ref()
        .filter(|path| path.exists())
        .and_then(|path| read_utf8_lossy(path).ok())
        .is_some_and(|text| {
            window_name
                .map(|window| text.contains(window))
                .unwrap_or_else(|| gui_error_log_text_is_gui_related(&text.to_ascii_lowercase()))
        });
    let window_opened = map.flags.contains("window-opened")
        || map.flags.contains("opened")
        || value(&map, "window-evidence").is_some()
        || evidence_log_ok;
    let screenshot = value(&map, "screenshot")
        .or_else(|| value(&map, "image"))
        .map(normalize_path)
        .transpose()?;
    let resolution = value(&map, "resolution");
    let strict_image = map.flags.contains("strict-image")
        || map.flags.contains("require-strict-screenshot")
        || map.flags.contains("require-strict-image");
    let min_dimensions = gui_runtime_min_screenshot_dimensions(&map, resolution)?;
    let screenshot_probe = screenshot
        .as_ref()
        .and_then(|path| probe_gui_image_asset(path).ok());
    let screenshot_ok = screenshot.as_ref().is_some_and(|path| path.is_file());
    let strict_screenshot_ready = !strict_image
        || screenshot_ok
            && screenshot_probe.as_ref().is_some_and(|probe| {
                probe.width >= min_dimensions.0 && probe.height >= min_dimensions.1
            });
    let resolution_ok = resolution
        .map(|value| value.to_ascii_lowercase().contains('x'))
        .unwrap_or(false);
    let ui_scale_ok = value(&map, "ui-scale")
        .or_else(|| value(&map, "scale"))
        .is_some()
        || map.flags.contains("default-ui-scale");
    let text_fit_ok = map.flags.contains("text-fit-ok")
        || value(&map, "text-overflow")
            .map(|value| matches!(value, "none" | "ok" | "false" | "0"))
            .unwrap_or(false)
        || value(&map, "text-fit-report")
            .map(normalize_path)
            .transpose()?
            .filter(|path| path.exists())
            .and_then(|path| read_utf8_lossy(&path).ok())
            .is_some_and(|text| !text.to_ascii_lowercase().contains("overflow"));
    let click_evidence_ok = map.flags.contains("button-clicked")
        || map.flags.contains("click-ok")
        || value(&map, "click-evidence")
            .map(|value| !value.trim().is_empty())
            .unwrap_or(false);
    let visual_passed = code_passed
        && window_opened
        && screenshot_ok
        && strict_screenshot_ready
        && resolution_ok
        && ui_scale_ok
        && text_fit_ok
        && click_evidence_ok;
    let report = gui_visual_smoke_report_json(
        &mod_root,
        &game_root,
        &apply_report,
        code_passed,
        visual_passed,
        window_name,
        screenshot.as_deref(),
        evidence_log.as_deref(),
        resolution,
        value(&map, "ui-scale").or_else(|| value(&map, "scale")),
        strict_image,
        min_dimensions,
        screenshot_probe.as_ref(),
        screenshot
            .as_ref()
            .and_then(|path| gui_file_hash_hex(path))
            .as_deref(),
        strict_screenshot_ready,
        window_opened,
        screenshot_ok,
        resolution_ok,
        ui_scale_ok,
        text_fit_ok,
        click_evidence_ok,
    );
    write_or_print(&report, value(&map, "output"))?;
    if map.flags.contains("require-passed") && !visual_passed {
        return Err("gui-visual-smoke did not pass".to_string());
    }
    Ok(())
}

pub(crate) fn cmd_gui_runtime_visual_matrix(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let visual_reports = repeated_values(&map, "visual-smoke")
        .into_iter()
        .chain(repeated_values(&map, "gui-visual-smoke"))
        .chain(repeated_values(&map, "visual-report"))
        .map(normalize_path)
        .collect::<Result<Vec<_>, _>>()?;
    let visual_probes = repeated_values(&map, "runtime-visual-probe")
        .into_iter()
        .chain(repeated_values(&map, "gui-runtime-visual-probe"))
        .chain(repeated_values(&map, "visual-probe"))
        .map(normalize_path)
        .collect::<Result<Vec<_>, _>>()?;
    let screenshot_reports = repeated_values(&map, "runtime-screenshot")
        .into_iter()
        .chain(repeated_values(&map, "gui-runtime-screenshot"))
        .chain(repeated_values(&map, "screenshot-report"))
        .map(normalize_path)
        .collect::<Result<Vec<_>, _>>()?;
    let required_resolutions = repeated_values(&map, "require-resolution")
        .into_iter()
        .chain(repeated_values(&map, "resolution"))
        .map(normalize_gui_matrix_token)
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    let required_scales = repeated_values(&map, "require-ui-scale")
        .into_iter()
        .chain(repeated_values(&map, "ui-scale"))
        .chain(repeated_values(&map, "scale"))
        .map(normalize_gui_matrix_token)
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    let min_visual_reports = value(&map, "min-visual-reports")
        .or_else(|| value(&map, "min-report-count"))
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or_else(|| required_resolutions.len().max(required_scales.len()).max(1));
    let require_visual_probe = map.flags.contains("require-visual-probe")
        || map.flags.contains("require-runtime-visual-probe");
    let require_screenshot_report = map.flags.contains("require-runtime-screenshot")
        || map.flags.contains("require-screenshot-report");
    let require_screenshot_hash =
        map.flags.contains("require-screenshot-hash") || map.flags.contains("require-hash");
    let report = gui_runtime_visual_matrix_report_json(
        &mod_root,
        &visual_reports,
        &visual_probes,
        &screenshot_reports,
        &required_resolutions,
        &required_scales,
        min_visual_reports,
        require_visual_probe,
        require_screenshot_report,
        require_screenshot_hash,
    );
    let ready = status_json_top_level_bool_field_has_value(&report, "visual_matrix_ready", true);
    write_or_print(&report, value(&map, "output"))?;
    if map.flags.contains("require-passed") && !ready {
        return Err("gui-runtime-visual-matrix did not pass".to_string());
    }
    Ok(())
}

