pub(crate) fn cmd_gui_runtime_open_plan(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let apply_report = value(&map, "apply-report")
        .map(normalize_path)
        .transpose()?;
    let game_root = value(&map, "game-root")
        .or_else(|| value(&map, "hoi4-path"))
        .map(normalize_path)
        .transpose()?;
    if let Some(game_root) = &game_root {
        if !game_root.is_dir() {
            return Err(format!("game root does not exist: {}", game_root.display()));
        }
    }
    let strict_code_index = map.flags.contains("strict-code-index")
        || map.flags.contains("require-code-index")
        || game_root.is_some();
    if strict_code_index && game_root.is_none() {
        return Err(
            "gui-runtime-open-plan --strict-code-index requires --game-root <HOI4 root>"
                .to_string(),
        );
    }
    let code_index = if let Some(game_root) = &game_root {
        let mut code_index_roots =
            dependency_mod_roots_for_optional_edited_mod(&map, Some(&mod_root), true)?;
        code_index_roots.push(mod_root.clone());
        code_index_roots = dedupe_paths(code_index_roots);
        Some(build_game_index_with_mod_paths(
            game_root,
            &code_index_roots,
        )?)
    } else {
        None
    };
    let runtime_launch_plan = value(&map, "runtime-launch-plan")
        .or_else(|| value(&map, "launch-plan"))
        .or_else(|| value(&map, "gui-runtime-launch-plan"))
        .map(normalize_path)
        .transpose()?;
    let country_tag = value(&map, "country-tag").or_else(|| value(&map, "tag"));
    let window_name = value(&map, "window-name").or_else(|| value(&map, "window"));
    let gui_kind = value(&map, "gui-kind")
        .or_else(|| value(&map, "kind"))
        .unwrap_or("");
    let parent_window_token = value(&map, "parent-window-token")
        .or_else(|| value(&map, "parent-window"))
        .or_else(|| value(&map, "parent-token"));
    let map_window = value(&map, "map-window").or_else(|| value(&map, "map-window-name"));
    let decision_category = value(&map, "decision-category")
        .or_else(|| value(&map, "decision-category-id"))
        .or_else(|| value(&map, "category"));
    let decision_id = value(&map, "decision-id").or_else(|| value(&map, "decision"));
    let require_decision_route = map.flags.contains("require-decision-route")
        || map.flags.contains("require-decision-gui")
        || gui_kind.eq_ignore_ascii_case("decision_attached")
        || decision_category.is_some();
    let require_decision_id = map.flags.contains("require-decision-id") || decision_id.is_some();
    let open_flag = value(&map, "open-flag").or_else(|| value(&map, "flag"));
    let open_effect = value(&map, "open-effect").or_else(|| value(&map, "effect"));
    let click_target = value(&map, "click-target")
        .or_else(|| value(&map, "target-widget"))
        .or_else(|| value(&map, "button"));
    let expected_tokens = repeated_values(&map, "expect-log-token")
        .into_iter()
        .chain(repeated_values(&map, "expect-state-token"))
        .map(str::to_string)
        .collect::<Vec<_>>();
    let report = gui_runtime_open_plan_json(
        &mod_root,
        apply_report.as_deref(),
        runtime_launch_plan.as_deref(),
        Some(gui_kind),
        country_tag,
        window_name,
        parent_window_token,
        map_window,
        decision_category,
        decision_id,
        open_flag,
        open_effect,
        click_target,
        &expected_tokens,
        map.flags.contains("require-country"),
        require_decision_route,
        require_decision_id,
        strict_code_index,
        code_index.as_ref(),
    )?;
    let open_plan_ready =
        status_json_top_level_bool_field_has_value(&report, "open_plan_ready", true);
    write_or_print(&report, value(&map, "output"))?;
    if map.flags.contains("require-passed") && !open_plan_ready {
        return Err("gui-runtime-open-plan did not pass".to_string());
    }
    Ok(())
}

