pub(crate) fn cmd_gui_runtime_screenshot(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let screenshot = value(&map, "screenshot")
        .or_else(|| value(&map, "screenshot-output"))
        .or_else(|| value(&map, "image"))
        .map(normalize_path)
        .transpose()?
        .ok_or_else(|| "gui-runtime-screenshot requires --screenshot <path>".to_string())?;
    let window_probe = value(&map, "runtime-window-probe")
        .or_else(|| value(&map, "window-probe"))
        .or_else(|| value(&map, "gui-runtime-window-probe"))
        .map(normalize_path)
        .transpose()?;
    let window_name = value(&map, "window-name").or_else(|| value(&map, "window"));
    let process_name = value(&map, "process-name")
        .or_else(|| value(&map, "process"))
        .unwrap_or("hoi4");
    let require_window_probe =
        map.flags.contains("require-window-probe") || map.flags.contains("require-window-match");
    let capture = map.flags.contains("capture") || map.flags.contains("execute");
    let capture_window = map.flags.contains("capture-window")
        || map.flags.contains("window-capture")
        || (capture && (window_probe.is_some() || window_name.is_some()));
    let window_probe_text = read_optional_existing_report(window_probe.as_deref())?;
    let resolved_window_name = window_name
        .map(str::to_string)
        .or_else(|| status_json_string_field(&window_probe_text, "matched_window_title"))
        .or_else(|| status_json_string_field(&window_probe_text, "window_name"));
    let capture_error = if capture {
        if capture_window {
            capture_window_to_png(&screenshot, resolved_window_name.as_deref(), process_name).err()
        } else {
            capture_primary_screen_to_png(&screenshot).err()
        }
    } else {
        None
    };
    let capture_mode = if capture_window {
        "window"
    } else {
        "primary_screen"
    };
    let strict_image = map.flags.contains("strict-image")
        || map.flags.contains("require-image-header")
        || map.flags.contains("require-strict-image");
    let min_byte_len = value(&map, "min-bytes")
        .or_else(|| value(&map, "min-byte-len"))
        .map(|raw| {
            raw.parse::<u64>()
                .map_err(|_| format!("invalid --min-bytes `{raw}`"))
        })
        .unwrap_or(Ok(64))?;
    let min_width = value(&map, "min-width")
        .map(|raw| {
            raw.parse::<u32>()
                .map_err(|_| format!("invalid --min-width `{raw}`"))
        })
        .unwrap_or(Ok(1))?;
    let min_height = value(&map, "min-height")
        .map(|raw| {
            raw.parse::<u32>()
                .map_err(|_| format!("invalid --min-height `{raw}`"))
        })
        .unwrap_or(Ok(1))?;
    let report = gui_runtime_screenshot_report_json(
        &mod_root,
        &screenshot,
        capture,
        capture_error,
        capture_mode,
        window_probe.as_deref(),
        &window_probe_text,
        resolved_window_name.as_deref(),
        process_name,
        require_window_probe,
        strict_image,
        min_byte_len,
        (min_width, min_height),
    );
    let screenshot_ready =
        status_json_top_level_bool_field_has_value(&report, "screenshot_ready", true);
    write_or_print(&report, value(&map, "output"))?;
    if map.flags.contains("require-passed") && !screenshot_ready {
        return Err("gui-runtime-screenshot did not pass".to_string());
    }
    Ok(())
}

pub(crate) fn cmd_gui_runtime_visual_probe(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let apply_report = value(&map, "apply-report")
        .map(normalize_path)
        .transpose()?;
    let screenshot_report = value(&map, "runtime-screenshot")
        .or_else(|| value(&map, "gui-runtime-screenshot"))
        .or_else(|| value(&map, "screenshot-report"))
        .map(normalize_path)
        .transpose()?;
    let layout_probe = value(&map, "runtime-layout-probe")
        .or_else(|| value(&map, "gui-runtime-layout-probe"))
        .or_else(|| value(&map, "layout-probe"))
        .map(normalize_path)
        .transpose()?;
    let screenshot = value(&map, "screenshot")
        .or_else(|| value(&map, "image"))
        .map(normalize_path)
        .transpose()?;
    let window_name = value(&map, "window-name")
        .or_else(|| value(&map, "window"))
        .map(str::to_string)
        .or_else(|| {
            apply_report
                .as_ref()
                .and_then(|path| read_utf8_lossy(path).ok())
                .and_then(|text| status_json_string_field(&text, "window_name"))
        });
    let mut expected_widgets: Vec<String> = repeated_values(&map, "expected-widget")
        .into_iter()
        .map(str::to_string)
        .collect();
    if expected_widgets.is_empty() {
        expected_widgets.extend(
            repeated_values(&map, "widget")
                .into_iter()
                .map(str::to_string),
        );
    }
    let resolution = value(&map, "resolution")
        .and_then(parse_gui_resolution)
        .unwrap_or((1920, 1080));
    let report = gui_runtime_visual_probe_report_json(
        &mod_root,
        apply_report.as_deref(),
        screenshot_report.as_deref(),
        layout_probe.as_deref(),
        screenshot.as_deref(),
        window_name.as_deref(),
        &expected_widgets,
        resolution,
    );
    let visual_probe_ready =
        status_json_top_level_bool_field_has_value(&report, "visual_probe_ready", true);
    write_or_print(&report, value(&map, "output"))?;
    if map.flags.contains("require-passed") && !visual_probe_ready {
        return Err("gui-runtime-visual-probe did not pass".to_string());
    }
    Ok(())
}

pub(crate) fn cmd_gui_runtime_style_match(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let style_template_package = value(&map, "style-template-package")
        .or_else(|| value(&map, "gui-style-template-package"))
        .or_else(|| value(&map, "style-package"))
        .map(normalize_path)
        .transpose()?
        .ok_or_else(|| {
            "gui-runtime-style-match requires --style-template-package <gui_style_template_package.json>"
                .to_string()
        })?;
    let runtime_layout_probe = value(&map, "runtime-layout-probe")
        .or_else(|| value(&map, "gui-runtime-layout-probe"))
        .or_else(|| value(&map, "layout-probe"))
        .map(normalize_path)
        .transpose()?;
    let runtime_visual_probe = value(&map, "runtime-visual-probe")
        .or_else(|| value(&map, "gui-runtime-visual-probe"))
        .or_else(|| value(&map, "visual-probe"))
        .map(normalize_path)
        .transpose()?;
    let runtime_pixel_probe = value(&map, "runtime-pixel-probe")
        .or_else(|| value(&map, "gui-runtime-pixel-probe"))
        .or_else(|| value(&map, "pixel-probe"))
        .map(normalize_path)
        .transpose()?;
    let expected_components = repeated_values(&map, "expected-component")
        .into_iter()
        .chain(repeated_values(&map, "component"))
        .map(str::to_string)
        .collect::<Vec<_>>();
    let expected_visual_roles = repeated_values(&map, "expected-visual-role")
        .into_iter()
        .chain(repeated_values(&map, "visual-role"))
        .map(str::to_string)
        .collect::<Vec<_>>();
    let expected_visual_tokens = repeated_values(&map, "expected-sprite")
        .into_iter()
        .chain(repeated_values(&map, "expected-visual-token"))
        .chain(repeated_values(&map, "sprite"))
        .map(str::to_string)
        .collect::<Vec<_>>();
    let expected_fonts = repeated_values(&map, "expected-font")
        .into_iter()
        .chain(repeated_values(&map, "font"))
        .map(str::to_string)
        .collect::<Vec<_>>();
    let expected_structures = repeated_values(&map, "expected-structure")
        .into_iter()
        .chain(repeated_values(&map, "structure"))
        .map(str::to_string)
        .collect::<Vec<_>>();
    let require_layout_probe = !map.flags.contains("allow-missing-layout-probe");
    let require_visual_probe = map.flags.contains("require-visual-probe");
    let require_pixel_probe = map.flags.contains("require-pixel-probe");
    let require_visual_tokens = map.flags.contains("require-visual-tokens")
        || map.flags.contains("require-sprite-style")
        || map.flags.contains("require-sprites");
    let require_fonts =
        map.flags.contains("require-fonts") || map.flags.contains("require-font-style");
    let require_structure =
        map.flags.contains("require-structure") || map.flags.contains("require-structure-style");
    let require_visual_template = map.flags.contains("require-visual-template")
        || map.flags.contains("require-visual-templates")
        || map.flags.contains("require-template-examples");
    let report = gui_runtime_style_match_report_json(
        &mod_root,
        &style_template_package,
        runtime_layout_probe.as_deref(),
        runtime_visual_probe.as_deref(),
        runtime_pixel_probe.as_deref(),
        &expected_components,
        &expected_visual_roles,
        &expected_visual_tokens,
        &expected_fonts,
        &expected_structures,
        require_layout_probe,
        require_visual_probe,
        require_pixel_probe,
        require_visual_tokens,
        require_fonts,
        require_structure,
        require_visual_template,
    )?;
    let style_match_ready =
        status_json_top_level_bool_field_has_value(&report, "style_match_ready", true);
    write_or_print(&report, value(&map, "output"))?;
    if map.flags.contains("require-passed") && !style_match_ready {
        return Err("gui-runtime-style-match did not pass".to_string());
    }
    Ok(())
}

pub(crate) fn cmd_gui_runtime_layout_probe(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let window_name = value(&map, "window-name")
        .or_else(|| value(&map, "window"))
        .map(str::to_string);
    let expected_widgets = repeated_values(&map, "expected-widget")
        .into_iter()
        .chain(repeated_values(&map, "widget"))
        .map(str::to_string)
        .collect::<Vec<_>>();
    let interface_files = if let Some(input) = value(&map, "input").or_else(|| value(&map, "gui")) {
        vec![normalize_path(input)?]
    } else {
        collect_profile_files_relative(&mod_root, &mod_root.join("interface"), &["gui"], 5000)?
            .into_iter()
            .map(|relative| mod_root.join(slash_path_to_native(&relative)))
            .collect()
    };
    let report = gui_runtime_layout_probe_report_json(
        &mod_root,
        &interface_files,
        window_name.as_deref(),
        &expected_widgets,
    )?;
    let layout_probe_ready =
        status_json_top_level_bool_field_has_value(&report, "layout_probe_ready", true);
    write_or_print(&report, value(&map, "output"))?;
    if map.flags.contains("require-passed") && !layout_probe_ready {
        return Err("gui-runtime-layout-probe did not pass".to_string());
    }
    Ok(())
}

pub(crate) fn cmd_gui_runtime_click_plan(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let layout_probe = value(&map, "layout-probe")
        .or_else(|| value(&map, "gui-runtime-layout-probe"))
        .map(normalize_path)
        .transpose()?
        .ok_or_else(|| "gui-runtime-click-plan requires --layout-probe <json>".to_string())?;
    let runtime_session_plan = value(&map, "runtime-session-plan")
        .or_else(|| value(&map, "session-plan"))
        .or_else(|| value(&map, "gui-runtime-session-plan"))
        .map(normalize_path)
        .transpose()?;
    let session_text = read_optional_existing_report(runtime_session_plan.as_deref())?;
    let target_widget = value(&map, "target-widget")
        .or_else(|| value(&map, "button"))
        .or_else(|| value(&map, "widget"))
        .map(str::to_string)
        .or_else(|| status_json_string_field(&session_text, "click_target"));
    let after_log = value(&map, "after-log")
        .or_else(|| value(&map, "post-click-log"))
        .map(normalize_path)
        .transpose()?
        .or_else(|| status_json_string_field(&session_text, "error_log").map(PathBuf::from));
    let after_screenshot = value(&map, "after-screenshot")
        .or_else(|| value(&map, "post-click-screenshot"))
        .map(normalize_path)
        .transpose()?
        .or_else(|| status_json_string_field(&session_text, "screenshot").map(PathBuf::from));
    let capture_after_screenshot = map.flags.contains("capture-after-screenshot")
        || map.flags.contains("capture-screenshot-after-click");
    let require_session_plan =
        map.flags.contains("require-session-plan") || map.flags.contains("require-runtime-session");
    let execute = map.flags.contains("execute");
    let report = gui_runtime_click_plan_report_json(
        &mod_root,
        &layout_probe,
        runtime_session_plan.as_deref(),
        target_widget.as_deref(),
        after_log.as_deref(),
        after_screenshot.as_deref(),
        capture_after_screenshot,
        require_session_plan,
        execute,
    )?;
    let click_plan_ready =
        status_json_top_level_bool_field_has_value(&report, "click_plan_ready", true);
    write_or_print(&report, value(&map, "output"))?;
    if map.flags.contains("require-passed") && !click_plan_ready {
        return Err("gui-runtime-click-plan did not pass".to_string());
    }
    Ok(())
}

