pub(crate) fn cmd_gui_runtime_evidence_manifest(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let mod_root = normalize_path(&require_value(&map, "mod-root")?)?;
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let output_dir = value(&map, "output-dir")
        .map(normalize_path)
        .transpose()?
        .unwrap_or_else(|| mod_root.join(".hoi4skill").join("gui_runtime_evidence"));
    let path_for = |keys: &[&str], default_name: &str| -> Result<PathBuf, String> {
        for key in keys {
            if let Some(raw) = value(&map, key) {
                return normalize_path(raw);
            }
        }
        Ok(output_dir.join(default_name))
    };
    let report = gui_runtime_evidence_manifest_json(
        &mod_root,
        &output_dir,
        &path_for(
            &["runtime-evidence-collect", "collect-report"],
            "gui_runtime_evidence_collect.json",
        )?,
        &path_for(
            &["runtime-evidence-contract", "contract-report"],
            "gui_runtime_evidence_contract.json",
        )?,
        &path_for(
            &["runtime-evidence-bundle", "bundle-report"],
            "gui_runtime_evidence_bundle.json",
        )?,
        &path_for(
            &["playability-gate", "playability-report"],
            "gui_playability_gate.json",
        )?,
        &path_for(
            &["runtime-evidence-timeline", "timeline-report"],
            "gui_runtime_evidence_timeline.json",
        )?,
        &path_for(
            &["runtime-screenshot", "screenshot-report"],
            "gui_runtime_screenshot.json",
        )?,
        &path_for(
            &["runtime-click-probe", "click-probe"],
            "gui_runtime_click_probe.json",
        )?,
        &path_for(
            &["runtime-state-probe", "state-probe"],
            "gui_runtime_state_probe.json",
        )?,
        &path_for(
            &["runtime-log-probe", "log-probe"],
            "gui_runtime_log_probe.json",
        )?,
        &path_for(
            &["runtime-text-fit-matrix", "text-fit-matrix"],
            "gui_runtime_text_fit_matrix.json",
        )?,
        &path_for(
            &["gui-visual-smoke", "visual-smoke"],
            "gui_visual_smoke.json",
        )?,
        &path_for(&["gui-game-smoke", "game-smoke"], "gui_game_smoke.json")?,
    )?;
    let output = value(&map, "output")
        .map(PathBuf::from)
        .unwrap_or_else(|| output_dir.join("gui_runtime_evidence_manifest.json"));
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
    }
    fs::write(&output, &report).map_err(|e| format!("write {}: {e}", output.display()))?;
    let manifest_ready =
        status_json_top_level_bool_field_has_value(&report, "runtime_manifest_ready", true);
    if map.flags.contains("require-passed") && !manifest_ready {
        return Err("gui-runtime-evidence-manifest did not pass".to_string());
    }
    Ok(())
}

