pub(crate) fn cmd_gui_unknown_blockers_gate(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let workflow_report = if let Some(path) = value(&map, "workflow-report")
        .or_else(|| value(&map, "workflow"))
        .or_else(|| value(&map, "report"))
    {
        Some(normalize_path(path)?)
    } else if let Some(dir) = value(&map, "workflow-dir").or_else(|| value(&map, "output-dir")) {
        Some(normalize_path(dir)?.join("gui_request_workflow.json"))
    } else {
        None
    };
    let workflow_dir = workflow_report
        .as_ref()
        .and_then(|path| path.parent().map(Path::to_path_buf));
    let apply_report = value(&map, "apply-report")
        .or_else(|| value(&map, "apply"))
        .map(normalize_path)
        .transpose()?
        .or_else(|| {
            workflow_dir
                .as_ref()
                .map(|dir| dir.join("apply_gui_intent.json"))
        });
    let mount_audit = value(&map, "mount-audit")
        .or_else(|| value(&map, "gui-mount-audit"))
        .map(normalize_path)
        .transpose()?
        .or_else(|| {
            workflow_dir
                .as_ref()
                .map(|dir| dir.join("gui_mount_audit.json"))
        });
    let output_audit = value(&map, "output-audit")
        .or_else(|| value(&map, "gui-output-audit"))
        .map(normalize_path)
        .transpose()?;
    let report = gui_unknown_blockers_gate_report_json(
        workflow_report.as_deref(),
        apply_report.as_deref(),
        mount_audit.as_deref(),
        output_audit.as_deref(),
    );
    let ready = status_json_top_level_bool_field_has_value(&report, "unknown_blockers_ready", true);
    write_or_print(&report, value(&map, "output"))?;
    if map.flags.contains("require-passed") && !ready {
        return Err("gui-unknown-blockers-gate did not pass".to_string());
    }
    Ok(())
}

pub(crate) fn cmd_gui_repair_loop(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let (workflow_report, workflow_dir) = gui_repair_loop_workflow_paths(&map)?;
    let output = if let Some(path) = value(&map, "output") {
        normalize_path(path)?
    } else {
        workflow_dir.join("gui_repair_context.json")
    };
    let markdown_output = if let Some(path) = value(&map, "markdown-output")
        .or_else(|| value(&map, "md-output"))
        .or_else(|| value(&map, "prompt-output"))
    {
        Some(normalize_path(path)?)
    } else {
        Some(workflow_dir.join("gui_repair_context.md"))
    };
    let goal_gate = gui_repair_loop_optional_report(
        &map,
        &workflow_dir,
        &["goal-gate", "gui-goal-gate"],
        "gui_goal_gate.json",
    )?;
    let runtime_one_shot = gui_repair_loop_optional_report(
        &map,
        &workflow_dir,
        &[
            "runtime-one-shot",
            "runtime-gate",
            "gui-runtime-one-shot-gate",
        ],
        "gui_runtime_one_shot_gate.json",
    )?;
    let playability_gate = gui_repair_loop_optional_report(
        &map,
        &workflow_dir,
        &["playability-gate", "gui-playability-gate"],
        "gui_playability_gate.json",
    )?;
    let report = gui_repair_loop_report_json(
        &workflow_report,
        &workflow_dir,
        goal_gate.as_deref(),
        runtime_one_shot.as_deref(),
        playability_gate.as_deref(),
    )?;
    let repair_context_ready =
        status_json_top_level_bool_field_has_value(&report, "repair_context_ready", true);
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
    }
    write_or_print(&report, Some(&output.display().to_string()))?;
    if let Some(markdown_output) = markdown_output {
        let markdown = gui_repair_loop_markdown(&report);
        if let Some(parent) = markdown_output.parent() {
            fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
        }
        fs::write(&markdown_output, markdown)
            .map_err(|e| format!("write {}: {e}", markdown_output.display()))?;
    }
    if (map.flags.contains("require-passed") || map.flags.contains("require-repair"))
        && !repair_context_ready
    {
        return Err("gui-repair-loop did not produce a safe repair context".to_string());
    }
    Ok(())
}

