fn extract_gui_request_tag_refs(request: &str) -> Vec<String> {
    let mut out = Vec::new();
    for marker in [
        "tag:",
        "tag：",
        "tag =",
        "TAG:",
        "TAG：",
        "TAG =",
        "目标:",
        "目标：",
        "国家:",
        "国家：",
        "国家/势力:",
        "国家/势力：",
        "country:",
        "country：",
        "country =",
        "Country:",
        "Country：",
        "Country =",
        "target:",
        "target：",
        "target =",
        "Target:",
        "Target：",
        "Target =",
    ] {
        let mut rest = request;
        while let Some(idx) = rest.find(marker) {
            let after = &rest[idx + marker.len()..];
            let tag = after
                .trim_start()
                .trim_start_matches(['`', '"', '\''])
                .chars()
                .take_while(|ch| ch.is_ascii_alphanumeric() || *ch == '_')
                .collect::<String>();
            if gui_request_token_looks_country_tag(&tag) {
                push_capped_unique(&mut out, tag, 32);
            }
            rest = after;
        }
    }
    out
}

fn gui_request_token_looks_country_tag(token: &str) -> bool {
    (2..=12).contains(&token.len())
        && token
            .chars()
            .all(|ch| ch.is_ascii_uppercase() || ch.is_ascii_digit() || ch == '_')
        && token.chars().any(|ch| ch.is_ascii_uppercase())
}

fn extract_gui_request_named_token(request: &str, markers: &[&str]) -> Option<String> {
    for marker in markers {
        if let Some(token) = extract_gui_request_named_token_after(request, marker) {
            return Some(token);
        }
        let lower_request = request.to_ascii_lowercase();
        let lower_marker = marker.to_ascii_lowercase();
        if lower_marker != *marker {
            if let Some(idx) = lower_request.find(&lower_marker) {
                if let Some(after) = request.get(idx + marker.len()..) {
                    if let Some(token) = extract_gui_request_token_from_rest(after) {
                        return Some(token);
                    }
                }
            }
        }
    }
    None
}

fn extract_gui_request_named_token_after(request: &str, marker: &str) -> Option<String> {
    let idx = request.find(marker)?;
    let after = request.get(idx + marker.len()..)?;
    extract_gui_request_token_from_rest(after)
}

fn extract_gui_request_token_from_rest(rest: &str) -> Option<String> {
    let trimmed = rest.trim_start();
    let trimmed = trimmed
        .trim_start_matches([':', '：', '=', '-', '>', '到', '为'])
        .trim_start();
    let trimmed = trimmed.trim_start_matches(['`', '"', '\'']);
    let token = trimmed
        .chars()
        .take_while(|ch| ch.is_ascii_alphanumeric() || matches!(*ch, '_' | '-' | '.'))
        .collect::<String>();
    (!token.is_empty()).then_some(token)
}

fn nearest_string_candidates<'a>(
    query: &str,
    values: impl Iterator<Item = &'a str>,
    limit: usize,
) -> Vec<String> {
    let query_lower = query.to_ascii_lowercase();
    let mut out = Vec::new();
    for value in values {
        let lower = value.to_ascii_lowercase();
        if lower.contains(&query_lower) || query_lower.contains(&lower) {
            push_capped_unique(&mut out, value.to_string(), limit);
        }
        if out.len() >= limit {
            break;
        }
    }
    out
}

fn nearest_or_first_string_candidates<'a>(
    query: &str,
    values: impl Iterator<Item = &'a str>,
    limit: usize,
) -> Vec<String> {
    let values = values.map(str::to_string).collect::<Vec<_>>();
    let nearest = nearest_string_candidates(query, values.iter().map(String::as_str), limit);
    if nearest.is_empty() {
        values.into_iter().take(limit).collect()
    } else {
        nearest
    }
}

