fn gui_request_mount_catalog_json(
    mod_root: &Path,
    game_root: &Path,
    style_roots: &[PathBuf],
    reports: &[LargeModGuiPatternProfile],
    style_tokens: &GuiStyleTemplateTokens,
    code_index: &GameIndex,
) -> String {
    let style_mods = style_roots
        .iter()
        .map(|root| root.display().to_string())
        .collect::<Vec<_>>();
    let parent_tokens = style_tokens
        .parent_window_tokens
        .iter()
        .take(80)
        .map(|token| {
            format!(
                "    {{\"token\": {}, \"status\": \"style_evidence_ready\", \"evidence\": {}, \"repair_rule\": {}}}",
                json_str(token),
                json_array(&gui_mount_catalog_style_evidence(
                    &style_tokens.style_token_evidence,
                    "parent_window_token",
                    token,
                )),
                json_str("Use this value as mount.parent_window_token for topbar/parent-window GUI only after gui-mount-audit passes."),
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    let map_windows = gui_mount_catalog_window_candidates(reports, style_tokens)
        .into_iter()
        .take(120)
        .map(|window| {
            format!(
                "    {{\"window_name\": {}, \"status\": \"interface_window_evidence_ready\", \"evidence\": {}, \"repair_rule\": {}}}",
                json_str(&window),
                json_array(&gui_mount_catalog_style_evidence(
                    &style_tokens.style_token_evidence,
                    "window_name",
                    &window,
                )),
                json_str("Use this as map_window/window evidence only when it matches the intended parent GUI opening path."),
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    let decision_categories = code_index
        .decision_categories
        .iter()
        .take(120)
        .map(|category| {
            format!(
                "    {{\"decision_category\": {}, \"status\": \"strict_code_index_ready\", \"evidence\": {}, \"repair_rule\": {}}}",
                json_str(category),
                json_array(&[format!("indexed_decision_category:{category}")]),
                json_str("Use this value as mount.decision_category for decision_attached GUI; do not invent category ids."),
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_mount_catalog.v1\",\n  \"status\": \"ready\",\n  \"mod_root\": {},\n  \"game_root\": {},\n  \"style_mods\": {},\n  \"mount_contracts\": {},\n  \"gui_kind_catalog\": {},\n  \"parent_window_token_candidates\": [\n{}\n  ],\n  \"decision_category_candidates\": [\n{}\n  ],\n  \"map_window_candidates\": [\n{}\n  ],\n  \"style_mount_examples\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(&mod_root.display().to_string()),
        json_str(&game_root.display().to_string()),
        json_array(&style_mods),
        gui_mount_contracts_json(),
        gui_mount_catalog_kind_catalog_json(style_tokens, code_index, reports),
        parent_tokens,
        decision_categories,
        map_windows,
        gui_style_examples_json(reports),
        json_array(&[
            "Unknown parent_window_token, decision_category, or map_window must be chosen from this catalog or supplied with new evidence before final write.".to_string(),
            "Catalog candidates are evidence for authoring; final acceptance still requires gui-mount-audit and strict-code-index.".to_string(),
        ]),
    )
}

fn gui_mount_catalog_style_evidence(evidence: &[String], kind: &str, value: &str) -> Vec<String> {
    let prefix = format!("{kind}:{value}:");
    evidence
        .iter()
        .filter(|item| item.starts_with(&prefix))
        .take(12)
        .cloned()
        .collect()
}

fn gui_mount_catalog_window_candidates(
    reports: &[LargeModGuiPatternProfile],
    style_tokens: &GuiStyleTemplateTokens,
) -> Vec<String> {
    let mut out = style_tokens.window_names.clone();
    for report in reports {
        for window in &report.interface_windows {
            push_capped_unique(&mut out, window.clone(), 500);
        }
    }
    out.sort();
    out.dedup();
    out
}

fn gui_mount_catalog_kind_catalog_json(
    style_tokens: &GuiStyleTemplateTokens,
    code_index: &GameIndex,
    reports: &[LargeModGuiPatternProfile],
) -> String {
    let map_window_ready = !gui_mount_catalog_window_candidates(reports, style_tokens).is_empty();
    let items = [
        (
            "standalone",
            true,
            "requires generated scripted_gui/window_name/open-close protocol",
        ),
        (
            "topbar_mount",
            !style_tokens.parent_window_tokens.is_empty(),
            "requires parent_window_token from parent_window_token_candidates",
        ),
        (
            "decision_attached",
            !code_index.decision_categories.is_empty(),
            "requires decision_category from strict-code-index candidates",
        ),
        (
            "map_window",
            map_window_ready,
            "requires map_window/interface window evidence",
        ),
    ]
    .into_iter()
    .map(|(kind, ready, rule)| {
        format!(
            "\"{kind}\": {{\"ready\": {}, \"rule\": {}}}",
            json_bool(ready),
            json_str(rule)
        )
    })
    .collect::<Vec<_>>()
    .join(", ");
    format!("{{{items}}}")
}

