fn gui_error_regression_report_json(
    mod_root: &Path,
    input: &Path,
    analysis_report: &Path,
    analysis_text: &str,
    changed_files: &[String],
    baseline: Option<&str>,
    analysis_error: Option<&str>,
) -> String {
    let gui_diagnostics = gui_error_regression_diagnostic_objects(analysis_text);
    let effective = status_json_i64_field(analysis_text, "diagnostics_effective").unwrap_or(0);
    let baseline_filtered = status_json_i64_field(analysis_text, "baseline_filtered").unwrap_or(0);
    let gui_count = gui_diagnostics.len();
    let non_gui_effective = effective.saturating_sub(gui_count as i64);
    let baseline_separated = baseline.is_none() || analysis_error.is_none();
    let changed_file_attribution = changed_files.is_empty()
        || gui_diagnostics.iter().all(|object| {
            status_json_string_field(object, "file").is_some()
                || status_json_string_field(object, "resolved_file").is_some()
        });
    let ok = analysis_error.is_none() && gui_count == 0;
    let status = if ok {
        "passed"
    } else if analysis_error.is_some() {
        "analysis_failed"
    } else {
        "blocked"
    };
    let objective = vec![
        gui_request_acceptance_item_json(
            "baseline_separation",
            "Existing error.log diagnostics are separated from new GUI regressions when a baseline is supplied.",
            baseline_separated,
            "analyze-error-log.baseline_filtered",
        ),
        gui_request_acceptance_item_json(
            "gui_error_classification",
            "GUI-related diagnostics are classified separately from unrelated log noise.",
            analysis_error.is_none(),
            "gui_error_diagnostics",
        ),
        gui_request_acceptance_item_json(
            "changed_file_attribution",
            "GUI diagnostics are attributable to changed files when changed-only mode is used.",
            changed_file_attribution,
            "changed_files + diagnostic.file/resolved_file",
        ),
        gui_request_acceptance_item_json(
            "no_new_gui_errors",
            "No new GUI-related error.log diagnostics remain after baseline and changed-file filtering.",
            ok,
            "gui_error_diagnostic_count == 0",
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_error_regression.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"mod_root\": {},\n  \"input\": {},\n  \"baseline\": {},\n  \"analysis_report\": {},\n  \"analysis_error\": {},\n  \"changed_files\": {},\n  \"diagnostics_effective\": {},\n  \"baseline_filtered\": {},\n  \"non_gui_effective_count\": {},\n  \"gui_error_diagnostic_count\": {},\n  \"gui_error_diagnostics\": [\n{}\n  ],\n  \"objective_acceptance\": [\n{}\n  ],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(ok),
        json_str(&mod_root.display().to_string()),
        json_str(&input.display().to_string()),
        json_optional_str(baseline),
        json_str(&analysis_report.display().to_string()),
        json_optional_str(analysis_error),
        json_array(changed_files),
        effective,
        baseline_filtered,
        non_gui_effective,
        gui_count,
        gui_diagnostics
            .iter()
            .map(|object| format!("    {object}"))
            .collect::<Vec<_>>()
            .join(",\n"),
        objective.join(",\n"),
        json_array(&[
            format!(
                "hoi4skill repair-failed-output --input {} --kind error-log-report --mod-root {} --output .hoi4skill/gui_error_repair.md",
                analysis_report.display(),
                mod_root.display(),
            ),
            format!(
                "hoi4skill gui-request-workflow --mod-root {} --game-root <HOI4 root> --error-log {} --error-log-baseline <baseline> --require-passed",
                mod_root.display(),
                input.display(),
            ),
        ]),
        json_array(&[
            "Do not claim GUI runtime cleanliness while gui_error_diagnostic_count > 0.".to_string(),
            "Old baseline errors are not release blockers, but new GUI-related diagnostics are.".to_string(),
            "If changed_files is empty, this is a full GUI log scan rather than a changed-only attribution proof.".to_string(),
        ]),
    )
}

fn gui_error_regression_diagnostic_objects(report_text: &str) -> Vec<String> {
    json_objects_in_array_field(report_text, "diagnostics")
        .into_iter()
        .filter(|object| {
            let category = status_json_string_field(object, "category").unwrap_or_default();
            let file = status_json_string_field(object, "file")
                .or_else(|| status_json_string_field(object, "resolved_file"))
                .unwrap_or_default();
            let message = status_json_string_field(object, "message").unwrap_or_default();
            gui_error_log_text_is_gui_related(
                &format!("{category} {file} {message}").to_ascii_lowercase(),
            )
        })
        .take(80)
        .collect()
}

fn gui_visual_smoke_report_json(
    mod_root: &Path,
    game_root: &Path,
    apply_report: &Path,
    code_passed: bool,
    visual_passed: bool,
    window_name: Option<&str>,
    screenshot: Option<&Path>,
    evidence_log: Option<&Path>,
    resolution: Option<&str>,
    ui_scale: Option<&str>,
    strict_image_required: bool,
    min_dimensions: (u32, u32),
    screenshot_probe: Option<&GuiImageProbe>,
    screenshot_hash: Option<&str>,
    strict_screenshot_ready: bool,
    window_opened: bool,
    screenshot_ok: bool,
    resolution_ok: bool,
    ui_scale_ok: bool,
    text_fit_ok: bool,
    click_evidence_ok: bool,
) -> String {
    let status = if visual_passed {
        "passed"
    } else if code_passed {
        "code_only_needs_visual_evidence"
    } else {
        "blocked_until_code_passes"
    };
    let objective = vec![
        gui_request_acceptance_item_json(
            "code_passed",
            "GUI code already passed apply-gui-intent final checks.",
            code_passed,
            "apply_report.ok + final_check_ok + strict_validation_ok",
        ),
        gui_request_acceptance_item_json(
            "window_open_evidence",
            "The generated GUI window was opened in game or by an automation run.",
            window_opened,
            "window-opened flag, window evidence, or evidence log",
        ),
        gui_request_acceptance_item_json(
            "visual_evidence",
            "A screenshot or equivalent visual artifact exists for the opened GUI.",
            screenshot_ok,
            "screenshot path exists",
        ),
        gui_request_acceptance_item_json(
            "strict_screenshot",
            "When requested, visual smoke screenshot is a readable image with sufficient dimensions.",
            strict_screenshot_ready,
            "screenshot image header + dimensions",
        ),
        gui_request_acceptance_item_json(
            "resolution_and_scale",
            "Resolution and UI scale evidence were supplied.",
            resolution_ok && ui_scale_ok,
            "resolution + ui-scale/default-ui-scale",
        ),
        gui_request_acceptance_item_json(
            "text_fit",
            "Visible GUI text was checked for overflow.",
            text_fit_ok,
            "text-fit-ok or text-fit report",
        ),
        gui_request_acceptance_item_json(
            "click_evidence",
            "Key GUI button click/effect path has evidence.",
            click_evidence_ok,
            "click-evidence or button-clicked flag",
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_visual_smoke.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"code_passed\": {},\n  \"visual_passed\": {},\n  \"mod_root\": {},\n  \"game_root\": {},\n  \"apply_report\": {},\n  \"window_name\": {},\n  \"screenshot\": {},\n  \"screenshot_hash\": {},\n  \"evidence_log\": {},\n  \"resolution\": {},\n  \"ui_scale\": {},\n  \"strict_image_required\": {},\n  \"strict_screenshot_ready\": {},\n  \"min_width\": {},\n  \"min_height\": {},\n  \"image_probe\": {},\n  \"checks\": {{\"window_opened\": {}, \"screenshot_ok\": {}, \"strict_screenshot_ready\": {}, \"resolution_ok\": {}, \"ui_scale_ok\": {}, \"text_fit_ok\": {}, \"click_evidence_ok\": {}}},\n  \"objective_acceptance\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(visual_passed),
        json_bool(code_passed),
        json_bool(visual_passed),
        json_str(&mod_root.display().to_string()),
        json_str(&game_root.display().to_string()),
        json_str(&apply_report.display().to_string()),
        json_optional_str(window_name),
        screenshot
            .map(|path| json_str(&path.display().to_string()))
            .unwrap_or_else(|| "null".to_string()),
        json_optional_str(screenshot_hash),
        evidence_log
            .map(|path| json_str(&path.display().to_string()))
            .unwrap_or_else(|| "null".to_string()),
        json_optional_str(resolution),
        json_optional_str(ui_scale),
        json_bool(strict_image_required),
        json_bool(strict_screenshot_ready),
        min_dimensions.0,
        min_dimensions.1,
        gui_runtime_image_probe_json(screenshot_probe),
        json_bool(window_opened),
        json_bool(screenshot_ok),
        json_bool(strict_screenshot_ready),
        json_bool(resolution_ok),
        json_bool(ui_scale_ok),
        json_bool(text_fit_ok),
        json_bool(click_evidence_ok),
        objective.join(",\n"),
        json_array(&[
            "Do not claim playable GUI acceptance while visual_passed=false.".to_string(),
            "Code-passed GUI can still fail visual smoke if no screenshot/window/text/click evidence is supplied.".to_string(),
        ]),
    )
}

#[allow(clippy::too_many_arguments)]
fn gui_runtime_visual_matrix_report_json(
    mod_root: &Path,
    visual_reports: &[PathBuf],
    visual_probes: &[PathBuf],
    screenshot_reports: &[PathBuf],
    required_resolutions: &[String],
    required_scales: &[String],
    min_visual_reports: usize,
    require_visual_probe: bool,
    require_screenshot_report: bool,
    require_screenshot_hash: bool,
) -> String {
    let mut entries = Vec::new();
    let mut ready_visual_reports = 0usize;
    let mut available_resolutions = BTreeSet::new();
    let mut available_scales = BTreeSet::new();
    let mut screenshot_hashes = BTreeSet::new();
    let mut blockers = Vec::new();
    for path in visual_reports {
        let text = read_utf8_lossy(path).unwrap_or_default();
        let schema_ok = status_json_string_field(&text, "schema").as_deref()
            == Some("hoi4skill.gui_visual_smoke.v1");
        let visual_passed =
            status_json_top_level_bool_field_has_value(&text, "visual_passed", true);
        let hash = status_json_string_field(&text, "screenshot_hash");
        let hash_ready = !require_screenshot_hash || hash.as_deref().is_some_and(|v| !v.is_empty());
        let ready = schema_ok && visual_passed && hash_ready;
        if ready {
            ready_visual_reports += 1;
        }
        if let Some(resolution) = status_json_string_field(&text, "resolution") {
            available_resolutions.insert(normalize_gui_matrix_token(&resolution));
        }
        if let Some(scale) = status_json_string_field(&text, "ui_scale") {
            available_scales.insert(normalize_gui_matrix_token(&scale));
        }
        if let Some(hash) = &hash {
            if !hash.trim().is_empty() {
                screenshot_hashes.insert(hash.clone());
            }
        }
        if !ready {
            blockers.push(format!("visual_smoke_not_ready:{}", path.display()));
        }
        entries.push(gui_runtime_visual_matrix_entry_json(
            "visual_smoke",
            path,
            ready,
            status_json_string_field(&text, "status").as_deref(),
            status_json_string_field(&text, "resolution").as_deref(),
            status_json_string_field(&text, "ui_scale").as_deref(),
            hash.as_deref(),
        ));
    }

    let mut ready_visual_probes = 0usize;
    for path in visual_probes {
        let text = read_utf8_lossy(path).unwrap_or_default();
        let ready = status_json_string_field(&text, "schema").as_deref()
            == Some("hoi4skill.gui_runtime_visual_probe.v1")
            && status_json_top_level_bool_field_has_value(&text, "visual_probe_ready", true);
        if ready {
            ready_visual_probes += 1;
        } else {
            blockers.push(format!("runtime_visual_probe_not_ready:{}", path.display()));
        }
        entries.push(gui_runtime_visual_matrix_entry_json(
            "runtime_visual_probe",
            path,
            ready,
            status_json_string_field(&text, "status").as_deref(),
            status_json_string_field(&text, "resolution").as_deref(),
            None,
            None,
        ));
    }

    let mut ready_screenshot_reports = 0usize;
    for path in screenshot_reports {
        let text = read_utf8_lossy(path).unwrap_or_default();
        let hash = status_json_string_field(&text, "screenshot_hash");
        let hash_ready = !require_screenshot_hash || hash.as_deref().is_some_and(|v| !v.is_empty());
        let ready = status_json_string_field(&text, "schema").as_deref()
            == Some("hoi4skill.gui_runtime_screenshot.v1")
            && status_json_top_level_bool_field_has_value(&text, "screenshot_ready", true)
            && hash_ready;
        if ready {
            ready_screenshot_reports += 1;
        } else {
            blockers.push(format!("runtime_screenshot_not_ready:{}", path.display()));
        }
        if let Some(hash) = &hash {
            if !hash.trim().is_empty() {
                screenshot_hashes.insert(hash.clone());
            }
        }
        entries.push(gui_runtime_visual_matrix_entry_json(
            "runtime_screenshot",
            path,
            ready,
            status_json_string_field(&text, "status").as_deref(),
            None,
            None,
            hash.as_deref(),
        ));
    }

    let missing_resolutions = required_resolutions
        .iter()
        .filter(|value| !available_resolutions.contains(*value))
        .cloned()
        .collect::<Vec<_>>();
    let missing_scales = required_scales
        .iter()
        .filter(|value| !available_scales.contains(*value))
        .cloned()
        .collect::<Vec<_>>();
    if visual_reports.is_empty() {
        blockers.push("gui_visual_smoke_report_required".to_string());
    }
    if ready_visual_reports < min_visual_reports {
        blockers.push(format!(
            "ready_visual_smoke_reports_below_min:{ready_visual_reports}/{min_visual_reports}"
        ));
    }
    for resolution in &missing_resolutions {
        blockers.push(format!("missing_required_resolution:{resolution}"));
    }
    for scale in &missing_scales {
        blockers.push(format!("missing_required_ui_scale:{scale}"));
    }
    if require_visual_probe && ready_visual_probes == 0 {
        blockers.push("gui_runtime_visual_probe.visual_probe_ready=true".to_string());
    }
    if require_screenshot_report && ready_screenshot_reports == 0 {
        blockers.push("gui_runtime_screenshot.screenshot_ready=true".to_string());
    }
    if require_screenshot_hash && screenshot_hashes.is_empty() {
        blockers.push("screenshot_hash_required".to_string());
    }
    blockers.sort();
    blockers.dedup();

    let report_count_ready = ready_visual_reports >= min_visual_reports;
    let resolution_matrix_ready = missing_resolutions.is_empty();
    let scale_matrix_ready = missing_scales.is_empty();
    let visual_probe_ready = !require_visual_probe || ready_visual_probes > 0;
    let screenshot_report_ready = !require_screenshot_report || ready_screenshot_reports > 0;
    let screenshot_hash_ready = !require_screenshot_hash || !screenshot_hashes.is_empty();
    let visual_matrix_ready = !visual_reports.is_empty()
        && report_count_ready
        && resolution_matrix_ready
        && scale_matrix_ready
        && visual_probe_ready
        && screenshot_report_ready
        && screenshot_hash_ready;
    let status = if visual_matrix_ready {
        "visual_matrix_ready"
    } else if visual_reports.is_empty() {
        "blocked_missing_visual_smoke"
    } else if !report_count_ready {
        "blocked_visual_report_count"
    } else if !resolution_matrix_ready {
        "blocked_resolution_matrix"
    } else if !scale_matrix_ready {
        "blocked_ui_scale_matrix"
    } else if !visual_probe_ready {
        "blocked_runtime_visual_probe"
    } else if !screenshot_report_ready {
        "blocked_runtime_screenshot"
    } else {
        "blocked_screenshot_hash"
    };
    let available_resolutions_vec = available_resolutions.into_iter().collect::<Vec<_>>();
    let available_scales_vec = available_scales.into_iter().collect::<Vec<_>>();
    let screenshot_hashes_vec = screenshot_hashes.into_iter().collect::<Vec<_>>();
    let objective = vec![
        gui_request_acceptance_item_json(
            "visual_smoke_reports",
            "Every accepted visual matrix starts from machine-readable visual smoke reports.",
            !visual_reports.is_empty() && report_count_ready,
            "gui_visual_smoke.visual_passed",
        ),
        gui_request_acceptance_item_json(
            "resolution_matrix",
            "Required resolutions are represented by passing visual smoke reports.",
            resolution_matrix_ready,
            "require-resolution",
        ),
        gui_request_acceptance_item_json(
            "ui_scale_matrix",
            "Required UI scales are represented by passing visual smoke reports.",
            scale_matrix_ready,
            "require-ui-scale",
        ),
        gui_request_acceptance_item_json(
            "runtime_visual_probe",
            "When requested, visual smoke is tied to target-aware runtime visual probe evidence.",
            visual_probe_ready,
            "gui_runtime_visual_probe.visual_probe_ready",
        ),
        gui_request_acceptance_item_json(
            "runtime_screenshot",
            "When requested, visual matrix has a ready runtime screenshot report.",
            screenshot_report_ready,
            "gui_runtime_screenshot.screenshot_ready",
        ),
        gui_request_acceptance_item_json(
            "screenshot_hash",
            "When requested, visual matrix records screenshot hashes for evidence consistency.",
            screenshot_hash_ready,
            "screenshot_hash",
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_runtime_visual_matrix.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"visual_matrix_ready\": {},\n  \"mod_root\": {},\n  \"min_visual_reports\": {},\n  \"ready_visual_reports\": {},\n  \"ready_visual_probes\": {},\n  \"ready_screenshot_reports\": {},\n  \"require_visual_probe\": {},\n  \"require_screenshot_report\": {},\n  \"require_screenshot_hash\": {},\n  \"required_resolutions\": {},\n  \"available_resolutions\": {},\n  \"missing_resolutions\": {},\n  \"required_ui_scales\": {},\n  \"available_ui_scales\": {},\n  \"missing_ui_scales\": {},\n  \"screenshot_hashes\": {},\n  \"checks\": {{\"report_count_ready\": {}, \"resolution_matrix_ready\": {}, \"ui_scale_matrix_ready\": {}, \"visual_probe_ready\": {}, \"screenshot_report_ready\": {}, \"screenshot_hash_ready\": {}}},\n  \"reports\": [\n{}\n  ],\n  \"blockers\": {},\n  \"objective_acceptance\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(visual_matrix_ready),
        json_bool(visual_matrix_ready),
        json_str(&mod_root.display().to_string()),
        min_visual_reports,
        ready_visual_reports,
        ready_visual_probes,
        ready_screenshot_reports,
        json_bool(require_visual_probe),
        json_bool(require_screenshot_report),
        json_bool(require_screenshot_hash),
        json_array(&required_resolutions.to_vec()),
        json_array(&available_resolutions_vec),
        json_array(&missing_resolutions),
        json_array(&required_scales.to_vec()),
        json_array(&available_scales_vec),
        json_array(&missing_scales),
        json_array(&screenshot_hashes_vec),
        json_bool(report_count_ready),
        json_bool(resolution_matrix_ready),
        json_bool(scale_matrix_ready),
        json_bool(visual_probe_ready),
        json_bool(screenshot_report_ready),
        json_bool(screenshot_hash_ready),
        entries.join(",\n"),
        json_array(&blockers),
        objective.join(",\n"),
        json_array(&[
            "Do not claim multi-resolution GUI acceptance from one visual smoke report unless the target matrix has only one resolution.".to_string(),
            "Weak AI may add report paths or rerun visual smoke, but must not handwrite visual_matrix_ready=true.".to_string(),
            "Use runtime visual probe and screenshot reports when matrix acceptance needs target-widget and hash evidence.".to_string(),
        ]),
    )
}

fn gui_runtime_visual_matrix_entry_json(
    kind: &str,
    path: &Path,
    ready: bool,
    status: Option<&str>,
    resolution: Option<&str>,
    ui_scale: Option<&str>,
    screenshot_hash: Option<&str>,
) -> String {
    format!(
        "    {{\"kind\": {}, \"path\": {}, \"ready\": {}, \"status\": {}, \"resolution\": {}, \"ui_scale\": {}, \"screenshot_hash\": {}}}",
        json_str(kind),
        json_str(&path.display().to_string()),
        json_bool(ready),
        json_optional_str(status),
        json_optional_str(resolution),
        json_optional_str(ui_scale),
        json_optional_str(screenshot_hash),
    )
}

fn gui_runtime_text_fit_matrix_report_json(
    mod_root: &Path,
    visual_reports: &[PathBuf],
    text_fit_reports: &[PathBuf],
    required_resolutions: &[String],
    required_scales: &[String],
    require_no_overflow: bool,
    require_reports: bool,
) -> String {
    let mut entries = Vec::new();
    let mut ready_visual_reports = 0usize;
    let mut ready_text_fit_reports = 0usize;
    let mut available_resolutions = BTreeSet::new();
    let mut available_scales = BTreeSet::new();
    let mut blockers = Vec::new();

    for path in visual_reports {
        let text = read_utf8_lossy(path).unwrap_or_default();
        let schema_ok = status_json_string_field(&text, "schema").as_deref()
            == Some("hoi4skill.gui_visual_smoke.v1");
        let visual_passed =
            status_json_top_level_bool_field_has_value(&text, "visual_passed", true);
        let text_fit_true = status_json_bool_field_has_value(&text, "text_fit_ok", true);
        let text_fit_false = status_json_bool_field_has_value(&text, "text_fit_ok", false);
        let text_fit_ready = if require_no_overflow {
            text_fit_true && !text_fit_false
        } else {
            !text_fit_false || text_fit_true
        };
        let ready = schema_ok && visual_passed && text_fit_ready;
        if ready {
            ready_visual_reports += 1;
        } else if text_fit_false && require_no_overflow {
            blockers.push(format!("text_fit_overflow:{}", path.display()));
        } else {
            blockers.push(format!("visual_text_fit_not_ready:{}", path.display()));
        }
        if let Some(resolution) = status_json_string_field(&text, "resolution") {
            available_resolutions.insert(normalize_gui_matrix_token(&resolution));
        }
        if let Some(scale) = status_json_string_field(&text, "ui_scale") {
            available_scales.insert(normalize_gui_matrix_token(&scale));
        }
        entries.push(gui_runtime_text_fit_entry_json(
            "visual_smoke",
            path,
            ready,
            status_json_string_field(&text, "status").as_deref(),
            status_json_string_field(&text, "resolution").as_deref(),
            status_json_string_field(&text, "ui_scale").as_deref(),
            Some(text_fit_ready),
        ));
    }

    for path in text_fit_reports {
        let text = read_utf8_lossy(path).unwrap_or_default();
        let lower = text.to_ascii_lowercase();
        let explicit_failed = lower.contains("\"ok\": false")
            || lower.contains("\"text_fit_ok\": false")
            || lower.contains("\"overflow\": true")
            || lower.contains("text_overflow");
        let overflow_word = lower.contains("overflow") && !lower.contains("no overflow");
        let ready = !text.trim().is_empty() && !explicit_failed && !overflow_word;
        if ready {
            ready_text_fit_reports += 1;
        } else {
            blockers.push(format!("text_fit_report_not_ready:{}", path.display()));
        }
        entries.push(gui_runtime_text_fit_entry_json(
            "text_fit_report",
            path,
            ready,
            status_json_string_field(&text, "status").as_deref(),
            status_json_string_field(&text, "resolution").as_deref(),
            status_json_string_field(&text, "ui_scale").as_deref(),
            Some(ready),
        ));
    }

    let missing_resolutions = required_resolutions
        .iter()
        .filter(|value| !available_resolutions.contains(*value))
        .cloned()
        .collect::<Vec<_>>();
    let missing_scales = required_scales
        .iter()
        .filter(|value| !available_scales.contains(*value))
        .cloned()
        .collect::<Vec<_>>();
    if visual_reports.is_empty() {
        blockers.push("gui_visual_smoke_report_required".to_string());
    }
    if require_reports && text_fit_reports.is_empty() {
        blockers.push("text_fit_report_required".to_string());
    }
    for resolution in &missing_resolutions {
        blockers.push(format!("missing_required_resolution:{resolution}"));
    }
    for scale in &missing_scales {
        blockers.push(format!("missing_required_ui_scale:{scale}"));
    }
    blockers.sort();
    blockers.dedup();

    let visual_report_count_ready =
        !visual_reports.is_empty() && ready_visual_reports == visual_reports.len();
    let text_report_ready = !require_reports || ready_text_fit_reports > 0;
    let resolution_matrix_ready = missing_resolutions.is_empty();
    let scale_matrix_ready = missing_scales.is_empty();
    let text_fit_matrix_ready = visual_report_count_ready
        && text_report_ready
        && resolution_matrix_ready
        && scale_matrix_ready
        && blockers.is_empty();
    let status = if text_fit_matrix_ready {
        "text_fit_matrix_ready"
    } else if visual_reports.is_empty() {
        "blocked_missing_visual_smoke"
    } else if !visual_report_count_ready {
        "blocked_text_overflow"
    } else if !resolution_matrix_ready {
        "blocked_resolution_matrix"
    } else if !scale_matrix_ready {
        "blocked_ui_scale_matrix"
    } else {
        "blocked_text_fit_report"
    };
    let available_resolutions_vec = available_resolutions.into_iter().collect::<Vec<_>>();
    let available_scales_vec = available_scales.into_iter().collect::<Vec<_>>();
    let objective = vec![
        gui_request_acceptance_item_json(
            "visual_text_fit",
            "Every visual smoke report confirms visible text fits its GUI containers.",
            visual_report_count_ready,
            "gui_visual_smoke.checks.text_fit_ok",
        ),
        gui_request_acceptance_item_json(
            "text_fit_report",
            "When requested, a dedicated text-fit report exists and has no overflow failures.",
            text_report_ready,
            "text-fit-report",
        ),
        gui_request_acceptance_item_json(
            "resolution_matrix",
            "Required resolutions are covered by text-fit visual smoke evidence.",
            resolution_matrix_ready,
            "require-resolution",
        ),
        gui_request_acceptance_item_json(
            "ui_scale_matrix",
            "Required UI scales are covered by text-fit visual smoke evidence.",
            scale_matrix_ready,
            "require-ui-scale",
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_runtime_text_fit_matrix.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"text_fit_matrix_ready\": {},\n  \"mod_root\": {},\n  \"require_no_overflow\": {},\n  \"require_text_fit_reports\": {},\n  \"ready_visual_reports\": {},\n  \"ready_text_fit_reports\": {},\n  \"required_resolutions\": {},\n  \"available_resolutions\": {},\n  \"missing_resolutions\": {},\n  \"required_ui_scales\": {},\n  \"available_ui_scales\": {},\n  \"missing_ui_scales\": {},\n  \"checks\": {{\"visual_report_count_ready\": {}, \"text_report_ready\": {}, \"resolution_matrix_ready\": {}, \"ui_scale_matrix_ready\": {}}},\n  \"reports\": [\n{}\n  ],\n  \"blockers\": {},\n  \"objective_acceptance\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(text_fit_matrix_ready),
        json_bool(text_fit_matrix_ready),
        json_str(&mod_root.display().to_string()),
        json_bool(require_no_overflow),
        json_bool(require_reports),
        ready_visual_reports,
        ready_text_fit_reports,
        json_array(&required_resolutions.to_vec()),
        json_array(&available_resolutions_vec),
        json_array(&missing_resolutions),
        json_array(&required_scales.to_vec()),
        json_array(&available_scales_vec),
        json_array(&missing_scales),
        json_bool(visual_report_count_ready),
        json_bool(text_report_ready),
        json_bool(resolution_matrix_ready),
        json_bool(scale_matrix_ready),
        entries
            .iter()
            .map(|entry| format!("    {entry}"))
            .collect::<Vec<_>>()
            .join(",\n"),
        json_array(&blockers),
        objective.join(",\n"),
        json_array(&[
            "Do not accept GUI runtime evidence when any visual text overflows its container.".to_string(),
            "Required resolution/UI-scale coverage must be proven by visual smoke reports, not inferred from design intent.".to_string(),
        ]),
    )
}

fn gui_runtime_text_fit_entry_json(
    kind: &str,
    path: &Path,
    ready: bool,
    status: Option<&str>,
    resolution: Option<&str>,
    ui_scale: Option<&str>,
    text_fit_ok: Option<bool>,
) -> String {
    format!(
        "{{\"kind\": {}, \"path\": {}, \"ready\": {}, \"status\": {}, \"resolution\": {}, \"ui_scale\": {}, \"text_fit_ok\": {}}}",
        json_str(kind),
        json_str(&path.display().to_string()),
        json_bool(ready),
        json_optional_str(status),
        json_optional_str(resolution),
        json_optional_str(ui_scale),
        text_fit_ok.map(json_bool).unwrap_or("null"),
    )
}

fn normalize_gui_matrix_token(value: &str) -> String {
    value.trim().to_ascii_lowercase().replace(' ', "")
}

fn gui_playability_gate_report_json(
    mod_root: &Path,
    apply_report: &Path,
    error_report: Option<&Path>,
    visual_report: Option<&Path>,
    game_smoke_report: Option<&Path>,
    runtime_evidence_bundle: Option<&Path>,
    text_fit_matrix: Option<&Path>,
    code_passed: bool,
    error_regression_passed: bool,
    visual_passed: bool,
    game_smoke_required: bool,
    game_smoke_passed: bool,
    game_smoke_passed_raw: bool,
    game_smoke_launch_plan_passed: bool,
    runtime_evidence_bundle_required: bool,
    runtime_evidence_bundle_ready: bool,
    text_fit_matrix_required: bool,
    text_fit_matrix_ready: bool,
    playable_ready: bool,
) -> String {
    let status = if playable_ready {
        "playable_ready"
    } else if !code_passed {
        "blocked_code"
    } else if !error_regression_passed {
        "blocked_error_regression"
    } else if text_fit_matrix_required && !text_fit_matrix_ready {
        "blocked_text_fit_matrix"
    } else if runtime_evidence_bundle_required && !runtime_evidence_bundle_ready {
        "blocked_runtime_evidence_bundle"
    } else if game_smoke_required && !game_smoke_passed {
        "blocked_game_smoke"
    } else {
        "blocked_visual_smoke"
    };
    let mut missing = Vec::new();
    if !code_passed {
        missing.push("apply-gui-intent final-check evidence".to_string());
    }
    if error_report.is_none() {
        missing.push("gui-error-regression report".to_string());
    } else if !error_regression_passed {
        missing.push("passing gui-error-regression report".to_string());
    }
    if visual_report.is_none() {
        missing.push("gui-visual-smoke report".to_string());
    } else if !visual_passed {
        missing.push("passing gui-visual-smoke report".to_string());
    }
    if game_smoke_required && game_smoke_report.is_none() {
        missing.push("gui-game-smoke runtime report".to_string());
    } else if game_smoke_required && !game_smoke_passed_raw {
        missing.push("passing gui-game-smoke runtime report".to_string());
    } else if game_smoke_required && !game_smoke_launch_plan_passed {
        missing.push("gui-game-smoke launch-plan evidence".to_string());
    }
    if runtime_evidence_bundle_required && runtime_evidence_bundle.is_none() {
        missing.push("gui-runtime-evidence-bundle report".to_string());
    } else if runtime_evidence_bundle_required && !runtime_evidence_bundle_ready {
        missing.push("passing gui-runtime-evidence-bundle report".to_string());
    }
    if text_fit_matrix_required && text_fit_matrix.is_none() {
        missing.push("gui-runtime-text-fit-matrix report".to_string());
    } else if text_fit_matrix_required && !text_fit_matrix_ready {
        missing.push("passing gui-runtime-text-fit-matrix report".to_string());
    }
    let next_commands = gui_playability_gate_next_commands(
        mod_root,
        apply_report,
        !error_regression_passed,
        !visual_passed,
        game_smoke_required && !game_smoke_passed,
        runtime_evidence_bundle_required && !runtime_evidence_bundle_ready,
        text_fit_matrix_required && !text_fit_matrix_ready,
    );
    let blocking_details = gui_playability_gate_blocking_details_json(
        apply_report,
        error_report,
        visual_report,
        game_smoke_report,
        runtime_evidence_bundle,
        text_fit_matrix,
        code_passed,
        error_regression_passed,
        visual_passed,
        game_smoke_required,
        game_smoke_passed,
        game_smoke_passed_raw,
        game_smoke_launch_plan_passed,
        runtime_evidence_bundle_required,
        runtime_evidence_bundle_ready,
        text_fit_matrix_required,
        text_fit_matrix_ready,
    );
    let objective = vec![
        gui_request_acceptance_item_json(
            "code_final_check",
            "Generated GUI code passed apply-gui-intent final checks and strict-code-index.",
            code_passed,
            "apply_report.ok + final_check_ok + strict_validation_ok",
        ),
        gui_request_acceptance_item_json(
            "gui_error_regression",
            "No new GUI-related error.log diagnostics were introduced after write.",
            error_regression_passed,
            "gui-error-regression.ok",
        ),
        gui_request_acceptance_item_json(
            "visual_smoke",
            "In-game GUI smoke evidence proves the window opens, text fits, and key buttons work.",
            visual_passed,
            "gui-visual-smoke.visual_passed",
        ),
        gui_request_acceptance_item_json(
            "no_missing_evidence",
            "Playable acceptance has code, error-log, and visual evidence.",
            missing.is_empty(),
            "missing_evidence",
        ),
        gui_request_acceptance_item_json(
            "game_runtime_smoke",
            "When required, runtime game smoke evidence proves the generated GUI was opened in HOI4 with launch-plan evidence.",
            !game_smoke_required || game_smoke_passed,
            "gui_game_smoke.game_smoke_passed + launch_plan_passed",
        ),
        gui_request_acceptance_item_json(
            "runtime_text_fit_matrix",
            "When required, runtime text-fit matrix proves visible text does not overflow across required resolution/UI-scale evidence.",
            !text_fit_matrix_required || text_fit_matrix_ready,
            "gui_runtime_text_fit_matrix.text_fit_matrix_ready",
        ),
        gui_request_acceptance_item_json(
            "runtime_evidence_bundle",
            "When required, before/after log, screenshot, click, and state evidence are merged into one ready bundle.",
            !runtime_evidence_bundle_required || runtime_evidence_bundle_ready,
            "gui_runtime_evidence_bundle.bundle_ready",
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_playability_gate.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"playable_ready\": {},\n  \"code_passed\": {},\n  \"error_regression_passed\": {},\n  \"visual_passed\": {},\n  \"game_smoke_required\": {},\n  \"game_smoke_passed\": {},\n  \"game_smoke_report_passed\": {},\n  \"game_smoke_launch_plan_passed\": {},\n  \"runtime_evidence_bundle_required\": {},\n  \"runtime_evidence_bundle_ready\": {},\n  \"text_fit_matrix_required\": {},\n  \"text_fit_matrix_ready\": {},\n  \"mod_root\": {},\n  \"apply_report\": {},\n  \"gui_error_regression\": {},\n  \"gui_visual_smoke\": {},\n  \"gui_game_smoke\": {},\n  \"runtime_evidence_bundle\": {},\n  \"runtime_text_fit_matrix\": {},\n  \"missing_evidence\": {},\n  \"blocking_details\": {},\n  \"objective_acceptance\": [\n{}\n  ],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(playable_ready),
        json_bool(playable_ready),
        json_bool(code_passed),
        json_bool(error_regression_passed),
        json_bool(visual_passed),
        json_bool(game_smoke_required),
        json_bool(game_smoke_passed),
        json_bool(game_smoke_passed_raw),
        json_bool(game_smoke_launch_plan_passed),
        json_bool(runtime_evidence_bundle_required),
        json_bool(runtime_evidence_bundle_ready),
        json_bool(text_fit_matrix_required),
        json_bool(text_fit_matrix_ready),
        json_str(&mod_root.display().to_string()),
        json_str(&apply_report.display().to_string()),
        json_optional_str(error_report.map(|path| path.display().to_string()).as_deref()),
        json_optional_str(visual_report.map(|path| path.display().to_string()).as_deref()),
        json_optional_str(
            game_smoke_report
                .map(|path| path.display().to_string())
                .as_deref()
        ),
        json_optional_str(
            runtime_evidence_bundle
                .map(|path| path.display().to_string())
                .as_deref()
        ),
        json_optional_str(text_fit_matrix.map(|path| path.display().to_string()).as_deref()),
        json_array(&missing),
        blocking_details,
        objective.join(",\n"),
        json_array(&next_commands),
        json_array(&[
            "Do not claim generated GUI is playable unless playable_ready=true.".to_string(),
            "A passing apply report is code acceptance only; visual smoke and error-log regression are separate release gates.".to_string(),
        ]),
    )
}

fn gui_playability_gate_blocking_details_json(
    apply_report: &Path,
    error_report: Option<&Path>,
    visual_report: Option<&Path>,
    game_smoke_report: Option<&Path>,
    runtime_evidence_bundle: Option<&Path>,
    text_fit_matrix: Option<&Path>,
    code_passed: bool,
    error_regression_passed: bool,
    visual_passed: bool,
    game_smoke_required: bool,
    game_smoke_passed: bool,
    game_smoke_passed_raw: bool,
    game_smoke_launch_plan_passed: bool,
    runtime_evidence_bundle_required: bool,
    runtime_evidence_bundle_ready: bool,
    text_fit_matrix_required: bool,
    text_fit_matrix_ready: bool,
) -> String {
    let mut items = vec![
        gui_playability_gate_blocking_detail_json(
            "code_final_check",
            apply_report,
            if code_passed { "passed" } else { "blocking" },
            if code_passed {
                "apply-gui-intent final-check passed"
            } else {
                "rerun apply-gui-intent --execute --final-check --require-passed and inspect blockers"
            },
        ),
        gui_playability_gate_optional_blocking_detail_json(
            "gui_error_regression",
            error_report,
            error_regression_passed,
            "run gui-error-regression with baseline and changed files",
        ),
        gui_playability_gate_optional_blocking_detail_json(
            "visual_smoke",
            visual_report,
            visual_passed,
            "run gui-visual-smoke with window, screenshot, resolution, text-fit, and click evidence",
        ),
    ];
    if game_smoke_required || game_smoke_report.is_some() {
        items.push(gui_playability_gate_optional_blocking_detail_json(
            "game_runtime_smoke",
            game_smoke_report,
            game_smoke_passed,
            if game_smoke_passed_raw && !game_smoke_launch_plan_passed {
                "rerun gui-game-smoke-report with --runtime-launch-plan and --require-launch-plan so launch_plan_passed=true"
            } else {
                "provide gui_game_smoke.json with game_smoke_passed=true and launch_plan_passed=true after launching HOI4 and opening the generated GUI"
            },
        ));
    }
    if runtime_evidence_bundle_required || runtime_evidence_bundle.is_some() {
        items.push(gui_playability_gate_optional_blocking_detail_json(
            "runtime_evidence_bundle",
            runtime_evidence_bundle,
            runtime_evidence_bundle_ready,
            "provide gui_runtime_evidence_bundle.json with bundle_ready=true after collecting before/after log, screenshot, click, and state evidence",
        ));
    }
    if text_fit_matrix_required || text_fit_matrix.is_some() {
        items.push(gui_playability_gate_optional_blocking_detail_json(
            "runtime_text_fit_matrix",
            text_fit_matrix,
            text_fit_matrix_ready,
            "provide gui_runtime_text_fit_matrix.json with text_fit_matrix_ready=true after checking required resolution/UI-scale text overflow evidence",
        ));
    }
    format!("[\n{}\n  ]", items.join(",\n"))
}

fn gui_playability_gate_blocking_detail_json(
    id: &str,
    report: &Path,
    status: &str,
    required_action: &str,
) -> String {
    format!(
        "    {{\"id\": {}, \"status\": {}, \"report\": {}, \"required_action\": {}}}",
        json_str(id),
        json_str(status),
        json_str(&report.display().to_string()),
        json_str(required_action),
    )
}

fn gui_playability_gate_optional_blocking_detail_json(
    id: &str,
    report: Option<&Path>,
    passed: bool,
    required_action: &str,
) -> String {
    let status = if passed {
        "passed"
    } else if report.is_some() {
        "report_failed"
    } else {
        "missing_report"
    };
    format!(
        "    {{\"id\": {}, \"status\": {}, \"report\": {}, \"required_action\": {}}}",
        json_str(id),
        json_str(status),
        json_optional_str(report.map(|path| path.display().to_string()).as_deref()),
        json_str(required_action),
    )
}

fn gui_playability_gate_next_commands(
    mod_root: &Path,
    apply_report: &Path,
    needs_error_regression: bool,
    needs_visual_smoke: bool,
    needs_game_smoke: bool,
    needs_runtime_evidence_bundle: bool,
    needs_text_fit_matrix: bool,
) -> Vec<String> {
    let mut commands = Vec::new();
    if needs_error_regression {
        commands.push(format!(
            "hoi4skill gui-error-regression --mod-root {} --input <error.log> --baseline <baseline error report> --require-passed --output .hoi4skill/gui_error_regression.json",
            mod_root.display(),
        ));
    }
    if needs_visual_smoke {
        commands.push(format!(
            "hoi4skill gui-visual-smoke --mod-root {} --game-root <HOI4 root> --apply-report {} --window-name <generated window> --window-opened --screenshot <screenshot.png> --resolution 1920x1080 --ui-scale 1.0 --text-fit-ok --click-evidence <button/log evidence> --require-passed --output .hoi4skill/gui_visual_smoke.json",
            mod_root.display(),
            apply_report.display(),
        ));
    }
    if needs_game_smoke {
        commands.push(format!(
            "hoi4skill gui-playability-gate --mod-root {} --apply-report {} --gui-error-regression .hoi4skill/gui_error_regression.json --gui-visual-smoke .hoi4skill/gui_visual_smoke.json --game-smoke .hoi4skill/gui_game_smoke.json --require-game-smoke --require-passed --output .hoi4skill/gui_playability_gate.json",
            mod_root.display(),
            apply_report.display(),
        ));
    }
    if needs_runtime_evidence_bundle {
        commands.push(format!(
            "hoi4skill gui-runtime-evidence-bundle --mod-root {} --runtime-session-plan .hoi4skill/gui_runtime_session_plan.json --click-plan .hoi4skill/gui_runtime_click_plan.json --click-probe .hoi4skill/gui_runtime_click_probe.json --state-probe .hoi4skill/gui_runtime_state_probe.json --require-click-plan --require-click-probe --require-state-probe --require-passed --output .hoi4skill/gui_runtime_evidence_bundle.json",
            mod_root.display(),
        ));
    }
    if needs_text_fit_matrix {
        commands.push(format!(
            "hoi4skill gui-runtime-text-fit-matrix --mod-root {} --visual-smoke .hoi4skill/gui_visual_smoke.json --text-fit-report .hoi4skill/gui_text_fit_report.json --require-resolution 1920x1080 --require-ui-scale 1.0 --require-text-fit-report --require-passed --output .hoi4skill/gui_runtime_text_fit_matrix.json",
            mod_root.display(),
        ));
    }
    commands
}

fn gui_request_workflow_objective_acceptance_json(
    compiled: &GuiRequestCompiledIntent,
    smoke: &GuiRequestSmokeSummary,
    apply_report: &Path,
    ai_context_contract: &Path,
    related_code_context: &Path,
    mount_catalog: &Path,
    game_smoke_plan: &Path,
    runtime_launch_plan: &Path,
    runtime_open_plan: &Path,
    runtime_runner: &Path,
    runtime_collect_plan: &Path,
    runtime_evidence_contract: &Path,
    style_template_package: &GuiRequestStyleTemplatePackage,
    apply_error: Option<&str>,
    mount_audit: &Path,
    mount_audit_error: Option<&str>,
    ok: bool,
) -> String {
    let apply_text = read_utf8_lossy(apply_report).unwrap_or_default();
    let contract_exists = ai_context_contract.exists();
    let related_exists = related_code_context.exists();
    let mount_catalog_exists = mount_catalog.is_file()
        && read_utf8_lossy(mount_catalog).ok().is_some_and(|text| {
            status_json_string_field(&text, "schema").as_deref()
                == Some("hoi4skill.gui_mount_catalog.v1")
        });
    let game_smoke_plan_exists = game_smoke_plan.is_file();
    let runtime_launch_plan_exists = runtime_launch_plan.is_file();
    let runtime_open_plan_exists = runtime_open_plan.is_file();
    let runtime_runner_exists = runtime_runner.is_file();
    let runtime_collect_plan_exists = runtime_collect_plan.is_file();
    let runtime_evidence_contract_exists = runtime_evidence_contract.is_file();
    let mount_audit_text = read_utf8_lossy(mount_audit).unwrap_or_default();
    let mount_audit_ok = mount_audit.is_file()
        && status_json_string_field(&mount_audit_text, "schema").as_deref()
            == Some("hoi4skill.gui_mount_audit.v1")
        && status_json_bool_field_has_value(&mount_audit_text, "ok", true)
        && mount_audit_error.is_none();
    let style_package_ready =
        gui_request_style_template_package_ready(&style_template_package.manifest);
    let style_reuse_ok = ok
        && (apply_text.contains("\"style_source\": \"style_mod_auto_learned\"")
            || apply_text.contains("\"style_source\": \"style_template_file\""))
        && status_json_array_has_items(&apply_text, "style_evidence");
    let resource_resolution_ok = compiled
        .resource_resolution
        .iter()
        .all(|item| item.status != "blocking");
    let action_intent_ok = matches!(
        compiled.action_intent.status.as_str(),
        "safe_shell_only" | "verified_scripted_effect"
    );
    let asset_pipeline_ok = compiled.asset_pipeline.status == "no_missing_assets"
        || compiled.asset_pipeline.status == "questions_and_todo_ready";
    let component_template_plan_ok = compiled.component_template_plan.requested.is_empty()
        || !compiled.component_template_plan.selected.is_empty()
        || compiled.component_template_plan.available.is_empty();
    let output_audit_ok = smoke.output_audit_ok == Some(true);
    let output_plan_audit_ready = smoke.output_plan_audit_ready == Some(true);
    let final_check_ok = smoke.final_check_ok == Some(true);
    let text_alignment_ok =
        status_json_bool_field_has_value(&apply_text, "text_alignment_ok", true);
    let strict_code_index_ok =
        status_json_bool_field_has_value(&apply_text, "strict_validation_ok", true);
    let final_write_ok = ok
        && smoke.apply_status.as_deref() == Some("applied")
        && smoke.apply_final_code_safety_status.as_deref() == Some("written_after_final_check");
    let no_guessed_code_saved = if ok {
        final_write_ok && output_audit_ok && final_check_ok && strict_code_index_ok
    } else {
        smoke.changed_files.is_empty() && apply_error.is_some()
            || (!compiled.ok && smoke.changed_files.is_empty())
    };
    let blocking_report_ok = ok
        || (!compiled.blockers.is_empty() || apply_error.is_some())
            && contract_exists
            && related_exists
            && compiled
                .recommended_game_code
                .iter()
                .all(|candidate| candidate.status != "candidate_unverified_not_written");
    let items = vec![
        gui_request_acceptance_item_json(
            "structured_intent",
            "Natural-language GUI request produced hoi4skill.gui_intent.v1 fields.",
            compiled.ok,
            if compiled.ok {
                "intent_path"
            } else {
                "intent blocked before write"
            },
        ),
        gui_request_acceptance_item_json(
            "style_reuse",
            "Parent/target mod GUI style evidence was learned and used before final write.",
            style_reuse_ok,
            "apply_report.style_source + style_evidence",
        ),
        gui_request_acceptance_item_json(
            "style_template_package",
            "Workflow wrote a reusable parent-mod GUI style package for future GUI requests.",
            style_package_ready,
            "gui_style_template_package.json + style_tokens/control_examples/mount_examples/resource_index",
        ),
        gui_request_acceptance_item_json(
            "component_template_plan",
            "Requested GUI component layouts reuse parent-mod component templates when available.",
            component_template_plan_ok,
            "component_template_plan.requested + selected + missing",
        ),
        gui_request_acceptance_item_json(
            "resource_resolution",
            "All requested sprites, tags, mount points, and action helpers resolved or blocked.",
            resource_resolution_ok,
            "resource_resolution has no blocking items",
        ),
        gui_request_acceptance_item_json(
            "action_intent",
            "GUI button behavior is either safe shell behavior or an indexed scripted_effect helper.",
            action_intent_ok,
            "action_intent.status",
        ),
        gui_request_acceptance_item_json(
            "asset_pipeline",
            "Missing GUI assets produce asset_questions and asset_todo instead of guessed GFX code.",
            asset_pipeline_ok,
            "asset_pipeline.status + asset_questions + asset_todo",
        ),
        gui_request_acceptance_item_json(
            "text_alignment",
            "Visible GUI text was checked against the original user request.",
            text_alignment_ok,
            "final_check.text_alignment_ok",
        ),
        gui_request_acceptance_item_json(
            "strict_code_index",
            "Final generated GUI files passed strict-code-index validation.",
            strict_code_index_ok,
            "final_check.strict_validation_ok",
        ),
        gui_request_acceptance_item_json(
            "gui_output_audit",
            "Generated GUI/scripted_gui/localisation files passed output audit.",
            output_audit_ok,
            "apply_report.output_audit_ok",
        ),
        gui_request_acceptance_item_json(
            "gui_output_plan_audit",
            "Generated GUI output matches the structured intent/open-plan expectations for window, button, scripted_effect, and open flag.",
            output_plan_audit_ready,
            "apply_report.output_plan_audit_ready + output_audit.plan_audit_ready",
        ),
        gui_request_acceptance_item_json(
            "gui_mount_audit",
            "Generated scripted_gui mounts, window bindings, and parent/decision/map mount evidence passed audit.",
            mount_audit_ok,
            "gui_mount_audit.json",
        ),
        gui_request_acceptance_item_json(
            "final_write",
            "Workflow wrote GUI files only after final checks passed.",
            final_write_ok && mount_audit_ok,
            "smoke_summary.apply_status + changed_files + gui_mount_audit",
        ),
        gui_request_acceptance_item_json(
            "ai_context_contract",
            "Workflow wrote an AI context contract and related code context sidecar.",
            contract_exists && related_exists,
            "gui_ai_context_contract.json + gui_related_code_context.json",
        ),
        gui_request_acceptance_item_json(
            "gui_mount_catalog",
            "Workflow wrote a mount catalog with parent_window_token, decision_category, and map_window candidates.",
            mount_catalog_exists,
            "gui_mount_catalog.json",
        ),
        gui_request_acceptance_item_json(
            "game_smoke_plan",
            "Workflow wrote a runtime game-smoke plan before playable acceptance can be claimed.",
            game_smoke_plan_exists,
            "gui_game_smoke_plan.json",
        ),
        gui_request_acceptance_item_json(
            "runtime_launch_plan",
            "Workflow wrote a HOI4 runtime launch precondition plan before game smoke can be accepted.",
            runtime_launch_plan_exists,
            "gui_runtime_launch_plan.json",
        ),
        gui_request_acceptance_item_json(
            "runtime_open_plan",
            "Workflow wrote an in-game open-path plan so runtime testing must name country, window, trigger, and expected token.",
            runtime_open_plan_exists,
            "gui_runtime_open_plan.json",
        ),
        gui_request_acceptance_item_json(
            "runtime_runner",
            "Workflow wrote a dry-run runtime runner report so launch execution cannot be confused with visual acceptance.",
            runtime_runner_exists,
            "gui_runtime_runner.json",
        ),
        gui_request_acceptance_item_json(
            "runtime_collect_plan",
            "Workflow wrote a post-run evidence collection plan that aggregates error, visual, game, contract, and playability reports.",
            runtime_collect_plan_exists,
            "gui_runtime_evidence_collect_plan.json",
        ),
        gui_request_acceptance_item_json(
            "runtime_evidence_contract",
            "Workflow wrote a runtime evidence contract so AI cannot confuse code acceptance with playable acceptance.",
            runtime_evidence_contract_exists,
            "gui_runtime_evidence_contract.json",
        ),
        gui_request_acceptance_item_json(
            "no_guessed_code_saved",
            "Blocked workflows saved no guessed final GUI code; successful writes passed final gates.",
            no_guessed_code_saved,
            "changed_files empty when blocked, or final gates passed when applied",
        ),
        gui_request_acceptance_item_json(
            "blocking_report",
            "Unknown or unsafe requests report questions/evidence instead of final code.",
            blocking_report_ok,
            "blockers/questions/recommended_game_code/sidecars",
        ),
    ];
    format!("[\n{}\n  ]", items.join(",\n"))
}

