fn gui_request_apply_blocked_recommended_game_code_json(
    apply_report: &Path,
    related_code_context: &Path,
    apply_error: Option<&str>,
) -> String {
    let blockers = gui_request_apply_report_blockers(apply_report);
    let blockers_text = if blockers.is_empty() {
        apply_error
            .unwrap_or("apply-gui-intent did not pass")
            .to_string()
    } else {
        blockers.join(", ")
    };
    let candidate = GuiRequestGameCodeCandidate {
        role: "apply_gui_evidence_required".to_string(),
        relative_path: ".hoi4skill/apply_gui_evidence_required.md".to_string(),
        status: "blocked_no_clausewitz_candidate".to_string(),
        reason: "apply_or_final_check_blockers_prevent_top_level_gui_code_candidates".to_string(),
        code: format!(
            "No final Clausewitz GUI code is recommended while apply-gui-intent/final-check blockers are unresolved: `{blockers_text}`. Inspect `{}` and `{}` for exact blockers, indexed candidates, source snippets, and user questions. Repair the GUI intent or provide indexed evidence, then rerun gui-request-workflow; do not use earlier generic scripted_gui/interface/localisation candidates as final code.",
            apply_report.display(),
            related_code_context.display(),
        ),
    };
    gui_request_game_code_candidate_json(&candidate)
}

fn gui_request_mount_blocked_recommended_game_code_json(
    mount_audit: &Path,
    mount_audit_error: Option<&str>,
) -> String {
    let audit_text = read_utf8_lossy(mount_audit).unwrap_or_default();
    let blockers = status_json_string_array_values(&audit_text, "blockers");
    let blockers_text = if blockers.is_empty() {
        mount_audit_error
            .unwrap_or("gui-mount-audit did not pass")
            .to_string()
    } else {
        blockers.join(", ")
    };
    let candidate = GuiRequestGameCodeCandidate {
        role: "gui_mount_evidence_required".to_string(),
        relative_path: ".hoi4skill/gui_mount_evidence_required.md".to_string(),
        status: "blocked_no_clausewitz_candidate".to_string(),
        reason: "gui_mount_audit_blockers_prevent_top_level_gui_code_candidates".to_string(),
        code: format!(
            "No final Clausewitz GUI code is recommended while gui-mount-audit blockers are unresolved: `{blockers_text}`. Inspect `{}` for exact missing window bindings, parent_window_token candidates, decision mounts, or map-window evidence. Repair the GUI intent or choose indexed parent/game code, then rerun gui-request-workflow.",
            mount_audit.display(),
        ),
    };
    gui_request_game_code_candidate_json(&candidate)
}

fn gui_request_final_code_safety_status(
    compiled: &GuiRequestCompiledIntent,
    ok: bool,
) -> &'static str {
    if ok {
        "applied_after_final_check"
    } else if compiled
        .recommended_game_code
        .iter()
        .any(|candidate| candidate.status == "blocked_no_clausewitz_candidate")
    {
        "blocked_no_clausewitz_candidate"
    } else {
        "candidate_only_requires_apply_gui_intent_final_check"
    }
}

