fn gui_requested_control_support_summary_json(workflow_text: &str) -> String {
    let body = status_json_top_level_array_body(workflow_text, "requested_control_support")
        .unwrap_or_default();
    let intent_types = status_json_string_field_values(&body, "intent_type");
    let statuses = status_json_string_field_values(&body, "status");
    let blockers = status_json_string_field_values(&body, "blocker")
        .into_iter()
        .filter(|value| !value.trim().is_empty())
        .collect::<Vec<_>>();
    let blocking_count = gui_requested_control_support_blocking_count(&body);
    let ready = blocking_count == 0;
    format!(
        "{{\"ready\": {}, \"requested_count\": {}, \"blocking_count\": {}, \"requested_controls\": {}, \"statuses\": {}, \"blockers\": {}}}",
        json_bool(ready),
        intent_types.len(),
        blocking_count,
        json_array(&intent_types),
        json_array(&statuses),
        json_array(&blockers),
    )
}

fn gui_requested_control_support_blocking_count(body: &str) -> usize {
    status_json_string_field_values(body, "status")
        .into_iter()
        .filter(|status| {
            matches!(
                status.as_str(),
                "blocking_missing_style_control_evidence" | "blocking_writer_missing"
            )
        })
        .count()
}

