#[derive(Clone, Debug, Default)]
struct GuiStyleRuntimeTemplate {
    fonts: Vec<String>,
    sprites: Vec<String>,
    button_sprites: Vec<String>,
    close_sprites: Vec<String>,
    panel_sprites: Vec<String>,
    tab_sprites: Vec<String>,
    map_sprites: Vec<String>,
    parent_window_tokens: Vec<String>,
    structure_signatures: Vec<String>,
    component_templates: Vec<String>,
    style_evidence: Vec<String>,
    style_token_evidence: Vec<String>,
    control_type_evidence: Vec<String>,
    strict_sprite_index: bool,
    indexed_sprites: BTreeSet<String>,
}

impl GuiStyleRuntimeTemplate {
    fn from_tokens(tokens: GuiStyleTemplateTokens) -> Self {
        Self {
            fonts: tokens.fonts,
            sprites: tokens.sprites,
            button_sprites: tokens.button_sprites,
            close_sprites: tokens.close_sprites,
            panel_sprites: tokens.panel_sprites,
            tab_sprites: tokens.tab_sprites,
            map_sprites: tokens.map_sprites,
            parent_window_tokens: tokens.parent_window_tokens,
            structure_signatures: tokens.structure_signatures,
            component_templates: tokens.component_templates,
            style_evidence: Vec::new(),
            style_token_evidence: tokens.style_token_evidence,
            control_type_evidence: tokens.control_type_evidence,
            strict_sprite_index: false,
            indexed_sprites: BTreeSet::new(),
        }
    }

    fn filtered_to_indexed_sprites(&self, code_index: &GameIndex) -> Self {
        let mut filtered = self.clone();
        filtered.button_sprites =
            filter_indexed_gui_style_sprites(&filtered.button_sprites, code_index);
        filtered.close_sprites =
            filter_indexed_gui_style_sprites(&filtered.close_sprites, code_index);
        filtered.panel_sprites =
            filter_indexed_gui_style_sprites(&filtered.panel_sprites, code_index);
        filtered.tab_sprites = filter_indexed_gui_style_sprites(&filtered.tab_sprites, code_index);
        filtered.map_sprites = filter_indexed_gui_style_sprites(&filtered.map_sprites, code_index);
        filtered.strict_sprite_index = true;
        filtered.indexed_sprites = code_index.sprites.clone();
        filtered
    }

    fn preferred_font(&self, candidates: &[&str], fallback: &str) -> String {
        for candidate in candidates {
            if self.fonts.iter().any(|font| font == candidate) {
                return (*candidate).to_string();
            }
        }
        self.fonts
            .first()
            .cloned()
            .unwrap_or_else(|| fallback.to_string())
    }

    fn preferred_button_sprite(&self, candidates: &[&str], fallback: &str) -> String {
        for candidate in candidates {
            if self.button_sprites.iter().any(|sprite| sprite == candidate) {
                return (*candidate).to_string();
            }
        }
        if let Some(sprite) = self.button_sprites.first() {
            return sprite.clone();
        }
        for candidate in candidates {
            if self.sprites.iter().any(|sprite| sprite == candidate)
                && (!self.strict_sprite_index || self.indexed_sprites.contains(*candidate))
            {
                return (*candidate).to_string();
            }
        }
        if self.strict_sprite_index {
            if self.indexed_sprites.contains(fallback) {
                return fallback.to_string();
            }
            return self
                .sprites
                .first()
                .cloned()
                .unwrap_or_else(|| fallback.to_string());
        }
        self.sprites
            .first()
            .cloned()
            .unwrap_or_else(|| fallback.to_string())
    }

    fn preferred_close_sprite(&self, candidates: &[&str], fallback: &str) -> String {
        for candidate in candidates {
            if self.close_sprites.iter().any(|sprite| sprite == candidate) {
                return (*candidate).to_string();
            }
        }
        self.close_sprites
            .first()
            .cloned()
            .unwrap_or_else(|| fallback.to_string())
    }

    fn preferred_parent_window_token(&self, fallback: Option<&str>) -> Option<String> {
        fallback
            .filter(|value| !gui_intent_value_missing(Some(value)))
            .map(str::to_string)
            .or_else(|| {
                self.parent_window_tokens
                    .iter()
                    .find(|token| token.as_str() == "top_bar")
                    .cloned()
            })
            .or_else(|| {
                self.parent_window_tokens
                    .iter()
                    .find(|token| token.as_str() == "politics_tab")
                    .cloned()
            })
            .or_else(|| self.parent_window_tokens.first().cloned())
    }
}

fn filter_indexed_gui_style_sprites(values: &[String], code_index: &GameIndex) -> Vec<String> {
    values
        .iter()
        .filter(|sprite| code_index.sprites.contains(*sprite))
        .cloned()
        .collect()
}

fn load_gui_style_runtime_template(
    path: Option<&str>,
) -> Result<Option<GuiStyleRuntimeTemplate>, String> {
    let Some(path) = path else {
        return Ok(None);
    };
    let template_path = normalize_path(path)?;
    let text = read_utf8_lossy(&template_path)?;
    let mut style_evidence = parse_json_string_array_field(&text, "style_evidence")
        .into_iter()
        .collect::<Vec<_>>();
    if style_evidence.is_empty() {
        style_evidence.push(format!("style_template_file:{}", template_path.display()));
    }
    let style_token_evidence = parse_json_string_array_field(&text, "style_token_evidence")
        .into_iter()
        .collect::<Vec<_>>();
    let control_type_evidence = parse_json_string_array_field(&text, "control_type_evidence")
        .into_iter()
        .collect::<Vec<_>>();
    Ok(Some(GuiStyleRuntimeTemplate {
        fonts: parse_json_string_array_field(&text, "fonts")
            .into_iter()
            .collect(),
        sprites: parse_json_string_array_field(&text, "sprites")
            .into_iter()
            .collect(),
        button_sprites: parse_json_string_array_field(&text, "button_sprites")
            .into_iter()
            .collect(),
        close_sprites: parse_json_string_array_field(&text, "close_sprites")
            .into_iter()
            .collect(),
        panel_sprites: parse_json_string_array_field(&text, "panel_sprites")
            .into_iter()
            .collect(),
        tab_sprites: parse_json_string_array_field(&text, "tab_sprites")
            .into_iter()
            .collect(),
        map_sprites: parse_json_string_array_field(&text, "map_sprites")
            .into_iter()
            .collect(),
        parent_window_tokens: parse_json_string_array_field(&text, "parent_window_tokens")
            .into_iter()
            .collect(),
        structure_signatures: parse_json_string_array_field(&text, "structure_signatures")
            .into_iter()
            .collect(),
        component_templates: parse_json_string_array_field(&text, "component_templates")
            .into_iter()
            .collect(),
        style_evidence,
        style_token_evidence,
        control_type_evidence,
        strict_sprite_index: false,
        indexed_sprites: BTreeSet::new(),
    }))
}

fn load_or_learn_gui_style_runtime_template(
    path: Option<&str>,
    reports: &[LargeModGuiPatternProfile],
) -> Result<Option<GuiStyleRuntimeTemplate>, String> {
    if let Some(template) = load_gui_style_runtime_template(path)? {
        return Ok(Some(template));
    }
    if reports.is_empty() {
        return Ok(None);
    }
    let tokens = collect_gui_style_template_tokens(reports)?;
    if tokens.fonts.is_empty()
        && tokens.sprites.is_empty()
        && tokens.button_sprites.is_empty()
        && tokens.close_sprites.is_empty()
        && tokens.panel_sprites.is_empty()
        && tokens.tab_sprites.is_empty()
        && tokens.map_sprites.is_empty()
        && tokens.parent_window_tokens.is_empty()
    {
        return Ok(None);
    }
    let mut template = GuiStyleRuntimeTemplate::from_tokens(tokens);
    template.style_evidence = gui_style_runtime_evidence_from_reports(reports);
    Ok(Some(template))
}

fn gui_style_runtime_evidence_from_reports(reports: &[LargeModGuiPatternProfile]) -> Vec<String> {
    let mut evidence = Vec::new();
    for report in reports {
        for path in &report.scripted_gui_files {
            push_capped_unique(
                &mut evidence,
                format!("scripted_gui_file:{}:{}", report.mod_root.display(), path),
                80,
            );
        }
        for path in &report.interface_gui_files {
            push_capped_unique(
                &mut evidence,
                format!("interface_gui_file:{}:{}", report.mod_root.display(), path),
                80,
            );
        }
        for path in &report.scripted_effect_files {
            push_capped_unique(
                &mut evidence,
                format!(
                    "scripted_effect_file:{}:{}",
                    report.mod_root.display(),
                    path
                ),
                80,
            );
        }
        for entry in report.scripted_guis.iter().take(20) {
            push_capped_unique(
                &mut evidence,
                format!(
                    "scripted_gui_entry:{}:{}:{}:line{}",
                    entry.id,
                    report.mod_root.display(),
                    entry.path,
                    entry.line
                ),
                80,
            );
        }
    }
    evidence
}

fn gui_style_runtime_source(
    map: &ArgMap,
    path: Option<&str>,
    template: Option<&GuiStyleRuntimeTemplate>,
) -> String {
    if path.is_some() {
        return "style_template_file".to_string();
    }
    if template.is_some() {
        if !repeated_values(map, "style-mod").is_empty() {
            return "style_mod_auto_learned".to_string();
        }
        return "mod_root_auto_learned".to_string();
    }
    "writer_defaults".to_string()
}

#[derive(Clone, Debug)]
struct GuiFinalCheckReport {
    ok: bool,
    required: bool,
    reports_dir: PathBuf,
    game_root: Option<PathBuf>,
    changed_files: Vec<String>,
    gui_output_ok: bool,
    gfx_audit_ok: bool,
    text_alignment_ok: bool,
    text_source: PathBuf,
    expected_visible_texts: Vec<String>,
    text_alignment_missing_count: i64,
    strict_validation_ok: bool,
    error_log_ok: bool,
    error_log_gui_diagnostic_count: usize,
    error_log_gui_diagnostics: Vec<String>,
    blockers: Vec<String>,
    artifacts: Vec<String>,
}

fn run_apply_gui_intent_final_checks(
    map: &ArgMap,
    mod_root: &Path,
    input: &Path,
    intent: &GuiIntentFields,
    plan: &GuiIntentWritePlan,
    output_audit: Option<&GuiOutputAudit>,
    execute: bool,
    write_error: Option<&str>,
    extra_mod_paths: &[PathBuf],
) -> Result<Option<GuiFinalCheckReport>, String> {
    if !map.flags.contains("final-check") {
        return Ok(None);
    }
    let changed_files = plan
        .files
        .iter()
        .map(|file| file.relative_path.clone())
        .collect::<Vec<_>>();
    let reports_dir = apply_gui_intent_final_check_reports_dir(map, mod_root, intent)?;
    fs::create_dir_all(&reports_dir)
        .map_err(|e| format!("create {}: {e}", reports_dir.display()))?;
    let mut blockers = Vec::new();
    let mut artifacts = Vec::new();
    let gui_output_ok = output_audit.is_some_and(|audit| audit.ok);
    if !execute {
        blockers.push("final_check_requires_execute".to_string());
    }
    if let Some(error) = write_error {
        blockers.push(format!("write_failed_before_final_check:{error}"));
    }
    if !gui_output_ok {
        blockers.push("gui_output_audit_failed_or_missing".to_string());
    }

    let gfx_report = reports_dir.join("gfx_audit.json");
    let gfx_audit_ok = if execute && write_error.is_none() {
        let mut args = vec![
            mod_root.display().to_string(),
            "--changed-only".to_string(),
            "--output".to_string(),
            gfx_report.display().to_string(),
        ];
        for changed in &changed_files {
            args.push("--changed".to_string());
            args.push(changed.clone());
        }
        let result = cmd_gfx_audit(&args);
        artifacts.push(gfx_report.display().to_string());
        if let Err(error) = &result {
            blockers.push(format!("gfx_audit_command_failed:{error}"));
        }
        result.is_ok()
    } else {
        false
    };

    let text_report = reports_dir.join("text_alignment.json");
    let expected_texts = gui_intent_expected_visible_texts(intent);
    let text_source = value(map, "text-source")
        .or_else(|| value(map, "source-file"))
        .or_else(|| value(map, "user-text-source"))
        .map(normalize_path)
        .transpose()?
        .unwrap_or_else(|| input.to_path_buf());
    let mut text_alignment_missing_count = 0;
    let text_alignment_ok = if execute && write_error.is_none() {
        let mut args = vec![
            "--mod-root".to_string(),
            mod_root.display().to_string(),
            "--input".to_string(),
            text_source.display().to_string(),
            "--output".to_string(),
            text_report.display().to_string(),
        ];
        for text in expected_texts {
            args.push("--expect-text".to_string());
            args.push(text);
        }
        let result = cmd_check_text_alignment(&args);
        artifacts.push(text_report.display().to_string());
        if let Err(error) = &result {
            blockers.push(format!("text_alignment_failed:{error}"));
        }
        if let Ok(text) = read_utf8_lossy(&text_report) {
            text_alignment_missing_count =
                status_json_i64_field(&text, "missing_count").unwrap_or(0);
            if text_alignment_missing_count > 0 {
                blockers.push(format!(
                    "text_alignment_missing_user_visible_text:{text_alignment_missing_count}"
                ));
            }
        }
        result.is_ok()
    } else {
        false
    };

    let game_root = value(map, "game-root")
        .or_else(|| value(map, "hoi4-path"))
        .map(normalize_path)
        .transpose()?;
    let validation_report = reports_dir.join("validation_strict_code_index.json");
    let strict_validation_ok = if execute && write_error.is_none() {
        if let Some(game_root) = game_root.as_ref() {
            if !game_root.is_dir() {
                blockers.push(format!("game_root_does_not_exist:{}", game_root.display()));
                false
            } else {
                let mut args = vec![
                    mod_root.display().to_string(),
                    "--game-root".to_string(),
                    game_root.display().to_string(),
                    "--strict-code-index".to_string(),
                    "--changed-only".to_string(),
                    "--output".to_string(),
                    validation_report.display().to_string(),
                ];
                let mut dependency_roots = extra_mod_paths.to_vec();
                dependency_roots.extend(
                    repeated_values(map, "style-mod")
                        .into_iter()
                        .map(normalize_path)
                        .collect::<Result<Vec<_>, _>>()?,
                );
                dependency_roots.sort();
                dependency_roots.dedup();
                for style_mod in dependency_roots {
                    if style_mod != mod_root && style_mod != *game_root {
                        args.push("--mod-path".to_string());
                        args.push(style_mod.display().to_string());
                    }
                }
                for changed in &changed_files {
                    args.push("--changed".to_string());
                    args.push(changed.clone());
                }
                let result = if map.flags.contains("full-validate-final-check") {
                    run_validate_with_optional_timeout(map, &args)
                } else {
                    run_gui_final_strict_validation_report(
                        map,
                        mod_root,
                        game_root,
                        &changed_files,
                        output_audit,
                        extra_mod_paths,
                        &validation_report,
                    )
                };
                artifacts.push(validation_report.display().to_string());
                if let Err(error) = &result {
                    blockers.push(format!("strict_code_index_validation_failed:{error}"));
                }
                result.is_ok()
            }
        } else {
            blockers.push("final_check_requires_game_root_for_strict_code_index".to_string());
            false
        }
    } else {
        false
    };
    let error_log_report = reports_dir.join("error_log_report.json");
    let mut error_log_gui_diagnostics = Vec::new();
    let error_log_ok = if execute && write_error.is_none() {
        if let Some(error_log) = value(map, "error-log").or_else(|| value(map, "error-log-input")) {
            let error_log = normalize_path(error_log)?;
            let mut args = vec![
                "--input".to_string(),
                error_log.display().to_string(),
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--changed-only".to_string(),
                "--output".to_string(),
                error_log_report.display().to_string(),
            ];
            if let Some(baseline) = value(map, "error-log-baseline") {
                args.push("--baseline".to_string());
                args.push(baseline.to_string());
            }
            for changed in &changed_files {
                args.push("--changed".to_string());
                args.push(changed.clone());
            }
            let result = cmd_analyze_error_log(&args);
            artifacts.push(error_log_report.display().to_string());
            if let Err(error) = &result {
                blockers.push(format!("error_log_analysis_failed:{error}"));
                false
            } else {
                let text = read_utf8_lossy(&error_log_report)?;
                let effective = status_json_i64_field(&text, "diagnostics_effective").unwrap_or(0);
                error_log_gui_diagnostics = gui_error_log_diagnostic_summaries(&text);
                if !error_log_gui_diagnostics.is_empty() {
                    blockers.push(format!(
                        "error_log_gui_diagnostics_effective:{}",
                        error_log_gui_diagnostics.len()
                    ));
                }
                if effective == 0 {
                    true
                } else {
                    blockers.push(format!("error_log_diagnostics_effective:{effective}"));
                    false
                }
            }
        } else {
            true
        }
    } else {
        value(map, "error-log")
            .or_else(|| value(map, "error-log-input"))
            .is_none()
    };
    let ok = blockers.is_empty()
        && gui_output_ok
        && text_alignment_ok
        && strict_validation_ok
        && error_log_ok;
    Ok(Some(GuiFinalCheckReport {
        ok,
        required: true,
        reports_dir,
        game_root,
        changed_files,
        gui_output_ok,
        gfx_audit_ok,
        text_alignment_ok,
        text_source,
        expected_visible_texts: gui_intent_expected_visible_texts(intent),
        text_alignment_missing_count,
        strict_validation_ok,
        error_log_ok,
        error_log_gui_diagnostic_count: error_log_gui_diagnostics.len(),
        error_log_gui_diagnostics,
        blockers,
        artifacts,
    }))
}

fn run_gui_final_strict_validation_report(
    map: &ArgMap,
    mod_root: &Path,
    game_root: &Path,
    changed_files: &[String],
    output_audit: Option<&GuiOutputAudit>,
    extra_mod_paths: &[PathBuf],
    output: &Path,
) -> Result<(), String> {
    let mut dependency_roots = extra_mod_paths.to_vec();
    dependency_roots.extend(
        repeated_values(map, "style-mod")
            .into_iter()
            .map(normalize_path)
            .collect::<Result<Vec<_>, _>>()?,
    );
    dependency_roots.sort();
    dependency_roots.dedup();
    let code_index_roots = gui_request_workflow_code_index_roots(mod_root, &dependency_roots);
    let code_index = build_gui_request_game_index_with_mod_paths(game_root, &code_index_roots)?;
    let mut reporter = Reporter::default();
    let options = ValidationOptions {
        strict_code_index: true,
    };
    if changed_files.is_empty() {
        reporter
            .error("GUI final strict validation requires at least one changed file".to_string());
    }
    for changed in changed_files {
        let path = mod_root.join(slash_path_to_native(changed));
        let ext = path
            .extension()
            .and_then(OsStr::to_str)
            .unwrap_or("")
            .to_ascii_lowercase();
        if !path.is_file() {
            reporter.error(format!(
                "{}: changed GUI final-check file does not exist",
                path.display()
            ));
            continue;
        }
        let text = read_utf8_lossy(&path)?;
        if matches!(ext.as_str(), "txt" | "mod" | "gfx" | "gui" | "asset") {
            check_braces(&path, &text, &mut reporter);
            check_script_semantics_with_options(
                &path,
                &text,
                Some(&code_index),
                options,
                &mut reporter,
            );
            check_unresolved_generation_markers(&path, &text, options, &mut reporter);
        } else if matches!(ext.as_str(), "yml" | "yaml") {
            check_localisation(&path, &mut reporter);
            check_localisation_tokens(&path, &text, &mut reporter);
            check_indexed_localisation_tokens(
                &path,
                &text,
                Some(&code_index),
                options,
                &mut reporter,
            );
        } else {
            reporter.warn(format!(
                "{}: changed GUI final-check file has unclassified extension `{ext}`",
                path.display()
            ));
        }
    }
    match output_audit {
        Some(audit) => {
            if !audit.strict_code_index {
                reporter.error(
                    "GUI output audit did not run with strict code index; final GUI write is blocked"
                        .to_string(),
                );
            }
            for blocker in &audit.blockers {
                reporter.error(format!("gui_output_audit:{blocker}"));
            }
            for warning in &audit.warnings {
                reporter.warn(format!("gui_output_audit:{warning}"));
            }
        }
        None => reporter.error(
            "GUI final strict validation requires a GUI output audit before final write"
                .to_string(),
        ),
    }
    let dependency_strings = dependency_roots
        .iter()
        .map(|path| path.display().to_string())
        .collect::<Vec<_>>();
    let report = gui_fast_validation_report_json(
        mod_root,
        Some(game_root),
        &dependency_strings,
        changed_files,
        &reporter,
    );
    fs::write(output, report).map_err(|e| format!("write {}: {e}", output.display()))?;
    if reporter.errors.is_empty() {
        Ok(())
    } else {
        Err("GUI final strict validation failed".to_string())
    }
}

fn gui_fast_validation_report_json(
    mod_root: &Path,
    game_root: Option<&Path>,
    dependency_mods: &[String],
    changed_files: &[String],
    reporter: &Reporter,
) -> String {
    format!(
        "{{\n  \"schema\": \"hoi4skill.validation_report.v1\",\n  \"validation_mode\": \"gui_changed_only_fast_strict_code_index\",\n  \"ok\": {},\n  \"status\": {},\n  \"mod_root\": {},\n  \"game_root\": {},\n  \"dependency_mods\": {},\n  \"strict_code_index\": true,\n  \"total_errors\": {},\n  \"total_warnings\": {},\n  \"effective_errors\": {},\n  \"effective_warnings\": {},\n  \"baseline_errors_filtered\": 0,\n  \"baseline_warnings_filtered\": 0,\n  \"changed_files\": {},\n  \"error_groups\": {},\n  \"warning_groups\": {},\n  \"errors\": {},\n  \"warnings\": {}\n}}\n",
        json_bool(reporter.errors.is_empty()),
        if reporter.errors.is_empty() {
            if reporter.warnings.is_empty() {
                json_str("ok")
            } else {
                json_str("warnings")
            }
        } else {
            json_str("errors")
        },
        json_str(&mod_root.display().to_string()),
        game_root
            .map(|path| json_str(&path.display().to_string()))
            .unwrap_or_else(|| "null".to_string()),
        json_array(dependency_mods),
        reporter.errors.len(),
        reporter.warnings.len(),
        reporter.errors.len(),
        reporter.warnings.len(),
        json_array(&changed_files.to_vec()),
        gui_fast_validation_issue_groups_json(&reporter.errors, 40),
        gui_fast_validation_issue_groups_json(&reporter.warnings, 40),
        json_array(&reporter.errors),
        json_array(&reporter.warnings),
    )
}

fn gui_fast_validation_issue_groups_json(items: &[String], limit: usize) -> String {
    let mut counts = BTreeMap::<String, usize>::new();
    for item in items {
        let key = item
            .split(':')
            .next()
            .unwrap_or("message")
            .trim()
            .chars()
            .take(120)
            .collect::<String>();
        *counts.entry(key).or_insert(0) += 1;
    }
    let entries = counts
        .into_iter()
        .take(limit)
        .map(|(kind, count)| format!("    {{\"kind\": {}, \"count\": {count}}}", json_str(&kind)))
        .collect::<Vec<_>>()
        .join(",\n");
    format!("[\n{entries}\n  ]")
}

fn run_validate_with_optional_timeout(map: &ArgMap, args: &[String]) -> Result<(), String> {
    let Some(seconds) =
        value(map, "final-check-timeout-seconds").or_else(|| value(map, "strict-timeout-seconds"))
    else {
        return cmd_validate(args);
    };
    let seconds = seconds
        .parse::<u64>()
        .map_err(|_| format!("invalid --final-check-timeout-seconds value `{seconds}`"))?;
    if seconds == 0 {
        return Err("--final-check-timeout-seconds must be greater than 0".to_string());
    }
    run_hoi4skill_subcommand_with_timeout("validate", args, Duration::from_secs(seconds))
}

fn run_hoi4skill_subcommand_with_timeout(
    subcommand: &str,
    args: &[String],
    timeout: Duration,
) -> Result<(), String> {
    let exe = std::env::current_exe().map_err(|e| format!("resolve current executable: {e}"))?;
    let mut child = Command::new(&exe)
        .arg(subcommand)
        .args(args)
        .spawn()
        .map_err(|e| format!("spawn {} {subcommand}: {e}", exe.display()))?;
    let start = Instant::now();
    loop {
        match child.try_wait() {
            Ok(Some(status)) => {
                if status.success() {
                    return Ok(());
                }
                return Err(format!("{subcommand} exited with status {status}"));
            }
            Ok(None) => {
                if start.elapsed() >= timeout {
                    let _ = child.kill();
                    let _ = child.wait();
                    return Err(format!(
                        "{subcommand} timed out after {} seconds",
                        timeout.as_secs()
                    ));
                }
                thread::sleep(Duration::from_millis(100));
            }
            Err(error) => {
                let _ = child.kill();
                let _ = child.wait();
                return Err(format!("poll {subcommand}: {error}"));
            }
        }
    }
}

fn apply_gui_intent_final_check_reports_dir(
    map: &ArgMap,
    mod_root: &Path,
    intent: &GuiIntentFields,
) -> Result<PathBuf, String> {
    if let Some(dir) = value(map, "final-check-dir").or_else(|| value(map, "check-dir")) {
        return normalize_path(dir);
    }
    let id = intent
        .scripted_gui_id
        .as_deref()
        .filter(|value| !gui_intent_value_missing(Some(value)))
        .unwrap_or("gui_intent");
    Ok(mod_root
        .join(".hoi4skill")
        .join("gui_final_checks")
        .join(sanitize_file_stem(id)))
}

fn gui_error_log_diagnostic_summaries(report_text: &str) -> Vec<String> {
    json_objects_in_array_field(report_text, "diagnostics")
        .into_iter()
        .filter_map(|object| {
            let category = status_json_string_field(&object, "category").unwrap_or_default();
            let file = status_json_string_field(&object, "file")
                .or_else(|| status_json_string_field(&object, "resolved_file"))
                .unwrap_or_default();
            let message = status_json_string_field(&object, "message").unwrap_or_default();
            let combined = format!("{category} {file} {message}").to_ascii_lowercase();
            if gui_error_log_text_is_gui_related(&combined) {
                Some(format!(
                    "{}:{}:{}",
                    if category.is_empty() {
                        "error_log"
                    } else {
                        category.as_str()
                    },
                    if file.is_empty() {
                        "<unknown>"
                    } else {
                        file.as_str()
                    },
                    if message.is_empty() {
                        "<no message>"
                    } else {
                        message.as_str()
                    },
                ))
            } else {
                None
            }
        })
        .take(40)
        .collect()
}

fn gui_error_log_text_is_gui_related(text: &str) -> bool {
    [
        ".gui",
        "scripted_gui",
        "scripted gui",
        "spritetype",
        "sprite type",
        "window",
        "button",
        "interface",
        "localisation",
        "localization",
        "could not find sprite",
        "failed to create window",
        "unknown window",
        "invalid scripted gui",
    ]
    .iter()
    .any(|needle| text.contains(needle))
}

fn sanitize_file_stem(value: &str) -> String {
    let mut out = value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-') {
                ch
            } else {
                '_'
            }
        })
        .collect::<String>();
    while out.contains("__") {
        out = out.replace("__", "_");
    }
    let out = out.trim_matches('_').to_string();
    if out.is_empty() {
        "gui_intent".to_string()
    } else {
        out
    }
}

fn gui_intent_expected_visible_texts(intent: &GuiIntentFields) -> Vec<String> {
    let mut out = Vec::new();
    for value in [intent.title.as_deref(), intent.description.as_deref()]
        .into_iter()
        .flatten()
    {
        if !gui_intent_value_missing(Some(value)) {
            push_capped_unique(&mut out, value.to_string(), 64);
        }
    }
    for widget in &intent.widgets {
        if let Some(value) = widget.localisation.as_deref() {
            if !gui_intent_value_missing(Some(value)) {
                push_capped_unique(&mut out, value.to_string(), 64);
            }
        }
        if let Some(value) = widget.placeholder.as_deref() {
            if !gui_intent_value_missing(Some(value)) {
                push_capped_unique(&mut out, value.to_string(), 64);
            }
        }
    }
    out
}

#[derive(Clone, Debug, Default)]
struct GuiIntentFields {
    schema: Option<String>,
    gui_kind: Option<String>,
    id_prefix: Option<String>,
    scripted_gui_id: Option<String>,
    window_name: Option<String>,
    title: Option<String>,
    description: Option<String>,
    decision_category: Option<String>,
    parent_window_token: Option<String>,
    map_window: Option<String>,
    open_flag: Option<String>,
    close_button: Option<String>,
    open_effect: Option<String>,
    close_effect: Option<String>,
    widget_count: usize,
    click_effects: Vec<String>,
    widgets: Vec<GuiIntentWidget>,
}

#[derive(Clone, Debug, Default)]
struct GuiIntentWidget {
    id: String,
    widget_type: Option<String>,
    localisation: Option<String>,
    sprite: Option<String>,
    click_effect: Option<String>,
    call_scripted_effect: Option<String>,
    x: Option<i32>,
    y: Option<i32>,
    width: Option<i32>,
    height: Option<i32>,
    rows: Option<i32>,
    columns: Option<i32>,
    placeholder: Option<String>,
    invalid_layout_fields: Vec<String>,
}

#[derive(Clone, Debug)]
struct GuiIntentValidation {
    ok: bool,
    blockers: Vec<String>,
    warnings: Vec<String>,
    questions: Vec<String>,
    asset_questions: Vec<String>,
    asset_todo: Vec<GuiRequestAssetTodo>,
}

fn parse_gui_intent_fields(text: &str) -> GuiIntentFields {
    let yaml = extract_first_fenced_block(text, "yaml").unwrap_or(text);
    let mut fields = GuiIntentFields::default();
    let mut section = "";
    let mut current_widget: Option<usize> = None;
    for raw in yaml.lines() {
        let line = raw.split('#').next().unwrap_or("").trim_end();
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed == "---" {
            continue;
        }
        let indent = line.chars().take_while(|ch| ch.is_whitespace()).count();
        if indent == 0 && trimmed.ends_with(':') {
            section = trimmed.trim_end_matches(':').trim();
            if section != "widgets" {
                current_widget = None;
            }
            continue;
        }
        let Some((key, value)) = gui_intent_yaml_assignment(trimmed) else {
            continue;
        };
        if indent == 0 {
            section = "";
            current_widget = None;
        }
        if section == "widgets" && key == "id" {
            fields.widget_count += 1;
            fields.widgets.push(GuiIntentWidget {
                id: value.clone(),
                widget_type: None,
                localisation: None,
                sprite: None,
                click_effect: None,
                call_scripted_effect: None,
                x: None,
                y: None,
                width: None,
                height: None,
                rows: None,
                columns: None,
                placeholder: None,
                invalid_layout_fields: Vec::new(),
            });
            current_widget = Some(fields.widgets.len() - 1);
            continue;
        }
        match (section, key.as_str()) {
            ("", "schema") => fields.schema = Some(value),
            ("", "gui_kind") => fields.gui_kind = Some(value),
            ("", "id_prefix") => fields.id_prefix = Some(value),
            ("", "scripted_gui_id") => fields.scripted_gui_id = Some(value),
            ("", "window_name") => fields.window_name = Some(value),
            ("", "title") => fields.title = Some(value),
            ("", "description") => fields.description = Some(value),
            ("mount", "decision_category") => fields.decision_category = Some(value),
            ("mount", "parent_window_token") => fields.parent_window_token = Some(value),
            ("mount", "map_window") => fields.map_window = Some(value),
            ("state_protocol", "open_flag") => fields.open_flag = Some(value),
            ("state_protocol", "close_button") => fields.close_button = Some(value),
            ("scripted_effects", "open_effect") => fields.open_effect = Some(value),
            ("scripted_effects", "close_effect") => fields.close_effect = Some(value),
            ("widgets", "type") => {
                if let Some(idx) = current_widget {
                    fields.widgets[idx].widget_type = Some(value);
                }
            }
            ("widgets", "localisation") => {
                if let Some(idx) = current_widget {
                    fields.widgets[idx].localisation = Some(value);
                }
            }
            ("widgets", "sprite") | ("widgets", "spriteType") => {
                if let Some(idx) = current_widget {
                    fields.widgets[idx].sprite = Some(value);
                }
            }
            ("widgets", "click_effect") => {
                if let Some(idx) = current_widget {
                    fields.widgets[idx].click_effect = Some(value.clone());
                }
                push_capped_unique(&mut fields.click_effects, value, 30)
            }
            ("widgets", "call_scripted_effect") | ("widgets", "scripted_effect") => {
                if let Some(idx) = current_widget {
                    fields.widgets[idx].call_scripted_effect = Some(value);
                }
            }
            ("widgets", "x") => {
                if let Some(idx) = current_widget {
                    match value.parse::<i32>() {
                        Ok(parsed) => fields.widgets[idx].x = Some(parsed),
                        Err(_) => fields.widgets[idx]
                            .invalid_layout_fields
                            .push("x".to_string()),
                    }
                }
            }
            ("widgets", "y") => {
                if let Some(idx) = current_widget {
                    match value.parse::<i32>() {
                        Ok(parsed) => fields.widgets[idx].y = Some(parsed),
                        Err(_) => fields.widgets[idx]
                            .invalid_layout_fields
                            .push("y".to_string()),
                    }
                }
            }
            ("widgets", "width") => {
                if let Some(idx) = current_widget {
                    match value.parse::<i32>() {
                        Ok(parsed) => fields.widgets[idx].width = Some(parsed),
                        Err(_) => fields.widgets[idx]
                            .invalid_layout_fields
                            .push("width".to_string()),
                    }
                }
            }
            ("widgets", "height") => {
                if let Some(idx) = current_widget {
                    match value.parse::<i32>() {
                        Ok(parsed) => fields.widgets[idx].height = Some(parsed),
                        Err(_) => fields.widgets[idx]
                            .invalid_layout_fields
                            .push("height".to_string()),
                    }
                }
            }
            ("widgets", "rows") => {
                if let Some(idx) = current_widget {
                    match value.parse::<i32>() {
                        Ok(parsed) => fields.widgets[idx].rows = Some(parsed),
                        Err(_) => fields.widgets[idx]
                            .invalid_layout_fields
                            .push("rows".to_string()),
                    }
                }
            }
            ("widgets", "columns") => {
                if let Some(idx) = current_widget {
                    match value.parse::<i32>() {
                        Ok(parsed) => fields.widgets[idx].columns = Some(parsed),
                        Err(_) => fields.widgets[idx]
                            .invalid_layout_fields
                            .push("columns".to_string()),
                    }
                }
            }
            ("widgets", "placeholder") => {
                if let Some(idx) = current_widget {
                    fields.widgets[idx].placeholder = Some(value);
                }
            }
            _ => {}
        }
    }
    fields
}

fn extract_first_fenced_block<'a>(text: &'a str, language: &str) -> Option<&'a str> {
    let marker = format!("```{language}");
    let start = text.find(&marker)?;
    let rest = text.get(start + marker.len()..)?;
    let rest = rest.strip_prefix('\r').unwrap_or(rest);
    let rest = rest.strip_prefix('\n').unwrap_or(rest);
    let end = rest.find("```")?;
    Some(&rest[..end])
}

fn gui_intent_yaml_assignment(line: &str) -> Option<(String, String)> {
    let (key, value) = line.split_once(':')?;
    let key = key.trim().trim_start_matches("- ").trim().to_string();
    let value = value.trim().trim_matches('"').trim_matches('\'').trim();
    if key.is_empty() || value.is_empty() {
        return None;
    }
    Some((key, value.to_string()))
}

fn validate_gui_intent_fields(
    intent: &GuiIntentFields,
    source: &str,
    aggregate: &LargeModGuiPatternAggregate,
) -> GuiIntentValidation {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let mut questions = Vec::new();
    let gui_kind = intent.gui_kind.as_deref().unwrap_or("");
    if intent.schema.as_deref() != Some("hoi4skill.gui_intent.v1") {
        blockers.push("schema_missing_or_not_hoi4skill_gui_intent_v1".to_string());
    }
    if !matches!(
        gui_kind,
        "decision_attached" | "standalone" | "topbar_mount" | "map_window"
    ) {
        blockers.push(
            "gui_kind_invalid_expected_decision_attached_standalone_topbar_mount_or_map_window"
                .to_string(),
        );
    }
    for (field, value) in [
        ("id_prefix", intent.id_prefix.as_deref()),
        ("scripted_gui_id", intent.scripted_gui_id.as_deref()),
        ("window_name", intent.window_name.as_deref()),
        ("title", intent.title.as_deref()),
        ("description", intent.description.as_deref()),
    ] {
        if gui_intent_value_missing(value) {
            blockers.push(format!("missing_required_field:{field}"));
        }
    }
    for (field, value) in [
        ("id_prefix", intent.id_prefix.as_deref()),
        ("scripted_gui_id", intent.scripted_gui_id.as_deref()),
        ("window_name", intent.window_name.as_deref()),
        ("state_protocol.open_flag", intent.open_flag.as_deref()),
        (
            "state_protocol.close_button",
            intent.close_button.as_deref(),
        ),
        (
            "scripted_effects.open_effect",
            intent.open_effect.as_deref(),
        ),
        (
            "scripted_effects.close_effect",
            intent.close_effect.as_deref(),
        ),
        (
            "mount.decision_category",
            intent.decision_category.as_deref(),
        ),
        (
            "mount.parent_window_token",
            intent.parent_window_token.as_deref(),
        ),
        ("mount.map_window", intent.map_window.as_deref()),
    ] {
        validate_gui_intent_identifier_field(field, value, &mut blockers, &mut questions);
    }
    validate_gui_intent_visible_text_field(
        "title",
        intent.title.as_deref(),
        &mut blockers,
        &mut questions,
    );
    validate_gui_intent_visible_text_field(
        "description",
        intent.description.as_deref(),
        &mut blockers,
        &mut questions,
    );
    match gui_kind {
        "decision_attached" => {
            if gui_intent_value_missing(intent.decision_category.as_deref()) {
                blockers.push("missing_mount:decision_category".to_string());
            }
            if !aggregate.has_decision_attached_gui {
                blockers.push("style_context_missing_decision_attached_gui_pattern".to_string());
            }
        }
        "standalone" => {
            require_gui_open_close_protocol(intent, &mut blockers);
            if !aggregate.has_standalone_gui {
                blockers.push("style_context_missing_standalone_gui_pattern".to_string());
            }
        }
        "topbar_mount" => {
            require_gui_open_close_protocol(intent, &mut blockers);
            if gui_intent_value_missing(intent.parent_window_token.as_deref()) {
                blockers.push("missing_mount:parent_window_token".to_string());
            }
            if !aggregate.has_mount_points {
                blockers.push("style_context_missing_mount_point_pattern".to_string());
            }
        }
        "map_window" => {
            require_gui_open_close_protocol(intent, &mut blockers);
            if gui_intent_value_missing(intent.map_window.as_deref())
                && gui_intent_value_missing(intent.parent_window_token.as_deref())
            {
                blockers.push("missing_mount:map_window_or_parent_window_token".to_string());
            }
            if !aggregate.has_tdr_map_gui {
                blockers.push("style_context_missing_tdr_map_gui_pattern".to_string());
            }
        }
        _ => {}
    }
    if intent.widget_count == 0 {
        blockers.push("missing_widgets".to_string());
    }
    if !intent.widgets.iter().any(gui_intent_widget_is_clickable) {
        blockers.push("missing_widget_click_effects".to_string());
    }
    for widget in &intent.widgets {
        validate_gui_intent_widget_type_field(widget, &mut blockers, &mut questions);
        validate_gui_intent_identifier_field(
            "widget.id",
            Some(widget.id.as_str()),
            &mut blockers,
            &mut questions,
        );
        validate_gui_intent_visible_text_field(
            "widget.localisation",
            widget.localisation.as_deref(),
            &mut blockers,
            &mut questions,
        );
        validate_gui_intent_identifier_field(
            "widget.sprite",
            widget.sprite.as_deref(),
            &mut blockers,
            &mut questions,
        );
        if gui_intent_widget_requires_sprite(widget)
            && gui_intent_value_missing(widget.sprite.as_deref())
        {
            blockers.push(format!("missing_widget_sprite:{}", widget.id));
            questions.push(format!(
                "Widget `{}` is an icon and must provide an indexed GFX sprite or an approved registered GUI asset before final GUI write.",
                widget.id
            ));
        }
        validate_gui_intent_identifier_field(
            "widget.click_effect",
            widget.click_effect.as_deref(),
            &mut blockers,
            &mut questions,
        );
        validate_gui_intent_identifier_field(
            "widget.call_scripted_effect",
            widget.call_scripted_effect.as_deref(),
            &mut blockers,
            &mut questions,
        );
        validate_gui_intent_widget_layout_fields(widget, &mut blockers, &mut questions);
    }
    for click in &intent.click_effects {
        if click.contains('{') || click.contains('=') || click.contains('}') {
            blockers.push("widget_click_effect_contains_inline_code".to_string());
            break;
        }
    }
    if gui_request_contains_raw_gui_code(source) {
        blockers.push("raw_clausewitz_gui_code_detected_use_intent_fields_only".to_string());
    }
    if gui_intent_value_missing(intent.open_flag.as_deref())
        && matches!(gui_kind, "standalone" | "topbar_mount" | "map_window")
    {
        questions.push("Which country flag should open this GUI?".to_string());
    }
    if source.contains('<') && source.contains('>') {
        questions.push("Replace template placeholders or ask the user for missing GUI ids, mounts, icons, flags, leaders, or cosmetic tags.".to_string());
    }
    if !aggregate.has_scripted_effects {
        warnings.push("style_context_has_no_scripted_effect_gui_bridge_examples".to_string());
    }
    blockers.sort();
    blockers.dedup();
    questions.sort();
    questions.dedup();
    warnings.sort();
    warnings.dedup();
    GuiIntentValidation {
        ok: blockers.is_empty(),
        blockers,
        warnings,
        questions,
        asset_questions: Vec::new(),
        asset_todo: Vec::new(),
    }
}

fn validate_gui_intent_widget_layout_fields(
    widget: &GuiIntentWidget,
    blockers: &mut Vec<String>,
    questions: &mut Vec<String>,
) {
    let id = if widget.id.is_empty() {
        "<unknown_widget>"
    } else {
        widget.id.as_str()
    };
    for field in &widget.invalid_layout_fields {
        blockers.push(format!("invalid_widget_layout_number:{id}:{field}"));
        questions.push(format!(
            "Widget `{id}` layout field `{field}` must be an integer; repair the GUI intent instead of writing raw .gui code."
        ));
    }
    for (field, value, min, max) in [
        ("x", widget.x, 0, 4096),
        ("y", widget.y, 0, 4096),
        ("width", widget.width, 1, 4096),
        ("height", widget.height, 1, 4096),
        ("rows", widget.rows, 1, 200),
        ("columns", widget.columns, 1, 200),
    ] {
        let Some(value) = value else {
            continue;
        };
        if value < min || value > max {
            blockers.push(format!("widget_layout_out_of_range:{id}:{field}:{value}"));
            questions.push(format!(
                "Widget `{id}` layout field `{field}` must be between {min} and {max}; use bounded structured layout fields only."
            ));
        }
    }
}

fn validate_gui_intent_identifier_field(
    field: &str,
    value: Option<&str>,
    blockers: &mut Vec<String>,
    questions: &mut Vec<String>,
) {
    let Some(value) = value.map(str::trim) else {
        return;
    };
    if gui_intent_value_missing(Some(value)) {
        return;
    }
    if gui_intent_identifier_unsafe(value) {
        blockers.push(format!("unsafe_identifier_field:{field}"));
        questions.push(format!(
            "Replace `{field}` with an existing ASCII Clausewitz id/token from indexed evidence; do not use prose, placeholders, inline code, or invented syntax."
        ));
    }
}

fn validate_gui_intent_widget_type_field(
    widget: &GuiIntentWidget,
    blockers: &mut Vec<String>,
    questions: &mut Vec<String>,
) {
    let id = if widget.id.is_empty() {
        "<unknown_widget>"
    } else {
        widget.id.as_str()
    };
    let Some(value) = widget.widget_type.as_deref().map(str::trim) else {
        blockers.push(format!("missing_widget_type:{id}"));
        questions.push(format!(
            "Widget `{id}` must declare type `button`; other GUI controls need explicit writer support before final GUI write."
        ));
        return;
    };
    if gui_intent_value_missing(Some(value)) {
        blockers.push(format!("missing_widget_type:{id}"));
        questions.push(format!(
            "Widget `{id}` must declare type `button`; placeholders are not accepted as GUI control types."
        ));
        return;
    }
    if !gui_intent_widget_type_supported(value) {
        blockers.push(format!("unsupported_widget_type:{id}:{value}"));
        questions.push(format!(
            "Widget `{id}` requested unsupported type `{value}`. This writer supports `button`, `text`, `icon`, `progressbar`, `checkbox`, `listbox`, `scrollbar`, `editbox`, `gridbox`, `dropdown`, and `overlapping`; add a dedicated writer before generating `{value}` GUI code."
        ));
    }
}

fn gui_intent_widget_type_supported(value: &str) -> bool {
    matches!(
        value,
        "button"
            | "buttonType"
            | "text"
            | "instantTextBoxType"
            | "icon"
            | "iconType"
            | "progressbar"
            | "progressbarType"
            | "checkbox"
            | "checkboxType"
            | "listbox"
            | "listboxType"
            | "scrollbar"
            | "scrollbarType"
            | "editbox"
            | "editBoxType"
            | "gridbox"
            | "gridBoxType"
            | "dropdown"
            | "dropDownBoxType"
            | "dropdownType"
            | "comboBoxType"
            | "overlapping"
            | "overlappingElementsBoxType"
    )
}

fn gui_intent_widget_is_clickable(widget: &GuiIntentWidget) -> bool {
    widget
        .widget_type
        .as_deref()
        .is_some_and(|value| matches!(value, "button" | "buttonType"))
        && widget
            .click_effect
            .as_deref()
            .is_some_and(|value| !gui_intent_value_missing(Some(value)))
}

fn gui_intent_widget_requires_sprite(widget: &GuiIntentWidget) -> bool {
    widget
        .widget_type
        .as_deref()
        .is_some_and(|value| matches!(value, "icon" | "iconType"))
}

fn gui_intent_widget_requires_style_control_evidence(
    widget: &GuiIntentWidget,
) -> Option<&'static str> {
    match widget.widget_type.as_deref() {
        Some("progressbar" | "progressbarType") => Some("progressbar"),
        Some("checkbox" | "checkboxType") => Some("checkbox"),
        Some("listbox" | "listboxType") => Some("listbox"),
        Some("scrollbar" | "scrollbarType") => Some("scrollbar"),
        Some("editbox" | "editBoxType") => Some("editbox"),
        Some("gridbox" | "gridBoxType") => Some("gridbox"),
        Some("dropdown" | "dropDownBoxType" | "dropdownType" | "comboBoxType") => Some("dropdown"),
        Some("overlapping" | "overlappingElementsBoxType") => Some("overlapping"),
        _ => None,
    }
}

fn gui_intent_identifier_unsafe(value: &str) -> bool {
    value.is_empty()
        || value.contains("【")
        || value.contains("】")
        || value.contains('<')
        || value.contains('>')
        || value.contains('{')
        || value.contains('}')
        || value.contains('=')
        || value.contains('"')
        || value.contains('\'')
        || value
            .chars()
            .any(|ch| !(ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-' | '.')))
}

fn validate_gui_intent_visible_text_field(
    field: &str,
    value: Option<&str>,
    blockers: &mut Vec<String>,
    questions: &mut Vec<String>,
) {
    let Some(value) = value else {
        return;
    };
    if gui_intent_value_missing(Some(value)) {
        if value.contains('<') && value.contains('>') {
            blockers.push(format!("unresolved_visible_text_template:{field}"));
            questions.push(format!(
                "Resolve `{field}` visible text before writing final GUI files; template placeholders are not user-visible localisation."
            ));
        }
        return;
    }
    if value.contains('<') && value.contains('>') {
        blockers.push(format!("unresolved_visible_text_template:{field}"));
        questions.push(format!(
            "Resolve `{field}` visible text before writing final GUI files; template placeholders are not user-visible localisation."
        ));
    }
    for placeholder in extract_author_placeholders(value) {
        if gui_placeholder_requires_evidence(&placeholder) {
            blockers.push(format!("unresolved_visible_text_placeholder:{field}"));
            questions.push(gui_placeholder_question(&placeholder));
        }
    }
}

fn require_gui_open_close_protocol(intent: &GuiIntentFields, blockers: &mut Vec<String>) {
    for (field, value) in [
        ("state_protocol.open_flag", intent.open_flag.as_deref()),
        (
            "state_protocol.close_button",
            intent.close_button.as_deref(),
        ),
        (
            "scripted_effects.open_effect",
            intent.open_effect.as_deref(),
        ),
        (
            "scripted_effects.close_effect",
            intent.close_effect.as_deref(),
        ),
    ] {
        if gui_intent_value_missing(value) {
            blockers.push(format!("missing_required_field:{field}"));
        }
    }
}

fn gui_intent_value_missing(value: Option<&str>) -> bool {
    let Some(value) = value.map(str::trim) else {
        return true;
    };
    value.is_empty()
        || value == "[]"
        || value.starts_with('<')
        || value.ends_with('>')
        || value.eq_ignore_ascii_case("todo")
        || value.eq_ignore_ascii_case("null")
}

fn gui_intent_validation_json(
    input: &Path,
    intent: &GuiIntentFields,
    validation: &GuiIntentValidation,
    reports: &[LargeModGuiPatternProfile],
    aggregate: &LargeModGuiPatternAggregate,
) -> String {
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_intent_validation.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"input\": {},\n  \"gui_kind\": {},\n  \"scripted_gui_id\": {},\n  \"window_name\": {},\n  \"blocking_count\": {},\n  \"blockers\": {},\n  \"warnings\": {},\n  \"questions\": {},\n  \"style_patterns\": {{\"decision_attached_gui\": {}, \"standalone_gui\": {}, \"mount_points\": {}, \"scripted_effects\": {}, \"tdr_map_gui\": {}}},\n  \"semantic_context\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(if validation.ok { "passed" } else { "blocked" }),
        json_bool(validation.ok),
        json_str(&input.display().to_string()),
        json_optional_str(intent.gui_kind.as_deref()),
        json_optional_str(intent.scripted_gui_id.as_deref()),
        json_optional_str(intent.window_name.as_deref()),
        validation.blockers.len(),
        json_array(&validation.blockers),
        json_array(&validation.warnings),
        json_array(&validation.questions),
        json_bool(aggregate.has_decision_attached_gui),
        json_bool(aggregate.has_standalone_gui),
        json_bool(aggregate.has_mount_points),
        json_bool(aggregate.has_scripted_effects),
        json_bool(aggregate.has_tdr_map_gui),
        gui_intent_semantic_context_json(intent.gui_kind.as_deref(), reports),
        json_array(&large_mod_gui_authoring_stop_conditions()),
    )
}

fn gui_intent_semantic_context_json(
    gui_kind: Option<&str>,
    reports: &[LargeModGuiPatternProfile],
) -> String {
    let examples = reports
        .iter()
        .flat_map(|report| report.scripted_guis.iter())
        .filter(|entry| match gui_kind {
            Some("decision_attached") => entry.context_type.as_deref() == Some("decision_category"),
            Some("standalone" | "topbar_mount" | "map_window") => {
                entry.context_type.as_deref() == Some("player_context")
            }
            _ => true,
        })
        .take(8)
        .map(scripted_gui_entry_json)
        .collect::<Vec<_>>()
        .join(",\n");
    let decision_mounts = reports
        .iter()
        .flat_map(|report| report.decision_mounts.iter())
        .take(8)
        .map(gui_decision_mount_json)
        .collect::<Vec<_>>()
        .join(",\n");
    let scripted_effects = gui_intent_scripted_effect_context(reports);
    format!(
        "{{\"scripted_gui_examples\": [{}], \"decision_mount_examples\": [{}], \"scripted_effect_bridge_examples\": {}}}",
        examples,
        decision_mounts,
        json_array(&scripted_effects),
    )
}

fn gui_intent_scripted_effect_context(reports: &[LargeModGuiPatternProfile]) -> Vec<String> {
    let all = reports
        .iter()
        .flat_map(|report| report.scripted_effect_gui_entries.iter())
        .cloned()
        .collect::<Vec<_>>();
    let mut selected = all
        .iter()
        .filter(|entry| scripted_effect_entry_looks_gui_relevant(entry))
        .take(20)
        .cloned()
        .collect::<Vec<_>>();
    if selected.is_empty() {
        selected = all.into_iter().take(20).collect();
    }
    selected
}

fn scripted_effect_entry_looks_gui_relevant(entry: &str) -> bool {
    let lower = entry.to_ascii_lowercase();
    [
        "gui",
        "investment",
        "money",
        "progress",
        "window",
        "button",
        "click",
        "open_",
        "close_",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
}

struct GuiIntentWriteFile {
    role: String,
    path: PathBuf,
    relative_path: String,
    text: String,
}

struct GuiIntentWritePlan {
    files: Vec<GuiIntentWriteFile>,
}

#[derive(Clone, Debug)]
struct GuiWriteRollback {
    items: Vec<GuiWriteRollbackItem>,
}

#[derive(Clone, Debug)]
struct GuiWriteRollbackItem {
    path: PathBuf,
    relative_path: String,
    previous_bytes: Option<Vec<u8>>,
}

#[derive(Clone, Debug)]
struct GuiRollbackReport {
    attempted: bool,
    ok: bool,
    restored_files: Vec<String>,
    deleted_files: Vec<String>,
    blockers: Vec<String>,
}

fn build_gui_intent_write_plan(
    mod_root: &Path,
    intent: &GuiIntentFields,
    style_template: Option<&GuiStyleRuntimeTemplate>,
) -> Result<GuiIntentWritePlan, String> {
    let prefix = required_gui_intent_value(intent.id_prefix.as_deref(), "id_prefix")?;
    let scripted_gui_id =
        required_gui_intent_value(intent.scripted_gui_id.as_deref(), "scripted_gui_id")?;
    let window_name = required_gui_intent_value(intent.window_name.as_deref(), "window_name")?;
    let gui_kind = required_gui_intent_value(intent.gui_kind.as_deref(), "gui_kind")?;
    let mut files = Vec::new();
    let scripted_gui_rel = format!("common/scripted_guis/{scripted_gui_id}.txt");
    let scripted_effect_rel = format!("common/scripted_effects/{scripted_gui_id}.txt");
    let interface_rel = format!("interface/{window_name}.gui");
    let loc_rel = format!("localisation/simp_chinese/{prefix}_gui_l_simp_chinese.yml");
    files.push(GuiIntentWriteFile {
        role: "scripted_gui".to_string(),
        path: mod_root.join(slash_path_to_native(&scripted_gui_rel)),
        relative_path: scripted_gui_rel,
        text: render_gui_intent_scripted_gui(intent, style_template)?,
    });
    files.push(GuiIntentWriteFile {
        role: "scripted_effects".to_string(),
        path: mod_root.join(slash_path_to_native(&scripted_effect_rel)),
        relative_path: scripted_effect_rel,
        text: render_gui_intent_scripted_effects(intent)?,
    });
    files.push(GuiIntentWriteFile {
        role: "interface_gui".to_string(),
        path: mod_root.join(slash_path_to_native(&interface_rel)),
        relative_path: interface_rel,
        text: render_gui_intent_interface(intent, style_template)?,
    });
    files.push(GuiIntentWriteFile {
        role: "localisation".to_string(),
        path: mod_root.join(slash_path_to_native(&loc_rel)),
        relative_path: loc_rel,
        text: render_gui_intent_localisation(intent)?,
    });
    if gui_kind == "decision_attached" {
        let decision_category =
            required_gui_intent_value(intent.decision_category.as_deref(), "decision_category")?;
        let mount_rel = format!("common/decisions/categories/{prefix}_gui_mount.txt");
        files.push(GuiIntentWriteFile {
            role: "decision_category_mount".to_string(),
            path: mod_root.join(slash_path_to_native(&mount_rel)),
            relative_path: mount_rel,
            text: render_gui_intent_decision_mount(&decision_category, &scripted_gui_id),
        });
    }
    Ok(GuiIntentWritePlan { files })
}

fn slash_path_to_native(path: &str) -> PathBuf {
    path.split('/').collect()
}

fn required_gui_intent_value(value: Option<&str>, field: &str) -> Result<String, String> {
    if gui_intent_value_missing(value) {
        Err(format!("missing required GUI intent field: {field}"))
    } else {
        Ok(value.unwrap_or("").trim().to_string())
    }
}

fn render_gui_intent_scripted_gui(
    intent: &GuiIntentFields,
    style_template: Option<&GuiStyleRuntimeTemplate>,
) -> Result<String, String> {
    let id = required_gui_intent_value(intent.scripted_gui_id.as_deref(), "scripted_gui_id")?;
    let window_name = required_gui_intent_value(intent.window_name.as_deref(), "window_name")?;
    let gui_kind = required_gui_intent_value(intent.gui_kind.as_deref(), "gui_kind")?;
    let context_type = if gui_kind == "decision_attached" {
        "decision_category"
    } else {
        "player_context"
    };
    let mut out = String::new();
    out.push_str("scripted_gui = {\n");
    out.push_str(&format!("\t{id} = {{\n"));
    out.push_str(&format!("\t\tcontext_type = {context_type}\n"));
    let parent_window_token = style_template
        .and_then(|template| {
            template.preferred_parent_window_token(intent.parent_window_token.as_deref())
        })
        .or_else(|| {
            intent
                .parent_window_token
                .as_deref()
                .filter(|parent| !gui_intent_value_missing(Some(parent)))
                .map(str::to_string)
        });
    if let Some(parent) = parent_window_token.as_deref() {
        if gui_kind != "decision_attached" {
            out.push_str(&format!("\t\tparent_window_token = {parent}\n"));
        }
    }
    out.push_str(&format!("\t\twindow_name = \"{window_name}\"\n"));
    if gui_kind != "decision_attached" {
        let open_flag = required_gui_intent_value(intent.open_flag.as_deref(), "open_flag")?;
        out.push_str("\t\tvisible = {\n");
        out.push_str(&format!("\t\t\thas_country_flag = {open_flag}\n"));
        out.push_str("\t\t}\n");
    }
    out.push_str("\t\teffects = {\n");
    if let Some(close_button) = intent.close_button.as_deref() {
        if !gui_intent_value_missing(Some(close_button)) {
            let close_effect =
                required_gui_intent_value(intent.close_effect.as_deref(), "close_effect")?;
            out.push_str(&format!("\t\t\t{close_button} = {{\n"));
            out.push_str(&format!("\t\t\t\t{close_effect} = yes\n"));
            out.push_str("\t\t\t}\n");
        }
    }
    for widget in &intent.widgets {
        if !gui_intent_widget_is_clickable(widget) {
            continue;
        }
        if let Some(click_effect) = widget.click_effect.as_deref() {
            if gui_intent_value_missing(Some(click_effect)) {
                continue;
            }
            let click_id = gui_widget_click_handler_id(&widget.id);
            if Some(click_id.as_str()) == intent.close_button.as_deref() {
                continue;
            }
            out.push_str(&format!("\t\t\t{click_id} = {{\n"));
            out.push_str(&format!("\t\t\t\t{click_effect} = yes\n"));
            out.push_str("\t\t\t}\n");
        }
    }
    out.push_str("\t\t}\n");
    out.push_str("\t}\n");
    out.push_str("}\n");
    Ok(out)
}

fn render_gui_intent_scripted_effects(intent: &GuiIntentFields) -> Result<String, String> {
    let open_flag = intent.open_flag.as_deref().unwrap_or("");
    let prefix = intent.id_prefix.as_deref().unwrap_or("");
    let mut out = String::new();
    if let Some(open_effect) = intent.open_effect.as_deref() {
        if !gui_intent_value_missing(Some(open_effect))
            && !gui_intent_value_missing(Some(open_flag))
        {
            out.push_str(&format!("{open_effect} = {{\n"));
            out.push_str(&format!("\tset_country_flag = {open_flag}\n"));
            out.push_str("}\n\n");
        }
    }
    if let Some(close_effect) = intent.close_effect.as_deref() {
        if !gui_intent_value_missing(Some(close_effect))
            && !gui_intent_value_missing(Some(open_flag))
        {
            out.push_str(&format!("{close_effect} = {{\n"));
            out.push_str(&format!("\tclr_country_flag = {open_flag}\n"));
            out.push_str("}\n\n");
        }
    }
    let mut emitted = BTreeSet::new();
    if let Some(open_effect) = intent.open_effect.as_deref() {
        emitted.insert(open_effect.to_string());
    }
    if let Some(close_effect) = intent.close_effect.as_deref() {
        emitted.insert(close_effect.to_string());
    }
    for widget in &intent.widgets {
        if !gui_intent_widget_is_clickable(widget) {
            continue;
        }
        let Some(click_effect) = widget.click_effect.as_deref() else {
            continue;
        };
        if gui_intent_value_missing(Some(click_effect)) || emitted.contains(click_effect) {
            continue;
        }
        if let Some(call) = widget.call_scripted_effect.as_deref() {
            if !gui_intent_value_missing(Some(call)) {
                out.push_str(&format!("{click_effect} = {{\n"));
                out.push_str(&format!("\t{call} = yes\n"));
                out.push_str("}\n\n");
                emitted.insert(click_effect.to_string());
            }
        } else if gui_click_effect_is_auto_shell(prefix, click_effect) {
            out.push_str(&format!("{click_effect} = {{\n"));
            out.push_str("}\n\n");
            emitted.insert(click_effect.to_string());
        }
    }
    Ok(out)
}

fn gui_click_effect_is_auto_shell(prefix: &str, click_effect: &str) -> bool {
    click_effect == format!("refresh_{prefix}")
        || click_effect == format!("refresh_{prefix}_gui")
        || click_effect == format!("prev_{prefix}_page")
        || click_effect == format!("next_{prefix}_page")
}

fn render_gui_intent_interface(
    intent: &GuiIntentFields,
    style_template: Option<&GuiStyleRuntimeTemplate>,
) -> Result<String, String> {
    let prefix = required_gui_intent_value(intent.id_prefix.as_deref(), "id_prefix")?;
    let window_name = required_gui_intent_value(intent.window_name.as_deref(), "window_name")?;
    let title_font = style_template
        .map(|template| {
            template.preferred_font(
                &["hoi_30header", "hoi_36header", "aldrich_32_outline"],
                "hoi_30header",
            )
        })
        .unwrap_or_else(|| "hoi_30header".to_string());
    let button_font = style_template
        .map(|template| {
            template.preferred_font(
                &["Main_14_black", "hoi_18mbs", "hoi_16mbs"],
                "Main_14_black",
            )
        })
        .unwrap_or_else(|| "Main_14_black".to_string());
    let button_sprite = style_template
        .map(|template| {
            template.preferred_button_sprite(
                &[
                    "GFX_button_123x34",
                    "GFX_tno_button_148x34",
                    "GFX_generic_button_wide",
                ],
                "GFX_button_123x34",
            )
        })
        .unwrap_or_else(|| "GFX_button_123x34".to_string());
    let close_sprite = style_template
        .map(|template| {
            template.preferred_close_sprite(
                &[
                    "GFX_closebutton",
                    "GFX_tno_close_button",
                    "GFX_collapse_or_close_large",
                    "GFX_crt_closebutton",
                ],
                "GFX_closebutton",
            )
        })
        .unwrap_or_else(|| "GFX_closebutton".to_string());
    let close_button = intent
        .close_button
        .as_deref()
        .map(gui_button_name_from_click)
        .unwrap_or_else(|| format!("{prefix}_close_button"));
    let mut out = String::new();
    out.push_str("guiTypes = {\n");
    out.push_str("\tcontainerWindowType = {\n");
    out.push_str(&format!("\t\tname = \"{window_name}\"\n"));
    out.push_str("\t\tposition = { x = 0 y = 0 }\n");
    out.push_str("\t\torientation = center\n");
    out.push_str("\t\torigo = center\n");
    out.push_str("\t\tmoveable = yes\n\n");
    out.push_str("\t\tinstantTextBoxType = {\n");
    out.push_str(&format!("\t\t\tname = \"{prefix}_title\"\n"));
    out.push_str("\t\t\tposition = { x = 20 y = 20 }\n");
    out.push_str(&format!("\t\t\tfont = \"{title_font}\"\n"));
    out.push_str(&format!("\t\t\ttext = \"{prefix}_title\"\n"));
    out.push_str("\t\t\tmaxWidth = 420\n");
    out.push_str("\t\t\tmaxHeight = 40\n");
    out.push_str("\t\t\tfixedsize = yes\n");
    out.push_str("\t\t}\n\n");
    out.push_str("\t\tbuttonType = {\n");
    out.push_str(&format!("\t\t\tname = \"{close_button}\"\n"));
    out.push_str("\t\t\tposition = { x = 440 y = 20 }\n");
    out.push_str(&format!("\t\t\tquadTextureSprite = \"{close_sprite}\"\n"));
    out.push_str(&format!("\t\t\tbuttonFont = \"{button_font}\"\n"));
    out.push_str("\t\t\tshortcut = \"ESCAPE\"\n");
    out.push_str("\t\t\tclicksound = click_close\n");
    out.push_str("\t\t}\n\n");
    let mut widget_y = 90;
    for widget in &intent.widgets {
        if widget.id.is_empty() || gui_intent_value_missing(Some(&widget.id)) {
            continue;
        }
        out.push_str(&render_gui_intent_widget_interface(
            &prefix,
            widget,
            widget_y,
            &button_sprite,
            &button_font,
            &title_font,
        ));
        let rendered_y = widget.y.unwrap_or(widget_y);
        widget_y = widget_y.max(rendered_y + gui_intent_widget_layout_height(widget) + 12);
    }
    out.push_str("\t}\n");
    out.push_str("}\n");
    Ok(out)
}

fn gui_intent_widget_layout_height(widget: &GuiIntentWidget) -> i32 {
    if let Some(height) = widget.height.filter(|height| *height > 0) {
        return height;
    }
    match widget.widget_type.as_deref().unwrap_or("button") {
        "listbox"
        | "listboxType"
        | "scrollbar"
        | "scrollbarType"
        | "gridbox"
        | "gridBoxType"
        | "overlapping"
        | "overlappingElementsBoxType" => 160,
        "text" | "instantTextBoxType" => 36,
        "progressbar" | "progressbarType" => 20,
        "checkbox" | "checkboxType" => 28,
        "editbox" | "editBoxType" => 28,
        "dropdown" | "dropDownBoxType" | "dropdownType" | "comboBoxType" => 32,
        "icon" | "iconType" => 32,
        _ => 34,
    }
}

fn render_gui_intent_widget_interface(
    prefix: &str,
    widget: &GuiIntentWidget,
    y: i32,
    button_sprite: &str,
    button_font: &str,
    text_font: &str,
) -> String {
    let widget_type = widget.widget_type.as_deref().unwrap_or("button");
    let key = gui_widget_localisation_key(prefix, &widget.id);
    let x = widget
        .x
        .unwrap_or_else(|| gui_intent_widget_default_x(widget));
    let y = widget.y.unwrap_or(y);
    let width = widget
        .width
        .unwrap_or_else(|| gui_intent_widget_default_width(widget));
    let height = widget
        .height
        .unwrap_or_else(|| gui_intent_widget_layout_height(widget));
    let placeholder_key = widget
        .placeholder
        .as_deref()
        .filter(|value| !gui_intent_value_missing(Some(value)))
        .map(|_| format!("{key}_placeholder"));
    match widget_type {
        "text" | "instantTextBoxType" => format!(
            "\t\tinstantTextBoxType = {{\n\t\t\tname = \"{}\"\n\t\t\tposition = {{ x = {x} y = {y} }}\n\t\t\tfont = \"{}\"\n\t\t\ttext = \"{}\"\n\t\t\tmaxWidth = {width}\n\t\t\tmaxHeight = {height}\n\t\t\tfixedsize = yes\n\t\t}}\n",
            widget.id, text_font, key
        ),
        "icon" | "iconType" => {
            let sprite = widget
                .sprite
                .as_deref()
                .filter(|value| !gui_intent_value_missing(Some(value)))
                .unwrap_or("<indexed_GFX_icon_sprite>");
            format!(
                "\t\ticonType = {{\n\t\t\tname = \"{}\"\n\t\t\tposition = {{ x = {x} y = {y} }}\n\t\t\tspriteType = \"{}\"\n\t\t}}\n",
                widget.id, sprite
            )
        }
        "progressbar" | "progressbarType" => format!(
            "\t\tprogressbarType = {{\n\t\t\tname = \"{}\"\n\t\t\tposition = {{ x = {x} y = {y} }}\n\t\t\tsize = {{ width = {width} height = {height} }}\n\t\t}}\n",
            widget.id
        ),
        "checkbox" | "checkboxType" => format!(
            "\t\tcheckboxType = {{\n\t\t\tname = \"{}\"\n\t\t\tposition = {{ x = {x} y = {y} }}\n\t\t\ttext = \"{}\"\n\t\t}}\n",
            widget.id, key
        ),
        "listbox" | "listboxType" => {
            format!(
                "\t\tlistboxType = {{\n\t\t\tname = \"{}\"\n\t\t\tposition = {{ x = {x} y = {y} }}\n\t\t\tsize = {{ width = {width} height = {height} }}\n\t\t}}\n",
                widget.id
            )
        }
        "scrollbar" | "scrollbarType" => format!(
            "\t\tscrollbarType = {{\n\t\t\tname = \"{}\"\n\t\t\tposition = {{ x = {x} y = {y} }}\n\t\t\tsize = {{ width = {width} height = {height} }}\n\t\t}}\n",
            widget.id
        ),
        "editbox" | "editBoxType" => {
            let text_key = placeholder_key.as_deref().unwrap_or(&key);
            format!(
                "\t\teditBoxType = {{\n\t\t\tname = \"{}\"\n\t\t\tposition = {{ x = {x} y = {y} }}\n\t\t\tsize = {{ width = {width} height = {height} }}\n\t\t\ttext = \"{}\"\n\t\t}}\n",
                widget.id, text_key
            )
        }
        "gridbox" | "gridBoxType" => {
            format!(
                "\t\tgridBoxType = {{\n\t\t\tname = \"{}\"\n\t\t\tposition = {{ x = {x} y = {y} }}\n\t\t\tsize = {{ width = {width} height = {height} }}\n\t\t}}\n",
                widget.id
            )
        }
        "dropdown" | "dropDownBoxType" | "dropdownType" | "comboBoxType" => {
            let clausewitz_type = match widget_type {
                "dropdownType" | "comboBoxType" | "dropDownBoxType" => widget_type,
                _ => "dropDownBoxType",
            };
            format!(
                "\t\t{clausewitz_type} = {{\n\t\t\tname = \"{}\"\n\t\t\tposition = {{ x = {x} y = {y} }}\n\t\t\tsize = {{ width = {width} height = {height} }}\n\t\t\ttext = \"{}\"\n\t\t}}\n",
                widget.id, key
            )
        }
        "overlapping" | "overlappingElementsBoxType" => format!(
            "\t\toverlappingElementsBoxType = {{\n\t\t\tname = \"{}\"\n\t\t\tposition = {{ x = {x} y = {y} }}\n\t\t\tsize = {{ width = {width} height = {height} }}\n\t\t}}\n",
            widget.id
        ),
        _ => {
            let widget_sprite = widget.sprite.as_deref().unwrap_or(button_sprite);
            format!(
                "\t\tbuttonType = {{\n\t\t\tname = \"{}\"\n\t\t\tposition = {{ x = {x} y = {y} }}\n\t\t\tsize = {{ width = {width} height = {height} }}\n\t\t\tspriteType = \"{}\"\n\t\t\tbuttonFont = \"{}\"\n\t\t\ttext = \"{}\"\n\t\t\tclicksound = click_default\n\t\t}}\n",
                widget.id, widget_sprite, button_font, key
            )
        }
    }
}

fn gui_intent_widget_default_x(widget: &GuiIntentWidget) -> i32 {
    match widget.widget_type.as_deref().unwrap_or("button") {
        "scrollbar" | "scrollbarType" => 410,
        _ => 40,
    }
}

fn gui_intent_widget_default_width(widget: &GuiIntentWidget) -> i32 {
    match widget.widget_type.as_deref().unwrap_or("button") {
        "text" | "instantTextBoxType" => 420,
        "progressbar" | "progressbarType" => 300,
        "checkbox" | "checkboxType" => 220,
        "scrollbar" | "scrollbarType" => 18,
        "editbox" | "editBoxType" => 300,
        "dropdown" | "dropDownBoxType" | "dropdownType" | "comboBoxType" => 260,
        "icon" | "iconType" => 32,
        "button" | "buttonType" => 180,
        _ => 360,
    }
}

fn render_gui_intent_localisation(intent: &GuiIntentFields) -> Result<String, String> {
    let prefix = required_gui_intent_value(intent.id_prefix.as_deref(), "id_prefix")?;
    let title = required_gui_intent_value(intent.title.as_deref(), "title")?;
    let description = required_gui_intent_value(intent.description.as_deref(), "description")?;
    let mut out = String::new();
    out.push_str("l_simp_chinese:\n");
    out.push_str(&format!(
        " {prefix}_title:0 \"{}\"\n",
        escape_loc_text(&title)
    ));
    out.push_str(&format!(
        " {prefix}_desc:0 \"{}\"\n",
        escape_loc_text(&description)
    ));
    for widget in &intent.widgets {
        if widget.id.is_empty() {
            continue;
        }
        let key = gui_widget_localisation_key(&prefix, &widget.id);
        let text = widget
            .localisation
            .as_deref()
            .filter(|value| !gui_intent_value_missing(Some(value)))
            .unwrap_or(&widget.id);
        out.push_str(&format!(" {key}:0 \"{}\"\n", escape_loc_text(text)));
        if let Some(placeholder) = widget
            .placeholder
            .as_deref()
            .filter(|value| !gui_intent_value_missing(Some(value)))
        {
            out.push_str(&format!(
                " {key}_placeholder:0 \"{}\"\n",
                escape_loc_text(placeholder)
            ));
        }
    }
    Ok(out)
}

fn render_gui_intent_decision_mount(decision_category: &str, scripted_gui_id: &str) -> String {
    format!(
        "{decision_category} = {{\n\ticon = GFX_decision_generic_political_discourse\n\tscripted_gui = {scripted_gui_id}\n\tvisible_when_empty = yes\n}}\n"
    )
}

fn apply_gui_intent_write_plan(plan: &GuiIntentWritePlan, force: bool) -> Result<(), String> {
    for file in &plan.files {
        if file.path.exists() && !force {
            return Err(format!(
                "refusing to overwrite existing file without --force: {}",
                file.path.display()
            ));
        }
    }
    for file in &plan.files {
        if let Some(parent) = file.path.parent() {
            fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
        }
        if file.role == "localisation" {
            let mut bytes = vec![0xef, 0xbb, 0xbf];
            bytes.extend_from_slice(file.text.as_bytes());
            fs::write(&file.path, bytes)
                .map_err(|e| format!("write {}: {e}", file.path.display()))?;
        } else {
            fs::write(&file.path, &file.text)
                .map_err(|e| format!("write {}: {e}", file.path.display()))?;
        }
    }
    Ok(())
}

fn prepare_gui_intent_staging_root(
    mod_root: &Path,
    intent: &GuiIntentFields,
) -> Result<PathBuf, String> {
    let scripted_gui_id =
        required_gui_intent_value(intent.scripted_gui_id.as_deref(), "scripted_gui_id")?;
    let staging_parent = mod_root.join(".hoi4skill").join("gui_staging");
    let staging_root = staging_parent.join(sanitize_file_stem(&scripted_gui_id));
    let canonical_parent = staging_parent
        .canonicalize()
        .or_else(|_| {
            fs::create_dir_all(&staging_parent)
                .map(|_| staging_parent.clone())
                .and_then(|path| path.canonicalize())
        })
        .map_err(|e| {
            format!(
                "prepare GUI staging parent {}: {e}",
                staging_parent.display()
            )
        })?;
    if staging_root.exists() {
        let canonical_staging = staging_root.canonicalize().map_err(|e| {
            format!(
                "canonicalize GUI staging root before cleanup {}: {e}",
                staging_root.display()
            )
        })?;
        if !canonical_staging.starts_with(&canonical_parent) {
            return Err(format!(
                "refusing to clean GUI staging root outside staging parent: {}",
                canonical_staging.display()
            ));
        }
        fs::remove_dir_all(&canonical_staging).map_err(|e| {
            format!(
                "clean GUI staging root {}: {e}",
                canonical_staging.display()
            )
        })?;
    }
    fs::create_dir_all(&staging_root)
        .map_err(|e| format!("create GUI staging root {}: {e}", staging_root.display()))?;
    Ok(staging_root)
}

fn retarget_gui_intent_write_plan(
    plan: &GuiIntentWritePlan,
    mod_root: &Path,
) -> GuiIntentWritePlan {
    GuiIntentWritePlan {
        files: plan
            .files
            .iter()
            .map(|file| GuiIntentWriteFile {
                role: file.role.clone(),
                path: mod_root.join(slash_path_to_native(&file.relative_path)),
                relative_path: file.relative_path.clone(),
                text: file.text.clone(),
            })
            .collect(),
    }
}

fn capture_gui_write_rollback(plan: &GuiIntentWritePlan) -> Result<GuiWriteRollback, String> {
    let mut items = Vec::new();
    for file in &plan.files {
        let previous_bytes = if file.path.exists() {
            Some(
                fs::read(&file.path)
                    .map_err(|e| format!("read {} before GUI write: {e}", file.path.display()))?,
            )
        } else {
            None
        };
        items.push(GuiWriteRollbackItem {
            path: file.path.clone(),
            relative_path: file.relative_path.clone(),
            previous_bytes,
        });
    }
    Ok(GuiWriteRollback { items })
}

fn restore_gui_write_rollback(rollback: &GuiWriteRollback) -> GuiRollbackReport {
    let mut restored_files = Vec::new();
    let mut deleted_files = Vec::new();
    let mut blockers = Vec::new();
    for item in rollback.items.iter().rev() {
        match &item.previous_bytes {
            Some(bytes) => match fs::write(&item.path, bytes) {
                Ok(()) => restored_files.push(item.relative_path.clone()),
                Err(error) => {
                    blockers.push(format!("restore_failed:{}:{error}", item.relative_path))
                }
            },
            None => {
                if item.path.exists() {
                    match fs::remove_file(&item.path) {
                        Ok(()) => deleted_files.push(item.relative_path.clone()),
                        Err(error) => blockers.push(format!(
                            "delete_generated_file_failed:{}:{error}",
                            item.relative_path
                        )),
                    }
                } else {
                    deleted_files.push(item.relative_path.clone());
                }
            }
        }
    }
    GuiRollbackReport {
        attempted: true,
        ok: blockers.is_empty(),
        restored_files,
        deleted_files,
        blockers,
    }
}

fn gui_widget_click_handler_id(widget_id: &str) -> String {
    if widget_id.ends_with("_click") {
        widget_id.to_string()
    } else {
        format!("{widget_id}_click")
    }
}

fn gui_button_name_from_click(click_id: &str) -> String {
    click_id
        .strip_suffix("_click")
        .unwrap_or(click_id)
        .to_string()
}

fn gui_widget_localisation_key(prefix: &str, widget_id: &str) -> String {
    format!("{prefix}_{widget_id}_text")
}

fn escape_loc_text(text: &str) -> String {
    text.replace('\\', "\\\\").replace('"', "\\\"")
}

fn apply_gui_intent_report_json(
    input: &Path,
    mod_root: &Path,
    intent: &GuiIntentFields,
    validation: &GuiIntentValidation,
    plan: &GuiIntentWritePlan,
    style_source: &str,
    style_template: Option<&GuiStyleRuntimeTemplate>,
    output_audit: Option<&GuiOutputAudit>,
    final_check: Option<&GuiFinalCheckReport>,
    evidence: &ApplyGuiIntentEvidenceContract,
    rollback: Option<&GuiRollbackReport>,
    execute: bool,
    ok: bool,
    write_error: Option<&str>,
) -> String {
    let files = plan
        .files
        .iter()
        .map(|file| {
            format!(
                "    {{\"role\": {}, \"path\": {}, \"relative_path\": {}, \"bytes\": {}, \"preview\": {}}}",
                json_str(&file.role),
                json_str(&file.path.display().to_string()),
                json_str(&file.relative_path),
                file.text.len(),
                json_str(&file.text),
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    let changed_files = if execute && ok {
        plan.files
            .iter()
            .map(|file| file.relative_path.clone())
            .collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    let mut blockers = validation.blockers.clone();
    if let Some(check) = final_check {
        blockers.extend(
            check
                .blockers
                .iter()
                .map(|blocker| format!("final_check:{blocker}")),
        );
    }
    if let Some(rollback) = rollback {
        blockers.extend(
            rollback
                .blockers
                .iter()
                .map(|blocker| format!("rollback:{blocker}")),
        );
    }
    blockers.sort();
    blockers.dedup();
    let final_code_safety_status =
        apply_gui_intent_final_code_safety_status(validation, final_check, ok);
    let output_plan_audit_ready = output_audit
        .map(|audit| !audit.plan_audit_requested || audit.plan_audit_ready)
        .unwrap_or(!execute || !ok);
    let final_text_source = final_check
        .map(|check| check.text_source.display().to_string())
        .unwrap_or_else(|| evidence.user_text_source.display().to_string());
    let expected_visible_text_count = final_check
        .map(|check| check.expected_visible_texts.len())
        .unwrap_or(evidence.expected_visible_text_count);
    let text_alignment_missing_count = final_check
        .map(|check| check.text_alignment_missing_count)
        .unwrap_or(-1);
    let text_alignment_ready = final_check.is_some_and(|check| {
        check.text_alignment_ok
            && check.text_alignment_missing_count == 0
            && check.text_source.is_file()
    });
    let user_text_source_ready = evidence.user_text_source_ready && text_alignment_ready;
    format!(
        "{{\n  \"schema\": \"hoi4skill.apply_gui_intent.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"final_code_safety_status\": {},\n  \"executed\": {},\n  \"input\": {},\n  \"mod_root\": {},\n  \"gui_kind\": {},\n  \"scripted_gui_id\": {},\n  \"window_name\": {},\n  \"validation_ok\": {},\n  \"style_source\": {},\n  \"style_token_summary\": {},\n  \"style_evidence\": {},\n  \"style_token_evidence\": {},\n  \"control_type_evidence\": {},\n  \"control_support_matrix\": {},\n  \"ai_context_contract\": {},\n  \"ai_context_contract_report_available\": {},\n  \"ai_context_contract_ready\": {},\n  \"require_ai_context_contract\": {},\n  \"user_text_source\": {},\n  \"user_text_source_explicit\": {},\n  \"user_text_source_exists\": {},\n  \"user_text_source_ready\": {},\n  \"require_user_text_source\": {},\n  \"expected_visible_text_count\": {},\n  \"text_alignment_missing_count\": {},\n  \"text_alignment_ready\": {},\n  \"output_audit_ok\": {},\n  \"output_plan_audit_ready\": {},\n  \"final_check_ok\": {},\n  \"rollback_ok\": {},\n  \"blocking_count\": {},\n  \"blockers\": {},\n  \"questions\": {},\n  \"asset_question_count\": {},\n  \"asset_questions\": {},\n  \"asset_todo\": {},\n  \"write_error\": {},\n  \"planned_files\": [\n{}\n  ],\n  \"changed_files\": {},\n  \"output_audit\": {},\n  \"final_check\": {},\n  \"rollback\": {},\n  \"recommended_actions\": {},\n  \"recommended_code\": {},\n  \"recommended_game_code\": {},\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(if ok && execute {
            "applied"
        } else if ok {
            "planned"
        } else {
            "blocked"
        }),
        json_bool(ok),
        json_str(final_code_safety_status),
        json_bool(execute && ok),
        json_str(&input.display().to_string()),
        json_str(&mod_root.display().to_string()),
        json_optional_str(intent.gui_kind.as_deref()),
        json_optional_str(intent.scripted_gui_id.as_deref()),
        json_optional_str(intent.window_name.as_deref()),
        json_bool(validation.ok),
        json_str(style_source),
        gui_style_runtime_template_summary_json(style_template),
        gui_style_runtime_template_evidence_json(style_template),
        gui_style_runtime_template_token_evidence_json(style_template),
        gui_style_runtime_template_control_type_evidence_json(style_template),
        gui_control_support_matrix_json(),
        json_optional_str(
            evidence
                .ai_context_contract
                .as_ref()
                .map(|path| path.display().to_string())
                .as_deref(),
        ),
        json_bool(evidence.ai_context_contract_report_available),
        json_bool(evidence.ai_context_contract_ready),
        json_bool(evidence.require_ai_context_contract),
        json_str(&final_text_source),
        json_bool(evidence.user_text_source_explicit),
        json_bool(evidence.user_text_source_exists),
        json_bool(user_text_source_ready),
        json_bool(evidence.require_user_text_source),
        expected_visible_text_count,
        text_alignment_missing_count,
        json_bool(text_alignment_ready),
        json_bool(output_audit.is_none_or(|audit| audit.ok)),
        json_bool(output_plan_audit_ready),
        json_bool(final_check.is_none_or(|check| check.ok)),
        json_bool(rollback.is_none_or(|rollback| rollback.ok)),
        blockers.len(),
        json_array(&blockers),
        json_array(&validation.questions),
        validation.asset_questions.len(),
        json_array(&validation.asset_questions),
        gui_request_asset_todo_json(&validation.asset_todo),
        json_optional_str(write_error),
        files,
        json_array(&changed_files),
        output_audit
            .map(gui_output_audit_summary_json)
            .unwrap_or_else(|| "null".to_string()),
        final_check
            .map(gui_final_check_report_json)
            .unwrap_or_else(|| "null".to_string()),
        rollback
            .map(gui_rollback_report_json)
            .unwrap_or_else(|| "null".to_string()),
        json_array(&apply_gui_intent_recommended_actions(
            final_check,
            evidence,
            rollback,
            write_error,
        )),
        json_array(&apply_gui_intent_recommended_code(
            intent,
            final_check,
            rollback,
            write_error,
        )),
        apply_gui_intent_recommended_game_code_json(
            plan,
            validation,
            final_check,
            rollback,
            ok,
        ),
        json_array(&vec![
            "hoi4skill gui-output-audit --mod-root <mod-root> --changed-file <changed files> --require-passed".to_string(),
            "hoi4skill apply-gui-intent --mod-root <mod-root> --input <gui intent> --style-mod <parent mod> --game-root <HOI4 root> --execute --final-check --require-passed".to_string(),
            "hoi4skill validate <mod-root> --game-root <HOI4 root> --strict-code-index".to_string(),
            "hoi4skill check-text-alignment --mod-root <mod-root> --input <original user GUI request>".to_string(),
        ]),
        json_array(&large_mod_gui_authoring_stop_conditions()),
    )
}

fn apply_gui_intent_final_code_safety_status(
    validation: &GuiIntentValidation,
    final_check: Option<&GuiFinalCheckReport>,
    ok: bool,
) -> &'static str {
    if ok {
        "written_after_final_check"
    } else if !validation.ok {
        "blocked_no_clausewitz_candidate"
    } else if final_check.is_some_and(|check| check.strict_validation_ok) {
        "candidate_verified_before_rollback"
    } else {
        "candidate_only_requires_final_check"
    }
}

fn gui_rollback_report_json(report: &GuiRollbackReport) -> String {
    format!(
        "{{\"attempted\": {}, \"ok\": {}, \"restored_files\": {}, \"deleted_files\": {}, \"blocking_count\": {}, \"blockers\": {}}}",
        json_bool(report.attempted),
        json_bool(report.ok),
        json_array(&report.restored_files),
        json_array(&report.deleted_files),
        report.blockers.len(),
        json_array(&report.blockers),
    )
}

fn apply_gui_intent_recommended_actions(
    final_check: Option<&GuiFinalCheckReport>,
    evidence: &ApplyGuiIntentEvidenceContract,
    rollback: Option<&GuiRollbackReport>,
    write_error: Option<&str>,
) -> Vec<String> {
    let mut actions = Vec::new();
    if let Some(error) = write_error {
        actions.push(format!(
            "Fix the write failure before rerun; no final GUI code is acceptable while write_error is `{error}`."
        ));
    }
    if let Some(check) = final_check {
        if check
            .blockers
            .iter()
            .any(|blocker| blocker.contains("final_check_requires_game_root"))
        {
            actions.push(
                "Rerun with --game-root <valid Hearts of Iron IV root>; strict-code-index is mandatory for final GUI writes."
                    .to_string(),
            );
        }
        if check
            .blockers
            .iter()
            .any(|blocker| blocker.contains("strict_code_index_validation_failed"))
        {
            actions.push(
                "Open final_check.artifacts validation_strict_code_index.json, fix every reported syntax/resource/localisation error in the GUI intent or style evidence, then rerun apply-gui-intent --execute --final-check."
                    .to_string(),
            );
        }
        if !check.text_alignment_ok {
            actions.push(
                "Restore every user-visible GUI title, description, and widget label from the intent; do not rename or drop text to make validation pass."
                    .to_string(),
            );
        }
        if !check.gui_output_ok {
            actions.push(
                "Fix scripted_gui window_name, button handler, and localisation key bindings before any file can be accepted."
                    .to_string(),
            );
        }
    }
    if evidence.require_ai_context_contract && !evidence.ai_context_contract_ready {
        actions.push(
            "Run gui-request-workflow or pass --ai-context-contract <gui_ai_context_contract.json>; final GUI writes are blocked until the AI context proves structured-intent-only authority, related-code context, strict gates, and a final-write boundary."
                .to_string(),
        );
    } else if evidence.ai_context_contract_report_available && !evidence.ai_context_contract_ready {
        actions.push(
            "Regenerate gui_ai_context_contract.json; the current contract is present but does not prove the allowed edit surface, forbidden raw Clausewitz output, related-code context, and strict final gates."
                .to_string(),
        );
    }
    if evidence.require_user_text_source
        && (!evidence.user_text_source_explicit || !evidence.user_text_source_ready)
    {
        actions.push(
            "Pass --text-source <original user GUI request> and rerun --final-check so visible GUI strings cannot drift from the user's requested wording."
                .to_string(),
        );
    }
    if let Some(rollback) = rollback {
        if rollback.ok {
            actions.push(
                "Generated files were rolled back because final checks failed; repair the intent or missing evidence before writing again."
                    .to_string(),
            );
        } else {
            actions.push(
                "Rollback failed for at least one file; inspect rollback.blockers before continuing and restore the listed files manually from version control or backups."
                    .to_string(),
            );
        }
    }
    if actions.is_empty() {
        actions.push(
            "If new GUI art, tags, icons, or mount points are required, provide indexed evidence or explicit user approval before rerunning."
                .to_string(),
        );
    }
    actions
}

fn apply_gui_intent_recommended_code(
    intent: &GuiIntentFields,
    final_check: Option<&GuiFinalCheckReport>,
    rollback: Option<&GuiRollbackReport>,
    write_error: Option<&str>,
) -> Vec<String> {
    let mut snippets = Vec::new();
    if write_error.is_some() {
        snippets.push(
            "Do not edit final GUI files by hand. Fix the path/overwrite issue, then rerun the same hoi4skill apply-gui-intent command with --force only if overwriting is intentional."
                .to_string(),
        );
    }
    if let Some(check) = final_check {
        if check
            .blockers
            .iter()
            .any(|blocker| blocker.contains("final_check_requires_game_root"))
        {
            snippets.push(
                "hoi4skill apply-gui-intent --mod-root <target mod> --input <gui_intent.md> --style-mod <parent mod> --game-root <valid HOI4 root> --execute --final-check --require-passed"
                    .to_string(),
            );
        }
        if check
            .blockers
            .iter()
            .any(|blocker| blocker.contains("strict_code_index_validation_failed"))
        {
            snippets.push(apply_gui_intent_repair_intent_snippet(intent));
        }
    }
    if rollback.is_some_and(|report| report.ok) {
        snippets.push(
            "The failed generated files were removed/restored. Apply only a repaired hoi4skill.gui_intent.v1; do not paste recovered final Clausewitz into common/, interface/, or localisation/."
                .to_string(),
        );
    }
    if snippets.is_empty() {
        snippets.push(
            "No blocking repair code is needed. Keep future changes in hoi4skill.gui_intent.v1 and rerun --final-check."
                .to_string(),
        );
    }
    snippets
}

fn apply_gui_intent_recommended_game_code_json(
    plan: &GuiIntentWritePlan,
    validation: &GuiIntentValidation,
    final_check: Option<&GuiFinalCheckReport>,
    _rollback: Option<&GuiRollbackReport>,
    ok: bool,
) -> String {
    if ok {
        return "[]".to_string();
    }
    if !validation.ok {
        let mut entries = apply_gui_validation_evidence_required_game_code(validation);
        append_apply_gui_asset_registration_candidates(validation, &mut entries);
        return format!("[\n{}\n  ]", entries.join(",\n"));
    }
    let status = if final_check.is_some_and(|check| check.strict_validation_ok) {
        "candidate_verified_before_rollback"
    } else {
        "candidate_unverified_not_written"
    };
    let reason = if final_check.is_some_and(|check| !check.strict_validation_ok) {
        "final_check_failed_or_incomplete"
    } else {
        "rolled_back_after_blocking_gate"
    };
    let mut entries = plan
        .files
        .iter()
        .map(|file| {
            format!(
                "    {{\"role\": {}, \"relative_path\": {}, \"status\": {}, \"written_to_mod\": false, \"must_rerun_final_check\": true, \"reason\": {}, \"code\": {}}}",
                json_str(&file.role),
                json_str(&file.relative_path),
                json_str(status),
                json_str(reason),
                json_str(&file.text),
            )
        })
        .collect::<Vec<_>>();
    append_apply_gui_asset_registration_candidates(validation, &mut entries);
    let entries = entries.join(",\n");
    format!("[\n{}\n  ]", entries)
}

fn apply_gui_validation_evidence_required_game_code(
    validation: &GuiIntentValidation,
) -> Vec<String> {
    let evidence_text = if validation.blockers.is_empty() {
        "missing apply-gui-intent evidence".to_string()
    } else {
        validation.blockers.join(", ")
    };
    vec![format!(
        "    {{\"role\": {}, \"relative_path\": {}, \"status\": {}, \"written_to_mod\": false, \"must_rerun_final_check\": true, \"reason\": {}, \"code\": {}}}",
        json_str("apply_gui_evidence_required"),
        json_str(".hoi4skill/apply_gui_evidence_required.md"),
        json_str("blocked_no_clausewitz_candidate"),
        json_str("validation_blockers_prevent_final_gui_code_candidates"),
        json_str(&format!(
            "No final GUI code is recommended while apply-gui-intent validation blockers are unresolved: `{evidence_text}`. Fix the intent, choose indexed resources, register approved assets, or provide parent-mod style evidence, then rerun apply-gui-intent --execute --final-check."
        )),
    )]
}

fn append_apply_gui_asset_registration_candidates(
    validation: &GuiIntentValidation,
    entries: &mut Vec<String>,
) {
    for todo in &validation.asset_todo {
        entries.push(format!(
            "    {{\"role\": {}, \"relative_path\": {}, \"status\": {}, \"written_to_mod\": false, \"must_rerun_final_check\": true, \"reason\": {}, \"code\": {}}}",
            json_str("gui_asset_registration_candidate"),
            json_str(&todo.suggested_gfx_file),
            json_str("candidate_only_not_written"),
            json_str("new_gui_asset_requires_user_authorization_and_image_file"),
            json_str(&format!(
                "spriteTypes = {{\n\tspriteType = {{\n\t\tname = \"{}\"\n\t\ttexturefile = \"{}\"\n\t}}\n}}\n# Required before use: create/approve the transparent image asset, verify dimensions, then rerun strict-code-index and GUI output audit.\n",
                todo.sprite,
                todo.suggested_texturefile,
            )),
        ));
    }
}

fn apply_gui_intent_repair_intent_snippet(intent: &GuiIntentFields) -> String {
    let gui_kind = intent.gui_kind.as_deref().unwrap_or("standalone");
    let id_prefix = intent.id_prefix.as_deref().unwrap_or("<safe_prefix>");
    let scripted_gui_id = intent.scripted_gui_id.as_deref().unwrap_or("<prefix>_gui");
    let window_name = intent.window_name.as_deref().unwrap_or("<prefix>_window");
    let title = intent.title.as_deref().unwrap_or("<visible title>");
    let description = intent
        .description
        .as_deref()
        .unwrap_or("<visible description>");
    let open_flag = intent.open_flag.as_deref().unwrap_or("open_<prefix>");
    let close_button = intent
        .close_button
        .as_deref()
        .unwrap_or("close_<prefix>_click");
    let open_effect = intent.open_effect.as_deref().unwrap_or("open_<prefix>_gui");
    let close_effect = intent
        .close_effect
        .as_deref()
        .unwrap_or("close_<prefix>_gui");
    format!(
        "```yaml\nschema: hoi4skill.gui_intent.v1\ngui_kind: {gui_kind}\nid_prefix: {id_prefix}\nscripted_gui_id: {scripted_gui_id}\nwindow_name: {window_name}\ntitle: {title}\ndescription: {description}\nstate_protocol:\n  open_flag: {open_flag}\n  close_button: {close_button}\nscripted_effects:\n  open_effect: {open_effect}\n  close_effect: {close_effect}\nwidgets:\n  - id: <verified_button_id>\n    type: button\n    localisation: <visible label preserved from user request>\n    sprite: <indexed_GFX_sprite_or_omit>\n    click_effect: <verified_scripted_effect_id>\nlocalisation_placeholders:\n  - <only unresolved icons flags leaders colors cosmetic tags>\nquestions_for_user:\n  - <ask for exact missing sprite/tag/mount evidence instead of guessing>\n```"
    )
}

fn gui_final_check_report_json(report: &GuiFinalCheckReport) -> String {
    format!(
        "{{\"ok\": {}, \"required\": {}, \"reports_dir\": {}, \"game_root\": {}, \"changed_files\": {}, \"gui_output_ok\": {}, \"gfx_audit_ok\": {}, \"text_alignment_ok\": {}, \"text_source\": {}, \"expected_visible_text_count\": {}, \"expected_visible_texts\": {}, \"text_alignment_missing_count\": {}, \"strict_validation_ok\": {}, \"error_log_ok\": {}, \"error_log_gui_diagnostic_count\": {}, \"error_log_gui_diagnostics\": {}, \"blocking_count\": {}, \"blockers\": {}, \"artifacts\": {}}}",
        json_bool(report.ok),
        json_bool(report.required),
        json_str(&report.reports_dir.display().to_string()),
        json_optional_str(report.game_root.as_ref().map(|path| path.display().to_string()).as_deref()),
        json_array(&report.changed_files),
        json_bool(report.gui_output_ok),
        json_bool(report.gfx_audit_ok),
        json_bool(report.text_alignment_ok),
        json_str(&report.text_source.display().to_string()),
        report.expected_visible_texts.len(),
        json_array(&report.expected_visible_texts),
        report.text_alignment_missing_count,
        json_bool(report.strict_validation_ok),
        json_bool(report.error_log_ok),
        report.error_log_gui_diagnostic_count,
        json_array(&report.error_log_gui_diagnostics),
        report.blockers.len(),
        json_array(&report.blockers),
        json_array(&report.artifacts),
    )
}

