#[derive(Clone, Debug)]
struct GuiOutputAudit {
    ok: bool,
    strict_code_index: bool,
    style_audit_requested: bool,
    plan_audit_requested: bool,
    plan_audit_ready: bool,
    plan_audit_matches: Vec<String>,
    plan_audit_missing: Vec<String>,
    style_token_reuse_ready: bool,
    style_token_match_count: usize,
    style_token_matches: Vec<String>,
    style_token_missing: Vec<String>,
    style_structure_reuse_ready: bool,
    style_structure_match_count: usize,
    style_structure_matches: Vec<String>,
    style_structure_missing: Vec<String>,
    style_component_reuse_ready: bool,
    style_component_match_count: usize,
    style_component_matches: Vec<String>,
    style_component_missing: Vec<String>,
    checked_scripted_gui_files: Vec<String>,
    scripted_gui_count: usize,
    interface_name_count: usize,
    interface_control_type_counts: Vec<(String, usize)>,
    interface_layout_issues: Vec<String>,
    localisation_key_count: usize,
    interface_sprite_ref_count: usize,
    blockers: Vec<String>,
    questions: Vec<String>,
    recommended_syntax: Vec<String>,
    recommended_game_code: Vec<GuiRequestGameCodeCandidate>,
    warnings: Vec<String>,
}

#[derive(Clone, Debug, Default)]
struct GuiOutputAuditExpected {
    scripted_gui_id: Option<String>,
    window_name: Option<String>,
    click_targets: Vec<String>,
    open_effect: Option<String>,
    close_effect: Option<String>,
    open_flag: Option<String>,
    source_reports: Vec<String>,
}

impl GuiOutputAuditExpected {
    fn has_any(&self) -> bool {
        self.scripted_gui_id.is_some()
            || self.window_name.is_some()
            || !self.click_targets.is_empty()
            || self.open_effect.is_some()
            || self.close_effect.is_some()
            || self.open_flag.is_some()
    }
}

#[derive(Clone, Debug)]
struct GuiLayoutWidget {
    relative_path: String,
    control_type: String,
    name: Option<String>,
    line: usize,
    x: Option<i32>,
    y: Option<i32>,
    width: Option<i32>,
    height: Option<i32>,
}

impl GuiLayoutWidget {
    fn location(&self) -> String {
        format!("{}:line{}", self.relative_path, self.line)
    }

    fn display_name(&self) -> String {
        self.name
            .clone()
            .unwrap_or_else(|| format!("{}@{}", self.control_type, self.location()))
    }
}

fn gui_output_audit_for_paths_with_style(
    mod_root: &Path,
    changed_paths: &[String],
    style_template: Option<&GuiStyleRuntimeTemplate>,
    expected: Option<&GuiOutputAuditExpected>,
) -> Result<GuiOutputAudit, String> {
    gui_output_audit_for_paths_with_index(mod_root, changed_paths, None, style_template, expected)
}

fn gui_output_audit_for_paths_with_index(
    mod_root: &Path,
    changed_paths: &[String],
    strict_index: Option<&GameIndex>,
    style_template: Option<&GuiStyleRuntimeTemplate>,
    expected: Option<&GuiOutputAuditExpected>,
) -> Result<GuiOutputAudit, String> {
    let changed = changed_paths
        .iter()
        .map(|path| path.replace('\\', "/"))
        .collect::<BTreeSet<_>>();
    let all_scripted_gui_files = collect_profile_files_relative(
        mod_root,
        &mod_root.join("common").join("scripted_guis"),
        &["txt"],
        5000,
    )?;
    let scripted_gui_files = if changed.is_empty() {
        all_scripted_gui_files.clone()
    } else {
        all_scripted_gui_files
            .into_iter()
            .filter(|path| changed.contains(path))
            .collect::<Vec<_>>()
    };
    let interface_files =
        collect_profile_files_relative(mod_root, &mod_root.join("interface"), &["gui"], 5000)?;
    let loc_files = collect_profile_files_relative(
        mod_root,
        &mod_root.join("localisation"),
        &["yml", "yaml"],
        10000,
    )?;
    let scripted_effect_files = collect_profile_files_relative(
        mod_root,
        &mod_root.join("common").join("scripted_effects"),
        &["txt"],
        5000,
    )?;

    let mut scripted_guis = Vec::new();
    for relative in &scripted_gui_files {
        scripted_guis.extend(parse_scripted_gui_entries(
            mod_root,
            &mod_root.join(slash_path_to_native(relative)),
        )?);
    }
    let mut interface_window_names = Vec::new();
    let mut interface_element_names = BTreeSet::new();
    let mut interface_text_keys = BTreeSet::new();
    let mut interface_sprite_refs = BTreeSet::new();
    let mut interface_font_refs = BTreeSet::new();
    let mut interface_structure_signatures = BTreeSet::new();
    let mut interface_component_templates = BTreeSet::new();
    let mut interface_control_type_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut interface_layout_widgets = Vec::new();
    for relative in &interface_files {
        let path = mod_root.join(slash_path_to_native(relative));
        let text = read_utf8_lossy(&path)?;
        interface_layout_widgets.extend(parse_gui_layout_widgets(&text, relative));
        for name in parse_gui_window_names(&path)? {
            push_capped_unique(&mut interface_window_names, name.clone(), 10000);
            interface_element_names.insert(name);
        }
        for text_key in parse_gui_text_keys(&text) {
            interface_text_keys.insert(text_key);
        }
        for sprite in parse_gui_sprite_refs(&text) {
            interface_sprite_refs.insert(sprite);
        }
        for font in parse_gui_font_refs(&text) {
            interface_font_refs.insert(font);
        }
        for signature in gui_style_structure_signatures_from_text(&text) {
            interface_structure_signatures.insert(signature);
        }
        for component in gui_style_component_templates_from_text(&text) {
            interface_component_templates.insert(component);
        }
        for control_type in parse_gui_control_type_refs(&text) {
            *interface_control_type_counts
                .entry(control_type)
                .or_insert(0) += 1;
        }
    }
    let mut localisation_keys = BTreeSet::new();
    for relative in &loc_files {
        let text = read_utf8_lossy(&mod_root.join(slash_path_to_native(relative)))?;
        localisation_keys.extend(parse_localisation_keys(&text));
    }
    let scripted_effect_ids =
        gui_output_collect_scripted_effect_ids(mod_root, &scripted_effect_files)?;
    let scripted_effect_text = gui_output_collect_text(mod_root, &scripted_effect_files)?;
    let enforce_action_helper_registration =
        expected.is_some_and(GuiOutputAuditExpected::has_any) || !scripted_effect_files.is_empty();
    let interface_container_names = interface_layout_widgets
        .iter()
        .filter(|widget| widget.control_type == "containerWindowType")
        .filter_map(|widget| widget.name.clone())
        .collect::<BTreeSet<_>>();

    let mut blockers = Vec::new();
    let mut questions = Vec::new();
    let mut warnings = Vec::new();
    if scripted_gui_files.is_empty() {
        warnings.push("no_changed_scripted_gui_files_to_audit".to_string());
    }
    let (style_token_reuse_ready, style_token_matches, style_token_missing) =
        gui_output_style_token_usage(
            style_template,
            &interface_font_refs,
            &interface_sprite_refs,
            &interface_control_type_counts,
            &scripted_guis,
        );
    if style_template.is_some() && !style_token_reuse_ready {
        blockers.push("style_token_reuse_not_observed_in_output".to_string());
        for missing in &style_token_missing {
            blockers.push(format!("style_reuse_missing:{missing}"));
        }
        questions.push(
            "Generated GUI output did not reuse enough parent-mod style tokens. Rerun apply-gui-intent with the style template package or choose indexed parent-mod font/sprite/control evidence before accepting final files."
                .to_string(),
        );
    }
    let (style_structure_reuse_ready, style_structure_matches, style_structure_missing) =
        gui_output_style_structure_usage(style_template, &interface_structure_signatures);
    if style_template.is_some() && !style_structure_reuse_ready {
        blockers.push("style_structure_reuse_not_observed_in_output".to_string());
        for missing in &style_structure_missing {
            blockers.push(format!("style_structure_missing:{missing}"));
        }
        questions.push(
            "Generated GUI output does not match enough parent-mod structural signatures. Reuse an indexed parent-mod window/control family, close/action button pattern, text area, or panel sprite before accepting final files."
                .to_string(),
        );
    }
    let (style_component_reuse_ready, style_component_matches, style_component_missing) =
        gui_output_style_component_usage(style_template, &interface_component_templates);
    if style_template.is_some() && !style_component_reuse_ready {
        blockers.push("style_component_reuse_not_observed_in_output".to_string());
        for missing in &style_component_missing {
            blockers.push(format!("style_component_missing:{missing}"));
        }
        questions.push(
            "Generated GUI output does not match enough parent-mod component templates. Reuse an indexed parent-mod component family such as titlebar_close, list_detail_scroll, pagination_buttons, filter_list, or progress_action before accepting final files."
                .to_string(),
        );
    }
    let interface_layout_issues = gui_output_layout_issues(&interface_layout_widgets);
    for issue in &interface_layout_issues {
        blockers.push(issue.clone());
    }
    for control_type in interface_control_type_counts.keys() {
        if !gui_output_audit_control_type_supported(control_type) {
            blockers.push(format!("interface_control_type_unsupported:{control_type}"));
            questions.push(format!(
                "Interface control `{control_type}` is not in the GUI writer support matrix. Add a writer and same-control style evidence before accepting this output."
            ));
        }
    }
    for entry in &scripted_guis {
        match entry.window_name.as_deref() {
            Some(window) if interface_window_names.iter().any(|name| name == window) => {}
            Some(window) => blockers.push(format!(
                "scripted_gui_window_missing_interface:{}:{}",
                entry.id, window
            )),
            None => blockers.push(format!("scripted_gui_missing_window_name:{}", entry.id)),
        }
        for effect in &entry.effect_tokens {
            let element = gui_button_name_from_click(effect);
            if !interface_element_names.contains(&element) {
                blockers.push(format!(
                    "scripted_gui_click_handler_missing_interface_button:{}:{}",
                    entry.id, effect
                ));
            }
        }
        for call in &entry.action_effect_calls {
            if enforce_action_helper_registration && !scripted_effect_ids.contains(call) {
                blockers.push(format!(
                    "scripted_gui_action_helper_missing_scripted_effect:{}:{}",
                    entry.id, call
                ));
                questions.push(format!(
                    "scripted_gui `{}` calls action helper `{call}`, but common/scripted_effects does not define `{call}`. Register it before accepting this GUI.",
                    entry.id
                ));
            }
        }
    }
    let scripted_gui_window_refs = scripted_guis
        .iter()
        .filter_map(|entry| entry.window_name.as_deref())
        .collect::<BTreeSet<_>>();
    let changed_interface_files = changed
        .iter()
        .any(|path| path.starts_with("interface/") && path.ends_with(".gui"));
    if changed_interface_files
        && scripted_gui_window_refs.is_empty()
        && !interface_window_names.is_empty()
    {
        for window in &interface_window_names {
            blockers.push(format!(
                "interface_window_unregistered_in_scripted_guis:{window}"
            ));
            questions.push(format!(
                "Interface window `{window}` exists but no changed common/scripted_guis entry references it. Register it through scripted_gui window_name before accepting the GUI."
            ));
        }
    }
    for key in &interface_text_keys {
        if looks_like_gui_localisation_key(key) && !localisation_keys.contains(key) {
            blockers.push(format!("interface_text_missing_localisation:{key}"));
        }
    }
    for sprite in &interface_sprite_refs {
        if gui_output_sprite_ref_unresolved_template(sprite) {
            blockers.push(format!("interface_sprite_unresolved_template:{sprite}"));
        } else if gui_output_sprite_ref_invalid_token(sprite) {
            blockers.push(format!("interface_sprite_invalid_token:{sprite}"));
        } else if let Some(index) = strict_index {
            if !index.sprites.contains(sprite) {
                blockers.push(format!(
                    "interface_sprite_unknown_in_strict_code_index:{sprite}"
                ));
                let candidates = nearest_or_first_string_candidates(
                    sprite,
                    index.sprites.iter().map(String::as_str),
                    8,
                );
                let candidate_text = if candidates.is_empty() {
                    "No indexed GUI sprite candidates were found.".to_string()
                } else {
                    format!("Candidate indexed sprites: {}.", candidates.join(", "))
                };
                questions.push(format!(
                    "GUI sprite `{sprite}` is not indexed by strict-code-index. {candidate_text} Choose an existing sprite or register the asset before accepting this GUI output."
                ));
            }
        }
    }
    let (plan_audit_ready, plan_audit_matches, plan_audit_missing) = gui_output_plan_audit(
        expected,
        &scripted_guis,
        &interface_container_names,
        &interface_element_names,
        &scripted_effect_ids,
        &scripted_effect_text,
        &mut blockers,
        &mut questions,
    );
    blockers.sort();
    blockers.dedup();
    questions.sort();
    questions.dedup();
    let recommended_syntax = gui_output_audit_recommended_syntax(&blockers);
    let recommended_game_code = gui_output_audit_recommended_game_code(&blockers);
    warnings.sort();
    warnings.dedup();
    Ok(GuiOutputAudit {
        ok: blockers.is_empty(),
        strict_code_index: strict_index.is_some(),
        style_audit_requested: style_template.is_some(),
        plan_audit_requested: expected.is_some_and(GuiOutputAuditExpected::has_any),
        plan_audit_ready,
        plan_audit_matches,
        plan_audit_missing,
        style_token_reuse_ready,
        style_token_match_count: style_token_matches.len(),
        style_token_matches,
        style_token_missing,
        style_structure_reuse_ready,
        style_structure_match_count: style_structure_matches.len(),
        style_structure_matches,
        style_structure_missing,
        style_component_reuse_ready,
        style_component_match_count: style_component_matches.len(),
        style_component_matches,
        style_component_missing,
        checked_scripted_gui_files: scripted_gui_files,
        scripted_gui_count: scripted_guis.len(),
        interface_name_count: interface_element_names.len(),
        interface_control_type_counts: interface_control_type_counts.into_iter().collect(),
        interface_layout_issues,
        localisation_key_count: localisation_keys.len(),
        interface_sprite_ref_count: interface_sprite_refs.len(),
        blockers,
        questions,
        recommended_syntax,
        recommended_game_code,
        warnings,
    })
}

fn parse_gui_text_keys(text: &str) -> Vec<String> {
    let mut keys = Vec::new();
    for raw in text.lines() {
        let line = raw.split('#').next().unwrap_or("").trim();
        for value in assignment_values(line, "text") {
            push_capped_unique(&mut keys, value, 10000);
        }
    }
    keys
}

fn gui_output_style_token_usage(
    style_template: Option<&GuiStyleRuntimeTemplate>,
    interface_font_refs: &BTreeSet<String>,
    interface_sprite_refs: &BTreeSet<String>,
    interface_control_type_counts: &BTreeMap<String, usize>,
    scripted_guis: &[ScriptedGuiEntry],
) -> (bool, Vec<String>, Vec<String>) {
    let Some(template) = style_template else {
        return (true, Vec::new(), Vec::new());
    };
    let mut matches = Vec::new();
    let mut missing = Vec::new();
    let font_match = template
        .fonts
        .iter()
        .find(|font| interface_font_refs.contains(*font));
    if let Some(font) = font_match {
        matches.push(format!("font:{font}"));
    } else if !template.fonts.is_empty() {
        missing.push("font".to_string());
    }
    let mut style_sprites = BTreeSet::new();
    for sprite in template
        .sprites
        .iter()
        .chain(template.button_sprites.iter())
        .chain(template.close_sprites.iter())
        .chain(template.panel_sprites.iter())
        .chain(template.tab_sprites.iter())
        .chain(template.map_sprites.iter())
    {
        style_sprites.insert(sprite.as_str());
    }
    let sprite_match = style_sprites
        .iter()
        .find(|sprite| interface_sprite_refs.contains(**sprite));
    if let Some(sprite) = sprite_match {
        matches.push(format!("sprite:{sprite}"));
    } else if !style_sprites.is_empty() {
        missing.push("sprite".to_string());
    }
    let control_match = interface_control_type_counts.keys().find(|control_type| {
        template
            .control_type_evidence
            .iter()
            .any(|item| gui_output_style_control_evidence_matches(control_type, item))
    });
    if let Some(control_type) = control_match {
        matches.push(format!("control_type:{control_type}"));
    } else if !template.control_type_evidence.is_empty() {
        missing.push("control_type".to_string());
    }
    let output_parent_tokens = scripted_guis
        .iter()
        .filter_map(|entry| entry.parent_window_token.as_deref())
        .collect::<BTreeSet<_>>();
    if !output_parent_tokens.is_empty() {
        if let Some(parent) = template
            .parent_window_tokens
            .iter()
            .find(|token| output_parent_tokens.contains(token.as_str()))
        {
            matches.push(format!("parent_window_token:{parent}"));
        } else {
            missing.push("parent_window_token".to_string());
        }
    }
    missing.sort();
    missing.dedup();
    matches.sort();
    matches.dedup();
    (missing.is_empty(), matches, missing)
}

fn gui_output_style_control_evidence_matches(output_control_type: &str, evidence: &str) -> bool {
    if evidence.starts_with(&format!("control_type:{output_control_type}:")) {
        return true;
    }
    let Some(rest) = evidence.strip_prefix("control_type:") else {
        return false;
    };
    let Some((intent_type, _)) = rest.split_once(':') else {
        return false;
    };
    gui_control_type_clausewitz_nodes()
        .into_iter()
        .find(|(candidate, _)| *candidate == intent_type)
        .is_some_and(|(_, nodes)| nodes.iter().any(|node| *node == output_control_type))
}

fn gui_output_style_structure_usage(
    style_template: Option<&GuiStyleRuntimeTemplate>,
    output_signatures: &BTreeSet<String>,
) -> (bool, Vec<String>, Vec<String>) {
    let Some(template) = style_template else {
        return (true, Vec::new(), Vec::new());
    };
    if template.structure_signatures.is_empty() {
        return (true, Vec::new(), Vec::new());
    }
    let mut matches = template
        .structure_signatures
        .iter()
        .filter(|signature| output_signatures.contains(*signature))
        .cloned()
        .collect::<Vec<_>>();
    matches.sort();
    matches.dedup();
    let mut missing = template
        .structure_signatures
        .iter()
        .filter(|signature| !output_signatures.contains(*signature))
        .take(24)
        .cloned()
        .collect::<Vec<_>>();
    missing.sort();
    missing.dedup();
    let required_matches = template.structure_signatures.len().min(2);
    (matches.len() >= required_matches, matches, missing)
}

fn gui_output_style_component_usage(
    style_template: Option<&GuiStyleRuntimeTemplate>,
    output_components: &BTreeSet<String>,
) -> (bool, Vec<String>, Vec<String>) {
    let Some(template) = style_template else {
        return (true, Vec::new(), Vec::new());
    };
    if template.component_templates.is_empty() {
        return (true, Vec::new(), Vec::new());
    }
    let mut matches = template
        .component_templates
        .iter()
        .filter(|component| output_components.contains(*component))
        .cloned()
        .collect::<Vec<_>>();
    matches.sort();
    matches.dedup();
    let mut missing = template
        .component_templates
        .iter()
        .filter(|component| !output_components.contains(*component))
        .take(24)
        .cloned()
        .collect::<Vec<_>>();
    missing.sort();
    missing.dedup();
    (matches.len() >= 1, matches, missing)
}

fn parse_gui_sprite_refs(text: &str) -> Vec<String> {
    let mut sprites = Vec::new();
    for raw in text.lines() {
        let line = raw.split('#').next().unwrap_or("").trim();
        for key in ["spriteType", "quadTextureSprite"] {
            for value in assignment_values(line, key) {
                push_capped_unique(&mut sprites, value, 10000);
            }
        }
    }
    sprites
}

fn parse_gui_font_refs(text: &str) -> Vec<String> {
    let mut fonts = Vec::new();
    for raw in text.lines() {
        let line = raw.split('#').next().unwrap_or("").trim();
        for key in ["font", "buttonFont"] {
            for value in assignment_values(line, key) {
                push_capped_unique(&mut fonts, value, 10000);
            }
        }
    }
    fonts
}

fn parse_gui_control_type_refs(text: &str) -> Vec<String> {
    let mut controls = Vec::new();
    for raw in text.lines() {
        let line = raw.split('#').next().unwrap_or("");
        let bytes = line.as_bytes();
        let mut i = 0usize;
        while i < bytes.len() {
            if bytes[i].is_ascii_alphabetic() {
                let start = i;
                i += 1;
                while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                    i += 1;
                }
                let token = &line[start..i];
                let mut after_token = i;
                while after_token < bytes.len() && bytes[after_token].is_ascii_whitespace() {
                    after_token += 1;
                }
                if token.ends_with("Type")
                    && after_token < bytes.len()
                    && bytes[after_token] == b'='
                    && gui_control_assignment_opens_block(bytes, after_token + 1)
                {
                    if controls.len() < 10000 {
                        controls.push(token.to_string());
                    }
                }
            } else {
                i += 1;
            }
        }
    }
    controls
}

fn parse_gui_layout_widgets(text: &str, relative_path: &str) -> Vec<GuiLayoutWidget> {
    let mut widgets = Vec::new();
    let mut stack: Vec<(GuiLayoutWidget, i32)> = Vec::new();
    for (idx, raw) in text.lines().enumerate() {
        let line = raw.split('#').next().unwrap_or("").trim();
        if line.is_empty() {
            continue;
        }
        if let Some(control_type) = gui_control_type_assignment_on_line(line) {
            stack.push((
                GuiLayoutWidget {
                    relative_path: relative_path.to_string(),
                    control_type,
                    name: None,
                    line: idx + 1,
                    x: None,
                    y: None,
                    width: None,
                    height: None,
                },
                0,
            ));
        }
        if let Some((widget, _)) = stack.last_mut() {
            gui_layout_widget_absorb_line(widget, line);
        }
        let delta = brace_delta(line);
        for (_, depth) in &mut stack {
            *depth += delta;
        }
        while stack.last().is_some_and(|(_, depth)| *depth <= 0) {
            if let Some((widget, _)) = stack.pop() {
                widgets.push(widget.clone());
            }
        }
    }
    while let Some((widget, _)) = stack.pop() {
        widgets.push(widget);
    }
    widgets
}

fn gui_control_type_assignment_on_line(line: &str) -> Option<String> {
    let bytes = line.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i].is_ascii_alphabetic() {
            let start = i;
            i += 1;
            while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                i += 1;
            }
            let token = &line[start..i];
            let mut after_token = i;
            while after_token < bytes.len() && bytes[after_token].is_ascii_whitespace() {
                after_token += 1;
            }
            if token.ends_with("Type")
                && after_token < bytes.len()
                && bytes[after_token] == b'='
                && gui_control_assignment_opens_block(bytes, after_token + 1)
            {
                return Some(token.to_string());
            }
        } else {
            i += 1;
        }
    }
    None
}

fn gui_layout_widget_absorb_line(widget: &mut GuiLayoutWidget, line: &str) {
    if widget.name.is_none() {
        widget.name = assignment_value(line, "name");
    }
    if widget.x.is_none() || widget.y.is_none() {
        if let Some((x, y)) = gui_assignment_xy_pair(line, "position", "x", "y") {
            widget.x = Some(x);
            widget.y = Some(y);
        }
    }
    if widget.width.is_none() || widget.height.is_none() {
        if let Some((width, height)) = gui_assignment_xy_pair(line, "size", "width", "height") {
            widget.width = Some(width);
            widget.height = Some(height);
        } else if let (Some(width), Some(height)) = (
            gui_assignment_i32(line, "maxWidth"),
            gui_assignment_i32(line, "maxHeight"),
        ) {
            widget.width = Some(width);
            widget.height = Some(height);
        }
    }
}

fn gui_assignment_xy_pair(line: &str, key: &str, x_key: &str, y_key: &str) -> Option<(i32, i32)> {
    let idx = line.find(key)?;
    let tail = &line[idx + key.len()..];
    let x = gui_assignment_i32(tail, x_key)?;
    let y = gui_assignment_i32(tail, y_key)?;
    Some((x, y))
}

fn gui_assignment_i32(line: &str, key: &str) -> Option<i32> {
    assignment_value(line, key)?.parse::<i32>().ok()
}

fn gui_output_layout_issues(widgets: &[GuiLayoutWidget]) -> Vec<String> {
    let mut issues = Vec::new();
    let mut names: BTreeMap<String, String> = BTreeMap::new();
    for widget in widgets {
        let location = widget.location();
        let Some(name) = widget.name.as_deref() else {
            push_capped_unique(
                &mut issues,
                format!(
                    "interface_layout_missing_name:{location}:{}",
                    widget.control_type
                ),
                2000,
            );
            continue;
        };
        if let Some(first) = names.insert(name.to_string(), location.clone()) {
            push_capped_unique(
                &mut issues,
                format!("interface_layout_duplicate_name:{name}:{first}:{location}"),
                2000,
            );
        }
        if widget.x.is_some_and(|x| x < 0) || widget.y.is_some_and(|y| y < 0) {
            push_capped_unique(
                &mut issues,
                format!("interface_layout_negative_position:{name}:{location}"),
                2000,
            );
        }
        if widget.width.is_some_and(|width| width <= 0)
            || widget.height.is_some_and(|height| height <= 0)
        {
            push_capped_unique(
                &mut issues,
                format!("interface_layout_invalid_size:{name}:{location}"),
                2000,
            );
        }
    }
    for (idx, left) in widgets.iter().enumerate() {
        for right in widgets.iter().skip(idx + 1) {
            if left.relative_path != right.relative_path {
                continue;
            }
            if gui_layout_widgets_overlap(left, right) {
                push_capped_unique(
                    &mut issues,
                    format!(
                        "interface_layout_rect_overlap:{}:{}:{}",
                        left.relative_path,
                        left.display_name(),
                        right.display_name()
                    ),
                    2000,
                );
            }
        }
    }
    issues
}

fn gui_layout_widgets_overlap(left: &GuiLayoutWidget, right: &GuiLayoutWidget) -> bool {
    if left.control_type == "containerWindowType" || right.control_type == "containerWindowType" {
        return false;
    }
    let (Some(lx), Some(ly), Some(lw), Some(lh), Some(rx), Some(ry), Some(rw), Some(rh)) = (
        left.x,
        left.y,
        left.width,
        left.height,
        right.x,
        right.y,
        right.width,
        right.height,
    ) else {
        return false;
    };
    if lw <= 0 || lh <= 0 || rw <= 0 || rh <= 0 {
        return false;
    }
    lx < rx + rw && lx + lw > rx && ly < ry + rh && ly + lh > ry
}

fn gui_control_assignment_opens_block(bytes: &[u8], mut index: usize) -> bool {
    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }
    index < bytes.len() && bytes[index] == b'{'
}

fn gui_output_audit_control_type_supported(control_type: &str) -> bool {
    matches!(
        control_type,
        "containerWindowType"
            | "buttonType"
            | "instantTextBoxType"
            | "iconType"
            | "progressbarType"
            | "checkboxType"
            | "listboxType"
            | "scrollbarType"
            | "editBoxType"
            | "gridBoxType"
            | "dropDownBoxType"
            | "dropdownType"
            | "comboBoxType"
            | "overlappingElementsBoxType"
    )
}

fn gui_output_audit_control_counts_json(audit: &GuiOutputAudit) -> String {
    let entries = audit
        .interface_control_type_counts
        .iter()
        .map(|(control_type, count)| {
            format!(
                "    {{\"control_type\": {}, \"count\": {}, \"writer_supported\": {}}}",
                json_str(control_type),
                count,
                json_bool(gui_output_audit_control_type_supported(control_type)),
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    format!("[\n{}\n  ]", entries)
}

fn gui_output_sprite_ref_unresolved_template(value: &str) -> bool {
    value.contains('<')
        || value.contains('>')
        || value.eq_ignore_ascii_case("todo")
        || value.eq_ignore_ascii_case("null")
}

fn gui_output_sprite_ref_invalid_token(value: &str) -> bool {
    value.is_empty()
        || value.contains("【")
        || value.contains("】")
        || value.contains('{')
        || value.contains('}')
        || value.contains('=')
        || value
            .chars()
            .any(|ch| !(ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-' | '.')))
}

fn parse_localisation_keys(text: &str) -> Vec<String> {
    let mut keys = Vec::new();
    for raw in text.lines() {
        let line = raw.trim_start_matches('\u{feff}').trim();
        if line.is_empty() || line.starts_with('#') || line.starts_with("l_") {
            continue;
        }
        if let Some((key, _)) = line.split_once(':') {
            let key = key.trim();
            if !key.is_empty() {
                push_capped_unique(&mut keys, key.to_string(), 20000);
            }
        }
    }
    keys
}

fn looks_like_gui_localisation_key(value: &str) -> bool {
    let value = value.trim();
    !value.is_empty()
        && value
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '-'))
        && value.chars().any(|ch| ch == '_')
}

fn gui_output_expected_from_intent(intent: &GuiIntentFields) -> GuiOutputAuditExpected {
    let mut expected = GuiOutputAuditExpected::default();
    gui_output_set_expected_value(
        &mut expected.scripted_gui_id,
        intent.scripted_gui_id.as_deref(),
    );
    gui_output_set_expected_value(&mut expected.window_name, intent.window_name.as_deref());
    gui_output_set_expected_value(&mut expected.open_effect, intent.open_effect.as_deref());
    gui_output_set_expected_value(&mut expected.close_effect, intent.close_effect.as_deref());
    gui_output_set_expected_value(&mut expected.open_flag, intent.open_flag.as_deref());
    for widget in &intent.widgets {
        if gui_intent_widget_is_clickable(widget) {
            gui_output_push_expected(&mut expected.click_targets, Some(widget.id.as_str()));
        }
    }
    if expected.has_any() {
        expected
            .source_reports
            .push("apply_gui_intent.in_memory_intent".to_string());
    }
    expected
}

fn gui_output_expected_from_reports(
    apply_report_path: Option<&Path>,
    apply_report_text: Option<&str>,
    runtime_open_plan_path: Option<&Path>,
    runtime_open_plan_text: Option<&str>,
) -> GuiOutputAuditExpected {
    let mut expected = GuiOutputAuditExpected::default();
    if let Some(text) = apply_report_text {
        gui_output_set_expected_value(
            &mut expected.scripted_gui_id,
            status_json_string_field(text, "scripted_gui_id").as_deref(),
        );
        gui_output_set_expected_value(
            &mut expected.window_name,
            status_json_string_field(text, "window_name").as_deref(),
        );
        if expected.has_any() {
            expected.source_reports.push(
                apply_report_path
                    .map(|path| path.display().to_string())
                    .unwrap_or_else(|| "apply_report".to_string()),
            );
        }
    }
    if let Some(text) = runtime_open_plan_text {
        gui_output_set_expected_value(
            &mut expected.window_name,
            status_json_string_field(text, "window_name").as_deref(),
        );
        gui_output_push_expected(
            &mut expected.click_targets,
            status_json_string_field(text, "click_target").as_deref(),
        );
        gui_output_set_expected_value(
            &mut expected.open_effect,
            status_json_string_field(text, "open_effect").as_deref(),
        );
        gui_output_set_expected_value(
            &mut expected.open_flag,
            status_json_string_field(text, "open_flag").as_deref(),
        );
        gui_output_set_expected_value(
            &mut expected.scripted_gui_id,
            status_json_string_field(text, "decision_scripted_gui").as_deref(),
        );
        if expected.has_any() {
            expected.source_reports.push(
                runtime_open_plan_path
                    .map(|path| path.display().to_string())
                    .unwrap_or_else(|| "runtime_open_plan".to_string()),
            );
        }
    }
    expected.source_reports.sort();
    expected.source_reports.dedup();
    expected
}

fn gui_output_set_expected_value(slot: &mut Option<String>, value: Option<&str>) {
    let Some(value) = gui_output_expected_token(value) else {
        return;
    };
    if slot.is_none() {
        *slot = Some(value);
    }
}

fn gui_output_push_expected(values: &mut Vec<String>, value: Option<&str>) {
    let Some(value) = gui_output_expected_token(value) else {
        return;
    };
    push_capped_unique(values, value, 80);
}

fn gui_output_expected_token(value: Option<&str>) -> Option<String> {
    let value = value?.trim();
    if value.is_empty() || gui_intent_value_missing(Some(value)) {
        None
    } else {
        Some(value.to_string())
    }
}

#[allow(clippy::too_many_arguments)]
fn gui_output_plan_audit(
    expected: Option<&GuiOutputAuditExpected>,
    scripted_guis: &[ScriptedGuiEntry],
    interface_container_names: &BTreeSet<String>,
    interface_element_names: &BTreeSet<String>,
    scripted_effect_ids: &BTreeSet<String>,
    scripted_effect_text: &str,
    blockers: &mut Vec<String>,
    questions: &mut Vec<String>,
) -> (bool, Vec<String>, Vec<String>) {
    let Some(expected) = expected.filter(|expected| expected.has_any()) else {
        return (true, Vec::new(), Vec::new());
    };
    let mut matches = Vec::new();
    let mut missing = Vec::new();
    let scripted_gui = expected.scripted_gui_id.as_ref().and_then(|id| {
        scripted_guis
            .iter()
            .find(|entry| entry.id == *id)
            .map(|entry| (id, entry))
    });
    if let Some(id) = expected.scripted_gui_id.as_deref() {
        if let Some((_, entry)) = scripted_gui {
            matches.push(format!("scripted_gui_id:{id}:{}", entry.path));
        } else {
            let blocker = format!("output_plan_missing_scripted_gui:{id}");
            blockers.push(blocker.clone());
            missing.push(blocker);
            questions.push(format!(
                "Expected scripted_gui `{id}` from apply/open-plan evidence is absent from common/scripted_guis. Rerun apply-gui-intent from structured intent; do not handwrite a replacement scripted_gui."
            ));
        }
    }
    if let Some(window) = expected.window_name.as_deref() {
        if interface_container_names.contains(window) {
            matches.push(format!("window_name:{window}"));
        } else {
            let blocker = format!("output_plan_missing_window:{window}");
            blockers.push(blocker.clone());
            missing.push(blocker);
            questions.push(format!(
                "Expected GUI window `{window}` from apply/open-plan evidence is absent from interface/*.gui containerWindowType names. Rerun the GUI writer or choose an indexed existing window."
            ));
        }
        if let Some((id, entry)) = scripted_gui {
            if entry.window_name.as_deref() == Some(window) {
                matches.push(format!("scripted_gui_window:{id}->{window}"));
            } else {
                let actual = entry.window_name.as_deref().unwrap_or("<missing>");
                let blocker = format!("output_plan_scripted_gui_window_mismatch:{id}:{window}");
                blockers.push(blocker.clone());
                missing.push(blocker);
                questions.push(format!(
                    "scripted_gui `{id}` points to window `{actual}` but apply/open-plan expects `{window}`. Regenerate from the same intent so scripted_guis and interface output stay paired."
                ));
            }
        }
    }
    for target in &expected.click_targets {
        if interface_element_names.contains(target) {
            matches.push(format!("click_target:{target}"));
        } else {
            let blocker = format!("output_plan_missing_click_target:{target}");
            blockers.push(blocker.clone());
            missing.push(blocker);
            questions.push(format!(
                "Expected click target `{target}` from intent/open-plan evidence is absent from interface element names. Fix the structured widget id or regenerate the interface file."
            ));
        }
    }
    for (role, effect) in [
        ("open_effect", expected.open_effect.as_deref()),
        ("close_effect", expected.close_effect.as_deref()),
    ] {
        let Some(effect) = effect else {
            continue;
        };
        if scripted_effect_ids.contains(effect) {
            matches.push(format!("{role}:{effect}"));
        } else {
            let blocker = format!("output_plan_missing_{role}:{effect}");
            blockers.push(blocker.clone());
            missing.push(blocker);
            questions.push(format!(
                "Expected {role} `{effect}` is absent from common/scripted_effects. Rerun apply-gui-intent so scripted effects are emitted by the Rust writer."
            ));
        }
    }
    if let Some(flag) = expected.open_flag.as_deref() {
        let flag_in_scripted_gui = scripted_guis
            .iter()
            .any(|entry| entry.visible_flag_tokens.iter().any(|token| token == flag));
        let flag_in_effects = scripted_effect_text.contains(&format!("set_country_flag = {flag}"))
            || scripted_effect_text.contains(&format!("clr_country_flag = {flag}"));
        if flag_in_scripted_gui || flag_in_effects {
            matches.push(format!("open_flag:{flag}"));
        } else {
            let blocker = format!("output_plan_missing_open_flag:{flag}");
            blockers.push(blocker.clone());
            missing.push(blocker);
            questions.push(format!(
                "Expected open flag `{flag}` is absent from visible/scripted_effect protocol. Regenerate the open/close state protocol instead of treating it as an arbitrary flag."
            ));
        }
    }
    matches.sort();
    matches.dedup();
    missing.sort();
    missing.dedup();
    (missing.is_empty(), matches, missing)
}

fn gui_output_collect_scripted_effect_ids(
    mod_root: &Path,
    files: &[String],
) -> Result<BTreeSet<String>, String> {
    let mut ids = BTreeSet::new();
    for relative in files {
        let text = read_utf8_lossy(&mod_root.join(slash_path_to_native(relative)))?;
        let mut depth = 0i32;
        for raw in text.lines() {
            let line = raw.split('#').next().unwrap_or("").trim();
            if depth == 0 {
                if let Some(id) = block_header_name(line) {
                    ids.insert(id);
                }
            }
            depth += brace_delta(line);
            if depth <= 0 {
                depth = 0;
            }
        }
    }
    Ok(ids)
}

fn gui_output_collect_text(mod_root: &Path, files: &[String]) -> Result<String, String> {
    let mut text = String::new();
    for relative in files {
        text.push_str(&read_utf8_lossy(
            &mod_root.join(slash_path_to_native(relative)),
        )?);
        text.push('\n');
    }
    Ok(text)
}

