fn gui_output_audit_final_code_safety_status(audit: &GuiOutputAudit) -> &'static str {
    if !audit.ok {
        "blocked_no_clausewitz_candidate"
    } else if audit.strict_code_index {
        "passed_strict_code_index"
    } else {
        "candidate_only_requires_strict_code_index"
    }
}

fn gui_output_audit_recommended_syntax(blockers: &[String]) -> Vec<String> {
    let mut values = Vec::new();
    for blocker in blockers {
        if blocker.starts_with("scripted_gui_window_missing_interface:")
            || blocker.starts_with("scripted_gui_missing_window_name:")
            || blocker.starts_with("interface_window_unregistered_in_scripted_guis:")
            || blocker.starts_with("output_plan_scripted_gui_window_mismatch:")
        {
            push_capped_unique(
                &mut values,
                "Pair common/scripted_guis/<id>.txt with interface/<window>.gui: scripted_gui = { window_name = <existing_containerWindowType_name> } and keep the same window_name in the interface container.".to_string(),
                64,
            );
        }
        if blocker.starts_with("scripted_gui_click_handler_missing_interface_button:")
            || blocker.starts_with("output_plan_missing_click_target:")
        {
            push_capped_unique(
                &mut values,
                "For every scripted_gui click handler, add a matching interface buttonType name or change the structured widget id; do not leave a click target that has no button.".to_string(),
                64,
            );
        }
        if blocker.starts_with("output_plan_missing_open_effect:")
            || blocker.starts_with("output_plan_missing_close_effect:")
            || blocker.starts_with("scripted_gui_action_helper_missing_scripted_effect:")
        {
            push_capped_unique(
                &mut values,
                "Define the missing open/close helper in common/scripted_effects/<id>.txt, then reference that scripted_effect from the GUI state protocol.".to_string(),
                64,
            );
        }
        if blocker.starts_with("output_plan_missing_open_flag:") {
            push_capped_unique(
                &mut values,
                "Use one open flag consistently: scripted_gui visible trigger checks has_country_flag = <flag>, open_effect sets it, and close_effect clears it.".to_string(),
                64,
            );
        }
        if blocker.starts_with("interface_sprite_unknown_in_strict_code_index:")
            || blocker.starts_with("interface_sprite_unresolved_template:")
            || blocker.starts_with("interface_sprite_invalid_token:")
        {
            push_capped_unique(
                &mut values,
                "Register GUI sprite refs in interface/<name>_sprites.gfx as spriteTypes = { spriteType = { name = \"GFX_name\" texturefile = \"gfx/interface/name.dds\" } }, or replace the ref with an indexed parent/game sprite.".to_string(),
                64,
            );
        }
        if blocker.starts_with("interface_text_missing_localisation:") {
            push_capped_unique(
                &mut values,
                "Add missing GUI localisation under localisation/simp_chinese/<id>_l_simp_chinese.yml with l_simp_chinese: and <key>:0 \"visible text\".".to_string(),
                64,
            );
        }
        if blocker.starts_with("interface_layout_missing_name:")
            || blocker.starts_with("interface_layout_duplicate_name:")
            || blocker.starts_with("interface_layout_invalid_size:")
            || blocker.starts_with("interface_layout_negative_position:")
            || blocker.starts_with("interface_layout_rect_overlap:")
        {
            push_capped_unique(
                &mut values,
                "Fix interface layout before acceptance: every control needs a unique name, positive size, valid position, and no unintended overlap in the same parent window.".to_string(),
                64,
            );
        }
    }
    values.sort();
    values.dedup();
    values
}

fn gui_output_audit_recommended_game_code(blockers: &[String]) -> Vec<GuiRequestGameCodeCandidate> {
    let mut candidates = Vec::new();
    for blocker in blockers {
        if let Some(key) = blocker.strip_prefix("interface_text_missing_localisation:") {
            candidates.push(GuiRequestGameCodeCandidate {
                role: "localisation_candidate".to_string(),
                relative_path: "localisation/simp_chinese/<gui>_l_simp_chinese.yml".to_string(),
                status: "candidate_only_not_written".to_string(),
                reason: "interface_text_key_missing_localisation".to_string(),
                code: format!(
                    "l_simp_chinese:\n {key}:0 \"<user-approved visible GUI text>\"\n# Candidate only: fill with the exact user-provided visible text, then rerun check-text-alignment and gui-output-audit --strict-code-index.\n"
                ),
            });
        } else if let Some(sprite) =
            blocker.strip_prefix("interface_sprite_unknown_in_strict_code_index:")
        {
            let todo = gui_request_missing_sprite_asset_todo(sprite);
            candidates.push(GuiRequestGameCodeCandidate {
                role: "gui_asset_registration_candidate".to_string(),
                relative_path: todo.suggested_gfx_file,
                status: "candidate_only_not_written".to_string(),
                reason: "sprite_ref_missing_from_strict_code_index".to_string(),
                code: format!(
                    "spriteTypes = {{\n\tspriteType = {{\n\t\tname = \"{}\"\n\t\ttexturefile = \"{}\"\n\t}}\n}}\n# Candidate only: create/approve the image file first, then rerun strict-code-index.\n",
                    todo.sprite, todo.suggested_texturefile
                ),
            });
        } else if blocker.starts_with("scripted_gui_click_handler_missing_interface_button:")
            || blocker.starts_with("scripted_gui_window_missing_interface:")
            || blocker.starts_with("scripted_gui_missing_window_name:")
            || blocker.starts_with("output_plan_missing_scripted_gui:")
            || blocker.starts_with("output_plan_scripted_gui_window_mismatch:")
            || blocker.starts_with("output_plan_missing_window:")
            || blocker.starts_with("output_plan_missing_click_target:")
            || blocker.starts_with("output_plan_missing_open_effect:")
            || blocker.starts_with("output_plan_missing_close_effect:")
            || blocker.starts_with("output_plan_missing_open_flag:")
        {
            candidates.push(GuiRequestGameCodeCandidate {
                role: "gui_evidence_required".to_string(),
                relative_path: ".hoi4skill/gui_output_audit_evidence_required.md".to_string(),
                status: "blocked_no_clausewitz_candidate".to_string(),
                reason: "gui_output_structure_mismatch_requires_indexed_window_or_button_evidence"
                    .to_string(),
                code: format!(
                    "No final GUI code is recommended for `{blocker}`. Fix the GUI intent/window/button/effect mapping from indexed parent-mod evidence or rerun gui-request-workflow with the exact runtime open-plan requirement."
                ),
            });
        } else if blocker.starts_with("interface_layout_") {
            candidates.push(GuiRequestGameCodeCandidate {
                role: "gui_layout_repair_candidate".to_string(),
                relative_path: "interface/<gui_window>.gui".to_string(),
                status: "candidate_only_not_written".to_string(),
                reason: "interface_layout_static_audit_failed".to_string(),
                code: "Repair the structured GUI intent/widget layout, then rerun apply-gui-intent --execute --final-check. Use unique name values, non-negative positions, positive sizes, and enough spacing so widget rectangles do not overlap. Candidate only; do not paste guessed .gui code directly.\n".to_string(),
            });
        } else if blocker.starts_with("style_token_reuse_not_observed_in_output")
            || blocker.starts_with("style_reuse_missing:")
        {
            candidates.push(GuiRequestGameCodeCandidate {
                role: "gui_style_reuse_evidence_required".to_string(),
                relative_path: ".hoi4skill/gui_style_reuse_repair_required.md".to_string(),
                status: "blocked_no_clausewitz_candidate".to_string(),
                reason: "generated_gui_did_not_reuse_parent_mod_style_tokens".to_string(),
                code: format!(
                    "No final GUI code is recommended for `{blocker}`. Rerun gui-style-template on the parent mod, choose indexed parent-mod font/sprite/control tokens, then rerun apply-gui-intent --execute --final-check and gui-output-audit with the style package."
                ),
            });
        } else if blocker.starts_with("style_structure_reuse_not_observed_in_output")
            || blocker.starts_with("style_structure_missing:")
        {
            candidates.push(GuiRequestGameCodeCandidate {
                role: "gui_style_structure_evidence_required".to_string(),
                relative_path: ".hoi4skill/gui_style_structure_repair_required.md".to_string(),
                status: "blocked_no_clausewitz_candidate".to_string(),
                reason: "generated_gui_did_not_match_parent_mod_structure_signatures".to_string(),
                code: format!(
                    "No final GUI code is recommended for `{blocker}`. Choose an indexed parent-mod GUI family with matching text/button/close/panel structure, then regenerate structured GUI intent and rerun final-check."
                ),
            });
        } else if blocker.starts_with("style_component_reuse_not_observed_in_output")
            || blocker.starts_with("style_component_missing:")
        {
            candidates.push(GuiRequestGameCodeCandidate {
                role: "gui_style_component_evidence_required".to_string(),
                relative_path: ".hoi4skill/gui_style_component_repair_required.md".to_string(),
                status: "blocked_no_clausewitz_candidate".to_string(),
                reason: "generated_gui_did_not_match_parent_mod_component_templates".to_string(),
                code: format!(
                    "No final GUI code is recommended for `{blocker}`. Choose an indexed parent-mod component template such as list_detail_scroll, titlebar_close, pagination_buttons, filter_list, or progress_action, then regenerate structured GUI intent and rerun final-check."
                ),
            });
        }
    }
    candidates
}

fn gui_output_audit_recommended_game_code_json(audit: &GuiOutputAudit) -> String {
    let entries = audit
        .recommended_game_code
        .iter()
        .map(gui_request_game_code_candidate_json)
        .collect::<Vec<_>>()
        .join(",\n");
    format!("[\n{}\n  ]", entries)
}

fn gui_output_audit_recommended_game_code_status(audit: &GuiOutputAudit) -> &'static str {
    if audit.recommended_game_code.is_empty() {
        "none"
    } else if audit
        .recommended_game_code
        .iter()
        .all(|candidate| candidate.status == "blocked_no_clausewitz_candidate")
    {
        "evidence_required_only"
    } else if audit
        .recommended_game_code
        .iter()
        .all(|candidate| candidate.status == "candidate_only_not_written")
    {
        "candidate_only_not_written"
    } else {
        "mixed_evidence_and_candidates"
    }
}

fn large_mod_gui_authoring_request_text(map: &ArgMap) -> Result<String, String> {
    if let Some(text) = value(map, "text").or_else(|| value(map, "request")) {
        return Ok(text.to_string());
    }
    if let Some(input) = value(map, "input") {
        return read_utf8_lossy(&normalize_path(input)?);
    }
    Ok(String::new())
}

fn large_mod_gui_authoring_intent_template(
    mod_root: &Path,
    style_roots: &[PathBuf],
    gui_kind: &str,
    request: &str,
) -> String {
    let style_mods = style_roots
        .iter()
        .map(|root| format!("- `{}`\n", root.display()))
        .collect::<String>();
    let request = if request.trim().is_empty() {
        "<empty>"
    } else {
        request
    };
    let mut out = String::new();
    out.push_str("# hoi4skill.gui_intent.v1\n\n");
    out.push_str("## User Request\n\n");
    out.push_str(request);
    out.push_str("\n\n## Target\n\n");
    out.push_str(&format!("- mod_root: `{}`\n", mod_root.display()));
    out.push_str(&format!("- gui_kind: `{gui_kind}`\n"));
    out.push_str("- style_mods:\n");
    out.push_str(&style_mods);
    out.push_str("\n## Intent Fields For The Model\n\n");
    out.push_str("Fill these fields only. Do not output final Clausewitz GUI code.\n\n");
    out.push_str("```yaml\n");
    out.push_str("schema: hoi4skill.gui_intent.v1\n");
    out.push_str(&format!("gui_kind: {gui_kind}\n"));
    out.push_str("id_prefix: <safe_lowercase_prefix>\n");
    out.push_str("scripted_gui_id: <prefix>_gui\n");
    out.push_str("window_name: <prefix>_window\n");
    out.push_str("title: <player visible title>\n");
    out.push_str("description: <player visible description>\n");
    out.push_str("mount:\n");
    out.push_str("  decision_category: <only for decision_attached>\n");
    out.push_str("  parent_window_token: <only for topbar_mount or politics_tab mount>\n");
    out.push_str("  map_window: <only for map_window>\n");
    out.push_str("state_protocol:\n");
    out.push_str("  open_flag: <prefix>_open\n");
    out.push_str("  close_button: close_<prefix>_click\n");
    out.push_str("  variables: []\n");
    out.push_str("scripted_effects:\n");
    out.push_str("  open_effect: open_<prefix>_gui\n");
    out.push_str("  close_effect: close_<prefix>_gui\n");
    out.push_str("  update_effects: []\n");
    out.push_str("widgets:\n");
    out.push_str("  - id: <button_or_text_id>\n");
    out.push_str("    type: button\n");
    out.push_str("    localisation: <visible text or tooltip>\n");
    out.push_str("    click_effect: <scripted effect id, not inline raw code>\n");
    out.push_str("localisation_placeholders:\n");
    out.push_str("  - <icons, flags, leaders, cosmetic tag names, color spans to resolve>\n");
    out.push_str("questions_for_user: []\n");
    out.push_str("```\n");
    out
}

fn large_mod_gui_authoring_contract_markdown(
    gui_kind: &str,
    aggregate: &LargeModGuiPatternAggregate,
) -> String {
    let mut out = String::new();
    out.push_str("# hoi4skill.gui_authoring_contract.v1\n\n");
    out.push_str("## Scope\n\n");
    out.push_str(&format!("- requested_gui_kind: `{gui_kind}`\n"));
    out.push_str("- AI may write GUI intent only; Rust writers must emit final HOI4 files.\n");
    out.push_str("- Required file families are `common/scripted_guis`, `common/scripted_effects`, `interface/*.gui`, and optional `common/decisions` category mounts.\n\n");
    out.push_str("## Learned Style Coverage\n\n");
    out.push_str(&format!(
        "- decision_attached_gui: `{}`\n",
        aggregate.has_decision_attached_gui
    ));
    out.push_str(&format!(
        "- standalone_gui: `{}`\n",
        aggregate.has_standalone_gui
    ));
    out.push_str(&format!(
        "- mount_points: `{}`\n",
        aggregate.has_mount_points
    ));
    out.push_str(&format!(
        "- scripted_effects: `{}`\n",
        aggregate.has_scripted_effects
    ));
    out.push_str(&format!(
        "- tdr_map_gui: `{}`\n\n",
        aggregate.has_tdr_map_gui
    ));
    out.push_str("## Stop Conditions\n\n");
    for condition in large_mod_gui_authoring_stop_conditions() {
        out.push_str(&format!("- {condition}\n"));
    }
    out
}

fn large_mod_gui_authoring_pack_json(
    mod_root: &Path,
    style_roots: &[PathBuf],
    output_dir: &Path,
    pattern_audit: &Path,
    intent_template: &Path,
    contract: &Path,
    gui_kind: &str,
    request: &str,
    aggregate: &LargeModGuiPatternAggregate,
    ok: bool,
) -> String {
    let style_mods = style_roots
        .iter()
        .map(|root| root.display().to_string())
        .collect::<Vec<_>>();
    let artifacts = vec![
        pattern_audit.display().to_string(),
        intent_template.display().to_string(),
        contract.display().to_string(),
    ];
    let next_commands = vec![
        format!(
            "hoi4skill large-mod-gui-pattern-audit --mod-root {} --require-gui-patterns --output {}",
            command_path_arg(mod_root),
            command_path_arg(&output_dir.join("target_gui_patterns.json"))
        ),
        format!(
            "fill {} with hoi4skill.gui_intent.v1 fields; do not write final GUI code by hand",
            intent_template.display()
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_gui_authoring_pack.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"writer_status\": \"intent_pack_only\",\n  \"mod_root\": {},\n  \"style_mods\": {},\n  \"output_dir\": {},\n  \"gui_kind\": {},\n  \"request\": {},\n  \"patterns\": {{\"decision_attached_gui\": {}, \"standalone_gui\": {}, \"mount_points\": {}, \"scripted_effects\": {}, \"tdr_map_gui\": {}}},\n  \"artifacts\": {},\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(if ok { "prepared" } else { "style_patterns_incomplete" }),
        json_bool(ok),
        json_str(&mod_root.display().to_string()),
        json_array(&style_mods),
        json_str(&output_dir.display().to_string()),
        json_str(gui_kind),
        json_str(request),
        json_bool(aggregate.has_decision_attached_gui),
        json_bool(aggregate.has_standalone_gui),
        json_bool(aggregate.has_mount_points),
        json_bool(aggregate.has_scripted_effects),
        json_bool(aggregate.has_tdr_map_gui),
        json_array(&artifacts),
        json_array(&next_commands),
        json_array(&large_mod_gui_authoring_stop_conditions()),
    )
}

fn command_path_arg(path: &Path) -> String {
    format!("\"{}\"", path.display())
}

fn large_mod_gui_authoring_stop_conditions() -> Vec<String> {
    vec![
        "Do not accept final GUI code directly from the AI; accept only hoi4skill.gui_intent.v1 fields.".to_string(),
        "Decision-attached GUI must declare a decision category mount and a scripted_gui with context_type=decision_category.".to_string(),
        "Standalone GUI must declare an open/close flag protocol and a player_context scripted_gui.".to_string(),
        "Every scripted_gui window_name must resolve to an interface .gui window before final write.".to_string(),
        "Reusable state, variable changes, and button side effects belong in scripted_effects, not copied inline across widgets.".to_string(),
        "Ask the user before inventing missing icons, flags, cosmetic tags, leaders, map windows, parent_window_token values, or GUI art assets.".to_string(),
        "Final GUI writers must run validate with strict code index and text alignment before release.".to_string(),
    ]
}

#[derive(Clone, Debug, Default)]
struct GuiStyleTemplateTokens {
    fonts: Vec<String>,
    sprites: Vec<String>,
    button_sprites: Vec<String>,
    close_sprites: Vec<String>,
    panel_sprites: Vec<String>,
    tab_sprites: Vec<String>,
    map_sprites: Vec<String>,
    parent_window_tokens: Vec<String>,
    visible_flags: Vec<String>,
    click_handlers: Vec<String>,
    scripted_effect_bridges: Vec<String>,
    window_names: Vec<String>,
    structure_signatures: Vec<String>,
    component_templates: Vec<String>,
    style_token_evidence: Vec<String>,
    control_type_evidence: Vec<String>,
}

fn collect_gui_style_template_tokens(
    reports: &[LargeModGuiPatternProfile],
) -> Result<GuiStyleTemplateTokens, String> {
    let mut tokens = GuiStyleTemplateTokens::default();
    for report in reports {
        for entry in &report.scripted_guis {
            if let Some(parent) = entry.parent_window_token.as_deref() {
                push_capped_unique(&mut tokens.parent_window_tokens, parent.to_string(), 40);
                push_gui_style_token_evidence(
                    &mut tokens,
                    "parent_window_token",
                    parent,
                    report,
                    &entry.path,
                    entry.line,
                );
            }
            if let Some(window) = entry.window_name.as_deref() {
                push_capped_unique(&mut tokens.window_names, window.to_string(), 80);
                push_gui_style_token_evidence(
                    &mut tokens,
                    "window_name",
                    window,
                    report,
                    &entry.path,
                    entry.line,
                );
            }
            for flag in &entry.visible_flag_tokens {
                push_capped_unique(&mut tokens.visible_flags, flag.clone(), 80);
                push_gui_style_token_evidence(
                    &mut tokens,
                    "visible_flag",
                    flag,
                    report,
                    &entry.path,
                    entry.line,
                );
            }
            for effect in &entry.effect_tokens {
                push_capped_unique(&mut tokens.click_handlers, effect.clone(), 80);
                push_gui_style_token_evidence(
                    &mut tokens,
                    "click_handler",
                    effect,
                    report,
                    &entry.path,
                    entry.line,
                );
            }
        }
        for bridge in gui_intent_scripted_effect_context(std::slice::from_ref(report)) {
            push_capped_unique(&mut tokens.scripted_effect_bridges, bridge, 80);
        }
        for relative in &report.interface_gui_files {
            let text = read_utf8_lossy(&report.mod_root.join(slash_path_to_native(relative)))?;
            collect_gui_style_structure_signatures(&text, report, relative, &mut tokens);
            collect_gui_style_component_templates(&text, report, relative, &mut tokens);
            collect_gui_style_control_type_evidence(&text, report, relative, &mut tokens);
            collect_gui_style_assignment_tokens(
                &text,
                "font",
                "font",
                report,
                relative,
                &mut tokens,
            );
            collect_gui_style_assignment_tokens(
                &text,
                "buttonFont",
                "button_font",
                report,
                relative,
                &mut tokens,
            );
            collect_gui_style_sprite_tokens(&text, "spriteType", report, relative, &mut tokens);
            collect_gui_style_sprite_tokens(
                &text,
                "quadTextureSprite",
                report,
                relative,
                &mut tokens,
            );
        }
    }
    Ok(tokens)
}

fn collect_gui_style_structure_signatures(
    text: &str,
    report: &LargeModGuiPatternProfile,
    relative: &str,
    tokens: &mut GuiStyleTemplateTokens,
) {
    for signature in gui_style_structure_signatures_from_text(text) {
        push_capped_unique(&mut tokens.structure_signatures, signature.clone(), 120);
        push_capped_unique(
            &mut tokens.style_token_evidence,
            format!(
                "structure:{}:{}:{}",
                signature,
                report.mod_root.display(),
                relative
            ),
            240,
        );
    }
}

fn collect_gui_style_component_templates(
    text: &str,
    report: &LargeModGuiPatternProfile,
    relative: &str,
    tokens: &mut GuiStyleTemplateTokens,
) {
    for component in gui_style_component_templates_from_text(text) {
        push_capped_unique(&mut tokens.component_templates, component.clone(), 120);
        push_capped_unique(
            &mut tokens.style_token_evidence,
            format!(
                "component_template:{}:{}:{}",
                component,
                report.mod_root.display(),
                relative
            ),
            240,
        );
    }
}

fn collect_gui_style_control_type_evidence(
    text: &str,
    report: &LargeModGuiPatternProfile,
    relative: &str,
    tokens: &mut GuiStyleTemplateTokens,
) {
    for (idx, raw) in text.lines().enumerate() {
        let line = raw.split('#').next().unwrap_or("").trim();
        if line.is_empty() {
            continue;
        }
        let lower = line.to_ascii_lowercase();
        for (control_type, clausewitz_nodes) in gui_control_type_clausewitz_nodes() {
            if clausewitz_nodes
                .iter()
                .any(|node| lower.contains(&node.to_ascii_lowercase()))
            {
                push_capped_unique(
                    &mut tokens.control_type_evidence,
                    format!(
                        "control_type:{}:{}:{}:line{}",
                        control_type,
                        report.mod_root.display(),
                        relative,
                        idx + 1
                    ),
                    240,
                );
            }
        }
    }
}

fn gui_style_structure_signatures_from_text(text: &str) -> Vec<String> {
    let controls = parse_gui_control_type_refs(text)
        .into_iter()
        .collect::<BTreeSet<_>>();
    let sprites = parse_gui_sprite_refs(text);
    let fonts = parse_gui_font_refs(text);
    let lower = text.to_ascii_lowercase();
    let mut signatures = Vec::new();
    if controls.contains("containerWindowType") {
        push_capped_unique(
            &mut signatures,
            "structure:has_container_window".to_string(),
            80,
        );
    }
    if controls.contains("instantTextBoxType") {
        push_capped_unique(&mut signatures, "structure:has_text_area".to_string(), 80);
    }
    if controls.contains("buttonType") {
        push_capped_unique(&mut signatures, "structure:has_button".to_string(), 80);
    }
    if lower.contains("close")
        || sprites
            .iter()
            .any(|sprite| sprite.to_ascii_lowercase().contains("close"))
    {
        push_capped_unique(
            &mut signatures,
            "structure:has_close_button".to_string(),
            80,
        );
    }
    if lower.contains("action_button")
        || lower.contains("refresh_button")
        || sprites.iter().any(|sprite| {
            let lower = sprite.to_ascii_lowercase();
            (lower.contains("button") || lower.contains("btn")) && !lower.contains("close")
        })
    {
        push_capped_unique(
            &mut signatures,
            "structure:has_action_button".to_string(),
            80,
        );
    }
    if sprites.iter().any(|sprite| {
        let lower = sprite.to_ascii_lowercase();
        ["panel", "bg", "background", "window", "frame", "border"]
            .iter()
            .any(|needle| lower.contains(needle))
    }) {
        push_capped_unique(
            &mut signatures,
            "structure:has_panel_sprite".to_string(),
            80,
        );
    }
    if !fonts.is_empty() && controls.contains("buttonType") {
        push_capped_unique(
            &mut signatures,
            "structure:fonted_button_family".to_string(),
            80,
        );
    }
    if controls.contains("buttonType") && controls.contains("instantTextBoxType") {
        push_capped_unique(
            &mut signatures,
            "structure:text_and_button_family".to_string(),
            80,
        );
    }
    if !controls.is_empty() {
        let family = controls.iter().cloned().collect::<Vec<_>>().join("+");
        push_capped_unique(
            &mut signatures,
            format!("structure:control_family:{family}"),
            80,
        );
    }
    signatures.sort();
    signatures.dedup();
    signatures
}

fn gui_style_component_templates_from_text(text: &str) -> Vec<String> {
    let controls = parse_gui_control_type_refs(text)
        .into_iter()
        .collect::<BTreeSet<_>>();
    let lower = text.to_ascii_lowercase();
    let mut components = Vec::new();
    let has_button = controls.contains("buttonType");
    let has_text = controls.contains("instantTextBoxType");
    let has_list = controls.contains("listboxType") || controls.contains("listBoxType");
    let has_scroll = controls.contains("scrollbarType") || controls.contains("scrollBarType");
    let has_edit = controls.contains("editBoxType");
    let has_dropdown = controls.contains("dropDownBoxType")
        || controls.contains("dropdownType")
        || controls.contains("comboBoxType");
    let has_grid = controls.contains("gridBoxType");
    let has_progress = controls.contains("progressbarType") || controls.contains("progressBarType");
    let has_close = lower.contains("close") || lower.contains("collapse");
    let has_detail = lower.contains("detail")
        || lower.contains("desc")
        || lower.contains("description")
        || lower.contains("right");
    let has_prev_next = (lower.contains("prev") || lower.contains("previous"))
        && lower.contains("next")
        || lower.contains("page");
    if has_text && has_close {
        push_capped_unique(&mut components, "component:titlebar_close".to_string(), 80);
    }
    if has_list && has_scroll {
        push_capped_unique(&mut components, "component:list_scroll".to_string(), 80);
    }
    if has_list && has_text && (has_detail || has_scroll) {
        push_capped_unique(&mut components, "component:list_detail".to_string(), 80);
    }
    if has_list && has_scroll && has_text {
        push_capped_unique(
            &mut components,
            "component:list_detail_scroll".to_string(),
            80,
        );
    }
    if has_prev_next && has_button {
        push_capped_unique(
            &mut components,
            "component:pagination_buttons".to_string(),
            80,
        );
    }
    if has_edit && has_list {
        push_capped_unique(&mut components, "component:filter_list".to_string(), 80);
    }
    if has_dropdown && (has_list || has_grid) {
        push_capped_unique(&mut components, "component:selector_list".to_string(), 80);
    }
    if has_grid && has_scroll {
        push_capped_unique(&mut components, "component:grid_scroll".to_string(), 80);
    }
    if has_progress && has_button {
        push_capped_unique(&mut components, "component:progress_action".to_string(), 80);
    }
    components
}

fn gui_style_control_type_evidence(
    tokens: &GuiStyleTemplateTokens,
    control_type: &str,
) -> Vec<String> {
    let prefix = format!("control_type:{control_type}:");
    tokens
        .control_type_evidence
        .iter()
        .filter(|evidence| evidence.starts_with(&prefix))
        .take(12)
        .cloned()
        .collect()
}

fn gui_control_type_clausewitz_nodes() -> Vec<(&'static str, Vec<&'static str>)> {
    vec![
        ("button", vec!["buttonType"]),
        ("text", vec!["instantTextBoxType"]),
        ("icon", vec!["iconType"]),
        ("progressbar", vec!["progressbarType", "progressBarType"]),
        ("checkbox", vec!["checkboxType", "checkBoxType"]),
        (
            "dropdown",
            vec!["dropdownType", "dropDownBoxType", "comboBoxType"],
        ),
        ("slider", vec!["sliderType"]),
        ("listbox", vec!["listboxType", "listBoxType"]),
        ("scrollbar", vec!["scrollbarType", "scrollBarType"]),
        ("editbox", vec!["editBoxType"]),
        ("gridbox", vec!["gridBoxType"]),
        ("overlapping", vec!["overlappingElementsBoxType"]),
    ]
}

fn collect_gui_style_assignment_tokens(
    text: &str,
    key: &str,
    kind: &str,
    report: &LargeModGuiPatternProfile,
    relative: &str,
    tokens: &mut GuiStyleTemplateTokens,
) {
    for (idx, raw) in text.lines().enumerate() {
        let line = raw.split('#').next().unwrap_or("").trim();
        for value in assignment_values(line, key) {
            push_capped_unique(&mut tokens.fonts, value.clone(), 80);
            push_gui_style_token_evidence(tokens, kind, &value, report, relative, idx + 1);
        }
    }
}

fn collect_gui_style_sprite_tokens(
    text: &str,
    key: &str,
    report: &LargeModGuiPatternProfile,
    relative: &str,
    tokens: &mut GuiStyleTemplateTokens,
) {
    for (idx, raw) in text.lines().enumerate() {
        let line = raw.split('#').next().unwrap_or("").trim();
        for value in assignment_values(line, key) {
            if gui_style_sprite_token_relevant(&value) {
                push_capped_unique(&mut tokens.sprites, value.clone(), 80);
                push_gui_style_token_evidence(tokens, "sprite", &value, report, relative, idx + 1);
                collect_gui_style_component_sprite_token(&value, tokens, report, relative, idx + 1);
            }
        }
    }
}

fn collect_gui_style_component_sprite_token(
    value: &str,
    tokens: &mut GuiStyleTemplateTokens,
    report: &LargeModGuiPatternProfile,
    relative: &str,
    line: usize,
) {
    let lower = value.to_ascii_lowercase();
    let is_close = lower.contains("close") || lower.contains("collapse");
    if is_close {
        push_capped_unique(&mut tokens.close_sprites, value.to_string(), 40);
        push_gui_style_token_evidence(tokens, "close_sprite", value, report, relative, line);
    }
    if !is_close && (lower.contains("button") || lower.contains("btn")) {
        push_capped_unique(&mut tokens.button_sprites, value.to_string(), 60);
        push_gui_style_token_evidence(tokens, "button_sprite", value, report, relative, line);
    }
    if [
        "bg",
        "background",
        "window",
        "panel",
        "frame",
        "border",
        "floater",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        push_capped_unique(&mut tokens.panel_sprites, value.to_string(), 60);
        push_gui_style_token_evidence(tokens, "panel_sprite", value, report, relative, line);
    }
    if lower.contains("tab") {
        push_capped_unique(&mut tokens.tab_sprites, value.to_string(), 40);
        push_gui_style_token_evidence(tokens, "tab_sprite", value, report, relative, line);
    }
    if lower.contains("map") || lower.contains("tdr") {
        push_capped_unique(&mut tokens.map_sprites, value.to_string(), 40);
        push_gui_style_token_evidence(tokens, "map_sprite", value, report, relative, line);
    }
}

fn push_gui_style_token_evidence(
    tokens: &mut GuiStyleTemplateTokens,
    kind: &str,
    value: &str,
    report: &LargeModGuiPatternProfile,
    relative: &str,
    line: usize,
) {
    push_capped_unique(
        &mut tokens.style_token_evidence,
        format!(
            "{}:{}:{}:{}:line{}",
            kind,
            value,
            report.mod_root.display(),
            relative,
            line
        ),
        240,
    );
}

fn gui_style_sprite_token_relevant(value: &str) -> bool {
    let lower = value.to_ascii_lowercase();
    !lower.starts_with("gfx_idea_")
        && [
            "gui",
            "button",
            "bg",
            "background",
            "window",
            "close",
            "map",
            "tab",
            "tooltip",
            "entry",
            "border",
            "floater",
            "countryinfo",
            "generic",
        ]
        .iter()
        .any(|needle| lower.contains(needle))
}

fn gui_style_template_ready_for_kind(
    aggregate: &LargeModGuiPatternAggregate,
    gui_kind: &str,
) -> bool {
    match gui_kind {
        "all" | "auto" => aggregate.has_decision_attached_gui || aggregate.has_standalone_gui,
        "decision_attached" => aggregate.has_decision_attached_gui,
        "standalone" => aggregate.has_standalone_gui,
        "topbar_mount" => aggregate.has_mount_points && aggregate.has_standalone_gui,
        "map_window" => aggregate.has_tdr_map_gui || aggregate.has_standalone_gui,
        _ => false,
    }
}

fn gui_style_template_markdown(
    reports: &[LargeModGuiPatternProfile],
    aggregate: &LargeModGuiPatternAggregate,
    tokens: &GuiStyleTemplateTokens,
    gui_kind: &str,
) -> String {
    let mut out = String::new();
    out.push_str("# hoi4skill.gui_style_template.v1\n\n");
    out.push_str("## Parent Mods\n\n");
    for report in reports {
        out.push_str(&format!("- `{}`\n", report.mod_root.display()));
    }
    out.push_str("\n## Learned GUI Families\n\n");
    out.push_str(&format!(
        "- decision_attached_gui: `{}`\n",
        aggregate.has_decision_attached_gui
    ));
    out.push_str(&format!(
        "- standalone_gui: `{}`\n",
        aggregate.has_standalone_gui
    ));
    out.push_str(&format!(
        "- mount_points: `{}`\n",
        aggregate.has_mount_points
    ));
    out.push_str(&format!(
        "- scripted_effects: `{}`\n",
        aggregate.has_scripted_effects
    ));
    out.push_str(&format!("- tdr_map_gui: `{}`\n", aggregate.has_tdr_map_gui));
    out.push_str("\n## Style Tokens\n\n");
    out.push_str(&format!(
        "- fonts: `{}`\n",
        tokens
            .fonts
            .iter()
            .take(12)
            .cloned()
            .collect::<Vec<_>>()
            .join("`, `")
    ));
    out.push_str(&format!(
        "- sprites: `{}`\n",
        tokens
            .sprites
            .iter()
            .take(16)
            .cloned()
            .collect::<Vec<_>>()
            .join("`, `")
    ));
    out.push_str(&format!(
        "- button_sprites: `{}`\n",
        tokens
            .button_sprites
            .iter()
            .take(12)
            .cloned()
            .collect::<Vec<_>>()
            .join("`, `")
    ));
    out.push_str(&format!(
        "- close_sprites: `{}`\n",
        tokens
            .close_sprites
            .iter()
            .take(12)
            .cloned()
            .collect::<Vec<_>>()
            .join("`, `")
    ));
    out.push_str(&format!(
        "- panel_sprites: `{}`\n",
        tokens
            .panel_sprites
            .iter()
            .take(12)
            .cloned()
            .collect::<Vec<_>>()
            .join("`, `")
    ));
    out.push_str(&format!(
        "- parent_window_token: `{}`\n",
        tokens
            .parent_window_tokens
            .iter()
            .take(12)
            .cloned()
            .collect::<Vec<_>>()
            .join("`, `")
    ));
    out.push_str(&format!(
        "- visible/open flags: `{}`\n",
        tokens
            .visible_flags
            .iter()
            .take(12)
            .cloned()
            .collect::<Vec<_>>()
            .join("`, `")
    ));
    out.push_str(&format!(
        "- click handlers: `{}`\n",
        tokens
            .click_handlers
            .iter()
            .take(12)
            .cloned()
            .collect::<Vec<_>>()
            .join("`, `")
    ));
    out.push_str(&format!(
        "- component_templates: `{}`\n",
        tokens
            .component_templates
            .iter()
            .take(16)
            .cloned()
            .collect::<Vec<_>>()
            .join("`, `")
    ));
    out.push_str("\n## Intent Template\n\n");
    out.push_str(
        "Use this as the AI-facing template. Keep it as intent; do not paste final GUI code.\n\n",
    );
    out.push_str("```yaml\n");
    out.push_str("schema: hoi4skill.gui_intent.v1\n");
    out.push_str(&format!(
        "gui_kind: {}\n",
        if gui_kind == "all" {
            "standalone"
        } else {
            gui_kind
        }
    ));
    out.push_str("id_prefix: <prefix_matching_parent_style>\n");
    out.push_str("scripted_gui_id: <prefix>_gui\n");
    out.push_str("window_name: <prefix>_window\n");
    out.push_str("title: <visible title>\n");
    out.push_str("description: <visible description>\n");
    out.push_str("mount:\n");
    out.push_str("  decision_category: <for decision_attached only>\n");
    out.push_str("  parent_window_token: <use learned token when topbar/politics_tab mounted>\n");
    out.push_str("  map_window: <for map_window only>\n");
    out.push_str("state_protocol:\n");
    out.push_str("  open_flag: open_<prefix>\n");
    out.push_str("  close_button: close_<prefix>_click\n");
    out.push_str("scripted_effects:\n");
    out.push_str("  open_effect: open_<prefix>_gui\n");
    out.push_str("  close_effect: close_<prefix>_gui\n");
    out.push_str("  update_effects: []\n");
    out.push_str("widgets:\n");
    out.push_str("  - id: <parent_style_button_id>\n");
    out.push_str("    type: button\n");
    out.push_str("    localisation: <visible text>\n");
    out.push_str("    click_effect: <scripted_effect_id>\n");
    out.push_str("localisation_placeholders: []\n");
    out.push_str("questions_for_user: []\n");
    out.push_str("```\n\n");
    out.push_str("## Representative Examples\n\n");
    for kind in [
        "decision_attached",
        "standalone",
        "topbar_mount",
        "map_window",
    ] {
        out.push_str(&format!("### {kind}\n\n"));
        let examples = gui_style_entries_for_kind(reports, kind);
        if examples.is_empty() {
            out.push_str("- No direct parent-mod example found.\n\n");
        } else {
            for entry in examples.iter().take(5) {
                out.push_str(&format!(
                    "- `{}` in `{}` line {}: context=`{}`, window=`{}`, parent=`{}`\n",
                    entry.id,
                    entry.path,
                    entry.line,
                    entry.context_type.as_deref().unwrap_or(""),
                    entry.window_name.as_deref().unwrap_or(""),
                    entry.parent_window_token.as_deref().unwrap_or("")
                ));
            }
            out.push('\n');
        }
    }
    out.push_str("## Guardrails\n\n");
    for condition in large_mod_gui_authoring_stop_conditions() {
        out.push_str(&format!("- {condition}\n"));
    }
    out
}

fn gui_style_entries_for_kind<'a>(
    reports: &'a [LargeModGuiPatternProfile],
    gui_kind: &str,
) -> Vec<&'a ScriptedGuiEntry> {
    reports
        .iter()
        .flat_map(|report| report.scripted_guis.iter())
        .filter(|entry| match gui_kind {
            "decision_attached" => entry.context_type.as_deref() == Some("decision_category"),
            "standalone" => entry.context_type.as_deref() == Some("player_context"),
            "topbar_mount" => {
                entry.context_type.as_deref() == Some("player_context")
                    && entry.parent_window_token.is_some()
            }
            "map_window" => {
                let id = entry.id.to_ascii_lowercase();
                let window = entry
                    .window_name
                    .as_deref()
                    .unwrap_or("")
                    .to_ascii_lowercase();
                id.contains("map") || window.contains("map")
            }
            _ => true,
        })
        .collect()
}

fn gui_style_template_json(
    roots: &[PathBuf],
    reports: &[LargeModGuiPatternProfile],
    aggregate: &LargeModGuiPatternAggregate,
    tokens: &GuiStyleTemplateTokens,
    gui_kind: &str,
    ok: bool,
    markdown_output: Option<&Path>,
    artifacts: &[String],
) -> String {
    let roots = roots
        .iter()
        .map(|root| root.display().to_string())
        .collect::<Vec<_>>();
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_style_template.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"gui_kind\": {},\n  \"parent_mods\": {},\n  \"markdown_output\": {},\n  \"patterns\": {{\"decision_attached_gui\": {}, \"standalone_gui\": {}, \"mount_points\": {}, \"scripted_effects\": {}, \"tdr_map_gui\": {}}},\n  \"style_tokens\": {},\n  \"examples\": {},\n  \"artifacts\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(if ok { "learned" } else { "insufficient_parent_gui_style" }),
        json_bool(ok),
        json_str(gui_kind),
        json_array(&roots),
        json_optional_str(markdown_output.map(|path| path.display().to_string()).as_deref()),
        json_bool(aggregate.has_decision_attached_gui),
        json_bool(aggregate.has_standalone_gui),
        json_bool(aggregate.has_mount_points),
        json_bool(aggregate.has_scripted_effects),
        json_bool(aggregate.has_tdr_map_gui),
        gui_style_tokens_json(tokens),
        gui_style_examples_json(reports),
        json_array(&artifacts.to_vec()),
        json_array(&large_mod_gui_authoring_stop_conditions()),
    )
}

fn gui_style_template_package_style_tokens_json(
    roots: &[PathBuf],
    tokens: &GuiStyleTemplateTokens,
) -> String {
    let roots = roots
        .iter()
        .map(|root| root.display().to_string())
        .collect::<Vec<_>>();
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_style_tokens.v1\",\n  \"parent_mods\": {},\n  \"style_tokens\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_array(&roots),
        gui_style_tokens_json(tokens),
        json_array(&[
            "Every token must be backed by style_token_evidence before a writer treats it as learned style.".to_string(),
            "Do not copy complete parent-mod GUI implementations; reuse only tokenized style evidence.".to_string(),
        ]),
    )
}

fn gui_style_template_package_control_examples_json(
    roots: &[PathBuf],
    tokens: &GuiStyleTemplateTokens,
) -> String {
    let roots = roots
        .iter()
        .map(|root| root.display().to_string())
        .collect::<Vec<_>>();
    let control_items = gui_control_type_clausewitz_nodes()
        .into_iter()
        .map(|(control_type, clausewitz_nodes)| {
            let evidence = gui_style_control_type_evidence(tokens, control_type);
            format!(
                "    {{\"control_type\": {}, \"clausewitz_nodes\": {}, \"evidence_count\": {}, \"evidence\": {}, \"usable_by_writer\": {}}}",
                json_str(control_type),
                json_array(&clausewitz_nodes.iter().map(|value| value.to_string()).collect::<Vec<_>>()),
                evidence.len(),
                json_array(&evidence),
                json_bool(!evidence.is_empty()),
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_control_examples.v1\",\n  \"parent_mods\": {},\n  \"controls\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_array(&roots),
        control_items,
        json_array(&[
            "A control type with evidence_count=0 must not be emitted by the GUI writer.".to_string(),
            "Unsupported or unevidenced controls must block and ask for parent-mod examples.".to_string(),
        ]),
    )
}

fn gui_style_template_package_mount_examples_json(
    roots: &[PathBuf],
    reports: &[LargeModGuiPatternProfile],
) -> String {
    let roots = roots
        .iter()
        .map(|root| root.display().to_string())
        .collect::<Vec<_>>();
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_mount_examples.v1\",\n  \"parent_mods\": {},\n  \"examples\": {},\n  \"mount_contracts\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_array(&roots),
        gui_style_examples_json(reports),
        gui_mount_contracts_json(),
        json_array(&[
            "A gui_kind without mount examples must block or ask for an indexed parent-mod mount.".to_string(),
            "decision_attached requires an indexed decision category and context_type=decision_category.".to_string(),
        ]),
    )
}

fn gui_mount_contracts_json() -> String {
    let items = [
        (
            "standalone",
            vec![
                "context_type=player_context",
                "window_name must resolve to interface/*.gui",
                "visible/open flag protocol required",
            ],
        ),
        (
            "topbar_mount",
            vec![
                "context_type=player_context",
                "parent_window_token must come from parent-mod style evidence",
                "window_name must resolve to interface/*.gui",
            ],
        ),
        (
            "decision_attached",
            vec![
                "context_type=decision_category",
                "decision category must mount scripted_gui",
                "decision category id must resolve through strict-code-index",
            ],
        ),
        (
            "map_window",
            vec![
                "map window must come from target/style interface evidence",
                "window_name must resolve to interface/*.gui",
                "TDR_map_GUI.gui style evidence is preferred when available",
            ],
        ),
    ]
    .into_iter()
    .map(|(kind, requirements)| {
        format!(
            "\"{}\": {{\"requirements\": {}}}",
            kind,
            json_array(
                &requirements
                    .into_iter()
                    .map(str::to_string)
                    .collect::<Vec<_>>()
            )
        )
    })
    .collect::<Vec<_>>()
    .join(", ");
    format!("{{{items}}}")
}

fn gui_style_template_package_resource_index_json(
    roots: &[PathBuf],
    tokens: &GuiStyleTemplateTokens,
) -> String {
    let roots = roots
        .iter()
        .map(|root| root.display().to_string())
        .collect::<Vec<_>>();
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_resource_index.v1\",\n  \"parent_mods\": {},\n  \"sprites\": {},\n  \"button_sprites\": {},\n  \"close_sprites\": {},\n  \"panel_sprites\": {},\n  \"tab_sprites\": {},\n  \"map_sprites\": {},\n  \"fonts\": {},\n  \"evidence\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_array(&roots),
        json_array(&tokens.sprites),
        json_array(&tokens.button_sprites),
        json_array(&tokens.close_sprites),
        json_array(&tokens.panel_sprites),
        json_array(&tokens.tab_sprites),
        json_array(&tokens.map_sprites),
        json_array(&tokens.fonts),
        json_array(&tokens.style_token_evidence),
        json_array(&[
            "A generated GUI sprite must resolve through this package, target mod, dependency mod, or game index before final write.".to_string(),
            "Missing sprites require asset_questions and register-gui-asset before apply-gui-intent final-check.".to_string(),
        ]),
    )
}

fn gui_style_template_package_visual_template_examples_json(
    roots: &[PathBuf],
    tokens: &GuiStyleTemplateTokens,
) -> String {
    let roots = roots
        .iter()
        .map(|root| root.display().to_string())
        .collect::<Vec<_>>();
    let templates = gui_visual_template_examples(tokens);
    let visual_roles = templates
        .iter()
        .map(|template| template.role.clone())
        .collect::<Vec<_>>();
    let template_items = templates
        .iter()
        .map(|template| {
            format!(
                "    {{\"visual_role\": {}, \"visual_roles\": {}, \"style_tokens\": {}, \"evidence_count\": {}, \"evidence\": {}, \"usable_by_matcher\": {}}}",
                json_str(&template.role),
                json_array(&[template.role.clone()]),
                json_array(&template.tokens),
                template.evidence.len(),
                json_array(&template.evidence),
                json_bool(!template.evidence.is_empty()),
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_visual_template_examples.v1\",\n  \"parent_mods\": {},\n  \"visual_roles\": {},\n  \"template_count\": {},\n  \"templates\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_array(&roots),
        json_array(&visual_roles),
        templates.len(),
        template_items,
        json_array(&[
            "Visual template examples are evidence summaries, not permission to copy parent GUI code.".to_string(),
            "Runtime style matching must still prove target GUI components, sprites, fonts, and structure overlap these parent examples.".to_string(),
        ]),
    )
}

#[derive(Clone, Debug)]
struct GuiVisualTemplateExample {
    role: String,
    tokens: Vec<String>,
    evidence: Vec<String>,
}

fn gui_visual_template_examples(tokens: &GuiStyleTemplateTokens) -> Vec<GuiVisualTemplateExample> {
    let specs: [(&str, Vec<String>, &[&str]); 8] = [
        (
            "panel_background",
            tokens.panel_sprites.clone(),
            &["panel_sprite:", "structure:structure:has_panel_sprite"],
        ),
        (
            "close_button",
            tokens.close_sprites.clone(),
            &[
                "close_sprite:",
                "component_template:component:titlebar_close",
                "structure:structure:has_close_button",
            ],
        ),
        (
            "action_button",
            tokens.button_sprites.clone(),
            &[
                "button_sprite:",
                "structure:structure:has_action_button",
                "structure:structure:fonted_button_family",
            ],
        ),
        (
            "titlebar_close",
            vec!["component:titlebar_close".to_string()],
            &["component_template:component:titlebar_close"],
        ),
        (
            "list_detail_scroll",
            vec!["component:list_detail_scroll".to_string()],
            &["component_template:component:list_detail_scroll"],
        ),
        (
            "pagination_buttons",
            vec!["component:pagination_buttons".to_string()],
            &["component_template:component:pagination_buttons"],
        ),
        (
            "filter_list",
            vec!["component:filter_list".to_string()],
            &["component_template:component:filter_list"],
        ),
        (
            "fonted_text",
            tokens.fonts.clone(),
            &[
                "font:",
                "button_font:",
                "structure:structure:has_text_area",
                "structure:structure:text_and_button_family",
            ],
        ),
    ];
    specs
        .into_iter()
        .filter_map(|(role, raw_tokens, evidence_prefixes)| {
            let mut role_tokens = raw_tokens
                .into_iter()
                .filter(|token| {
                    !token.trim().is_empty()
                        && (token.starts_with("component:")
                            || tokens.sprites.contains(token)
                            || tokens.fonts.contains(token))
                })
                .collect::<Vec<_>>();
            role_tokens.sort();
            role_tokens.dedup();
            let evidence = gui_style_evidence_with_prefixes(
                &tokens.style_token_evidence,
                evidence_prefixes,
                32,
            );
            if role_tokens.is_empty() && evidence.is_empty() {
                None
            } else {
                Some(GuiVisualTemplateExample {
                    role: role.to_string(),
                    tokens: role_tokens,
                    evidence,
                })
            }
        })
        .collect()
}

fn gui_style_evidence_with_prefixes(
    evidence: &[String],
    prefixes: &[&str],
    limit: usize,
) -> Vec<String> {
    let mut out = Vec::new();
    for item in evidence {
        if prefixes.iter().any(|prefix| item.starts_with(prefix)) {
            push_capped_unique(&mut out, item.clone(), limit);
        }
        if out.len() >= limit {
            break;
        }
    }
    out
}

fn gui_style_tokens_json(tokens: &GuiStyleTemplateTokens) -> String {
    format!(
        "{{\"fonts\": {}, \"sprites\": {}, \"button_sprites\": {}, \"close_sprites\": {}, \"panel_sprites\": {}, \"tab_sprites\": {}, \"map_sprites\": {}, \"parent_window_tokens\": {}, \"visible_flags\": {}, \"click_handlers\": {}, \"scripted_effect_bridges\": {}, \"window_names\": {}, \"structure_signatures\": {}, \"component_templates\": {}, \"style_token_evidence\": {}, \"control_type_evidence\": {}}}",
        json_array(&tokens.fonts),
        json_array(&tokens.sprites),
        json_array(&tokens.button_sprites),
        json_array(&tokens.close_sprites),
        json_array(&tokens.panel_sprites),
        json_array(&tokens.tab_sprites),
        json_array(&tokens.map_sprites),
        json_array(&tokens.parent_window_tokens),
        json_array(&tokens.visible_flags),
        json_array(&tokens.click_handlers),
        json_array(&tokens.scripted_effect_bridges),
        json_array(&tokens.window_names),
        json_array(&tokens.structure_signatures),
        json_array(&tokens.component_templates),
        json_array(&tokens.style_token_evidence),
        json_array(&tokens.control_type_evidence),
    )
}

fn gui_style_examples_json(reports: &[LargeModGuiPatternProfile]) -> String {
    let mut groups = Vec::new();
    for kind in [
        "decision_attached",
        "standalone",
        "topbar_mount",
        "map_window",
    ] {
        let examples = gui_style_entries_for_kind(reports, kind)
            .into_iter()
            .take(8)
            .map(scripted_gui_entry_json)
            .collect::<Vec<_>>()
            .join(",\n");
        groups.push(format!("\"{kind}\": [{examples}]"));
    }
    format!("{{{}}}", groups.join(", "))
}

#[derive(Clone, Debug)]
struct LargeModGuiPatternProfile {
    mod_root: PathBuf,
    scripted_gui_files: Vec<String>,
    interface_gui_files: Vec<String>,
    scripted_effect_files: Vec<String>,
    decision_mounts: Vec<GuiDecisionMount>,
    scripted_guis: Vec<ScriptedGuiEntry>,
    interface_windows: Vec<String>,
    scripted_effect_gui_entries: Vec<String>,
    tdr_map_gui_files: Vec<String>,
    missing_window_bindings: Vec<String>,
}

impl LargeModGuiPatternProfile {
    fn has_decision_attached_gui(&self) -> bool {
        self.scripted_guis
            .iter()
            .any(|entry| entry.context_type.as_deref() == Some("decision_category"))
            || self.decision_mounts.iter().any(|mount| {
                self.scripted_guis
                    .iter()
                    .any(|entry| entry.id == mount.scripted_gui)
            })
    }

    fn has_standalone_gui(&self) -> bool {
        self.scripted_guis
            .iter()
            .any(|entry| entry.context_type.as_deref() == Some("player_context"))
    }

    fn has_mount_points(&self) -> bool {
        !self.decision_mounts.is_empty()
            || self
                .scripted_guis
                .iter()
                .any(|entry| entry.parent_window_token.is_some())
    }

    fn has_scripted_effects(&self) -> bool {
        !self.scripted_effect_gui_entries.is_empty()
    }

    fn has_tdr_map_gui(&self) -> bool {
        !self.tdr_map_gui_files.is_empty()
    }
}

#[derive(Clone, Debug)]
struct GuiDecisionMount {
    scripted_gui: String,
    path: String,
    line: usize,
}

#[derive(Clone, Debug)]
struct GuiMountAudit {
    ok: bool,
    mod_root: PathBuf,
    style_roots: Vec<PathBuf>,
    gui_kind: String,
    strict_code_index: bool,
    target_profile: LargeModGuiPatternProfile,
    style_profiles: Vec<LargeModGuiPatternProfile>,
    style_tokens: GuiStyleTemplateTokens,
    decision_category: Option<String>,
    map_window: Option<String>,
    blockers: Vec<String>,
    questions: Vec<String>,
    recommended_game_code: Vec<GuiRequestGameCodeCandidate>,
}

#[derive(Clone, Debug, Default)]
struct GuiMountAuditScope {
    scripted_gui_ids: BTreeSet<String>,
    window_names: BTreeSet<String>,
}

fn gui_mount_audit_scope_from_args(map: &ArgMap) -> Result<GuiMountAuditScope, String> {
    let mut scope = GuiMountAuditScope::default();
    for id in repeated_values(map, "scripted-gui-id")
        .into_iter()
        .chain(repeated_values(map, "scripted-gui"))
    {
        scope.scripted_gui_ids.insert(id.to_string());
    }
    for window in repeated_values(map, "window-name") {
        scope.window_names.insert(window.to_string());
    }
    if let Some(apply_report) = value(map, "apply-report") {
        let apply_report = normalize_path(apply_report)?;
        let text = read_utf8_lossy(&apply_report)?;
        if let Some(id) = top_level_json_string_field(&text, "scripted_gui_id") {
            if !id.trim().is_empty() {
                scope.scripted_gui_ids.insert(id);
            }
        }
        if let Some(window) = top_level_json_string_field(&text, "window_name") {
            if !window.trim().is_empty() {
                scope.window_names.insert(window);
            }
        }
    }
    Ok(scope)
}

fn gui_mount_audit_report(
    mod_root: &Path,
    style_roots: &[PathBuf],
    gui_kind: &str,
    decision_category: Option<&str>,
    map_window: Option<&str>,
    strict_index: Option<&GameIndex>,
    scope: &GuiMountAuditScope,
) -> Result<GuiMountAudit, String> {
    let target_profile = large_mod_gui_pattern_profile(mod_root)?;
    let style_profiles = style_roots
        .iter()
        .map(|root| large_mod_gui_pattern_profile(root))
        .collect::<Result<Vec<_>, _>>()?;
    let token_reports = if style_profiles.is_empty() {
        vec![target_profile.clone()]
    } else {
        style_profiles.clone()
    };
    let style_tokens = collect_gui_style_template_tokens(&token_reports)?;
    let mut blockers = Vec::new();
    let mut questions = Vec::new();
    let target_windows = target_profile
        .interface_windows
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let target_scripted_gui_ids = target_profile
        .scripted_guis
        .iter()
        .map(|entry| entry.id.clone())
        .collect::<BTreeSet<_>>();
    let target_decision_mount_ids = target_profile
        .decision_mounts
        .iter()
        .map(|mount| mount.scripted_gui.clone())
        .collect::<BTreeSet<_>>();
    let scoped_scripted_guis = if scope.scripted_gui_ids.is_empty() && scope.window_names.is_empty()
    {
        target_profile.scripted_guis.clone()
    } else {
        target_profile
            .scripted_guis
            .iter()
            .filter(|entry| {
                scope.scripted_gui_ids.contains(&entry.id)
                    || entry
                        .window_name
                        .as_ref()
                        .is_some_and(|window| scope.window_names.contains(window))
            })
            .cloned()
            .collect::<Vec<_>>()
    };
    let scoped_ids = scoped_scripted_guis
        .iter()
        .map(|entry| entry.id.clone())
        .collect::<BTreeSet<_>>();
    for mount in &target_profile.decision_mounts {
        if !scoped_ids.is_empty() && !scoped_ids.contains(&mount.scripted_gui) {
            continue;
        }
        if !target_scripted_gui_ids.contains(&mount.scripted_gui) {
            blockers.push(format!(
                "decision_mount_unknown_scripted_gui:{}:{}",
                mount.path, mount.scripted_gui
            ));
            questions.push(format!(
                "Decision mount `{}` in `{}` line {} does not point to a scripted_gui in the target mod; choose one of the audited scripted_gui ids.",
                mount.scripted_gui, mount.path, mount.line
            ));
        }
    }
    if !scope.scripted_gui_ids.is_empty()
        && scoped_scripted_guis.len() < scope.scripted_gui_ids.len()
    {
        for id in &scope.scripted_gui_ids {
            if !scoped_ids.contains(id) {
                blockers.push(format!("scoped_scripted_gui_missing:{id}"));
                questions.push(format!(
                    "The current apply report names scripted_gui `{id}`, but gui-mount-audit could not find it in the target profile."
                ));
            }
        }
    }
    for entry in &scoped_scripted_guis {
        match entry.window_name.as_deref() {
            Some(window) if target_windows.contains(window) => {}
            Some(window) => {
                blockers.push(format!(
                    "scripted_gui_window_missing_interface:{}:{}",
                    entry.id, window
                ));
                questions.push(format!(
                    "scripted_gui `{}` uses window `{window}`, but the target mod has no matching interface .gui window name. Create the window through the GUI writer or choose an indexed existing window.",
                    entry.id
                ));
            }
            None => {
                blockers.push(format!("scripted_gui_missing_window_name:{}", entry.id));
                questions.push(format!(
                    "scripted_gui `{}` must declare window_name before final GUI output is accepted.",
                    entry.id
                ));
            }
        }
        match entry.context_type.as_deref() {
            Some("player_context") | Some("decision_category") => {}
            Some(context) => {
                blockers.push(format!(
                    "scripted_gui_unknown_context_type:{}:{}",
                    entry.id, context
                ));
                questions.push(format!(
                    "scripted_gui `{}` has unsupported context_type `{context}`. Use indexed parent examples for player_context or decision_category before accepting it.",
                    entry.id
                ));
            }
            None => {
                blockers.push(format!("scripted_gui_missing_context_type:{}", entry.id));
                questions.push(format!(
                    "scripted_gui `{}` must declare context_type so the CLI can validate its mount contract.",
                    entry.id
                ));
            }
        }
        if entry.context_type.as_deref() == Some("decision_category")
            && !target_decision_mount_ids.contains(&entry.id)
        {
            blockers.push(format!(
                "decision_attached_scripted_gui_unmounted:{}",
                entry.id
            ));
            questions.push(format!(
                "scripted_gui `{}` is context_type=decision_category but no target decision category mounts it with scripted_gui = {}.",
                entry.id, entry.id
            ));
        }
        if let Some(parent) = entry.parent_window_token.as_deref() {
            if !style_tokens
                .parent_window_tokens
                .iter()
                .any(|candidate| candidate == parent)
            {
                blockers.push(format!("unknown_parent_window_token_mount:{parent}"));
                let candidates = nearest_or_first_string_candidates(
                    parent,
                    style_tokens.parent_window_tokens.iter().map(String::as_str),
                    12,
                );
                questions.push(format!(
                    "parent_window_token `{parent}` has no parent-mod style evidence. Choose one of the candidate tokens or provide a parent GUI sample: {}",
                    if candidates.is_empty() {
                        "no candidates found".to_string()
                    } else {
                        candidates.join(", ")
                    }
                ));
            }
        }
    }
    if gui_kind == "topbar_mount"
        && !scoped_scripted_guis
            .iter()
            .any(|entry| entry.parent_window_token.is_some())
    {
        blockers.push("topbar_mount_missing_parent_window_token".to_string());
        questions.push(
            "topbar_mount GUI must bind through an evidenced parent_window_token from the parent mod."
                .to_string(),
        );
    }
    if gui_kind == "decision_attached" {
        if !scoped_scripted_guis
            .iter()
            .any(|entry| entry.context_type.as_deref() == Some("decision_category"))
        {
            blockers.push("decision_attached_missing_scripted_gui_context".to_string());
        }
        if target_profile.decision_mounts.is_empty() {
            blockers.push("decision_attached_missing_decision_mount".to_string());
        }
    }
    if let Some(category) = decision_category {
        match strict_index {
            Some(index) if index.decision_categories.contains(category) => {}
            Some(index) => {
                blockers.push(format!("unknown_decision_category_mount:{category}"));
                let candidates = nearest_or_first_string_candidates(
                    category,
                    index.decision_categories.iter().map(String::as_str),
                    12,
                );
                questions.push(format!(
                    "Decision category `{category}` is absent from strict-code-index. Choose an indexed category before writing the GUI mount: {}",
                    if candidates.is_empty() {
                        "no candidates found".to_string()
                    } else {
                        candidates.join(", ")
                    }
                ));
            }
            None => {
                blockers.push(format!(
                    "decision_category_mount_requires_strict_code_index:{category}"
                ));
                questions.push(
                    "Rerun gui-mount-audit with --game-root <HOI4 root> --strict-code-index so the decision category mount can be proven instead of guessed."
                        .to_string(),
                );
            }
        }
    }
    let mut known_map_windows = style_tokens.window_names.clone();
    for window in &target_profile.interface_windows {
        push_capped_unique(&mut known_map_windows, window.clone(), 500);
    }
    if let Some(window) = map_window {
        if !known_map_windows.iter().any(|known| known == window) {
            blockers.push(format!("unknown_map_window_mount:{window}"));
            let candidates = nearest_or_first_string_candidates(
                window,
                known_map_windows.iter().map(String::as_str),
                12,
            );
            questions.push(format!(
                "Map window `{window}` is not evidenced by target/style interface windows. Choose a candidate or provide a parent GUI sample: {}",
                if candidates.is_empty() {
                    "no candidates found".to_string()
                } else {
                    candidates.join(", ")
                }
            ));
        }
    } else if gui_kind == "map_window"
        && !target_profile.has_tdr_map_gui()
        && !style_profiles
            .iter()
            .any(LargeModGuiPatternProfile::has_tdr_map_gui)
    {
        blockers.push("map_window_mount_missing_window_evidence".to_string());
        questions.push(
            "map_window GUI needs an explicit --map-window value or a parent-mod map GUI example."
                .to_string(),
        );
    }
    blockers.sort();
    blockers.dedup();
    questions.sort();
    questions.dedup();
    let recommended_game_code = gui_output_audit_recommended_game_code(&blockers);
    Ok(GuiMountAudit {
        ok: blockers.is_empty(),
        mod_root: mod_root.to_path_buf(),
        style_roots: style_roots.to_vec(),
        gui_kind: gui_kind.to_string(),
        strict_code_index: strict_index.is_some(),
        target_profile,
        style_profiles,
        style_tokens,
        decision_category: decision_category.map(str::to_string),
        map_window: map_window.map(str::to_string),
        blockers,
        questions,
        recommended_game_code,
    })
}

fn gui_mount_audit_report_json(report: &GuiMountAudit) -> String {
    let style_roots = report
        .style_roots
        .iter()
        .map(|root| root.display().to_string())
        .collect::<Vec<_>>();
    let style_profiles = report
        .style_profiles
        .iter()
        .map(large_mod_gui_pattern_profile_json)
        .collect::<Vec<_>>()
        .join(",\n");
    format!(
        "{{\n  \"schema\": \"hoi4skill.gui_mount_audit.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"mod_root\": {},\n  \"style_roots\": {},\n  \"gui_kind\": {},\n  \"strict_code_index\": {},\n  \"decision_category\": {},\n  \"map_window\": {},\n  \"target_profile\": {},\n  \"style_profiles\": [\n{}\n  ],\n  \"style_mount_tokens\": {{\"parent_window_tokens\": {}, \"window_names\": {}, \"style_token_evidence\": {}}},\n  \"blockers\": {},\n  \"questions\": {},\n  \"recommended_game_code\": [\n{}\n  ],\n  \"objective_acceptance\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_str(if report.ok { "passed" } else { "blocked" }),
        json_bool(report.ok),
        json_str(&report.mod_root.display().to_string()),
        json_array(&style_roots),
        json_str(&report.gui_kind),
        json_bool(report.strict_code_index),
        json_optional_str(report.decision_category.as_deref()),
        json_optional_str(report.map_window.as_deref()),
        large_mod_gui_pattern_profile_json(&report.target_profile),
        style_profiles,
        json_array(&report.style_tokens.parent_window_tokens),
        json_array(&report.style_tokens.window_names),
        json_array(&report.style_tokens.style_token_evidence),
        json_array(&report.blockers),
        json_array(&report.questions),
        report
            .recommended_game_code
            .iter()
            .map(gui_request_game_code_candidate_json)
            .collect::<Vec<_>>()
            .join(",\n"),
        vec![
            gui_request_acceptance_item_json(
                "scripted_gui_window_bindings",
                "Every scripted_gui window_name resolves to a target interface .gui window.",
                report
                    .blockers
                    .iter()
                    .all(|blocker| !blocker.starts_with("scripted_gui_window_missing_interface")
                        && !blocker.starts_with("scripted_gui_missing_window_name")),
                "common/scripted_guis + interface/*.gui",
            ),
            gui_request_acceptance_item_json(
                "mount_points",
                "Decision, parent-window, and map-window mounts are evidenced before final GUI write.",
                report.blockers.iter().all(|blocker| {
                    !blocker.contains("_mount")
                        && !blocker.starts_with("decision_attached_")
                        && !blocker.starts_with("topbar_mount_")
                        && !blocker.starts_with("map_window_")
                }),
                "scripted_guis/decisions/style profile/strict-code-index",
            ),
            gui_request_acceptance_item_json(
                "strict_decision_category",
                "Requested decision category mount is proven by strict-code-index when supplied.",
                report.decision_category.is_none()
                    || (report.strict_code_index
                        && report
                            .blockers
                            .iter()
                            .all(|blocker| !blocker.contains("decision_category"))),
                "game-root + strict-code-index",
            ),
        ]
        .join(",\n"),
        json_array(&[
            "Do not save generated GUI files when gui_mount_audit.ok=false.".to_string(),
            "Unknown parent_window_token, decision category, or map window must ask the user or use the listed indexed candidates.".to_string(),
            "scripted_gui window_name must resolve to a concrete interface window before runtime GUI evidence is trusted.".to_string(),
        ]),
    )
}

#[derive(Clone, Debug)]
struct ScriptedGuiEntry {
    id: String,
    path: String,
    line: usize,
    context_type: Option<String>,
    parent_window_token: Option<String>,
    window_name: Option<String>,
    visible_flag_tokens: Vec<String>,
    effect_tokens: Vec<String>,
    action_effect_calls: Vec<String>,
}

#[derive(Clone, Debug)]
struct LargeModGuiPatternAggregate {
    mod_count: usize,
    has_decision_attached_gui: bool,
    has_standalone_gui: bool,
    has_mount_points: bool,
    has_scripted_effects: bool,
    has_tdr_map_gui: bool,
}

impl LargeModGuiPatternAggregate {
    fn from_reports(reports: &[LargeModGuiPatternProfile]) -> Self {
        Self {
            mod_count: reports.len(),
            has_decision_attached_gui: reports
                .iter()
                .any(LargeModGuiPatternProfile::has_decision_attached_gui),
            has_standalone_gui: reports
                .iter()
                .any(LargeModGuiPatternProfile::has_standalone_gui),
            has_mount_points: reports
                .iter()
                .any(LargeModGuiPatternProfile::has_mount_points),
            has_scripted_effects: reports
                .iter()
                .any(LargeModGuiPatternProfile::has_scripted_effects),
            has_tdr_map_gui: reports
                .iter()
                .any(LargeModGuiPatternProfile::has_tdr_map_gui),
        }
    }

    fn required_patterns_ready(&self) -> bool {
        self.has_decision_attached_gui
            && self.has_standalone_gui
            && self.has_mount_points
            && self.has_scripted_effects
    }
}

fn large_mod_gui_pattern_profile(mod_root: &Path) -> Result<LargeModGuiPatternProfile, String> {
    if !mod_root.is_dir() {
        return Err(format!("mod root does not exist: {}", mod_root.display()));
    }
    let scripted_gui_files = collect_profile_files_relative(
        mod_root,
        &mod_root.join("common").join("scripted_guis"),
        &["txt"],
        200,
    )?;
    let interface_gui_files =
        collect_profile_files_relative(mod_root, &mod_root.join("interface"), &["gui"], 500)?;
    let scripted_effect_files = collect_profile_files_relative(
        mod_root,
        &mod_root.join("common").join("scripted_effects"),
        &["txt"],
        500,
    )?;
    let mut scripted_guis = Vec::new();
    for path in &scripted_gui_files {
        let full = mod_root.join(path);
        scripted_guis.extend(parse_scripted_gui_entries(mod_root, &full)?);
    }
    let mut decision_mounts = Vec::new();
    for path in collect_profile_files_relative(
        mod_root,
        &mod_root.join("common").join("decisions"),
        &["txt"],
        500,
    )? {
        decision_mounts.extend(parse_decision_scripted_gui_mounts(
            mod_root,
            &mod_root.join(path),
        )?);
    }
    let mut interface_windows = Vec::new();
    for path in &interface_gui_files {
        interface_windows.extend(parse_gui_window_names(&mod_root.join(path))?);
    }
    interface_windows.sort();
    interface_windows.dedup();
    let scripted_effect_gui_entries =
        collect_scripted_effect_gui_entries(mod_root, &scripted_effect_files)?;
    let tdr_map_gui_files = interface_gui_files
        .iter()
        .filter(|path| {
            path.replace('\\', "/")
                .to_ascii_lowercase()
                .ends_with("tdr_map_gui.gui")
        })
        .cloned()
        .collect::<Vec<_>>();
    let missing_window_bindings = scripted_guis
        .iter()
        .filter_map(|entry| {
            let window = entry.window_name.as_ref()?;
            (!interface_windows
                .iter()
                .any(|candidate| candidate == window))
            .then(|| format!("{} -> {}", entry.id, window))
        })
        .take(40)
        .collect::<Vec<_>>();
    Ok(LargeModGuiPatternProfile {
        mod_root: mod_root.to_path_buf(),
        scripted_gui_files,
        interface_gui_files,
        scripted_effect_files,
        decision_mounts,
        scripted_guis,
        interface_windows,
        scripted_effect_gui_entries,
        tdr_map_gui_files,
        missing_window_bindings,
    })
}

fn collect_profile_files_relative(
    root: &Path,
    dir: &Path,
    extensions: &[&str],
    cap: usize,
) -> Result<Vec<String>, String> {
    if !dir.is_dir() {
        return Ok(Vec::new());
    }
    let mut files = collect_files(dir)?
        .into_iter()
        .filter(|path| {
            path.is_file()
                && path
                    .extension()
                    .and_then(|value| value.to_str())
                    .is_some_and(|value| {
                        extensions.iter().any(|ext| value.eq_ignore_ascii_case(ext))
                    })
        })
        .map(|path| relative_slash_path(root, &path))
        .collect::<Vec<_>>();
    files.sort();
    files.truncate(cap);
    Ok(files)
}

fn parse_scripted_gui_entries(root: &Path, path: &Path) -> Result<Vec<ScriptedGuiEntry>, String> {
    let text = read_utf8_lossy(path)?;
    let rel = relative_slash_path(root, path);
    let mut entries = Vec::new();
    let mut in_root = false;
    let mut depth = 0i32;
    let mut current: Option<usize> = None;
    for (idx, raw_line) in text.lines().enumerate() {
        let line = raw_line.split('#').next().unwrap_or("").trim();
        if line.is_empty() {
            continue;
        }
        let before_depth = depth;
        if !in_root && line.starts_with("scripted_gui") && line.contains('{') {
            in_root = true;
            depth += brace_delta(line);
            continue;
        }
        if in_root && before_depth == 1 {
            if let Some(id) = block_header_name(line) {
                entries.push(ScriptedGuiEntry {
                    id,
                    path: rel.clone(),
                    line: idx + 1,
                    context_type: None,
                    parent_window_token: None,
                    window_name: None,
                    visible_flag_tokens: Vec::new(),
                    effect_tokens: Vec::new(),
                    action_effect_calls: Vec::new(),
                });
                current = Some(entries.len() - 1);
            }
        }
        if let Some(entry_idx) = current {
            if let Some(value) = assignment_value(line, "context_type") {
                entries[entry_idx].context_type = Some(value);
            }
            if let Some(value) = assignment_value(line, "parent_window_token") {
                entries[entry_idx].parent_window_token = Some(value);
            }
            if let Some(value) = assignment_value(line, "window_name") {
                entries[entry_idx].window_name = Some(value);
            }
            for key in ["has_country_flag", "set_country_flag", "clr_country_flag"] {
                if let Some(value) = assignment_value(line, key) {
                    push_capped_unique(&mut entries[entry_idx].visible_flag_tokens, value, 12);
                }
            }
            if line.ends_with("_click = {") || line.contains("_click = {") {
                if let Some(id) = block_header_name(line) {
                    push_capped_unique(&mut entries[entry_idx].effect_tokens, id, 12);
                }
            }
            for call in parse_scripted_gui_action_helper_calls(line) {
                push_capped_unique(&mut entries[entry_idx].action_effect_calls, call, 32);
            }
        }
        depth += brace_delta(line);
        if current.is_some() && depth <= 1 {
            current = None;
        }
        if in_root && depth <= 0 {
            in_root = false;
            depth = 0;
        }
    }
    Ok(entries)
}

fn parse_scripted_gui_action_helper_calls(line: &str) -> Vec<String> {
    let mut calls = Vec::new();
    let line = line.split('#').next().unwrap_or("");
    let mut search_end = line.len();
    while let Some(eq_idx) = line[..search_end].rfind('=') {
        let tail = line[eq_idx + 1..].trim_start();
        if tail.starts_with("yes")
            && tail.get(3..).is_none_or(|rest| {
                rest.chars()
                    .next()
                    .is_none_or(|ch| !ch.is_ascii_alphanumeric() && ch != '_')
            })
        {
            let before = &line[..eq_idx];
            let token = before
                .trim_end()
                .rsplit(|ch: char| !(ch.is_ascii_alphanumeric() || ch == '_'))
                .next()
                .unwrap_or("")
                .trim();
            if gui_scripted_gui_action_helper_call_token(token) {
                push_capped_unique(&mut calls, token.to_string(), 32);
            }
        }
        search_end = eq_idx;
    }
    calls
}

fn gui_scripted_gui_action_helper_call_token(token: &str) -> bool {
    if token.is_empty() || !token.contains('_') || token.ends_with("_click") {
        return false;
    }
    !matches!(
        token,
        "always"
            | "has_country_flag"
            | "set_country_flag"
            | "clr_country_flag"
            | "hidden_effect"
            | "visible"
    )
}

fn parse_decision_scripted_gui_mounts(
    root: &Path,
    path: &Path,
) -> Result<Vec<GuiDecisionMount>, String> {
    let text = read_utf8_lossy(path)?;
    let rel = relative_slash_path(root, path);
    let mut mounts = Vec::new();
    for (idx, line) in text.lines().enumerate() {
        for value in assignment_values(line.split('#').next().unwrap_or(""), "scripted_gui") {
            mounts.push(GuiDecisionMount {
                scripted_gui: value,
                path: rel.clone(),
                line: idx + 1,
            });
        }
    }
    Ok(mounts)
}

fn parse_gui_window_names(path: &Path) -> Result<Vec<String>, String> {
    let text = read_utf8_lossy(path)?;
    let mut names = Vec::new();
    for line in text.lines() {
        for value in assignment_values(line.split('#').next().unwrap_or(""), "name") {
            push_capped_unique(&mut names, value, 2000);
        }
    }
    Ok(names)
}

fn collect_scripted_effect_gui_entries(
    mod_root: &Path,
    files: &[String],
) -> Result<Vec<String>, String> {
    let mut entries = Vec::new();
    for relative in files {
        let text = read_utf8_lossy(&mod_root.join(relative))?;
        let mut current_effect: Option<String> = None;
        let mut depth = 0i32;
        for line in text.lines() {
            let line = line.split('#').next().unwrap_or("").trim();
            let before_depth = depth;
            if before_depth == 0 {
                current_effect = block_header_name(line);
            }
            let gui_related = line.contains("set_temp_variable")
                || line.contains("custom_effect_tooltip")
                || line.contains("set_country_flag")
                || line.contains("clr_country_flag")
                || line.contains("_gui")
                || line.contains("open_")
                || line.contains("close_");
            if gui_related {
                let label = current_effect
                    .as_deref()
                    .map(|effect| format!("{relative}:{effect}"))
                    .unwrap_or_else(|| relative.to_string());
                push_capped_unique(&mut entries, label, 80);
            }
            depth += brace_delta(line);
            if depth <= 0 {
                depth = 0;
                current_effect = None;
            }
        }
    }
    Ok(entries)
}

fn block_header_name(line: &str) -> Option<String> {
    let (raw, rest) = line.split_once('=')?;
    if !rest.trim_start().starts_with('{') {
        return None;
    }
    let name = raw.trim();
    if name.is_empty()
        || matches!(
            name,
            "scripted_gui"
                | "effects"
                | "triggers"
                | "properties"
                | "visible"
                | "if"
                | "else_if"
                | "limit"
                | "OR"
                | "AND"
                | "NOT"
        )
    {
        None
    } else {
        Some(name.trim_matches('"').to_string())
    }
}

fn assignment_value(line: &str, key: &str) -> Option<String> {
    assignment_values(line, key).into_iter().next()
}

fn assignment_values(line: &str, key: &str) -> Vec<String> {
    let mut values = Vec::new();
    let mut offset = 0usize;
    while let Some(idx) = line[offset..].find(key) {
        let start = offset + idx;
        let before_ok = line[..start]
            .chars()
            .next_back()
            .is_none_or(|ch| !(ch.is_ascii_alphanumeric() || ch == '_'));
        let Some(after) = line.get(start + key.len()..) else {
            break;
        };
        let after_trimmed = after.trim_start();
        if before_ok && after_trimmed.starts_with('=') {
            if let Some(value) = assignment_value_token(after_trimmed[1..].trim_start()) {
                push_capped_unique(&mut values, value, 2000);
            }
        }
        offset = start + key.len();
    }
    values
}

fn assignment_value_token(raw_value: &str) -> Option<String> {
    let value = raw_value.trim();
    if value.is_empty() {
        return None;
    }
    if let Some(rest) = value.strip_prefix('"') {
        let token = rest.split('"').next().unwrap_or("").trim();
        return (!token.is_empty()).then(|| token.to_string());
    }
    let value = value.trim_start_matches('{').trim_start();
    let token = value
        .split(|ch: char| ch.is_whitespace() || matches!(ch, '{' | '}'))
        .next()
        .unwrap_or("")
        .trim_matches('"')
        .trim();
    (!token.is_empty()).then(|| token.to_string())
}

fn brace_delta(line: &str) -> i32 {
    line.chars().filter(|ch| *ch == '{').count() as i32
        - line.chars().filter(|ch| *ch == '}').count() as i32
}

fn push_capped_unique(values: &mut Vec<String>, value: String, cap: usize) {
    if values.len() < cap && !values.iter().any(|existing| existing == &value) {
        values.push(value);
    }
}

fn large_mod_gui_pattern_audit_json(
    reports: &[LargeModGuiPatternProfile],
    aggregate: &LargeModGuiPatternAggregate,
    ok: bool,
) -> String {
    let report_json = reports
        .iter()
        .map(large_mod_gui_pattern_profile_json)
        .collect::<Vec<_>>()
        .join(",\n");
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_gui_pattern_audit.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"mod_count\": {},\n  \"patterns\": {{\"decision_attached_gui\": {}, \"standalone_gui\": {}, \"mount_points\": {}, \"scripted_effects\": {}, \"tdr_map_gui\": {}}},\n  \"reports\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_str(if ok { "passed" } else { "failed" }),
        json_bool(ok),
        aggregate.mod_count,
        json_bool(aggregate.has_decision_attached_gui),
        json_bool(aggregate.has_standalone_gui),
        json_bool(aggregate.has_mount_points),
        json_bool(aggregate.has_scripted_effects),
        json_bool(aggregate.has_tdr_map_gui),
        report_json,
        json_array(&[
            "Do not write GUI code until scripted_gui window_name has a matching interface window name.".to_string(),
            "Decision-attached GUI needs both common/scripted_guis context_type=decision_category and a decision category scripted_gui mount.".to_string(),
            "Standalone GUI needs a player_context scripted_gui, a visible/open flag protocol, and an interface .gui window.".to_string(),
            "Scripted effects should own reusable state/variable updates; GUI click handlers should call those helpers where possible.".to_string(),
        ])
    )
}

fn large_mod_gui_pattern_profile_json(report: &LargeModGuiPatternProfile) -> String {
    let scripted_guis = report
        .scripted_guis
        .iter()
        .take(80)
        .map(scripted_gui_entry_json)
        .collect::<Vec<_>>()
        .join(",\n");
    let decision_mounts = report
        .decision_mounts
        .iter()
        .take(80)
        .map(|mount| {
            format!(
                "      {{\"scripted_gui\": {}, \"path\": {}, \"line\": {}}}",
                json_str(&mount.scripted_gui),
                json_str(&mount.path),
                mount.line
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    format!(
        "    {{\n      \"mod_root\": {},\n      \"has_decision_attached_gui\": {},\n      \"has_standalone_gui\": {},\n      \"has_mount_points\": {},\n      \"has_scripted_effects\": {},\n      \"has_tdr_map_gui\": {},\n      \"scripted_gui_file_count\": {},\n      \"interface_gui_file_count\": {},\n      \"scripted_effect_file_count\": {},\n      \"scripted_gui_count\": {},\n      \"decision_mount_count\": {},\n      \"interface_window_count\": {},\n      \"scripted_effect_gui_entry_count\": {},\n      \"scripted_gui_files\": {},\n      \"interface_gui_files\": {},\n      \"tdr_map_gui_files\": {},\n      \"missing_window_bindings\": {},\n      \"decision_mounts\": [\n{}\n      ],\n      \"scripted_guis\": [\n{}\n      ],\n      \"scripted_effect_gui_entries\": {}\n    }}",
        json_str(&report.mod_root.display().to_string()),
        json_bool(report.has_decision_attached_gui()),
        json_bool(report.has_standalone_gui()),
        json_bool(report.has_mount_points()),
        json_bool(report.has_scripted_effects()),
        json_bool(report.has_tdr_map_gui()),
        report.scripted_gui_files.len(),
        report.interface_gui_files.len(),
        report.scripted_effect_files.len(),
        report.scripted_guis.len(),
        report.decision_mounts.len(),
        report.interface_windows.len(),
        report.scripted_effect_gui_entries.len(),
        json_array(&report.scripted_gui_files),
        json_array(&report.interface_gui_files),
        json_array(&report.tdr_map_gui_files),
        json_array(&report.missing_window_bindings),
        decision_mounts,
        scripted_guis,
        json_array(&report.scripted_effect_gui_entries),
    )
}

fn scripted_gui_entry_json(entry: &ScriptedGuiEntry) -> String {
    format!(
        "      {{\"id\": {}, \"path\": {}, \"line\": {}, \"context_type\": {}, \"parent_window_token\": {}, \"window_name\": {}, \"visible_flag_tokens\": {}, \"effect_tokens\": {}}}",
        json_str(&entry.id),
        json_str(&entry.path),
        entry.line,
        json_optional_str(entry.context_type.as_deref()),
        json_optional_str(entry.parent_window_token.as_deref()),
        json_optional_str(entry.window_name.as_deref()),
        json_array(&entry.visible_flag_tokens),
        json_array(&entry.effect_tokens),
    )
}

fn gui_decision_mount_json(mount: &GuiDecisionMount) -> String {
    format!(
        "      {{\"scripted_gui\": {}, \"path\": {}, \"line\": {}}}",
        json_str(&mount.scripted_gui),
        json_str(&mount.path),
        mount.line
    )
}

fn init_large_mod_user_request_smoke_mod(mod_root: &Path) -> Result<(), String> {
    fs::create_dir_all(mod_root).map_err(|e| format!("create {}: {e}", mod_root.display()))?;
    fs::write(
        mod_root.join("descriptor.mod"),
        "name=\"HOI4Skill User Request Smoke\"\nsupported_version=\"1.16.*\"\n",
    )
    .map_err(|e| format!("write descriptor.mod: {e}"))
}

fn write_large_mod_user_request_smoke_inputs(
    request_input: &Path,
    focus_input: &Path,
    event_input: &Path,
    feature_input: &Path,
    dynamic_input: &Path,
    request_text: &str,
    tag: &str,
    prefix: &str,
) -> Result<(), String> {
    fs::write(request_input, request_text)
        .map_err(|e| format!("write {}: {e}", request_input.display()))?;
    fs::write(focus_input, "没收资本家\n革命工业委员会\n人民经济动员\n")
        .map_err(|e| format!("write {}: {e}", focus_input.display()))?;
    fs::write(
        event_input,
        format!("事件：建国宣言\n类型：国家事件\n目标：{tag}\n命名空间：{prefix}\n标题：建国宣言\n描述：【红色：人民站起来了】。新的政府宣布旧秩序已经结束。\n选项A：继续\n效果A：政治点+25"),
    )
    .map_err(|e| format!("write {}: {e}", event_input.display()))?;
    fs::write(
        feature_input,
        format!("决议：镇压资本家\n目标：{tag}\n分类：革命经济\n花费：25政治点\n效果：稳定度+5%\n描述：清查投机商与破坏生产的资本势力。\n\n民族精神：资本家的反抗\n目标：{tag}\n效果：稳定度-10%，政治点获取-5%\n描述：旧有资本势力正在组织抵抗。"),
    )
    .map_err(|e| format!("write {}: {e}", feature_input.display()))?;
    fs::write(
        dynamic_input,
        "动态修正：中国制造\n效果：建造速度+10%，生产效率上限+0.05",
    )
    .map_err(|e| format!("write {}: {e}", dynamic_input.display()))
}

fn large_mod_user_request_smoke_report_json(
    output_dir: &Path,
    mod_root: &Path,
    target_mod_root: &Path,
    game_root: &Path,
    game_root_detected: bool,
    tag: &str,
    prefix: &str,
    request_input: &Path,
    focus_report: &Path,
    event_report: &Path,
    feature_report: &Path,
    dynamic_report: &Path,
    text_alignment_report: &Path,
    validation_report: &Path,
    target_profile: &LargeModCapabilitySmokeTargetProfile,
    generated_profile: &LargeModCapabilitySmokeTargetProfile,
    text_alignment_ok: bool,
    final_validation_ok: bool,
    steps: &[String],
) -> String {
    let ok = target_profile.ready()
        && generated_profile.ready()
        && text_alignment_ok
        && final_validation_ok
        && steps.iter().all(|step| step.contains("\"ok\": true"));
    let objective = [
        (
            "focus_writer",
            "User request produces national focus files through Rust writer final-check.",
            generated_profile.has_focus_content(),
            "common/national_focus",
        ),
        (
            "event_writer",
            "User request produces event files through Rust writer final-check.",
            generated_profile.has_event_content(),
            "events",
        ),
        (
            "decision_writer",
            "User request produces decision files through Rust writer final-check.",
            generated_profile.has_decision_content(),
            "common/decisions",
        ),
        (
            "national_spirit_writer",
            "User request produces national spirit files through Rust writer final-check.",
            generated_profile.has_national_spirit_content(),
            "common/ideas",
        ),
        (
            "dynamic_modifier_writer",
            "User request produces dynamic modifier protocol files, not national-spirit fallback.",
            generated_profile.has_dynamic_modifier_content(),
            "common/dynamic_modifiers + common/scripted_effects",
        ),
        (
            "localisation_writer",
            "User request produces localisation and preserves expected player-visible text.",
            generated_profile.has_localisation_content() && text_alignment_ok,
            "localisation + text_alignment",
        ),
        (
            "real_game_strict_validation",
            "Generated files pass validate --strict-code-index against a real HOI4 game root.",
            final_validation_ok,
            "validation_strict_code_index",
        ),
    ]
    .into_iter()
    .map(|(id, requirement, passed, evidence)| {
        format!(
            "    {{\"id\": {}, \"requirement\": {}, \"ok\": {}, \"evidence\": {}}}",
            json_str(id),
            json_str(requirement),
            json_bool(passed),
            json_str(evidence)
        )
    })
    .collect::<Vec<_>>();
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_user_request_smoke.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"output_dir\": {},\n  \"mod_root\": {},\n  \"target_mod_root\": {},\n  \"target_profile_ready\": {},\n  \"generated_profile_ready\": {},\n  \"generated_profile_missing\": {},\n  \"game_root\": {},\n  \"game_root_detected\": {},\n  \"tag\": {},\n  \"prefix\": {},\n  \"request_input\": {},\n  \"focus_report\": {},\n  \"event_report\": {},\n  \"feature_report\": {},\n  \"dynamic_report\": {},\n  \"text_alignment_report\": {},\n  \"validation_report\": {},\n  \"text_alignment_ok\": {},\n  \"final_validation_ok\": {},\n  \"objective_acceptance\": [\n{}\n  ],\n  \"steps\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_str(if ok { "passed" } else { "failed" }),
        json_bool(ok),
        json_str(&output_dir.display().to_string()),
        json_str(&mod_root.display().to_string()),
        json_str(&target_mod_root.display().to_string()),
        json_bool(target_profile.ready()),
        json_bool(generated_profile.ready()),
        json_array(&generated_profile.missing),
        json_str(&game_root.display().to_string()),
        json_bool(game_root_detected),
        json_str(tag),
        json_str(prefix),
        json_str(&request_input.display().to_string()),
        json_str(&focus_report.display().to_string()),
        json_str(&event_report.display().to_string()),
        json_str(&feature_report.display().to_string()),
        json_str(&dynamic_report.display().to_string()),
        json_str(&text_alignment_report.display().to_string()),
        json_str(&validation_report.display().to_string()),
        json_bool(text_alignment_ok),
        json_bool(final_validation_ok),
        objective.join(",\n"),
        steps.join(",\n"),
        json_array(&[
            "This smoke writes only to its temporary output mod, never to the target KXC/MDARD mod root.".to_string(),
            "Dynamic modifiers must stay in common/dynamic_modifiers plus scripted_effects; do not rewrite them as national spirits.".to_string(),
            "After real user edits, rerun validate --strict-code-index and check-text-alignment on the actual changed files.".to_string(),
        ])
    )
}

fn large_mod_real_readiness_smoke_report_json(
    output_dir: &Path,
    target_mod_root: &Path,
    game_root: &Path,
    game_root_detected: bool,
    capability_report: &Path,
    validation_report: &Path,
    generated_mod_root: &Path,
    capability_smoke_passed: bool,
    target_profile_ready: bool,
    final_validation_ok: bool,
    capability_error: Option<&str>,
    validation_error: Option<&str>,
) -> String {
    let ok = capability_smoke_passed && target_profile_ready && final_validation_ok;
    let objective = [
        (
            "word_excel_text_semiauto_inputs",
            "Word, Excel, and plain text requests are accepted by the semiauto large-mod workflow.",
            capability_smoke_passed,
            "capability_smoke.smoke_passed",
        ),
        (
            "kxc_mdard_target_profile",
            "Target mod root is a real large-mod-shaped directory with all required content families.",
            target_profile_ready,
            "capability_smoke.target_profile_ready",
        ),
        (
            "real_game_strict_validation",
            "Generated smoke mod passes validate --strict-code-index against a real HOI4 game root.",
            final_validation_ok,
            "validation_strict_code_index.ok + strict_code_index",
        ),
    ]
    .into_iter()
    .map(|(id, requirement, passed, evidence)| {
        format!(
            "    {{\"id\": {}, \"requirement\": {}, \"ok\": {}, \"evidence\": {}}}",
            json_str(id),
            json_str(requirement),
            json_bool(passed),
            json_str(evidence)
        )
    })
    .collect::<Vec<_>>();
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_real_readiness_smoke.v1\",\n  \"status\": {},\n  \"ok\": {},\n  \"output_dir\": {},\n  \"target_mod_root\": {},\n  \"game_root\": {},\n  \"game_root_detected\": {},\n  \"generated_mod_root\": {},\n  \"capability_report\": {},\n  \"validation_report\": {},\n  \"capability_smoke_passed\": {},\n  \"target_profile_ready\": {},\n  \"final_validation_ok\": {},\n  \"capability_error\": {},\n  \"validation_error\": {},\n  \"objective_acceptance\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_str(if ok { "passed" } else { "failed" }),
        json_bool(ok),
        json_str(&output_dir.display().to_string()),
        json_str(&target_mod_root.display().to_string()),
        json_str(&game_root.display().to_string()),
        json_bool(game_root_detected),
        json_str(&generated_mod_root.display().to_string()),
        json_str(&capability_report.display().to_string()),
        json_str(&validation_report.display().to_string()),
        json_bool(capability_smoke_passed),
        json_bool(target_profile_ready),
        json_bool(final_validation_ok),
        json_optional_str(capability_error),
        json_optional_str(validation_error),
        objective.join(",\n"),
        json_array(&[
            "This command writes only temporary smoke output; it does not edit the target KXC/MDARD mod root.".to_string(),
            "Passing this smoke does not replace validating the final user-requested edit after real writers apply it.".to_string(),
            "If final_validation_ok is false, feed validation_report into validate-repair-context before any claim of readiness.".to_string(),
        ])
    )
}

fn large_mod_real_readiness_smoke_report_markdown(
    target_mod_root: &Path,
    game_root: &Path,
    capability_report: &Path,
    validation_report: &Path,
    capability_smoke_passed: bool,
    target_profile_ready: bool,
    final_validation_ok: bool,
    capability_error: Option<&str>,
    validation_error: Option<&str>,
) -> String {
    let ok = capability_smoke_passed && target_profile_ready && final_validation_ok;
    let mut out = String::new();
    out.push_str("# Real Mod Smoke\n\n");
    out.push_str(&format!(
        "- status: `{}`\n",
        if ok { "passed" } else { "failed" }
    ));
    out.push_str(&format!("- ok: `{}`\n", ok));
    out.push_str(&format!(
        "- target_mod_root: `{}`\n",
        target_mod_root.display()
    ));
    out.push_str(&format!("- game_root: `{}`\n", game_root.display()));
    out.push_str(&format!(
        "- capability_report: `{}`\n",
        capability_report.display()
    ));
    out.push_str(&format!(
        "- validation_report: `{}`\n",
        validation_report.display()
    ));
    out.push_str("\n## Checks\n\n");
    out.push_str(&format!(
        "- capability_smoke_passed: `{}`\n",
        capability_smoke_passed
    ));
    out.push_str(&format!(
        "- target_profile_ready: `{}`\n",
        target_profile_ready
    ));
    out.push_str(&format!(
        "- final_validation_ok: `{}`\n",
        final_validation_ok
    ));
    if let Some(error) = capability_error {
        out.push_str(&format!("- capability_error: `{}`\n", error));
    }
    if let Some(error) = validation_error {
        out.push_str(&format!("- validation_error: `{}`\n", error));
    }
    out.push_str("\n## Stop Conditions\n\n");
    out.push_str(
        "- This smoke writes only temporary output and does not edit the target mod root.\n",
    );
    out.push_str(
        "- Passing this smoke does not replace validating the final user-requested edit.\n",
    );
    out
}

