fn write_large_mod_country_dry_run_inputs(
    package: &WorkPackage,
    blueprint: &LargeModBlueprint,
    output_dir: &Path,
) -> Result<(), String> {
    let input_dir = output_dir.join("inputs");
    fs::create_dir_all(&input_dir).map_err(|e| format!("create {}: {e}", input_dir.display()))?;
    let tag = package_tag(package).unwrap_or_else(|| "TAG".to_string());
    let token = package_token(package);
    let prefix = format!("{}_{}", tag.to_ascii_lowercase(), token);
    let namespace = package_namespace(package, blueprint);
    let focus_id = format!("{prefix}_opening_congress");
    let split_id = format!("{prefix}_route_split");
    let reform_id = format!("{prefix}_confiscate_capital");
    let idea_id = format!("{prefix}_capitalist_resistance_idea");
    let old_idea_id = format!("{prefix}_party_unity_idea");
    let new_idea_id = format!("{prefix}_party_split_idea");
    let dynamic_id = format!("{prefix}_made_in_country");
    let decision_category = format!("{prefix}_reform_category");
    let decision_id = format!("{prefix}_confiscate_assets");

    fs::write(
        input_dir.join("focus_layout.txt"),
        format!(
            "# hoi4skill.work_package_input.focus_layout.v1\n# dry_run: complete country package sample\n开局党政会议 | id = {focus_id} | x = 0 | y = 0 | 奖励 = 政治点数 +50\n路线分歧 | id = {split_id} | x = -1 | y = 1 | 前置 = {focus_id} | 奖励 = 稳定度 +5%\n没收资本家 | id = {reform_id} | x = 1 | y = 1 | 前置 = {focus_id} | 奖励 = 政治点数 -25\n"
        ),
    )
    .map_err(|e| format!("write focus_layout.txt: {e}"))?;
    fs::write(
        input_dir.join("event_cards.txt"),
        format!(
            "# hoi4skill.work_package_input.event_cards.v1\n# dry_run: event chain with localisation and natural-language effects\n事件键：opening_congress\n事件ID或命名空间：{namespace}\n事件：开局党政会议\n类型：country_event\n标题：开局党政会议\n描述：各派代表已经抵达首都，围绕国家路线、产业政策与群众动员的争论终于摆上桌面。\n选项A：维持暂时妥协\n效果A：政治点数 +25\n后续事件A：capital_confiscation\n延迟A：1\n选项B：推动彻底改革\n效果B：稳定度 +3%\n后续事件B：reform_proclaimed\n延迟B：1\n\n事件键：capital_confiscation\n事件：没收资本家的余波\n类型：country_event\n标题：没收资本家的余波\n描述：旧有资本网络开始用停工、外逃与舆论反击新政，政府必须在秩序与改革之间作出选择。\n选项A：继续没收\n效果A：政治点数 -25\n\n事件键：reform_proclaimed\n事件：改革路线公布\n类型：news_event\n标题：改革路线公布\n描述：【红色：【本国国旗】【本国领导人】】宣布国家改革路线已经进入公开执行阶段。\n选项A：世界将会注视\n效果A：战争支持度 +3%\n"
        ),
    )
    .map_err(|e| format!("write event_cards.txt: {e}"))?;
    fs::write(
        input_dir.join("feature_cards.txt"),
        format!(
            "# hoi4skill.work_package_input.feature_cards.v1\n# dry_run: decisions and national spirits\n决议组：改革整顿\nID：{decision_category}\n描述：围绕改革路线的行政与社会斗争需要持续处理。\n\n决议：没收资本家\nID：{decision_id}\n描述：旧资本集团仍在转移资产，国家必须在他们恢复组织能力之前行动。\n花费：50\n效果：稳定度 -2%\n\n民族精神：资本家的反抗\nID：{idea_id}\n描述：被触动利益的资本网络正在以停工、逃资与地方关系进行反扑，改革的每一步都需要付出额外政治代价。\n\n民族精神：中国共产党的团结\nID：{old_idea_id}\n描述：党内各派暂时服从中央路线，使国家机器获得了重新整合的余地。\n\n民族精神：中国共产党的分裂\nID：{new_idea_id}\n描述：路线冲突撕开了组织纪律的表层，干部系统不再能以同一种语言解释国家未来。\n"
        ),
    )
    .map_err(|e| format!("write feature_cards.txt: {e}"))?;
    fs::write(
        input_dir.join("intent.txt"),
        format!(
            "# hoi4skill.work_package_input.intent.v1\n# dry_run: natural-language intent compiled by Rust writers\n国策：没收资本家 效果：增加民族精神：资本家的反抗，稳定度 -10%\n逆转改革开放国策 效果：民族精神：中国共产党的团结 替换为 中国共产党的分裂，稳定度 -50%，政治点数 -1\n事件：开局党政会议 效果：政治点 +25\n决议：没收资本家 效果：稳定度 -2%\n动态修正：中国制造 建造速度 +10%，生产效率上限 +0.05\n"
        ),
    )
    .map_err(|e| format!("write intent.txt: {e}"))?;
    fs::write(
        input_dir.join("dynamic_modifier_intent.txt"),
        format!(
            "# hoi4skill.work_package_input.dynamic_modifier_intent.v1\n# dry_run: dynamic modifier protocol, not a national spirit\n{dynamic_id} 的效果 建造速度 +10%\n生产效率上限 +0.05\n调用协议：custom_effect_tooltip = {dynamic_id}_tt；set_temp_variable = {{ temp_{dynamic_id} = 0.10 }}；change_{dynamic_id} = yes\n"
        ),
    )
    .map_err(|e| format!("write dynamic_modifier_intent.txt: {e}"))?;
    fs::write(
        input_dir.join("localisation_placeholders.txt"),
        format!(
            "# hoi4skill.work_package_input.localisation_placeholders.v1\n# dry_run: icons, flags, leaders, cosmetic aliases, and colour tokens must be resolved or asked about\n# Add user-specific icon/cosmetic placeholders here; unresolved placeholders block execution and must be answered.\n【红色：【本国国旗】【本国领导人】】宣布【本国国旗】国家改革路线今天正式开始。\n"
        ),
    )
    .map_err(|e| format!("write localisation_placeholders.txt: {e}"))?;
    Ok(())
}

fn large_mod_country_dry_run_json(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    mod_root: &Path,
    output_dir: &Path,
    capability_path: &Path,
    game_root: Option<&str>,
    style_mods: &[String],
) -> String {
    let input_dir = output_dir.join("inputs");
    let input_files = [
        "style_context.md",
        "focus_layout.txt",
        "event_cards.txt",
        "feature_cards.txt",
        "intent.txt",
        "dynamic_modifier_intent.txt",
        "localisation_placeholders.txt",
        "translated_l_simp_chinese.yml",
    ]
    .iter()
    .map(|name| {
        let path = input_dir.join(name);
        format!(
            "{{\"name\": {}, \"path\": {}, \"exists\": {}}}",
            json_str(name),
            json_str(&path.display().to_string()),
            json_bool(path.exists())
        )
    })
    .collect::<Vec<_>>()
    .join(", ");
    let root = mod_root.display().to_string();
    let next_commands = vec![
        format!(
            "hoi4skill large-mod-capability-audit --mod-root {root} --package {} --output .hoi4skill/capability_{}.json",
            package.id, package.id
        ),
        format!(
            "hoi4skill large-mod-content-audit --mod-root {root} --package {} --output .hoi4skill/content_{}.json",
            package.id, package.id
        ),
        format!(
            "hoi4skill run-work-package --mod-root {root} --package {} --execute --game-root <HOI4 root> --output-dir {} --allow-failure",
            package.id,
            output_dir.display()
        ),
        format!(
            "hoi4skill apply-work-package-repair --repair-bundle {root}/.hoi4skill/repair_bundle_{} --input <ai_repair_inputs.md> --execute --game-root <HOI4 root>",
            package.id
        ),
        format!("hoi4skill large-mod-playtest-gate --mod-root {root} --output .hoi4skill/playtest_gate.json"),
        format!("hoi4skill large-mod-release-gate --mod-root {root} --output .hoi4skill/release_gate.json"),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_country_dry_run.v1\",\n  \"status\": \"sample_ready\",\n  \"dry_run\": true,\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"package\": {},\n  \"kind\": {},\n  \"output_dir\": {},\n  \"run_manifest\": {},\n  \"capability_audit\": {},\n  \"game_root\": {},\n  \"style_mods\": {},\n  \"content_lanes\": {},\n  \"input_files\": [{}],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&root),
        json_str(&package.id),
        json_str(&package.kind),
        json_str(&output_dir.display().to_string()),
        json_str(&output_dir.join("run.json").display().to_string()),
        json_str(&capability_path.display().to_string()),
        json_optional_str(game_root),
        json_array(style_mods),
        json_array(
            &large_mod_capability_requirements()
                .iter()
                .map(|requirement| requirement.id.to_string())
                .collect::<Vec<_>>()
        ),
        input_files,
        json_array(&next_commands),
        json_array(&large_mod_country_dry_run_stop_conditions()),
    )
}

fn large_mod_country_dry_run_stop_conditions() -> Vec<String> {
    vec![
        "This dry-run writes work-package inputs and manifests only; final Clausewitz must still be emitted by Rust writers with --final-check.".to_string(),
        "Do not claim production readiness until large-mod-capability-audit, run-work-package --execute, validation, playtest, and release gates pass.".to_string(),
        "If placeholder, tag, icon, effect, trigger, dynamic modifier, or event picture evidence is missing, ask for evidence instead of inventing final code.".to_string(),
    ]
}

fn large_mod_sample_acceptance_json(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    mod_root: &Path,
    output_dir: &Path,
    dry_run_path: &Path,
    execution_report: &Path,
    content_audit_path: &Path,
    execution_status: &str,
    content_ready: bool,
    six_content_families_ok: bool,
    content_family_matrix: &str,
    executed: bool,
    check_written: bool,
    execution_error: Option<&str>,
    game_root: Option<&str>,
) -> String {
    let accepted = ((executed && execution_status == "ok") || check_written)
        && content_ready
        && six_content_families_ok;
    let status = if accepted {
        if check_written && !executed {
            "written_content_accepted"
        } else {
            "accepted"
        }
    } else if check_written {
        "needs_content"
    } else if !executed {
        "sample_inputs_ready"
    } else if execution_status != "ok" {
        "needs_repair"
    } else {
        "needs_content"
    };
    let root = mod_root.display().to_string();
    let next_commands = vec![
        format!(
            "hoi4skill run-work-package --mod-root {root} --package {} --execute --game-root <HOI4 root> --output-dir {} --allow-failure",
            package.id,
            output_dir.display()
        ),
        format!(
            "hoi4skill large-mod-ai-output-insurance --mod-root {root} --package {} --input <failed_output.md> --game-root <HOI4 root> --output .hoi4skill/ai_output_insurance_{}.json --markdown-output .hoi4skill/ai_output_insurance_{}.md",
            package.id,
            package.id,
            package.id
        ),
        format!(
            "hoi4skill large-mod-content-audit --mod-root {root} --package {} --output .hoi4skill/content_{}.json",
            package.id, package.id
        ),
        format!(
            "hoi4skill validate {root} --game-root <HOI4 root> --strict-code-index --output .hoi4skill/validation.json"
        ),
        format!(
            "hoi4skill large-mod-repair-cycle --mod-root {root} --output .hoi4skill/repair_cycle.json"
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_sample_acceptance.v1\",\n  \"status\": {},\n  \"accepted\": {},\n  \"executed\": {},\n  \"check_written\": {},\n  \"execution_status\": {},\n  \"content_ready\": {},\n  \"six_content_families_ok\": {},\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"game_root\": {},\n  \"package\": {},\n  \"kind\": {},\n  \"output_dir\": {},\n  \"dry_run\": {},\n  \"execution_report\": {},\n  \"content_audit\": {},\n  \"execution_error\": {},\n  \"required_content_families\": {},\n  \"content_family_matrix\": [\n{}\n  ],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(accepted),
        json_bool(executed),
        json_bool(check_written),
        json_str(execution_status),
        json_bool(content_ready),
        json_bool(six_content_families_ok),
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&root),
        json_optional_str(game_root),
        json_str(&package.id),
        json_str(&package.kind),
        json_str(&output_dir.display().to_string()),
        json_str(&dry_run_path.display().to_string()),
        json_str(&execution_report.display().to_string()),
        json_str(&content_audit_path.display().to_string()),
        json_optional_str(execution_error),
        json_array(&large_mod_content_family_ids()),
        content_family_matrix,
        json_array(&next_commands),
        json_array(&large_mod_sample_acceptance_stop_conditions()),
    )
}

fn large_mod_sample_content_families_ok(content_audit_text: &str) -> bool {
    large_mod_content_family_ids().iter().all(|required| {
        large_mod_sample_content_family_status(content_audit_text, required)
            .map(|status| status.ok)
            .unwrap_or(false)
    })
}

fn large_mod_sample_content_family_matrix_json(content_audit_text: &str) -> String {
    let required = large_mod_content_family_ids();
    required
        .iter()
        .map(|family| {
            let status = large_mod_sample_content_family_status(content_audit_text, family)
                .unwrap_or_else(|| LargeModSampleContentFamilyStatus {
                    ok: false,
                    count: 0,
                    blocker: format!("missing_{family}_content"),
                });
            format!(
                "    {{\"id\": {}, \"ok\": {}, \"count\": {}, \"blocker\": {}}}",
                json_str(family),
                json_bool(status.ok),
                status.count,
                json_str(&status.blocker)
            )
        })
        .collect::<Vec<_>>()
        .join(",\n")
}

struct LargeModSampleContentFamilyStatus {
    ok: bool,
    count: i64,
    blocker: String,
}

fn large_mod_sample_content_family_status(
    content_audit_text: &str,
    family: &str,
) -> Option<LargeModSampleContentFamilyStatus> {
    let object = large_mod_content_family_object(content_audit_text, family)?;
    let ok = status_json_bool_field_has_value(&object, "ok", true);
    let count = status_json_i64_field(&object, "count").unwrap_or(0);
    let blocker = if ok {
        "none".to_string()
    } else {
        status_json_string_array_values(&object, "blockers")
            .into_iter()
            .next()
            .unwrap_or_else(|| format!("missing_{family}_content"))
    };
    Some(LargeModSampleContentFamilyStatus { ok, count, blocker })
}

fn large_mod_content_family_object(content_audit_text: &str, family: &str) -> Option<String> {
    let marker = format!("\"id\": {}", json_str(family));
    let marker_idx = content_audit_text.find(&marker)?;
    let object_start = content_audit_text[..marker_idx].rfind('{')?;
    let object_end = large_mod_json_object_end(content_audit_text, object_start)?;
    Some(content_audit_text[object_start..object_end].to_string())
}

fn large_mod_json_object_end(text: &str, object_start: usize) -> Option<usize> {
    let bytes = text.as_bytes();
    if bytes.get(object_start) != Some(&b'{') {
        return None;
    }
    let mut depth = 0usize;
    let mut in_string = false;
    let mut escaped = false;
    for (idx, ch) in text[object_start..].char_indices() {
        let absolute = object_start + idx;
        if in_string {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
            continue;
        }
        match ch {
            '"' => in_string = true,
            '{' => depth += 1,
            '}' => {
                depth = depth.checked_sub(1)?;
                if depth == 0 {
                    return Some(absolute + ch.len_utf8());
                }
            }
            _ => {}
        }
    }
    None
}

fn large_mod_sample_acceptance_stop_conditions() -> Vec<String> {
    vec![
        "accepted requires --execute, an ok execution_report, and content_ready=true for all six required content families.".to_string(),
        "sample_inputs_ready is not production readiness; run the writer chain with --game-root and strict final checks.".to_string(),
        "If execution fails, use ai-output-insurance, input repair prompts, and repair-cycle before rerunning the package.".to_string(),
        "After sample acceptance, still run strict-code-index validation, text alignment, playtest gate, and release gate before claiming a large mod milestone.".to_string(),
    ]
}

