fn large_mod_batch_acceptance_json(
    blueprint: &LargeModBlueprint,
    blueprint_path: &Path,
    mod_root: &Path,
    game_root: Option<&str>,
    executed: bool,
    check_written: bool,
    status: &str,
    selected_count: usize,
    accepted_count: usize,
    content_ready_count: usize,
    six_content_families_ok_count: usize,
    execution_ok_count: usize,
    needs_repair_count: usize,
    execution_error_count: usize,
    items: &[String],
) -> String {
    let root = mod_root.display().to_string();
    let accepted = (executed || check_written)
        && selected_count > 0
        && accepted_count == selected_count
        && content_ready_count == selected_count
        && six_content_families_ok_count == selected_count
        && (check_written || execution_ok_count == selected_count)
        && needs_repair_count == 0
        && execution_error_count == 0;
    let next_commands = if accepted {
        vec![
            format!("hoi4skill large-mod-content-audit --mod-root {root} --output .hoi4skill/content_audit.json"),
            format!("hoi4skill validate {root} --game-root <HOI4 root> --strict-code-index --output .hoi4skill/validation.json"),
            format!("hoi4skill large-mod-playtest-gate --mod-root {root} --output .hoi4skill/playtest_gate.json"),
            format!("hoi4skill large-mod-release-gate --mod-root {root} --output .hoi4skill/release_gate.json"),
        ]
    } else if executed {
        vec![
            format!("hoi4skill large-mod-repair-cycle --mod-root {root} --output .hoi4skill/repair_cycle.json"),
            format!("hoi4skill large-mod-input-repair-queue --mod-root {root} --output .hoi4skill/input_repair_queue.json"),
            format!("hoi4skill large-mod-batch-acceptance --mod-root {root} --execute --game-root <HOI4 root> --require-accepted --output .hoi4skill/batch_acceptance.json"),
        ]
    } else {
        vec![format!(
            "hoi4skill large-mod-batch-acceptance --mod-root {root} --execute --game-root <HOI4 root> --require-accepted --output .hoi4skill/batch_acceptance.json"
        )]
    };
    format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_batch_acceptance.v1\",\n  \"status\": {},\n  \"accepted\": {},\n  \"executed\": {},\n  \"check_written\": {},\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"blueprint\": {},\n  \"game_root\": {},\n  \"selected_package_count\": {},\n  \"accepted_count\": {},\n  \"content_ready_count\": {},\n  \"six_content_families_ok_count\": {},\n  \"execution_ok_count\": {},\n  \"needs_repair_count\": {},\n  \"execution_error_count\": {},\n  \"required_content_families\": {},\n  \"packages\": [\n{}\n  ],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_bool(accepted),
        json_bool(executed),
        json_bool(check_written),
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&root),
        json_str(&blueprint_path.display().to_string()),
        json_optional_str(game_root),
        selected_count,
        accepted_count,
        content_ready_count,
        six_content_families_ok_count,
        execution_ok_count,
        needs_repair_count,
        execution_error_count,
        json_array(&large_mod_content_family_ids()),
        items.join(",\n"),
        json_array(&next_commands),
        json_array(&large_mod_batch_acceptance_stop_conditions()),
    )
}

fn large_mod_batch_acceptance_stop_conditions() -> Vec<String> {
    vec![
        "accepted=true requires every selected country package to have accepted=true from sample acceptance.".to_string(),
        "Batch acceptance proves package writer coverage; it does not replace final strict-code-index validation, playtest gate, or release gate.".to_string(),
        "If any package needs repair, use repair-cycle and input-repair-queue before rerunning batch acceptance.".to_string(),
    ]
}

fn large_mod_run_summary_json(
    blueprint: &LargeModBlueprint,
    packages: &[WorkPackage],
    blueprint_path: &Path,
    mod_root: &Path,
) -> Result<String, String> {
    let run_reports = collect_large_mod_run_summary_reports(mod_root)?;
    let mut ready_count = 0usize;
    let mut blocked_count = 0usize;
    let mut executed_count = 0usize;
    let mut failed_count = 0usize;
    let mut repair_count = 0usize;
    let mut needs_playtest_count = 0usize;
    let mut playtest_ok_count = 0usize;
    let package_json = packages
        .iter()
        .map(|package| {
            let start_state = work_package_start_state(package, packages, Some(mod_root));
            if start_state.blocked_by.is_empty() {
                ready_count += 1;
            } else {
                blocked_count += 1;
            }
            let run_dir = mod_root
                .join(".hoi4skill")
                .join("work_package_runs")
                .join(&package.id);
            let execution_path = run_dir.join("execution_report.json");
            let (execution_status, execution_error) = if execution_path.exists() {
                let text = read_utf8_lossy(&execution_path)?;
                let status = status_json_string_field(&text, "status")
                    .unwrap_or_else(|| "unknown".to_string());
                if status == "ok" {
                    executed_count += 1;
                } else if status == "failed" {
                    failed_count += 1;
                }
                (status, status_json_string_field(&text, "error"))
            } else {
                ("missing".to_string(), None)
            };
            let repair_bundle = mod_root
                .join(".hoi4skill")
                .join(format!("repair_bundle_{}", package.id))
                .join("repair_bundle.json");
            let input_repair_prompt = repair_bundle
                .parent()
                .map(|dir| dir.join("input_repair_prompt.md"))
                .unwrap_or_else(|| {
                    mod_root
                        .join(".hoi4skill")
                        .join(format!("repair_bundle_{}", package.id))
                        .join("input_repair_prompt.md")
                });
            let repair_status = if repair_bundle.exists() {
                repair_count += 1;
                read_work_package_report_status(&repair_bundle)
                    .map(|report| report.status)
                    .unwrap_or_else(|_| "needs_review".to_string())
            } else {
                "missing".to_string()
            };
            let playtest_path = mod_root
                .join(".hoi4skill")
                .join(format!("playtest_{}.json", package.id));
            let playtest_status = if playtest_path.exists() {
                let status = read_work_package_report_status(&playtest_path)
                    .map(|report| report.status)
                    .unwrap_or_else(|_| "needs_review".to_string());
                if status == "needs_review" {
                    needs_playtest_count += 1;
                } else {
                    playtest_ok_count += 1;
                }
                status
            } else {
                "missing".to_string()
            };
            let next_commands = large_mod_run_summary_package_commands(
                package,
                mod_root,
                &start_state,
                &execution_status,
                &repair_status,
                &playtest_status,
            );
            let repair_apply_command = if repair_bundle.exists() || execution_status == "failed" {
                Some(format!(
                    "hoi4skill apply-work-package-repair --repair-bundle {} --input <ai_repair_inputs.md> --execute --game-root <HOI4 root>",
                    repair_bundle.display()
                ))
            } else {
                None
            };
            Ok(format!(
                "    {{\"id\": {}, \"kind\": {}, \"title\": {}, \"start_state\": {}, \"blocked_by\": {}, \"execution_report\": {}, \"execution_status\": {}, \"execution_error\": {}, \"repair_bundle\": {}, \"repair_status\": {}, \"input_repair_prompt\": {}, \"repair_apply_command\": {}, \"playtest_report\": {}, \"playtest_status\": {}, \"next_commands\": {}}}",
                json_str(&package.id),
                json_str(&package.kind),
                json_str(&package.title),
                json_str(&start_state.state),
                json_array(&start_state.blocked_by),
                json_str(&execution_path.display().to_string()),
                json_str(&execution_status),
                json_optional_str(execution_error.as_deref()),
                json_str(&repair_bundle.display().to_string()),
                json_str(&repair_status),
                json_str(&input_repair_prompt.display().to_string()),
                json_optional_str(repair_apply_command.as_deref()),
                json_str(&playtest_path.display().to_string()),
                json_str(&playtest_status),
                json_array(&next_commands),
            ))
        })
        .collect::<Result<Vec<_>, String>>()?
        .join(",\n");
    let report_json = run_reports
        .iter()
        .map(|path| {
            let status = read_work_package_report_status(path)
                .map(|report| report.status)
                .unwrap_or_else(|_| "needs_review".to_string());
            format!(
                "    {{\"path\": {}, \"status\": {}}}",
                json_str(&path.display().to_string()),
                json_str(&status)
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    let status = if failed_count > 0 || repair_count > 0 || needs_playtest_count > 0 {
        "needs_review"
    } else if blocked_count > 0 {
        "blocked"
    } else {
        "ok"
    };
    let package_count = packages.len();
    let ready_percent = percentage(ready_count, package_count);
    let executed_percent = percentage(executed_count, package_count);
    let repair_clear_count = package_count.saturating_sub(failed_count + repair_count);
    let repair_clear_percent = percentage(repair_clear_count, package_count);
    let playtest_percent = percentage(playtest_ok_count, package_count);
    let overall_progress_percent =
        (ready_percent + executed_percent + repair_clear_percent + playtest_percent) / 4;
    let next_commands = vec![
        format!(
            "hoi4skill run-work-packages --mod-root {} --ready-only --max-packages 4 --output .hoi4skill/run_queue.json",
            mod_root.display()
        ),
        format!(
            "hoi4skill large-mod-fix-queue --mod-root {} --output .hoi4skill/fix_queue.json",
            mod_root.display()
        ),
        format!(
            "hoi4skill large-mod-repair-cycle --mod-root {} --output .hoi4skill/repair_cycle.json",
            mod_root.display()
        ),
        format!(
            "hoi4skill large-mod-playtest-gate --mod-root {} --output .hoi4skill/playtest_gate.json",
            mod_root.display()
        ),
        format!(
            "hoi4skill large-mod-release-gate --mod-root {} --output .hoi4skill/release_gate.json",
            mod_root.display()
        ),
    ];
    Ok(format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_run_summary.v1\",\n  \"status\": {},\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"blueprint\": {},\n  \"package_count\": {},\n  \"ready_count\": {},\n  \"blocked_count\": {},\n  \"executed_count\": {},\n  \"failed_count\": {},\n  \"repair_bundle_count\": {},\n  \"needs_playtest_count\": {},\n  \"ready_percent\": {},\n  \"executed_percent\": {},\n  \"repair_clear_percent\": {},\n  \"playtest_percent\": {},\n  \"overall_progress_percent\": {},\n  \"reports\": [\n{}\n  ],\n  \"packages\": [\n{}\n  ],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&mod_root.display().to_string()),
        json_str(&blueprint_path.display().to_string()),
        packages.len(),
        ready_count,
        blocked_count,
        executed_count,
        failed_count,
        repair_count,
        needs_playtest_count,
        ready_percent,
        executed_percent,
        repair_clear_percent,
        playtest_percent,
        overall_progress_percent,
        report_json,
        package_json,
        json_array(&next_commands),
        json_array(&large_mod_run_summary_stop_conditions()),
    ))
}

fn collect_large_mod_run_summary_reports(mod_root: &Path) -> Result<Vec<PathBuf>, String> {
    let mut paths = Vec::new();
    let hoi4skill_dir = mod_root.join(".hoi4skill");
    if !hoi4skill_dir.is_dir() {
        return Ok(paths);
    }
    for entry in fs::read_dir(&hoi4skill_dir)
        .map_err(|e| format!("read {}: {e}", hoi4skill_dir.display()))?
    {
        let entry = entry.map_err(|e| format!("read {}: {e}", hoi4skill_dir.display()))?;
        let path = entry.path();
        let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
            continue;
        };
        if path.is_file()
            && path.extension().and_then(|ext| ext.to_str()) == Some("json")
            && (name.starts_with("run_queue")
                || name == "playtest_gate.json"
                || name == "release_gate.json"
                || name == "fix_queue.json"
                || name == "repair_cycle.json")
        {
            paths.push(path);
        } else if path.is_dir() && name == "work_package_runs" {
            for package_entry in
                fs::read_dir(&path).map_err(|e| format!("read {}: {e}", path.display()))?
            {
                let package_entry =
                    package_entry.map_err(|e| format!("read {}: {e}", path.display()))?;
                let report = package_entry.path().join("execution_report.json");
                if report.exists() {
                    paths.push(report);
                }
            }
        } else if path.is_dir() && name.starts_with("repair_bundle") {
            let report = path.join("repair_bundle.json");
            if report.exists() {
                paths.push(report);
            }
        }
    }
    paths.sort();
    paths.dedup();
    Ok(paths)
}

fn large_mod_input_repair_queue_json(
    blueprint: &LargeModBlueprint,
    packages: &[WorkPackage],
    blueprint_path: &Path,
    mod_root: &Path,
) -> Result<String, String> {
    let mut item_count = 0usize;
    let mut prompt_ready_count = 0usize;
    let mut missing_prompt_count = 0usize;
    let mut bundle_missing_count = 0usize;
    let mut retrieval_blocked_count = 0usize;
    let mut answers_recorded_count = 0usize;
    let mut context_verified_count = 0usize;
    let mut context_pending_count = 0usize;
    let verification_report = mod_root
        .join(".hoi4skill")
        .join("context_evidence_verification.json");
    let verification_text = read_utf8_lossy(&verification_report).ok();
    let mut entries = Vec::new();
    for package in packages {
        let run_dir = mod_root
            .join(".hoi4skill")
            .join("work_package_runs")
            .join(&package.id);
        let execution_report = run_dir.join("execution_report.json");
        let execution_status = if execution_report.exists() {
            let text = read_utf8_lossy(&execution_report)?;
            status_json_string_field(&text, "status").unwrap_or_else(|| "unknown".to_string())
        } else {
            "missing".to_string()
        };
        let repair_dir = mod_root
            .join(".hoi4skill")
            .join(format!("repair_bundle_{}", package.id));
        let repair_bundle = repair_dir.join("repair_bundle.json");
        if !repair_bundle.exists() && execution_status != "failed" {
            continue;
        }
        item_count += 1;
        if !repair_bundle.exists() {
            bundle_missing_count += 1;
        }
        let input_repair_prompt = repair_dir.join("input_repair_prompt.md");
        let prompt_exists = input_repair_prompt.exists();
        if prompt_exists {
            prompt_ready_count += 1;
        } else {
            missing_prompt_count += 1;
        }
        let repair_status = if repair_bundle.exists() {
            read_work_package_report_status(&repair_bundle)
                .map(|report| report.status)
                .unwrap_or_else(|_| "needs_review".to_string())
        } else {
            "missing".to_string()
        };
        let retrieval_status = if repair_bundle.exists() {
            read_utf8_lossy(&repair_bundle)
                .ok()
                .and_then(|text| status_json_string_field(&text, "retrieval_status"))
                .unwrap_or_else(|| "unknown".to_string())
        } else {
            "missing".to_string()
        };
        let retrieval_blocked =
            repair_bundle.exists() && !matches!(retrieval_status.as_str(), "ok");
        if retrieval_blocked {
            retrieval_blocked_count += 1;
        }
        let answer_file = mod_root
            .join(".hoi4skill")
            .join(format!("context_evidence_answers_{}.md", package.id));
        let answers_recorded = answer_file.exists();
        let context_verified = retrieval_blocked
            && verification_text.as_deref().is_some_and(|text| {
                context_evidence_package_verified_current(text, &package.id, &answer_file)
            });
        let context_verification_fresh = retrieval_blocked
            && verification_text.as_deref().is_some_and(|text| {
                context_evidence_package_fingerprint_matches(text, &package.id, &answer_file)
            });
        if retrieval_blocked {
            if context_verified {
                context_verified_count += 1;
            } else {
                context_pending_count += 1;
                if answers_recorded {
                    answers_recorded_count += 1;
                }
            }
        }
        let evidence_questions = if retrieval_blocked && !context_verified {
            large_mod_repair_context_evidence_questions(
                package,
                &repair_dir,
                &run_dir,
                &retrieval_status,
            )
        } else {
            Vec::new()
        };
        let retrieved_code_context = repair_dir.join("retrieved_code_context.md");
        let apply_command = format!(
            "hoi4skill apply-work-package-repair --repair-bundle {} --input <ai_repair_inputs.md> --execute --game-root <HOI4 root>",
            repair_bundle.display()
        );
        let prompt_command = format!(
            "feed {} to the AI and save its fenced-block-only response as ai_repair_inputs_{}.md",
            input_repair_prompt.display(),
            package.id
        );
        entries.push(format!(
            "    {{\"package\": {}, \"title\": {}, \"execution_report\": {}, \"execution_status\": {}, \"repair_bundle\": {}, \"repair_status\": {}, \"repair_bundle_exists\": {}, \"retrieval_status\": {}, \"retrieval_blocked\": {}, \"context_verified\": {}, \"context_verification_fresh\": {}, \"answers_recorded\": {}, \"answer_file\": {}, \"verification_report\": {}, \"evidence_questions\": {}, \"input_repair_prompt\": {}, \"input_repair_prompt_exists\": {}, \"retrieved_code_context\": {}, \"apply_command\": {}, \"prompt_command\": {}, \"allowed_response_schema\": {}}}",
            json_str(&package.id),
            json_str(&package.title),
            json_str(&execution_report.display().to_string()),
            json_str(&execution_status),
            json_str(&repair_bundle.display().to_string()),
            json_str(&repair_status),
            json_bool(repair_bundle.exists()),
            json_str(&retrieval_status),
            json_bool(retrieval_blocked),
            json_bool(context_verified),
            json_bool(context_verification_fresh),
            json_bool(answers_recorded),
            json_str(&answer_file.display().to_string()),
            json_str(&verification_report.display().to_string()),
            json_array(&evidence_questions),
            json_str(&input_repair_prompt.display().to_string()),
            json_bool(prompt_exists),
            json_str(&retrieved_code_context.display().to_string()),
            json_str(&apply_command),
            json_str(&prompt_command),
            json_str("hoi4skill-input:<kind> fenced blocks only")
        ));
    }
    let status = if item_count == 0 {
        "ok"
    } else if missing_prompt_count > 0 || bundle_missing_count > 0 {
        "needs_repair_artifacts"
    } else if context_pending_count > 0 {
        if answers_recorded_count >= context_pending_count {
            "needs_context_verification"
        } else {
            "needs_context_evidence"
        }
    } else {
        "needs_input_repair"
    };
    let next_commands = if item_count == 0 {
        vec![format!(
            "hoi4skill run-work-packages --mod-root {} --ready-only --execute --game-root <HOI4 root> --max-packages 1",
            mod_root.display()
        )]
    } else {
        let mut commands = Vec::new();
        if context_pending_count > 0 {
            commands.push("Regenerate each blocked repair bundle with --game-root and dependency --mod-path evidence before asking the AI to repair inputs.".to_string());
            if answers_recorded_count < context_pending_count {
                commands.push("If retrieval_status remains no_matches, ask the user for the real symbol, icon, tag, dynamic-modifier helper, or source-mod reference instead of guessing.".to_string());
            } else {
                commands.push("Context evidence answers are recorded; regenerate repair bundles and rerun retrieval before asking the AI to repair inputs.".to_string());
            }
            commands.push(format!(
                "hoi4skill large-mod-context-evidence-verify --mod-root {} --game-root <HOI4 root> --output .hoi4skill/context_evidence_verification.json",
                mod_root.display()
            ));
            commands.push(format!(
                "hoi4skill large-mod-context-evidence-brief --mod-root {} --output .hoi4skill/context_evidence_brief.md",
                mod_root.display()
            ));
        }
        commands.extend([
            "For each item, feed input_repair_prompt to the AI and save fenced input blocks.".to_string(),
            "Run each apply_command; do not edit final HOI4 files by hand.".to_string(),
            format!(
                "hoi4skill large-mod-run-summary --mod-root {} --output .hoi4skill/run_summary.json",
                mod_root.display()
            ),
        ]);
        commands
    };
    Ok(format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_input_repair_queue.v1\",\n  \"status\": {},\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"blueprint\": {},\n  \"repair_item_count\": {},\n  \"prompt_ready_count\": {},\n  \"missing_prompt_count\": {},\n  \"missing_repair_bundle_count\": {},\n  \"retrieval_blocked_count\": {},\n  \"context_pending_count\": {},\n  \"context_verified_count\": {},\n  \"answers_recorded_count\": {},\n  \"context_evidence_verification\": {},\n  \"items\": [\n{}\n  ],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&mod_root.display().to_string()),
        json_str(&blueprint_path.display().to_string()),
        item_count,
        prompt_ready_count,
        missing_prompt_count,
        bundle_missing_count,
        retrieval_blocked_count,
        context_pending_count,
        context_verified_count,
        answers_recorded_count,
        json_str(&verification_report.display().to_string()),
        entries.join(",\n"),
        json_array(&next_commands),
        json_array(&large_mod_input_repair_queue_stop_conditions()),
    ))
}

fn large_mod_input_repair_queue_stop_conditions() -> Vec<String> {
    vec![
        "Do not feed final HOI4 files or diffs back as repair output; only accept hoi4skill-input fenced blocks.".to_string(),
        "Do not apply a repair item whose input_repair_prompt_exists is false; rerun the failed package to regenerate the repair bundle first.".to_string(),
        "Do not ask the AI to repair from a bundle whose retrieval_status is missing_game_root, unavailable, no_matches, or unknown; gather local evidence first.".to_string(),
        "Do not treat context evidence answers as verified until retrieval is regenerated and strict validation passes.".to_string(),
        "Do not mark a package repaired until apply-work-package-repair reruns the writer and the package leaves failed_repair_ready status.".to_string(),
    ]
}

fn large_mod_repair_cycle_json(
    blueprint: &LargeModBlueprint,
    packages: &[WorkPackage],
    blueprint_path: &Path,
    mod_root: &Path,
    run_summary_path: &Path,
    repair_queue_path: &Path,
    run_summary: &str,
    repair_queue: &str,
) -> Result<String, String> {
    let run_status =
        status_json_string_field(run_summary, "status").unwrap_or_else(|| "unknown".to_string());
    let repair_status =
        status_json_string_field(repair_queue, "status").unwrap_or_else(|| "unknown".to_string());
    let mut context_count = 0usize;
    let mut ai_output_plan_count = 0usize;
    let mut ai_repair_count = 0usize;
    let mut apply_count = 0usize;
    let mut rerun_count = 0usize;
    let mut playtest_count = 0usize;
    let mut blocked_count = 0usize;
    let mut items = Vec::new();
    for package in packages {
        let item = large_mod_repair_cycle_item_json(
            package,
            packages,
            mod_root,
            &mut context_count,
            &mut ai_output_plan_count,
            &mut ai_repair_count,
            &mut apply_count,
            &mut rerun_count,
            &mut playtest_count,
            &mut blocked_count,
        )?;
        items.push(item);
    }
    let status = if context_count > 0 {
        "needs_context_evidence"
    } else if ai_output_plan_count > 0 {
        "needs_ai_output_repair_plan"
    } else if ai_repair_count > 0 {
        "needs_ai_input_repair"
    } else if apply_count > 0 {
        "needs_repair_apply"
    } else if rerun_count > 0 {
        "ready_to_rerun"
    } else if playtest_count > 0 {
        "needs_playtest_or_content_audit"
    } else if blocked_count > 0 {
        "blocked_by_dependencies"
    } else {
        "ready_for_next_batch"
    };
    let next_commands = large_mod_repair_cycle_next_commands(
        mod_root,
        status,
        context_count,
        ai_output_plan_count,
        ai_repair_count,
        apply_count,
        rerun_count,
        playtest_count,
    );
    Ok(format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_repair_cycle.v1\",\n  \"status\": {},\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"blueprint\": {},\n  \"run_summary\": {},\n  \"run_summary_status\": {},\n  \"input_repair_queue\": {},\n  \"input_repair_queue_status\": {},\n  \"package_count\": {},\n  \"needs_context_evidence_count\": {},\n  \"needs_ai_output_repair_plan_count\": {},\n  \"needs_ai_input_repair_count\": {},\n  \"needs_repair_apply_count\": {},\n  \"ready_to_rerun_count\": {},\n  \"needs_playtest_or_content_audit_count\": {},\n  \"blocked_by_dependencies_count\": {},\n  \"packages\": [\n{}\n  ],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&mod_root.display().to_string()),
        json_str(&blueprint_path.display().to_string()),
        json_str(&run_summary_path.display().to_string()),
        json_str(&run_status),
        json_str(&repair_queue_path.display().to_string()),
        json_str(&repair_status),
        packages.len(),
        context_count,
        ai_output_plan_count,
        ai_repair_count,
        apply_count,
        rerun_count,
        playtest_count,
        blocked_count,
        items.join(",\n"),
        json_array(&next_commands),
        json_array(&large_mod_repair_cycle_stop_conditions()),
    ))
}

fn large_mod_repair_cycle_item_json(
    package: &WorkPackage,
    packages: &[WorkPackage],
    mod_root: &Path,
    context_count: &mut usize,
    ai_output_plan_count: &mut usize,
    ai_repair_count: &mut usize,
    apply_count: &mut usize,
    rerun_count: &mut usize,
    playtest_count: &mut usize,
    blocked_count: &mut usize,
) -> Result<String, String> {
    let start_state = work_package_start_state(package, packages, Some(mod_root));
    let run_dir = mod_root
        .join(".hoi4skill")
        .join("work_package_runs")
        .join(&package.id);
    let execution_report = run_dir.join("execution_report.json");
    let execution_status = status_from_optional_report(&execution_report)?;
    let repair_dir = mod_root
        .join(".hoi4skill")
        .join(format!("repair_bundle_{}", package.id));
    let repair_bundle = repair_dir.join("repair_bundle.json");
    let repair_status = status_from_optional_report(&repair_bundle)?;
    let retrieval_status = if repair_bundle.exists() {
        read_utf8_lossy(&repair_bundle)
            .ok()
            .and_then(|text| status_json_string_field(&text, "retrieval_status"))
            .unwrap_or_else(|| "unknown".to_string())
    } else {
        "missing".to_string()
    };
    let input_repair_prompt = repair_dir.join("input_repair_prompt.md");
    let repair_apply = mod_root
        .join(".hoi4skill")
        .join(format!("repair_apply_{}.json", package.id));
    let repair_apply_status = status_from_optional_report(&repair_apply)?;
    let playtest_report = mod_root
        .join(".hoi4skill")
        .join(format!("playtest_{}.json", package.id));
    let playtest_status = status_from_optional_report(&playtest_report)?;
    let ai_insurance = large_mod_repair_cycle_ai_insurance(mod_root, &package.id)?;
    let (next_action, command) = if !start_state.blocked_by.is_empty()
        && execution_status == "missing"
    {
        *blocked_count += 1;
        (
            "wait_for_dependencies",
            format!(
                "hoi4skill work-package-readiness --mod-root {} --package {} --output .hoi4skill/readiness_{}.json",
                mod_root.display(),
                package.id,
                package.id
            ),
        )
    } else if repair_bundle.exists()
        && !matches!(retrieval_status.as_str(), "ok")
        && repair_apply_status != "ok"
    {
        *context_count += 1;
        (
            "gather_context_evidence",
            format!(
                "hoi4skill large-mod-context-evidence-brief --mod-root {} --output .hoi4skill/context_evidence_brief.md",
                mod_root.display()
            ),
        )
    } else if ai_insurance.blocking_count > 0
        && ai_insurance.retrieval_ok
        && repair_apply_status != "ok"
        && execution_status != "ok"
    {
        *ai_output_plan_count += 1;
        (
            "repair_ai_output_with_insurance_plan",
            format!(
                "feed {} and {} to AI, require hoi4skill-input fenced blocks, then run apply-work-package-repair",
                ai_insurance.json_path.display(),
                ai_insurance.markdown_path.display()
            ),
        )
    } else if repair_bundle.exists()
        && input_repair_prompt.exists()
        && repair_apply_status != "ok"
        && execution_status != "ok"
    {
        *ai_repair_count += 1;
        (
            "ask_ai_for_structured_input_repair",
            format!(
                "feed {} to AI, save fenced blocks, then run apply-work-package-repair",
                input_repair_prompt.display()
            ),
        )
    } else if repair_bundle.exists() && repair_apply_status != "ok" && execution_status != "ok" {
        *apply_count += 1;
        (
            "apply_existing_repair_inputs",
            format!(
                "hoi4skill apply-work-package-repair --repair-bundle {} --input <ai_repair_inputs.md> --execute --game-root <HOI4 root>",
                repair_bundle.display()
            ),
        )
    } else if repair_apply_status == "ok" && execution_status != "ok" {
        *rerun_count += 1;
        (
            "rerun_package_after_repair",
            format!(
                "hoi4skill run-work-package --mod-root {} --package {} --execute --game-root <HOI4 root>",
                mod_root.display(),
                package.id
            ),
        )
    } else if execution_status == "ok" && playtest_status != "ok" {
        *playtest_count += 1;
        (
            "playtest_and_content_audit",
            format!(
                "hoi4skill large-mod-content-audit --mod-root {} --package {} --output .hoi4skill/content_{}.json",
                mod_root.display(),
                package.id,
                package.id
            ),
        )
    } else {
        (
            "run_or_continue_package",
            format!(
                "hoi4skill run-work-package --mod-root {} --package {} --execute --game-root <HOI4 root>",
                mod_root.display(),
                package.id
            ),
        )
    };
    Ok(format!(
        "    {{\"package\": {}, \"kind\": {}, \"title\": {}, \"start_state\": {}, \"blocked_by\": {}, \"execution_status\": {}, \"repair_status\": {}, \"retrieval_status\": {}, \"input_repair_prompt_exists\": {}, \"repair_apply_status\": {}, \"playtest_status\": {}, \"ai_output_insurance\": {}, \"ai_output_insurance_exists\": {}, \"ai_output_insurance_status\": {}, \"ai_output_insurance_retrieval_ok\": {}, \"ai_output_insurance_blocking_count\": {}, \"ai_output_insurance_repair_plan_ids\": {}, \"next_action\": {}, \"command\": {}}}",
        json_str(&package.id),
        json_str(&package.kind),
        json_str(&package.title),
        json_str(&start_state.state),
        json_array(&start_state.blocked_by),
        json_str(&execution_status),
        json_str(&repair_status),
        json_str(&retrieval_status),
        json_bool(input_repair_prompt.exists()),
        json_str(&repair_apply_status),
        json_str(&playtest_status),
        json_str(&ai_insurance.json_path.display().to_string()),
        json_bool(ai_insurance.exists),
        json_str(&ai_insurance.status),
        json_bool(ai_insurance.retrieval_ok),
        ai_insurance.blocking_count,
        json_array(&ai_insurance.repair_plan_ids),
        json_str(next_action),
        json_str(&command),
    ))
}

struct LargeModRepairCycleAiInsurance {
    json_path: PathBuf,
    markdown_path: PathBuf,
    exists: bool,
    status: String,
    retrieval_ok: bool,
    blocking_count: usize,
    repair_plan_ids: Vec<String>,
}

fn large_mod_repair_cycle_ai_insurance(
    mod_root: &Path,
    package_id: &str,
) -> Result<LargeModRepairCycleAiInsurance, String> {
    let json_path = mod_root
        .join(".hoi4skill")
        .join(format!("ai_output_insurance_{package_id}.json"));
    let markdown_path = mod_root
        .join(".hoi4skill")
        .join(format!("ai_output_insurance_{package_id}.md"));
    if !json_path.exists() {
        return Ok(LargeModRepairCycleAiInsurance {
            json_path,
            markdown_path,
            exists: false,
            status: "missing".to_string(),
            retrieval_ok: false,
            blocking_count: 0,
            repair_plan_ids: Vec::new(),
        });
    }
    let text = read_utf8_lossy(&json_path)?;
    let status = status_json_string_field(&text, "status").unwrap_or_else(|| "unknown".to_string());
    let retrieval_ok = status_json_bool_field_has_value(&text, "retrieval_ok", true);
    let blocking_count = status_json_usize_field(&text, "blocking_count").unwrap_or(0);
    let repair_plan_ids = large_mod_ai_output_insurance_repair_plan_ids(&text);
    Ok(LargeModRepairCycleAiInsurance {
        json_path,
        markdown_path,
        exists: true,
        status,
        retrieval_ok,
        blocking_count,
        repair_plan_ids,
    })
}

fn large_mod_ai_output_insurance_repair_plan_ids(text: &str) -> Vec<String> {
    let known = [
        "direct_clausewitz_code",
        "dynamic_modifier_as_national_spirit",
        "suspicious_code_tokens",
        "localisation_placeholder_or_icon",
        "no_blocking_pattern_detected",
    ];
    let mut out = Vec::new();
    for id in status_json_string_field_values(text, "id") {
        if known.contains(&id.as_str()) && !out.iter().any(|existing| existing == &id) {
            out.push(id);
        }
    }
    out
}

fn status_from_optional_report(path: &Path) -> Result<String, String> {
    if !path.exists() {
        return Ok("missing".to_string());
    }
    read_work_package_report_status(path).map(|report| report.status)
}

fn top_status_from_optional_report(path: &Path) -> Result<String, String> {
    if !path.exists() {
        return Ok("missing".to_string());
    }
    let text = read_utf8_lossy(path)?;
    Ok(status_json_string_field(&text, "status").unwrap_or_else(|| "unknown".to_string()))
}

fn large_mod_repair_cycle_next_commands(
    mod_root: &Path,
    status: &str,
    context_count: usize,
    ai_output_plan_count: usize,
    ai_repair_count: usize,
    apply_count: usize,
    rerun_count: usize,
    playtest_count: usize,
) -> Vec<String> {
    let root = mod_root.display().to_string();
    let mut commands = Vec::new();
    match status {
        "needs_context_evidence" if context_count > 0 => {
            commands.push(format!("hoi4skill large-mod-context-evidence-brief --mod-root {root} --output .hoi4skill/context_evidence_brief.md"));
            commands.push(format!("hoi4skill large-mod-context-evidence-verify --mod-root {root} --game-root <HOI4 root> --output .hoi4skill/context_evidence_verification.json"));
        }
        "needs_ai_output_repair_plan" if ai_output_plan_count > 0 => {
            commands.push("Feed each ai_output_insurance_<package>.json/md repair_plan to the AI and require hoi4skill-input fenced blocks only.".to_string());
            commands.push(format!("hoi4skill large-mod-apply-repair-queue --mod-root {root} --input-dir <ai_repair_inputs_dir> --execute --game-root <HOI4 root> --allow-failure --output .hoi4skill/repair_queue_apply.json"));
        }
        "needs_ai_input_repair" if ai_repair_count > 0 => {
            commands.push("Feed each input_repair_prompt.md to the AI and require hoi4skill-input fenced blocks only.".to_string());
            commands.push(format!("hoi4skill large-mod-input-repair-queue --mod-root {root} --output .hoi4skill/input_repair_queue.json"));
        }
        "needs_repair_apply" if apply_count > 0 => {
            commands
                .push("Run each package apply_command from input_repair_queue.json.".to_string());
        }
        "ready_to_rerun" if rerun_count > 0 => {
            commands.push(format!("hoi4skill run-work-packages --mod-root {root} --ready-only --execute --game-root <HOI4 root> --max-packages 4 --allow-failure --output .hoi4skill/run_queue.json"));
        }
        "needs_playtest_or_content_audit" if playtest_count > 0 => {
            commands.push(format!("hoi4skill large-mod-content-audit --mod-root {root} --output .hoi4skill/content_audit.json"));
            commands.push(format!("hoi4skill large-mod-playtest-gate --mod-root {root} --output .hoi4skill/playtest_gate.json"));
        }
        _ => {
            commands.push(format!("hoi4skill run-work-packages --mod-root {root} --ready-only --execute --game-root <HOI4 root> --max-packages 4 --allow-failure --output .hoi4skill/run_queue.json"));
        }
    }
    commands.push(format!(
        "hoi4skill large-mod-repair-cycle --mod-root {root} --output .hoi4skill/repair_cycle.json"
    ));
    commands
}

fn large_mod_repair_cycle_stop_conditions() -> Vec<String> {
    vec![
        "Do not run the next package batch while any package needs context evidence or AI input repair.".to_string(),
        "Do not feed final HOI4 files back to the AI; repair cycle items require structured hoi4skill-input blocks only.".to_string(),
        "When ai_output_insurance has a repair_plan, do not bypass it with raw Clausewitz or guessed symbols; use the listed writer route and strict-code-index commands.".to_string(),
        "Do not rerun a repaired package until apply-work-package-repair has produced an ok repair_apply report.".to_string(),
        "After any ok execution, run content-audit, strict validation, and playtest gates before release.".to_string(),
    ]
}

fn large_mod_context_evidence_brief_markdown(
    blueprint: &LargeModBlueprint,
    packages: &[WorkPackage],
    blueprint_path: &Path,
    mod_root: &Path,
) -> Result<String, String> {
    let mut blocked = Vec::new();
    for package in packages {
        let repair_dir = mod_root
            .join(".hoi4skill")
            .join(format!("repair_bundle_{}", package.id));
        let repair_bundle = repair_dir.join("repair_bundle.json");
        let run_dir = mod_root
            .join(".hoi4skill")
            .join("work_package_runs")
            .join(&package.id);
        let execution_report = run_dir.join("execution_report.json");
        let execution_status = if execution_report.exists() {
            let text = read_utf8_lossy(&execution_report)?;
            status_json_string_field(&text, "status").unwrap_or_else(|| "unknown".to_string())
        } else {
            "missing".to_string()
        };
        if !repair_bundle.exists() && execution_status != "failed" {
            continue;
        }
        let retrieval_status = if repair_bundle.exists() {
            read_utf8_lossy(&repair_bundle)
                .ok()
                .and_then(|text| status_json_string_field(&text, "retrieval_status"))
                .unwrap_or_else(|| "unknown".to_string())
        } else {
            "missing".to_string()
        };
        if matches!(retrieval_status.as_str(), "ok") {
            continue;
        }
        let questions = large_mod_repair_context_evidence_questions(
            package,
            &repair_dir,
            &run_dir,
            &retrieval_status,
        );
        blocked.push((
            package.id.clone(),
            package.title.clone(),
            retrieval_status,
            repair_bundle,
            repair_dir.join("retrieved_code_context.md"),
            mod_root
                .join(".hoi4skill")
                .join(format!("context_evidence_answers_{}.md", package.id)),
            questions,
        ));
    }

    let mut out = String::new();
    out.push_str(&format!("# Context Evidence Brief: {}\n\n", blueprint.name));
    out.push_str("- schema: `hoi4skill.large_mod_context_evidence_brief.v1`\n");
    out.push_str(&format!("- acronym: `{}`\n", blueprint.acronym));
    out.push_str(&format!("- mod_root: `{}`\n", mod_root.display()));
    out.push_str(&format!("- blueprint: `{}`\n", blueprint_path.display()));
    out.push_str(&format!(
        "- status: `{}`\n",
        if blocked.is_empty() {
            "ok"
        } else if blocked
            .iter()
            .all(|(_, _, _, _, _, answer_file, _)| answer_file.exists())
        {
            "needs_context_verification"
        } else {
            "needs_context_evidence"
        }
    ));
    out.push_str(&format!("- blocked_package_count: `{}`\n\n", blocked.len()));

    out.push_str("## How To Answer\n\n");
    out.push_str("Reply with package-scoped evidence only. Provide exact local symbols, source files, spriteType names, texture paths, country/cosmetic tags, or dynamic modifier helper names. If the requested thing does not exist, say it does not exist and whether a new asset/system is authorized.\n\n");
    out.push_str("Record the answer with:\n\n");
    out.push_str(&markdown_fence(
        "powershell",
        &format!(
            "hoi4skill large-mod-context-evidence-answers --mod-root \"{}\" --input \"context_answers.md\" --output .hoi4skill/context_evidence_answers.json",
            mod_root.display()
        ),
    ));
    out.push('\n');

    if blocked.is_empty() {
        out.push_str("## Evidence Questions\n\n- No context-evidence blockers found.\n");
    } else {
        out.push_str("## Evidence Questions\n\n");
        for (package, title, status, repair_bundle, retrieved_context, answer_file, questions) in
            blocked
        {
            out.push_str(&format!("### `{package}` - {title}\n\n"));
            out.push_str(&format!("- retrieval_status: `{status}`\n"));
            out.push_str(&format!("- repair_bundle: `{}`\n", repair_bundle.display()));
            out.push_str(&format!(
                "- answers_recorded: `{}`\n",
                if answer_file.exists() { "yes" } else { "no" }
            ));
            out.push_str(&format!("- answer_file: `{}`\n", answer_file.display()));
            out.push_str(&format!(
                "- retrieved_context: `{}`\n\n",
                retrieved_context.display()
            ));
            for question in questions {
                out.push_str(&format!("- [ ] {}\n", question));
            }
            out.push('\n');
        }
    }

    out.push_str("## Stop Conditions\n\n");
    out.push_str("- Do not ask the AI to repair inputs for a package until its evidence questions are answered or the unsupported request is removed.\n");
    out.push_str("- Do not invent HOI4 effects, triggers, sprites, country tags, cosmetic tags, localisation tokens, or dynamic modifier helpers.\n");
    out.push_str("- Recording answers is not proof that a code symbol exists; regenerate context and rerun strict validation before repair.\n");
    out.push_str("- After evidence is added, regenerate the repair bundle and run `large-mod-input-repair-queue` again.\n");
    Ok(out)
}

fn large_mod_context_evidence_answers_json(
    blueprint: &LargeModBlueprint,
    packages: &[WorkPackage],
    mod_root: &Path,
    answer_text: &str,
) -> Result<String, String> {
    let parsed = parse_context_evidence_answer_sections(answer_text, packages)?;
    if parsed.is_empty() {
        return Err("no package-scoped context evidence answers found".to_string());
    }
    let hoi4skill_dir = mod_root.join(".hoi4skill");
    fs::create_dir_all(&hoi4skill_dir)
        .map_err(|e| format!("create {}: {e}", hoi4skill_dir.display()))?;
    let mut entries = Vec::new();
    for (package, text) in parsed {
        let path = hoi4skill_dir.join(format!("context_evidence_answers_{package}.md"));
        let markdown = context_evidence_answer_markdown(&package, &text);
        fs::write(&path, markdown).map_err(|e| format!("write {}: {e}", path.display()))?;
        entries.push(format!(
            "    {{\"package\": {}, \"answer_file\": {}, \"answer_length\": {}, \"status\": {}}}",
            json_str(&package),
            json_str(&path.display().to_string()),
            text.chars().count(),
            json_str("recorded_not_verified")
        ));
    }
    let next_commands = vec![
        format!(
            "Regenerate blocked repair bundles with --game-root and dependency --mod-path evidence for {}",
            mod_root.display()
        ),
        format!(
            "hoi4skill large-mod-input-repair-queue --mod-root {} --output .hoi4skill/input_repair_queue.json",
            mod_root.display()
        ),
        format!(
            "hoi4skill large-mod-context-evidence-brief --mod-root {} --output .hoi4skill/context_evidence_brief.md",
            mod_root.display()
        ),
    ];
    Ok(format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_context_evidence_answers.v1\",\n  \"status\": \"recorded_not_verified\",\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"package_answer_count\": {},\n  \"answers\": [\n{}\n  ],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&mod_root.display().to_string()),
        entries.len(),
        entries.join(",\n"),
        json_array(&next_commands),
        json_array(&large_mod_context_evidence_answers_stop_conditions()),
    ))
}

fn parse_context_evidence_answer_sections(
    text: &str,
    packages: &[WorkPackage],
) -> Result<Vec<(String, String)>, String> {
    let package_ids = packages
        .iter()
        .map(|package| package.id.as_str())
        .collect::<Vec<_>>();
    let mut out = Vec::new();
    let mut current_package: Option<String> = None;
    let mut current_text = String::new();
    for line in text.lines() {
        if let Some(package) = parse_context_evidence_answer_heading(line, &package_ids) {
            push_context_evidence_answer_section(&mut out, &mut current_package, &mut current_text);
            current_package = Some(package);
            continue;
        }
        if current_package.is_some() {
            current_text.push_str(line);
            current_text.push('\n');
        }
    }
    push_context_evidence_answer_section(&mut out, &mut current_package, &mut current_text);
    Ok(out)
}

fn parse_context_evidence_answer_heading(line: &str, package_ids: &[&str]) -> Option<String> {
    let trimmed = line.trim();
    let candidate = parse_author_work_packages_heading(trimmed)
        .or_else(|| parse_author_work_packages_package_line(trimmed))
        .or_else(|| {
            package_ids
                .iter()
                .find(|package| trimmed.contains(**package))
                .map(|package| (*package).to_string())
        })?;
    package_ids
        .iter()
        .any(|package| *package == candidate)
        .then_some(candidate)
}

fn push_context_evidence_answer_section(
    out: &mut Vec<(String, String)>,
    current_package: &mut Option<String>,
    current_text: &mut String,
) {
    let Some(package) = current_package.take() else {
        return;
    };
    let text = current_text.trim().to_string();
    current_text.clear();
    if !text.is_empty() {
        out.push((package, text));
    }
}

fn context_evidence_answer_markdown(package: &str, answer: &str) -> String {
    let mut out = String::new();
    out.push_str("# Context Evidence Answers\n\n");
    out.push_str("- schema: `hoi4skill.context_evidence_answer.v1`\n");
    out.push_str(&format!("- package: `{package}`\n"));
    out.push_str("- status: `recorded_not_verified`\n");
    out.push_str("- rule: user-provided answers are evidence hints, not proof that HOI4 code symbols exist.\n\n");
    out.push_str("## Answer\n\n");
    out.push_str(answer.trim());
    out.push_str("\n\n## Required Follow-Up\n\n");
    out.push_str("- Regenerate repair context with local game/dependency paths.\n");
    out.push_str("- Rerun strict-code-index validation before accepting repaired inputs.\n");
    out
}

fn large_mod_context_evidence_answers_stop_conditions() -> Vec<String> {
    vec![
        "Do not treat recorded answers as verified code-index evidence.".to_string(),
        "Do not create a new icon, tag, helper, or system unless the answer explicitly authorizes creation.".to_string(),
        "Regenerate repair bundles and rerun large-mod-input-repair-queue before applying AI repair inputs.".to_string(),
    ]
}

fn large_mod_context_evidence_verification_json(
    blueprint: &LargeModBlueprint,
    packages: &[WorkPackage],
    mod_root: &Path,
    game_root: &Path,
    mod_paths: &[PathBuf],
    index: &GameIndex,
) -> Result<String, String> {
    let mut package_entries = Vec::new();
    let mut checked_count = 0usize;
    let mut verified_count = 0usize;
    let mut missing_count = 0usize;
    let mut answer_count = 0usize;
    for package in packages {
        let answer_file = mod_root
            .join(".hoi4skill")
            .join(format!("context_evidence_answers_{}.md", package.id));
        if !answer_file.exists() {
            continue;
        }
        answer_count += 1;
        let answer = read_utf8_lossy(&answer_file)?;
        let answer_fingerprint = stable_text_fingerprint(&answer);
        let answer_body = context_evidence_answer_body(&answer);
        let tokens = extract_context_evidence_verification_tokens(&answer_body);
        let mut token_entries = Vec::new();
        let mut package_missing = 0usize;
        let mut package_verified = 0usize;
        for token in tokens {
            checked_count += 1;
            let kind = context_evidence_token_kind(&token);
            let (_symbol_json, ok) = check_code_symbol_json(index, &token, kind);
            if ok {
                verified_count += 1;
                package_verified += 1;
            } else {
                missing_count += 1;
                package_missing += 1;
            }
            token_entries.push(format!(
                "        {{\"token\": {}, \"requested_kind\": {}, \"verified\": {}, \"message\": {}}}",
                json_str(&token),
                json_optional_str(kind),
                json_bool(ok),
                json_str(if ok {
                    "indexed local evidence found"
                } else {
                    "missing from local HOI4/dependency code index; do not use until created or replaced"
                })
            ));
        }
        let status = if token_entries.is_empty() {
            "no_code_tokens"
        } else if package_missing == 0 {
            "verified"
        } else {
            "needs_evidence"
        };
        package_entries.push(format!(
            "    {{\n      \"package\": {},\n      \"answer_file\": {},\n      \"answer_fingerprint\": {},\n      \"status\": {},\n      \"checked_count\": {},\n      \"verified_count\": {},\n      \"missing_count\": {},\n      \"tokens\": [\n{}\n      ]\n    }}",
            json_str(&package.id),
            json_str(&answer_file.display().to_string()),
            json_str(&answer_fingerprint),
            json_str(status),
            token_entries.len(),
            package_verified,
            package_missing,
            token_entries.join(",\n"),
        ));
    }
    let status = if answer_count == 0 {
        "missing_answers"
    } else if missing_count == 0 {
        "verified"
    } else {
        "needs_evidence"
    };
    let mod_path_strings = mod_paths
        .iter()
        .map(|path| path.display().to_string())
        .collect::<Vec<_>>();
    let next_commands = vec![
        format!(
            "hoi4skill large-mod-context-evidence-brief --mod-root {} --output .hoi4skill/context_evidence_brief.md",
            mod_root.display()
        ),
        format!(
            "hoi4skill large-mod-input-repair-queue --mod-root {} --output .hoi4skill/input_repair_queue.json",
            mod_root.display()
        ),
        format!(
            "Regenerate repair bundles with --game-root {} and the same --mod-path values before applying AI repair inputs.",
            game_root.display()
        ),
    ];
    Ok(format!(
        "{{\n  \"schema\": \"hoi4skill.large_mod_context_evidence_verification.v1\",\n  \"status\": {},\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"game_root\": {},\n  \"mod_paths\": {},\n  \"answer_count\": {},\n  \"checked_count\": {},\n  \"verified_count\": {},\n  \"missing_count\": {},\n  \"packages\": [\n{}\n  ],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(status),
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&mod_root.display().to_string()),
        json_str(&game_root.display().to_string()),
        json_array(&mod_path_strings),
        answer_count,
        checked_count,
        verified_count,
        missing_count,
        package_entries.join(",\n"),
        json_array(&next_commands),
        json_array(&large_mod_context_evidence_verification_stop_conditions()),
    ))
}

fn extract_context_evidence_verification_tokens(text: &str) -> Vec<String> {
    let verification_text = context_evidence_verification_relevant_text(text);
    let mut tokens = extract_limited_code_like_tokens(&verification_text, 80);
    for raw in verification_text.split(|ch: char| !ch.is_ascii_alphanumeric() && ch != '_') {
        let token = raw.trim();
        if token.len() == 3
            && token.chars().all(|ch| ch.is_ascii_uppercase())
            && !tokens.iter().any(|existing| existing == token)
        {
            tokens.push(token.to_string());
        }
    }
    tokens
}

fn context_evidence_verification_relevant_text(text: &str) -> String {
    let mut out = String::new();
    for line in text.lines() {
        let trimmed = line.trim();
        if trimmed.contains("不存在") && !trimmed.contains("授权创建") {
            if let Some((_, replacement)) = trimmed
                .split_once("改用")
                .or_else(|| trimmed.split_once("使用"))
            {
                out.push_str(replacement);
                out.push('\n');
            }
            continue;
        }
        out.push_str(trimmed);
        out.push('\n');
    }
    out
}

fn context_evidence_token_kind(token: &str) -> Option<&'static str> {
    if token.starts_with("GFX_") {
        Some("resource_id")
    } else if token.starts_with("add_")
        || token.starts_with("set_")
        || token.starts_with("remove_")
        || token.starts_with("swap_")
        || token.starts_with("change_")
    {
        Some("effect")
    } else if token.contains("dynamic_modifier") {
        Some("dynamic_modifier")
    } else {
        None
    }
}

fn context_evidence_answer_body(text: &str) -> String {
    if let Some((_, rest)) = text.split_once("## Answer") {
        if let Some((answer, _)) = rest.split_once("## Required Follow-Up") {
            return answer.trim().to_string();
        }
        return rest.trim().to_string();
    }
    text.to_string()
}

fn large_mod_context_evidence_verification_stop_conditions() -> Vec<String> {
    vec![
        "Do not apply AI repair inputs while status is missing_answers or needs_evidence.".to_string(),
        "Do not treat user answers as verified when any referenced token is missing from the local game/dependency index.".to_string(),
        "If a missing sprite, tag, helper, or effect is intentionally new, create/register it through the proper writer and rerun verification.".to_string(),
    ]
}

fn context_evidence_package_verified_current(
    text: &str,
    package_id: &str,
    answer_file: &Path,
) -> bool {
    let Some(slice) = context_evidence_package_json_slice(text, package_id) else {
        return false;
    };
    status_json_string_field(slice, "status").as_deref() == Some("verified")
        && context_evidence_package_fingerprint_matches(text, package_id, answer_file)
}

fn context_evidence_package_fingerprint_matches(
    text: &str,
    package_id: &str,
    answer_file: &Path,
) -> bool {
    let Some(slice) = context_evidence_package_json_slice(text, package_id) else {
        return false;
    };
    let Some(recorded) = status_json_string_field(slice, "answer_fingerprint") else {
        return false;
    };
    let Ok(answer) = read_utf8_lossy(answer_file) else {
        return false;
    };
    recorded == stable_text_fingerprint(&answer)
}

fn context_evidence_package_json_slice<'a>(text: &'a str, package_id: &str) -> Option<&'a str> {
    let marker = format!("\"package\": {}", json_str(package_id));
    let start = text.find(&marker)?;
    let rest = &text[start + marker.len()..];
    let end = rest
        .find("\"package\"")
        .map(|idx| start + marker.len() + idx)
        .unwrap_or(text.len());
    Some(&text[start..end])
}

fn stable_text_fingerprint(text: &str) -> String {
    let mut hash = 0xcbf29ce484222325u64;
    for byte in text.as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("{hash:016x}")
}

fn large_mod_repair_context_evidence_questions(
    package: &WorkPackage,
    repair_dir: &Path,
    run_dir: &Path,
    retrieval_status: &str,
) -> Vec<String> {
    let mut questions = Vec::new();
    match retrieval_status {
        "missing_game_root" => questions.push(
            "Provide the Hearts of Iron IV game root and any dependency --mod-path values before repair; no local syntax evidence was indexed.".to_string(),
        ),
        "unavailable" | "unknown" | "missing" => questions.push(
            "Regenerate the repair bundle with a valid --game-root and dependency --mod-path evidence; current retrieval status cannot prove code symbols.".to_string(),
        ),
        "no_matches" => questions.push(
            "Provide a source file, local code example, or exact HOI4/dependency symbol for this package; retrieval found no matching local evidence.".to_string(),
        ),
        _ => {}
    }

    let input_dir = run_dir.join("inputs");
    let dynamic_text =
        read_utf8_lossy(&input_dir.join("dynamic_modifier_intent.txt")).unwrap_or_default();
    if !dynamic_text.trim().is_empty() {
        questions.push("Dynamic modifier evidence needed: provide the existing scripted_effect/scripted_modifier helper or authorize plan-dynamic-modifier-change; do not route this as a national spirit.".to_string());
    }

    let mut combined_inputs = String::new();
    for name in [
        "intent.txt",
        "focus_layout.txt",
        "event_cards.txt",
        "feature_cards.txt",
        "dynamic_modifier_intent.txt",
        "localisation_placeholders.txt",
        "translated_localisation.txt",
    ] {
        if let Ok(text) = read_utf8_lossy(&input_dir.join(name)) {
            combined_inputs.push_str(&text);
            combined_inputs.push('\n');
        }
    }

    for symbol in extract_limited_code_like_tokens(&combined_inputs, 8) {
        if symbol.starts_with("GFX_") {
            questions.push(format!(
                "Sprite evidence needed for `{symbol}`: provide an existing spriteType/texture path from the game or dependency mod, or confirm the icon must be created."
            ));
        } else {
            questions.push(format!(
                "Code symbol evidence needed for `{symbol}`: verify it exists in the local HOI4/dependency index before AI repair can use it."
            ));
        }
    }
    if combined_inputs.contains("图标") && !combined_inputs.contains("GFX_") {
        questions.push("Icon placeholder evidence needed: map the requested Chinese icon name to an existing GFX sprite, or ask the user whether a new icon asset exists.".to_string());
    }
    if combined_inputs.contains("国旗")
        || combined_inputs.contains("领导人")
        || combined_inputs.contains("cosmetic")
    {
        questions.push("Country/cosmetic tag evidence needed: verify the intended country or cosmetic tag alias from localisation before resolving flag, leader, or country-name placeholders.".to_string());
    }

    if let Ok(context) = read_utf8_lossy(&repair_dir.join("retrieved_code_context.json")) {
        if let Some(reason) = status_json_string_field(&context, "retrieval_error") {
            questions.push(format!(
                "Retrieval error evidence needed for `{}`: {}",
                package.id,
                truncate_chars(&reason, 180)
            ));
        }
        for query in parse_json_string_array_field(&context, "queries")
            .into_iter()
            .take(3)
        {
            questions.push(format!(
                "Provide local evidence for repair query `{}` or remove that unsupported request from the package input.",
                truncate_chars(&query, 120)
            ));
        }
    }

    if questions.is_empty() {
        questions.push(format!(
            "Provide local HOI4/dependency evidence for package `{}` before asking AI to repair inputs.",
            package.id
        ));
    }
    dedup_keep_order(questions).into_iter().take(12).collect()
}

fn extract_limited_code_like_tokens(text: &str, limit: usize) -> Vec<String> {
    let mut out = Vec::new();
    for raw in
        text.split(|ch: char| !(ch.is_ascii_alphanumeric() || ch == '_' || ch == '.' || ch == ':'))
    {
        let token = raw
            .trim_matches([':', '.', ',', ';', '"', '\''])
            .trim()
            .to_string();
        if !is_repair_evidence_token(&token) {
            continue;
        }
        if !out.iter().any(|existing| existing == &token) {
            out.push(token);
        }
        if out.len() >= limit {
            break;
        }
    }
    out
}

fn is_repair_evidence_token(token: &str) -> bool {
    if token.len() < 4 {
        return false;
    }
    if token.starts_with("GFX_") {
        return true;
    }
    if token.starts_with("add_")
        || token.starts_with("set_")
        || token.starts_with("has_")
        || token.starts_with("remove_")
        || token.starts_with("swap_")
        || token.starts_with("change_")
    {
        return true;
    }
    token.contains('_')
        && token.chars().any(|ch| ch.is_ascii_alphabetic())
        && !matches!(
            token,
            "hoi4skill_input"
                | "dynamic_modifier_intent"
                | "localisation_placeholders"
                | "translated_localisation"
                | "focus_layout"
                | "event_cards"
                | "feature_cards"
                | "scripted_effect"
                | "scripted_effects"
                | "scripted_trigger"
                | "scripted_triggers"
                | "sprite_type"
                | "spriteType"
                | "texturefile"
        )
}

fn dedup_keep_order(values: Vec<String>) -> Vec<String> {
    let mut out = Vec::new();
    for value in values {
        if !out.iter().any(|existing| existing == &value) {
            out.push(value);
        }
    }
    out
}

fn large_mod_run_summary_package_commands(
    package: &WorkPackage,
    mod_root: &Path,
    start_state: &WorkPackageStartState,
    execution_status: &str,
    repair_status: &str,
    playtest_status: &str,
) -> Vec<String> {
    let root = mod_root.display().to_string();
    if !start_state.blocked_by.is_empty() {
        return vec![format!(
            "hoi4skill large-mod-execution-queue --mod-root {root} --output .hoi4skill/execution_queue.json"
        )];
    }
    if repair_status != "missing" || execution_status == "failed" {
        let repair_bundle = mod_root
            .join(".hoi4skill")
            .join(format!("repair_bundle_{}", package.id))
            .join("repair_bundle.json");
        return vec![
            format!(
                "hoi4skill apply-work-package-repair --repair-bundle {} --input <ai_repair_inputs.md> --execute --game-root <HOI4 root>",
                repair_bundle.display()
            ),
            format!(
                "hoi4skill run-work-package --mod-root {root} --package {} --execute --game-root <HOI4 root>",
                package.id
            ),
        ];
    }
    if execution_status == "missing" {
        return vec![format!(
            "hoi4skill run-work-package --mod-root {root} --package {} --output-dir .hoi4skill/work_package_runs/{}",
            package.id, package.id
        )];
    }
    if playtest_status == "needs_review" || playtest_status == "missing" {
        return vec![format!(
            "hoi4skill work-package-playtest-report --mod-root {root} --package {} --result passed --validation-report .hoi4skill/validation_{}.json --error-log-report .hoi4skill/error_log_{}.json --output .hoi4skill/playtest_{}.json",
            package.id, package.id, package.id, package.id
        )];
    }
    vec![format!(
        "hoi4skill large-mod-release-gate --mod-root {root} --output .hoi4skill/release_gate.json"
    )]
}

fn large_mod_run_summary_stop_conditions() -> Vec<String> {
    vec![
        "Do not mark the project release-ready while failed_count, repair_bundle_count, or needs_playtest_count is nonzero.".to_string(),
        "Resolve package repair bundles before rerunning batch execution.".to_string(),
        "Replace auto-generated needs_review playtest skeletons with real in-game passed reports before release.".to_string(),
    ]
}

fn work_package_start_brief_markdown(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    packages: &[WorkPackage],
    blueprint_path: &Path,
    mod_root: Option<&Path>,
) -> String {
    let root = mod_root
        .map(|path| path.display().to_string())
        .unwrap_or_else(|| "<mod-root>".to_string());
    let package_token = package_token(package);
    let tag = package_tag(package);
    let namespace = package_namespace(package, blueprint);
    let start_state = work_package_start_state(package, packages, mod_root);
    let preflight_commands =
        work_package_preflight_commands(package, &root, tag.as_deref(), &namespace);
    let generator_commands = work_package_recommended_generators(package, tag.as_deref());
    let planned_files = work_package_planned_files(package, &root, tag.as_deref(), &package_token);

    let mut out = String::new();
    out.push_str(&format!(
        "# Work Package Start Brief: {}\n\n",
        package.title
    ));
    out.push_str("- schema: `hoi4skill.work_package_start_brief.v1`\n");
    out.push_str(&format!("- state: `{}`\n", start_state.state));
    out.push_str(&format!("- package: `{}`\n", package.id));
    out.push_str(&format!("- kind: `{}`\n", package.kind));
    out.push_str(&format!("- mod: `{}`\n", blueprint.name));
    out.push_str(&format!("- acronym: `{}`\n", blueprint.acronym));
    out.push_str(&format!("- mod_root: `{}`\n", root));
    out.push_str(&format!("- blueprint: `{}`\n", blueprint_path.display()));
    out.push_str(&format!("- token: `{}`\n", package_token));
    out.push_str(&format!("- tag: `{}`\n", tag.as_deref().unwrap_or("none")));
    out.push_str(&format!("- namespace: `{}`\n", namespace));

    out.push_str("\n## Dependency Gate\n\n");
    if start_state.dependencies.is_empty() {
        out.push_str("- No package dependencies.\n");
    } else {
        out.push_str(&format!(
            "- depends_on: `{}`\n",
            start_state.dependencies.join("`, `")
        ));
    }
    if start_state.blocked_by.is_empty() {
        out.push_str("- dependency_state: `clear`\n");
    } else {
        out.push_str(&format!(
            "- dependency_state: `blocked` by `{}`\n",
            start_state.blocked_by.join("`, `")
        ));
    }

    out.push_str("\n## Allowed Edit Surface\n\n");
    for path in work_package_boundary_allowed_prefixes(package) {
        out.push_str(&format!("- `{path}`\n"));
    }

    out.push_str("\n## Identity Terms\n\n");
    for term in work_package_identity_terms(package, blueprint) {
        out.push_str(&format!("- `{term}`\n"));
    }

    out.push_str("\n## Deliverables\n\n");
    for item in &package.deliverables {
        out.push_str(&format!("- {item}\n"));
    }

    out.push_str("\n## Planned Files\n\n");
    for path in planned_files {
        out.push_str(&format!("- `{path}`\n"));
    }

    out.push_str("\n## Preflight Commands\n\n");
    for command in preflight_commands {
        out.push_str(&format!("- `{command}`\n"));
    }

    out.push_str("\n## Generator Commands\n\n");
    for command in generator_commands {
        out.push_str(&format!("- `{command}`\n"));
    }

    out.push_str("\n## Code Authoring Contract\n\n");
    out.push_str("- AI outputs intent, structured layouts/cards, and player-visible text only.\n");
    out.push_str("- Rust `hoi4skill` writers emit final Clausewitz script.\n");
    out.push_str("- Run `hoi4skill code-catalog --game-root <HOI4 root> [--mod-path <dependency>]` before accepting generated code symbols.\n");
    out.push_str("- Use `hoi4skill compile-intent --kind auto --game-root <HOI4 root> --strict-code-index` for shorthand effects before writing.\n");
    out.push_str("- Stop if `safety.final_code_allowed` is false, `safety.blockers` is non-empty, a code-index category is empty, or `check-code-symbol` returns `ok=false`.\n");

    out.push_str("\n## Package Commands\n\n");
    for command in large_mod_execution_queue_package_commands(package, &root) {
        out.push_str(&format!("- `{command}`\n"));
    }

    out.push_str("\n## Stop Conditions\n\n");
    out.push_str("- Do not start while `state` is `blocked_by_dependencies`.\n");
    out.push_str(
        "- Do not write outside the allowed edit surface without updating boundary evidence.\n",
    );
    out.push_str("- Do not create country tags, country history, state history, initial units, characters, English localisation, GUI, technologies, or map data unless the literal user request authorizes them.\n");
    out.push_str("- Before final script output, run changed-only validation and keep strict-code-index clean.\n");
    out
}

struct WorkPackageStartState {
    state: String,
    dependencies: Vec<String>,
    blocked_by: Vec<String>,
}

fn work_package_start_state(
    package: &WorkPackage,
    packages: &[WorkPackage],
    mod_root: Option<&Path>,
) -> WorkPackageStartState {
    let dependencies = work_package_dependency_ids(package, packages);
    let blocked_by = dependencies
        .iter()
        .filter(|dependency| {
            packages
                .iter()
                .find(|candidate| &candidate.id == *dependency)
                .map(|dependency_package| {
                    let summary = work_package_readiness_summary(dependency_package, mod_root);
                    !work_package_completion_ready(&summary)
                })
                .unwrap_or(true)
        })
        .cloned()
        .collect::<Vec<_>>();
    let summary = work_package_readiness_summary(package, mod_root);
    let state = if !blocked_by.is_empty() {
        "blocked_by_dependencies"
    } else if work_package_completion_ready(&summary) {
        "already_handed_off"
    } else if !summary.blocking.is_empty() {
        "needs_review"
    } else {
        "ready_to_start"
    };
    WorkPackageStartState {
        state: state.to_string(),
        dependencies,
        blocked_by,
    }
}

fn write_work_package_start_briefs(
    blueprint: &LargeModBlueprint,
    packages: &[WorkPackage],
    blueprint_path: &Path,
    mod_root: Option<&Path>,
    output_dir: &Path,
    ready_only: bool,
) -> Result<String, String> {
    fs::create_dir_all(output_dir).map_err(|e| format!("create {}: {e}", output_dir.display()))?;
    let mut ordered = packages.iter().collect::<Vec<_>>();
    ordered.sort_by(|left, right| {
        work_package_layer(&left.kind)
            .cmp(&work_package_layer(&right.kind))
            .then_with(|| left.id.cmp(&right.id))
    });
    let mut entries = Vec::new();
    let mut generated_count = 0usize;
    let mut skipped_count = 0usize;
    for package in ordered {
        let start_state = work_package_start_state(package, packages, mod_root);
        let generated = !ready_only || start_state.state == "ready_to_start";
        let path = output_dir.join(format!("start_{}.md", package.id));
        if generated {
            let markdown = work_package_start_brief_markdown(
                blueprint,
                package,
                packages,
                blueprint_path,
                mod_root,
            );
            fs::write(&path, markdown).map_err(|e| format!("write {}: {e}", path.display()))?;
            generated_count += 1;
        } else {
            skipped_count += 1;
        }
        entries.push(format!(
            "{{\n      \"id\": {},\n      \"kind\": {},\n      \"title\": {},\n      \"state\": {},\n      \"generated\": {},\n      \"path\": {},\n      \"blocked_by\": {}\n    }}",
            json_str(&package.id),
            json_str(&package.kind),
            json_str(&package.title),
            json_str(&start_state.state),
            json_bool(generated),
            json_str(&path.display().to_string()),
            json_array(&start_state.blocked_by),
        ));
    }
    let manifest = format!(
        "{{\n  \"schema\": \"hoi4skill.work_package_start_briefs.v1\",\n  \"mod\": {},\n  \"acronym\": {},\n  \"blueprint\": {},\n  \"output_dir\": {},\n  \"ready_only\": {},\n  \"package_count\": {},\n  \"generated_count\": {},\n  \"skipped_count\": {},\n  \"briefs\": [\n{}\n  ],\n  \"stop_conditions\": {}\n}}\n",
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&blueprint_path.display().to_string()),
        json_str(&output_dir.display().to_string()),
        json_bool(ready_only),
        packages.len(),
        generated_count,
        skipped_count,
        entries.join(",\n"),
        json_array(&work_package_start_briefs_stop_conditions()),
    );
    let manifest_path = output_dir.join("manifest.json");
    fs::write(&manifest_path, &manifest)
        .map_err(|e| format!("write {}: {e}", manifest_path.display()))?;
    Ok(manifest)
}

fn work_package_start_briefs_stop_conditions() -> Vec<String> {
    vec![
        "Do not dispatch skipped packages while --ready-only filtering is active.".to_string(),
        "Do not start packages whose generated brief reports blocked_by_dependencies.".to_string(),
        "Treat generated briefs as task boundaries, not permission to write outside package ownership.".to_string(),
    ]
}

fn write_work_package_authoring_pack(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    packages: &[WorkPackage],
    blueprint_path: &Path,
    mod_root: Option<&Path>,
    output_dir: &Path,
) -> Result<String, String> {
    fs::create_dir_all(output_dir).map_err(|e| format!("create {}: {e}", output_dir.display()))?;
    let start_path = output_dir.join("start.md");
    let plan_path = output_dir.join("plan.json");
    let assets_path = output_dir.join("assets.md");
    let context_path = output_dir.join("context.md");
    let manifest_path = output_dir.join("manifest.json");

    fs::write(
        &start_path,
        work_package_start_brief_markdown(blueprint, package, packages, blueprint_path, mod_root),
    )
    .map_err(|e| format!("write {}: {e}", start_path.display()))?;
    fs::write(
        &plan_path,
        work_package_plan_json(blueprint, package, blueprint_path, mod_root),
    )
    .map_err(|e| format!("write {}: {e}", plan_path.display()))?;
    fs::write(
        &assets_path,
        asset_pack_plan_markdown(blueprint, package, blueprint_path, mod_root),
    )
    .map_err(|e| format!("write {}: {e}", assets_path.display()))?;
    fs::write(
        &context_path,
        work_package_authoring_context_markdown(
            blueprint,
            package,
            packages,
            blueprint_path,
            mod_root,
            output_dir,
        ),
    )
    .map_err(|e| format!("write {}: {e}", context_path.display()))?;

    let root = mod_root
        .map(|path| path.display().to_string())
        .unwrap_or_else(|| "<mod-root>".to_string());
    let start_state = work_package_start_state(package, packages, mod_root);
    let files = [
        ("start_brief", &start_path),
        ("generation_plan", &plan_path),
        ("asset_plan", &assets_path),
        ("authoring_context", &context_path),
    ]
    .iter()
    .map(|(kind, path)| {
        format!(
            "{{\"kind\": {}, \"path\": {}}}",
            json_str(kind),
            json_str(&path.display().to_string())
        )
    })
    .collect::<Vec<_>>()
    .join(", ");
    let commands = vec![
        format!("hoi4skill work-package-authoring-pack --mod-root {root} --package {} --output-dir {}", package.id, output_dir.display()),
        format!("hoi4skill check-work-package-boundary --mod-root {root} --package {} --changed-file .hoi4skill/changed_{}.txt --strict-names --fail-on-violation --output .hoi4skill/boundary_{}.json", package.id, package.id, package.id),
        format!("hoi4skill work-package-status --mod-root {root} --package {} --output .hoi4skill/status_{}.json", package.id, package.id),
        format!("hoi4skill work-package-handoff --mod-root {root} --package {} --output .hoi4skill/handoff_{}.md", package.id, package.id),
    ];
    let manifest = format!(
        "{{\n  \"schema\": \"hoi4skill.work_package_authoring_pack.v1\",\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"blueprint\": {},\n  \"output_dir\": {},\n  \"package\": {{\n    \"id\": {},\n    \"kind\": {},\n    \"title\": {},\n    \"state\": {},\n    \"blocked_by\": {}\n  }},\n  \"files\": [{}],\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&root),
        json_str(&blueprint_path.display().to_string()),
        json_str(&output_dir.display().to_string()),
        json_str(&package.id),
        json_str(&package.kind),
        json_str(&package.title),
        json_str(&start_state.state),
        json_array(&start_state.blocked_by),
        files,
        json_array(&commands),
        json_array(&work_package_authoring_pack_stop_conditions()),
    );
    fs::write(&manifest_path, &manifest)
        .map_err(|e| format!("write {}: {e}", manifest_path.display()))?;
    Ok(manifest)
}

fn work_package_authoring_context_markdown(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    packages: &[WorkPackage],
    blueprint_path: &Path,
    mod_root: Option<&Path>,
    output_dir: &Path,
) -> String {
    let root = mod_root
        .map(|path| path.display().to_string())
        .unwrap_or_else(|| "<mod-root>".to_string());
    let start_state = work_package_start_state(package, packages, mod_root);
    let tag = package_tag(package);
    let namespace = package_namespace(package, blueprint);
    let mut out = String::new();
    out.push_str(&format!(
        "# Work Package Authoring Context: {}\n\n",
        package.id
    ));
    out.push_str("- schema: `hoi4skill.work_package_authoring_context.v1`\n");
    out.push_str(&format!("- mod: `{}`\n", blueprint.name));
    out.push_str(&format!("- acronym: `{}`\n", blueprint.acronym));
    out.push_str(&format!("- mod_root: `{}`\n", root));
    out.push_str(&format!("- blueprint: `{}`\n", blueprint_path.display()));
    out.push_str(&format!("- output_dir: `{}`\n", output_dir.display()));
    out.push_str(&format!("- package: `{}`\n", package.id));
    out.push_str(&format!("- kind: `{}`\n", package.kind));
    out.push_str(&format!("- state: `{}`\n", start_state.state));
    out.push_str(&format!("- namespace: `{}`\n", namespace));
    if let Some(tag) = &tag {
        out.push_str(&format!("- tag: `{tag}`\n"));
    }

    out.push_str("\n## Allowed Edit Surface\n\n");
    for path in work_package_boundary_allowed_prefixes(package) {
        out.push_str(&format!("- `{path}`\n"));
    }

    out.push_str("\n## Identity Terms\n\n");
    for term in work_package_identity_terms(package, blueprint) {
        out.push_str(&format!("- `{term}`\n"));
    }

    out.push_str("\n## Dependencies\n\n");
    if start_state.dependencies.is_empty() {
        out.push_str("- No package dependencies.\n");
    } else {
        for dependency in &start_state.dependencies {
            let state = if start_state.blocked_by.contains(dependency) {
                "blocking"
            } else {
                "ready"
            };
            out.push_str(&format!("- `{dependency}`: `{state}`\n"));
        }
    }

    out.push_str("\n## Authoring Files\n\n");
    for file in [
        "start.md",
        "plan.json",
        "assets.md",
        "context.md",
        "manifest.json",
    ] {
        out.push_str(&format!("- `{}`\n", output_dir.join(file).display()));
    }

    out.push_str("\n## Style Context\n\n");
    out.push_str(&format!(
        "- style_context: `{}`\n",
        output_dir.join("inputs").join("style_context.md").display()
    ));
    out.push_str("- rule: Generate it with `hoi4skill work-package-style-context --style-mod <local style mod>` when the user wants a specific mod prose style.\n");
    out.push_str("- rule: Use style context for density, cadence, structure, and event template choice only; never copy source prose or worldbuilding.\n");

    out.push_str("\n## Suggested Commands\n\n");
    for command in work_package_preflight_commands(package, &root, tag.as_deref(), &namespace) {
        out.push_str(&format!("- `{command}`\n"));
    }
    out.push_str(&format!(
        "- `hoi4skill check-work-package-boundary --mod-root {root} --package {} --changed-file .hoi4skill/changed_{}.txt --strict-names --fail-on-violation --output .hoi4skill/boundary_{}.json`\n",
        package.id, package.id, package.id
    ));
    out.push_str(&format!(
        "- `hoi4skill work-package-handoff --mod-root {root} --package {} --output .hoi4skill/handoff_{}.md`\n",
        package.id, package.id
    ));

    out.push_str("\n## Stop Conditions\n\n");
    for condition in work_package_authoring_pack_stop_conditions() {
        out.push_str(&format!("- {condition}\n"));
    }
    out
}

fn work_package_authoring_pack_stop_conditions() -> Vec<String> {
    vec![
        "Do not write outside the allowed edit surface listed in context.md.".to_string(),
        "Do not start authoring while the manifest package state is blocked_by_dependencies."
            .to_string(),
        "Do not treat authoring pack generation as gameplay validation or handoff approval."
            .to_string(),
        "Run boundary, status, handoff, and final validation gates after changing package files."
            .to_string(),
    ]
}

struct WorkPackageRunInputTemplate {
    kind: &'static str,
    path: PathBuf,
    required: bool,
    writer: &'static str,
}

impl WorkPackageRunInputTemplate {
    fn to_json(&self) -> String {
        format!(
            "{{\"kind\": {}, \"path\": {}, \"required\": {}, \"writer\": {}}}",
            json_str(self.kind),
            json_str(&self.path.display().to_string()),
            json_bool(self.required),
            json_str(self.writer)
        )
    }
}

fn work_package_placeholder_preflight_input(
    input_templates: &[WorkPackageRunInputTemplate],
) -> Result<String, String> {
    let mut chunks = Vec::new();
    for template in input_templates {
        if !template.path.exists() {
            continue;
        }
        let text = read_text_document(&template.path)?;
        if text.contains('【') || text.contains('】') {
            chunks.push(format!(
                "# source: {}\n{}",
                template.path.display(),
                text.trim_end()
            ));
        }
    }
    Ok(chunks.join("\n\n"))
}

fn large_mod_request_text_from_args(map: &ArgMap) -> Result<String, String> {
    if let Some(text) = value(map, "text").or_else(|| value(map, "request")) {
        return Ok(text.to_string());
    }
    if let Some(input) = value(map, "input") {
        return read_text_document(&normalize_path(input)?);
    }
    Err("ingest-work-package-request requires --text, --request, or --input".to_string())
}

fn ingest_work_package_request(
    package: &WorkPackage,
    blueprint: &LargeModBlueprint,
    request: &str,
    output_dir: &Path,
    replace: bool,
) -> Result<String, String> {
    let inputs = output_dir.join("inputs");
    fs::create_dir_all(&inputs).map_err(|e| format!("create {}: {e}", inputs.display()))?;
    let tag = package_tag(package).unwrap_or_else(|| "TAG".to_string());
    let prefix = format!("{}_{}", tag.to_ascii_lowercase(), package_token(package));
    let lanes = classify_work_package_request_lanes(request);
    let mut files = Vec::new();
    let mut questions = Vec::new();
    if lanes.focus {
        let path = inputs.join("focus_layout.txt");
        let snippet = focus_layout_from_user_request(request, &prefix);
        write_ingested_input(&path, &snippet, replace)?;
        files.push(("national_focus", path));
    }
    if lanes.event {
        let path = inputs.join("event_cards.txt");
        let lane_request =
            filter_work_package_request_lanes(request, &[AuthorWorkPackageLane::Event]);
        let snippet = event_cards_from_user_request(&lane_request, &prefix);
        write_ingested_input(&path, &snippet, replace)?;
        files.push(("event_chain", path));
    }
    if lanes.feature {
        let path = inputs.join("feature_cards.txt");
        let snippet = feature_cards_from_user_request(request);
        write_ingested_input(&path, &snippet, replace)?;
        files.push(("decisions_or_national_spirits", path));
    }
    if lanes.intent {
        let path = inputs.join("intent.txt");
        let intent_text = intent_text_from_user_request(request);
        let snippet = format!(
            "\n# Ingested user request: intent\n{}\n",
            intent_text.trim()
        );
        write_ingested_input(&path, &snippet, replace)?;
        files.push(("intent", path));
    }
    if lanes.dynamic_modifier {
        let path = inputs.join("dynamic_modifier_intent.txt");
        let dynamic_intent = dynamic_modifier_intent_from_user_request(request);
        let snippet = format!(
            "\n# Ingested user request: dynamic modifier\n{}\n",
            dynamic_intent.trim()
        );
        write_ingested_input(&path, &snippet, replace)?;
        files.push(("dynamic_modifiers", path));
    }
    if lanes.localisation {
        let path = inputs.join("localisation_placeholders.txt");
        let localisation_text = localisation_placeholders_from_user_request(request);
        let snippet = format!(
            "\n# Ingested user request: localisation placeholders\n{}\n",
            localisation_text.trim()
        );
        write_ingested_input(&path, &snippet, replace)?;
        files.push(("localisation", path));
    }
    let (placeholder_preflight_json, placeholder_preflight_questions) = if lanes.localisation {
        let localisation_text = localisation_placeholders_from_user_request(request);
        work_package_localisation_placeholder_preflight_json(&localisation_text)
    } else {
        ("null".to_string(), Vec::new())
    };
    if lanes.localisation && request.contains('【') && request.contains('】') {
        questions.push("Run author-placeholder-plan with --game-root before final localisation; ask the user about unresolved icons, flags, leaders, cosmetic tags, or color tokens.".to_string());
    }
    questions.extend(placeholder_preflight_questions);
    if lanes.dynamic_modifier {
        questions.push("Dynamic modifier text must stay on plan-dynamic-modifier-change/scripted_effect protocol and must not be routed as a national spirit.".to_string());
    }
    questions = dedup_keep_order(questions);
    let file_json = files
        .iter()
        .map(|(lane, path)| {
            format!(
                "    {{\"lane\": {}, \"path\": {}}}",
                json_str(lane),
                json_str(&path.display().to_string())
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    let lane_isolation = work_package_ingest_lane_isolation_json(&files)?;
    let next_commands = vec![
        format!(
            "hoi4skill run-work-package --mod-root <mod-root> --package {} --output-dir {}",
            package.id,
            output_dir.display()
        ),
        format!(
            "hoi4skill author-placeholder-plan --input {} --game-root <HOI4 root>",
            inputs.join("localisation_placeholders.txt").display()
        ),
        format!(
            "hoi4skill compile-intent --input {} --kind auto --game-root <HOI4 root> --strict-code-index",
            inputs.join("intent.txt").display()
        ),
    ];
    Ok(format!(
        "{{\n  \"schema\": \"hoi4skill.work_package_request_ingest.v1\",\n  \"mod\": {},\n  \"package\": {},\n  \"request\": {},\n  \"lanes\": {{\"national_focus\": {}, \"event_chain\": {}, \"decisions_or_national_spirits\": {}, \"intent\": {}, \"dynamic_modifiers\": {}, \"localisation\": {}}},\n  \"files\": [\n{}\n  ],\n  \"lane_isolation\": {},\n  \"placeholder_preflight\": {},\n  \"questions\": {},\n  \"next_commands\": {}\n}}\n",
        json_str(&blueprint.name),
        json_str(&package.id),
        json_str(request),
        json_bool(lanes.focus),
        json_bool(lanes.event),
        json_bool(lanes.feature),
        json_bool(lanes.intent),
        json_bool(lanes.dynamic_modifier),
        json_bool(lanes.localisation),
        file_json,
        lane_isolation,
        placeholder_preflight_json,
        json_array(&questions),
        json_array(&next_commands),
    ))
}

fn work_package_ingest_lane_isolation_json(files: &[(&str, PathBuf)]) -> Result<String, String> {
    let mut entries = Vec::new();
    let mut warning_count = 0usize;
    for (lane, path) in files {
        let text = read_utf8_lossy(path)?;
        let warnings = work_package_ingest_lane_warnings(lane, &text);
        warning_count += warnings.len();
        entries.push(format!(
            "    {{\"lane\": {}, \"ok\": {}, \"warning_count\": {}, \"warnings\": {}, \"line_count\": {}}}",
            json_str(lane),
            json_bool(warnings.is_empty()),
            warnings.len(),
            json_array(&warnings),
            text.lines().filter(|line| !line.trim().is_empty()).count()
        ));
    }
    Ok(format!(
        "{{\"ok\": {}, \"warning_count\": {}, \"entries\": [\n{}\n  ], \"anti_hallucination_rule\": {}}}",
        json_bool(warning_count == 0),
        warning_count,
        entries.join(",\n"),
        json_str("If lane_isolation is not ok, repair the structured input lane before asking a weak model to write or repair HOI4 content.")
    ))
}

pub(crate) fn cmd_lane_isolation_audit(args: &[String]) -> Result<(), String> {
    let map = parse_args(args);
    let text = large_mod_request_text_from_args(&map)
        .map_err(|_| "lane-isolation-audit requires --text, --request, or --input".to_string())?;
    let report = lane_isolation_audit_json(&text);
    let ok = status_json_top_level_bool_field_has_value(&report, "ok", true);
    write_or_print(&report, value(&map, "output"))?;
    if map.flags.contains("require-passed") && !ok {
        return Err(
            "lane isolation audit failed; fix blockers before ingesting weak-AI output".to_string(),
        );
    }
    Ok(())
}

fn lane_isolation_audit_json(request: &str) -> String {
    let normalized = normalise_work_package_request_lane_lines(request);
    let mut current_lane: Option<AuthorWorkPackageLane> = None;
    let mut blocks = Vec::new();
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let mut focus_lines = Vec::new();
    let mut event_lines = Vec::new();
    let mut feature_lines = Vec::new();
    let mut dynamic_lines = Vec::new();
    let mut localisation_lines = Vec::new();
    let mut intent_lines = Vec::new();
    let mut lanes_present = BTreeSet::new();
    let mut line_count = 0usize;

    for (idx, raw_line) in normalized.lines().enumerate() {
        let line = raw_line.trim();
        if line.is_empty() {
            continue;
        }
        line_count += 1;
        let mut reason = "inherited";
        let lane = if let Some(explicit) = explicit_work_package_request_line_lane(line) {
            current_lane = Some(explicit);
            reason = "explicit_lane";
            Some(explicit)
        } else if let Some(contextual) =
            contextual_work_package_request_line_lane(line, current_lane)
        {
            if explicit_contextual_lane_starter(line, contextual) {
                current_lane = Some(contextual);
                reason = "contextual_starter";
            } else {
                reason = "contextual_field";
            }
            Some(contextual)
        } else {
            current_lane
        };
        let line_no = idx + 1;
        let mut line_warnings = Vec::new();
        if let Some(lane) = lane {
            lanes_present.insert(lane.audit_key().to_string());
            push_lane_line(
                lane,
                line,
                &mut focus_lines,
                &mut event_lines,
                &mut feature_lines,
                &mut dynamic_lines,
                &mut localisation_lines,
                &mut intent_lines,
            );
            line_warnings.extend(lane_isolation_line_warnings(lane, line));
        } else {
            line_warnings.push("unassigned_line".to_string());
        }
        for warning in &line_warnings {
            let item = format!("line {line_no}: {warning}");
            if lane_isolation_warning_is_blocking(warning) {
                blockers.push(item);
            } else {
                warnings.push(item);
            }
        }
        blocks.push(format!(
            "    {{\"line\": {}, \"lane\": {}, \"reason\": {}, \"warnings\": {}, \"text\": {}}}",
            line_no,
            json_optional_str(lane.map(|value| value.audit_key()).as_deref()),
            json_str(reason),
            json_array(&line_warnings),
            json_str(line)
        ));
    }

    let lane_text_items = vec![
        format!("    \"focus\": {}", json_str(&focus_lines.join("\n"))),
        format!("    \"event_chain\": {}", json_str(&event_lines.join("\n"))),
        format!(
            "    \"decisions_or_national_spirits\": {}",
            json_str(&feature_lines.join("\n"))
        ),
        format!(
            "    \"dynamic_modifiers\": {}",
            json_str(&dynamic_lines.join("\n"))
        ),
        format!(
            "    \"localisation\": {}",
            json_str(&localisation_lines.join("\n"))
        ),
        format!("    \"intent\": {}", json_str(&intent_lines.join("\n"))),
    ];
    let lanes_present_vec = lanes_present.into_iter().collect::<Vec<_>>();
    let ok = blockers.is_empty();
    format!(
        "{{\n  \"schema\": \"hoi4skill.lane_isolation_audit.v1\",\n  \"ok\": {},\n  \"status\": {},\n  \"line_count\": {},\n  \"lane_count\": {},\n  \"blocker_count\": {},\n  \"warning_count\": {},\n  \"lanes_present\": {},\n  \"blocks\": [\n{}\n  ],\n  \"lane_text\": {{\n{}\n  }},\n  \"blockers\": {},\n  \"warnings\": {},\n  \"anti_hallucination_rule\": {},\n  \"next_commands\": {}\n}}\n",
        json_bool(ok),
        json_str(if ok { "passed" } else { "blocked" }),
        line_count,
        lanes_present_vec.len(),
        blockers.len(),
        warnings.len(),
        json_array(&lanes_present_vec),
        blocks.join(",\n"),
        lane_text_items.join(",\n"),
        json_array(&blockers),
        json_array(&warnings),
        json_str("Each gameplay writer must consume only its lane_text field; unresolved or cross-lane lines must be repaired before weak-AI output is accepted."),
        json_array(&[
            "hoi4skill lane-isolation-audit --input <request> --require-passed".to_string(),
            "hoi4skill ingest-work-package-request --input <request> --mod-root <mod-root> --package <package>".to_string(),
        ])
    )
}

fn push_lane_line(
    lane: AuthorWorkPackageLane,
    line: &str,
    focus_lines: &mut Vec<String>,
    event_lines: &mut Vec<String>,
    feature_lines: &mut Vec<String>,
    dynamic_lines: &mut Vec<String>,
    localisation_lines: &mut Vec<String>,
    intent_lines: &mut Vec<String>,
) {
    match lane {
        AuthorWorkPackageLane::Focus => focus_lines.push(line.to_string()),
        AuthorWorkPackageLane::Event => event_lines.push(line.to_string()),
        AuthorWorkPackageLane::Decision | AuthorWorkPackageLane::NationalSpirit => {
            feature_lines.push(line.to_string())
        }
        AuthorWorkPackageLane::DynamicModifier => dynamic_lines.push(line.to_string()),
        AuthorWorkPackageLane::Localisation => localisation_lines.push(line.to_string()),
        AuthorWorkPackageLane::Intent => intent_lines.push(line.to_string()),
    }
}

fn lane_isolation_line_warnings(lane: AuthorWorkPackageLane, line: &str) -> Vec<String> {
    let lower = line.to_ascii_lowercase();
    let mut warnings = work_package_ingest_lane_warnings(lane.audit_key(), line);
    match lane {
        AuthorWorkPackageLane::Focus => {
            if request_line_is_event_text(line, &lower) {
                warnings.push("focus_contains_event_text".to_string());
            }
            if request_line_is_dynamic_modifier_start(line, &lower) {
                warnings.push("focus_contains_dynamic_modifier_text".to_string());
            }
            if request_line_is_localisation_text(line, &lower) || line.contains('【') {
                warnings.push("focus_contains_localisation_text".to_string());
            }
        }
        AuthorWorkPackageLane::Decision | AuthorWorkPackageLane::NationalSpirit => {
            if request_line_is_dynamic_modifier_start(line, &lower) {
                warnings.push("feature_contains_dynamic_modifier_text".to_string());
            }
        }
        _ => {}
    }
    warnings.sort();
    warnings.dedup();
    warnings
}

fn lane_isolation_warning_is_blocking(warning: &str) -> bool {
    !matches!(
        warning,
        "focus_contains_event_text"
            | "focus_contains_localisation_text"
            | "focus_contains_dynamic_modifier_text"
    )
}

pub(crate) fn work_package_ingest_lane_warnings(lane: &str, text: &str) -> Vec<String> {
    let mut warnings = Vec::new();
    let normalized_dynamic_intent = model_normalized_intent(text)
        .is_some_and(|normalized| normalized.intent_type == "dynamic_modifier_change");
    for line in text
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
    {
        let lower = line.to_ascii_lowercase();
        let warning = match lane {
            "event_chain" if request_line_is_feature_text(line, &lower) => {
                Some("event_chain_contains_feature_text")
            }
            "event_chain" if request_line_is_dynamic_modifier_start(line, &lower) => {
                Some("event_chain_contains_dynamic_modifier_text")
            }
            "decisions_or_national_spirits" if request_line_is_event_text(line, &lower) => {
                Some("feature_contains_event_text")
            }
            "decisions_or_national_spirits"
                if line.contains('【') || request_line_is_dynamic_modifier_start(line, &lower) =>
            {
                Some("feature_contains_localisation_or_dynamic_text")
            }
            "intent" if request_line_is_localisation_text(line, &lower) || line.contains('【') => {
                Some("intent_contains_localisation_text")
            }
            "intent"
                if !normalized_dynamic_intent
                    && request_line_is_dynamic_modifier_start(line, &lower) =>
            {
                Some("intent_contains_dynamic_modifier_text")
            }
            "dynamic_modifiers" if request_line_is_feature_text(line, &lower) => {
                Some("dynamic_modifier_contains_feature_text")
            }
            "dynamic_modifiers" if dynamic_modifier_line_uses_idea_syntax(line, &lower) => {
                Some("dynamic_modifier_uses_national_spirit_syntax")
            }
            "dynamic_modifiers"
                if request_line_is_event_text(line, &lower) || line.contains('【') =>
            {
                Some("dynamic_modifier_contains_event_or_localisation_text")
            }
            "localisation" if request_line_is_feature_text(line, &lower) => {
                Some("localisation_contains_feature_text")
            }
            "localisation" if request_line_is_dynamic_modifier_start(line, &lower) => {
                Some("localisation_contains_dynamic_modifier_text")
            }
            _ => None,
        };
        if let Some(warning) = warning {
            if !warnings.iter().any(|existing| existing == warning) {
                warnings.push(warning.to_string());
            }
        }
    }
    warnings
}

fn dynamic_modifier_line_uses_idea_syntax(line: &str, lower: &str) -> bool {
    line.contains("民族精神")
        || lower.contains("add_ideas")
        || lower.contains("remove_ideas")
        || lower.contains("swap_ideas")
        || lower.contains("has_idea")
        || lower.contains("national spirit")
        || lower.contains("national idea")
}

struct WorkPackageRequestLanes {
    focus: bool,
    event: bool,
    feature: bool,
    intent: bool,
    dynamic_modifier: bool,
    localisation: bool,
}

fn classify_work_package_request_lanes(text: &str) -> WorkPackageRequestLanes {
    let lower = text.to_ascii_lowercase();
    let normalized = model_normalized_intent(text);
    let normalized_dynamic = normalized
        .as_ref()
        .is_some_and(|intent| intent.intent_type == "dynamic_modifier_change");
    let normalized_spirit = normalized.as_ref().is_some_and(|intent| {
        matches!(
            intent.intent_type.as_str(),
            "add_national_spirit"
                | "add_idea"
                | "replace_national_spirit"
                | "replace_idea"
                | "swap_ideas"
        )
    });
    let focus = text.contains("国策") || lower.contains("focus");
    let event = text.contains("事件") || lower.contains("event");
    let decision = request_mentions_decision(text, &lower);
    let idea = normalized_spirit
        || request_mentions_national_spirit(text, &lower)
        || lower.contains("idea");
    let dynamic_modifier =
        normalized_dynamic || request_text_mentions_dynamic_modifier(text, &lower);
    let localisation = text.contains("本地化")
        || text.contains("文案")
        || text.contains('【')
        || lower.contains("localisation")
        || lower.contains("localization");
    let intent = dynamic_modifier
        || idea
        || text.contains("效果")
        || text.contains('+')
        || text.contains('-')
        || text.contains('=')
        || lower.contains("effect");
    WorkPackageRequestLanes {
        focus,
        event,
        feature: decision || idea,
        intent,
        dynamic_modifier,
        localisation,
    }
}

fn request_mentions_decision(text: &str, lower: &str) -> bool {
    text.contains("决议") || lower.contains("decision")
}

fn request_mentions_national_spirit(text: &str, lower: &str) -> bool {
    text.contains("民族精神")
        || lower.contains("national spirit")
        || lower.contains("national idea")
        || lower.contains("add spirit")
        || lower.contains("add idea")
        || lower.contains("spirit:")
        || lower.contains("idea:")
        || lower.contains("spirit：")
        || lower.contains("idea：")
}

fn request_text_mentions_dynamic_modifier(text: &str, lower: &str) -> bool {
    if text.contains("动态修正")
        || text.contains("动态修饰")
        || lower.contains("dynamic modifier")
        || lower.contains("dynamic_mod")
        || lower.contains("change_")
    {
        return true;
    }
    text.lines().any(|line| {
        let trimmed = line.trim();
        let lower_line = trimmed.to_ascii_lowercase();
        !request_line_mentions_non_dynamic_parent(trimmed, &lower_line)
            && (trimmed.contains("的效果") || lower_line.contains("effect"))
            && request_line_mentions_dynamic_modifier_value(trimmed, &lower_line)
    })
}

fn request_line_mentions_non_dynamic_parent(line: &str, lower: &str) -> bool {
    line.contains("民族精神")
        || line.contains("决议")
        || line.contains("国策")
        || line.contains("事件")
        || lower.contains("national spirit")
        || lower.contains("idea")
        || lower.contains("decision")
        || lower.contains("focus")
        || lower.contains("event")
}

fn request_line_mentions_dynamic_modifier_value(line: &str, lower: &str) -> bool {
    line.contains("建造速度")
        || line.contains("生产效率")
        || line.contains("工厂效率")
        || line.contains("工业产能")
        || lower.contains("factory")
        || lower.contains("efficiency")
        || lower.contains("production")
}

fn normalise_work_package_request_lane_lines(request: &str) -> String {
    let mut out = String::new();
    for raw_line in request.lines() {
        let mut line = raw_line.trim().to_string();
        for separator in ['；', ';'] {
            let needle = separator.to_string();
            line = line.replace(&needle, "\n");
        }
        if !request_line_starts_with_effect_lane(&line) {
            for label in work_package_request_lane_boundary_labels() {
                for sep in ["：", ":"] {
                    let needle = format!("{label}{sep}");
                    let replacement = format!("\n{label}{sep}");
                    line = line.replace(&needle, &replacement);
                }
            }
        }
        for part in line.lines() {
            let part = part.trim();
            if !part.is_empty() {
                out.push_str(part);
                out.push('\n');
            }
        }
    }
    out.trim().to_string()
}

fn filter_work_package_request_lanes(request: &str, allowed: &[AuthorWorkPackageLane]) -> String {
    let normalized = normalise_work_package_request_lane_lines(request);
    let mut current_lane: Option<AuthorWorkPackageLane> = None;
    let mut out = Vec::new();
    for raw_line in normalized.lines() {
        let line = raw_line.trim();
        if line.is_empty() {
            continue;
        }
        if let Some(lane) = explicit_work_package_request_line_lane(line) {
            current_lane = Some(lane);
            if allowed.contains(&lane) {
                out.push(line.to_string());
            }
            continue;
        }
        if let Some(lane) = contextual_work_package_request_line_lane(line, current_lane) {
            if explicit_contextual_lane_starter(line, lane) {
                current_lane = Some(lane);
            }
            if allowed.contains(&lane) {
                out.push(line.to_string());
            }
            continue;
        }
        if let Some(lane) = current_lane {
            if allowed.contains(&lane) {
                out.push(line.to_string());
            }
        }
    }
    out.join("\n")
}

fn explicit_work_package_request_line_lane(line: &str) -> Option<AuthorWorkPackageLane> {
    let trimmed = line.trim_start();
    let lower = trimmed.to_ascii_lowercase();
    let starts = |labels: &[&str]| {
        labels.iter().any(|label| {
            trimmed.starts_with(&format!("{label}："))
                || trimmed.starts_with(&format!("{label}:"))
                || lower.starts_with(&format!("{}:", label.to_ascii_lowercase()))
        })
    };
    if starts(&["国策", "focus", "national_focus", "national focus"]) {
        return Some(AuthorWorkPackageLane::Focus);
    }
    if starts(&[
        "事件",
        "事件链",
        "事件文案",
        "event",
        "event chain",
        "event text",
    ]) {
        return Some(AuthorWorkPackageLane::Event);
    }
    if starts(&["决议", "decision"]) {
        return Some(AuthorWorkPackageLane::Decision);
    }
    if starts(&[
        "民族精神",
        "national_spirit",
        "national spirit",
        "national idea",
        "idea",
    ]) {
        return Some(AuthorWorkPackageLane::NationalSpirit);
    }
    if starts(&[
        "动态修正",
        "动态修饰",
        "dynamic_modifier",
        "dynamic modifier",
    ]) {
        return Some(AuthorWorkPackageLane::DynamicModifier);
    }
    if starts(&["本地化", "localisation", "localization", "loc"]) {
        return Some(AuthorWorkPackageLane::Localisation);
    }
    if starts(&["intent"]) {
        return Some(AuthorWorkPackageLane::Intent);
    }
    None
}

fn contextual_work_package_request_line_lane(
    line: &str,
    current_lane: Option<AuthorWorkPackageLane>,
) -> Option<AuthorWorkPackageLane> {
    let trimmed = line.trim_start();
    let lower = trimmed.to_ascii_lowercase();
    if starts_any_label(
        trimmed,
        &lower,
        &[
            "事件键",
            "事件ID或命名空间",
            "命名空间",
            "类型",
            "图片",
            "触发",
            "立即效果",
            "收尾效果",
            "收尾隐藏效果",
            "选项",
            "选项条件",
            "提示",
            "效果预览",
            "隐藏效果",
            "AI权重",
            "后续事件",
            "延迟",
            "event_key",
            "namespace",
            "picture",
            "trigger",
            "option",
            "next_event",
            "delay",
        ],
    ) {
        return Some(AuthorWorkPackageLane::Event);
    }
    if current_lane == Some(AuthorWorkPackageLane::Event)
        && starts_any_label(
            trimmed,
            &lower,
            &["标题", "描述", "效果", "title", "description", "effect"],
        )
    {
        return Some(AuthorWorkPackageLane::Event);
    }
    if starts_any_label(
        trimmed,
        &lower,
        &["决议组", "分类", "category", "decision_category"],
    ) {
        return Some(AuthorWorkPackageLane::Decision);
    }
    if matches!(
        current_lane,
        Some(AuthorWorkPackageLane::Decision | AuthorWorkPackageLane::NationalSpirit)
    ) && starts_any_label(
        trimmed,
        &lower,
        &[
            "ID",
            "目标",
            "描述",
            "花费",
            "可见",
            "可用",
            "冷却",
            "移除",
            "效果",
            "id",
            "target",
            "description",
            "cost",
            "visible",
            "available",
            "cooldown",
            "remove",
            "effect",
        ],
    ) {
        return current_lane;
    }
    if current_lane == Some(AuthorWorkPackageLane::DynamicModifier)
        && starts_any_label(
            trimmed,
            &lower,
            &[
                "效果",
                "效果提示key",
                "变量",
                "临时变量",
                "调用效果",
                "scripted_effect",
                "effect",
                "variable",
            ],
        )
    {
        return Some(AuthorWorkPackageLane::DynamicModifier);
    }
    if current_lane == Some(AuthorWorkPackageLane::Localisation)
        && starts_any_label(
            trimmed,
            &lower,
            &["key", "value", "language", "context", "文本", "语言"],
        )
    {
        return Some(AuthorWorkPackageLane::Localisation);
    }
    if current_lane == Some(AuthorWorkPackageLane::Intent)
        && starts_any_label(trimmed, &lower, &["效果", "effect"])
    {
        return Some(AuthorWorkPackageLane::Intent);
    }
    None
}

fn explicit_contextual_lane_starter(line: &str, lane: AuthorWorkPackageLane) -> bool {
    let trimmed = line.trim_start();
    let lower = trimmed.to_ascii_lowercase();
    match lane {
        AuthorWorkPackageLane::Event => starts_any_label(
            trimmed,
            &lower,
            &[
                "事件键",
                "事件ID或命名空间",
                "命名空间",
                "event_key",
                "namespace",
            ],
        ),
        AuthorWorkPackageLane::Decision => starts_any_label(
            trimmed,
            &lower,
            &["决议组", "分类", "category", "decision_category"],
        ),
        _ => false,
    }
}

fn starts_any_label(trimmed: &str, lower: &str, labels: &[&str]) -> bool {
    labels.iter().any(|label| {
        trimmed.starts_with(&format!("{label}："))
            || trimmed.starts_with(&format!("{label}:"))
            || lower.starts_with(&format!("{}:", label.to_ascii_lowercase()))
    })
}

fn request_line_starts_with_effect_lane(line: &str) -> bool {
    let trimmed = line.trim_start();
    let lower = trimmed.to_ascii_lowercase();
    ["效果", "奖励", "收益", "隐藏效果", "效果预览"]
        .iter()
        .any(|label| {
            trimmed.starts_with(&format!("{label}：")) || trimmed.starts_with(&format!("{label}:"))
        })
        || [
            "effect:",
            "effects:",
            "reward:",
            "hidden_effect:",
            "effect_preview:",
        ]
        .iter()
        .any(|label| lower.starts_with(label))
}

fn work_package_request_lane_boundary_labels() -> Vec<&'static str> {
    vec![
        "国策",
        "事件链",
        "事件文案",
        "决议",
        "民族精神",
        "动态修正",
        "动态修饰",
        "本地化",
        "localisation",
        "localization",
        "focus",
        "event chain",
        "event text",
        "decision",
        "national spirit",
        "national idea",
        "dynamic modifier",
    ]
}

fn dynamic_modifier_intent_from_user_request(request: &str) -> String {
    if let Some(normalized) = model_normalized_intent(request) {
        if normalized.intent_type == "dynamic_modifier_change" {
            return model_normalized_dynamic_modifier_intent_text(&normalized);
        }
    }
    let mut lines = Vec::new();
    let normalized = normalise_work_package_request_lane_lines(request);
    for line in normalized.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let lower = trimmed.to_ascii_lowercase();
        if request_line_is_dynamic_modifier_intent(trimmed, &lower) {
            lines.push(trimmed.to_string());
        }
    }
    if lines.is_empty() {
        request.trim().to_string()
    } else {
        lines.join("\n")
    }
}

fn model_normalized_dynamic_modifier_intent_text(normalized: &ModelNormalizedIntent) -> String {
    let mut lines = Vec::new();
    lines.push("hoi4skill_intent:".to_string());
    lines.push("type: dynamic_modifier_change".to_string());
    if let Some(dynamic_modifier) = normalized.dynamic_modifier.as_deref() {
        lines.push(format!("dynamic_modifier: {dynamic_modifier}"));
    }
    if let Some(effects) = normalized.effects.as_deref() {
        lines.push(format!("effects: {effects}"));
    }
    lines.join("\n")
}

fn request_line_is_dynamic_modifier_intent(line: &str, lower: &str) -> bool {
    if line.contains("动态修正")
        || line.contains("动态修饰")
        || line.contains("调用协议")
        || lower.contains("dynamic modifier")
        || lower.contains("dynamic_mod")
        || lower.contains("custom_effect_tooltip")
        || lower.contains("set_temp_variable")
        || lower.contains("add_to_variable")
        || lower.contains("add_dynamic_modifier")
        || lower.contains("remove_dynamic_modifier")
        || lower.contains("has_dynamic_modifier")
        || lower.contains("change_")
    {
        return true;
    }
    !request_line_mentions_non_dynamic_parent(line, lower)
        && request_line_mentions_dynamic_modifier_value(line, lower)
        && (line.contains("的效果")
            || lower.contains("effect")
            || line.contains('+')
            || line.contains('-')
            || line.contains('='))
}

fn localisation_placeholders_from_user_request(request: &str) -> String {
    let mut lines = Vec::new();
    let mut include_next_plain_line = false;
    let mut localisation_context = false;
    let normalized = normalise_work_package_request_lane_lines(request);
    for line in normalized.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            include_next_plain_line = false;
            localisation_context = false;
            continue;
        }
        let lower = trimmed.to_ascii_lowercase();
        let explicit_localisation = request_line_is_localisation_text(trimmed, &lower);
        if localisation_context && request_line_is_localisation_metadata(trimmed, &lower) {
            lines.push(trimmed.to_string());
            continue;
        }
        if explicit_localisation || include_next_plain_line {
            lines.push(trimmed.to_string());
            include_next_plain_line =
                explicit_localisation && localisation_label_expects_continuation(trimmed);
            localisation_context = true;
            continue;
        }
        if trimmed.contains('【') && trimmed.contains('】') {
            lines.push(trimmed.to_string());
            localisation_context = true;
        }
    }
    if lines.is_empty() {
        request.trim().to_string()
    } else {
        lines.join("\n")
    }
}

fn request_line_is_localisation_metadata(line: &str, lower: &str) -> bool {
    line.starts_with("语言：")
        || line.starts_with("语言:")
        || line.starts_with("上下文：")
        || line.starts_with("上下文:")
        || line.starts_with("用途：")
        || line.starts_with("用途:")
        || lower.starts_with("language:")
        || lower.starts_with("lang:")
        || lower.starts_with("context:")
        || lower.starts_with("usage:")
}

fn request_line_is_localisation_text(line: &str, lower: &str) -> bool {
    line.contains("文案")
        || line.contains("本地化")
        || lower.contains("localisation")
        || lower.contains("localization")
        || lower.contains("loc:")
        || lower.contains("loc：")
        || lower.contains("text:")
        || lower.contains("text：")
}

fn localisation_label_expects_continuation(line: &str) -> bool {
    for label in [
        "事件文案",
        "文案",
        "本地化",
        "localisation",
        "localization",
        "loc",
        "text",
    ] {
        for sep in ["：", ":"] {
            let needle = format!("{label}{sep}");
            if let Some((_, rest)) = line.split_once(&needle) {
                return rest.trim().is_empty();
            }
        }
    }
    false
}

pub(crate) fn work_package_localisation_placeholder_preflight_json(
    text: &str,
) -> (String, Vec<String>) {
    let placeholders = collect_author_placeholders(text);
    let mut entries = Vec::new();
    let mut questions = Vec::new();
    let mut icon_count = 0usize;
    let mut country_count = 0usize;
    let mut unknown_count = 0usize;
    for placeholder in placeholders {
        let name = placeholder.name.trim();
        let (kind, question) = if author_color_placeholder(name).is_some() {
            ("color", None)
        } else if author_localisation_placeholder_replacement(name).is_some() {
            ("builtin_scope", None)
        } else if let Some(icon_name) = author_placeholder_icon_name(name) {
            icon_count += 1;
            (
                "icon",
                Some(format!(
                    "{} needs indexed icon evidence for `{}`; ask for an existing GFX sprite or icon asset authorization before final localisation.",
                    placeholder.text, icon_name
                )),
            )
        } else if author_placeholder_country_accessor(name).is_some() {
            let country_name = author_placeholder_country_name(name);
            country_count += 1;
            (
                "country_or_cosmetic_alias",
                Some(format!(
                    "{} needs country/cosmetic tag evidence for `{}` before compiling GetName/GetLeader/GetFlag.",
                    placeholder.text, country_name
                )),
            )
        } else {
            unknown_count += 1;
            (
                "unknown",
                Some(format!(
                    "{} is not a built-in placeholder; ask the user for an exact HOI4 scripted localisation token, icon, tag, or authorised new asset.",
                    placeholder.text
                )),
            )
        };
        if let Some(question) = question {
            questions.push(question);
        }
        entries.push(format!(
            "    {{\"placeholder\": {}, \"name\": {}, \"kind\": {}}}",
            json_str(&placeholder.text),
            json_str(name),
            json_str(kind)
        ));
    }
    questions = dedup_keep_order(questions);
    let json = format!(
        "{{\"placeholder_count\": {}, \"icon_count\": {}, \"country_or_cosmetic_count\": {}, \"unknown_count\": {}, \"requires_author_placeholder_plan\": {}, \"entries\": [\n{}\n  ], \"questions\": {}}}",
        entries.len(),
        icon_count,
        country_count,
        unknown_count,
        json_bool(!entries.is_empty()),
        entries.join(",\n"),
        json_array(&questions)
    );
    (json, questions)
}

fn write_ingested_input(path: &Path, snippet: &str, replace: bool) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
    }
    if replace {
        fs::write(path, snippet).map_err(|e| format!("write {}: {e}", path.display()))
    } else {
        let mut text = if path.exists() {
            read_utf8_lossy(path)?
        } else {
            String::new()
        };
        if !text.ends_with('\n') && !text.is_empty() {
            text.push('\n');
        }
        text.push_str(snippet);
        fs::write(path, text).map_err(|e| format!("write {}: {e}", path.display()))
    }
}

fn feature_cards_from_user_request(request: &str) -> String {
    if let Some(normalized) = model_normalized_intent(request) {
        if let Some(cards) = model_normalized_feature_cards_from_user_request(&normalized, request)
        {
            return cards;
        }
    }
    let mut out = String::new();
    let normalized_request = normalise_work_package_request_lane_lines(request);
    if let Some(structured) = structured_feature_cards_from_user_request(&normalized_request) {
        return structured;
    }
    let lower = normalized_request.to_ascii_lowercase();
    let feature_text = feature_text_from_user_request(&normalized_request);
    let compact_feature_text = compact_request_line(&feature_text);
    if request_mentions_decision(&normalized_request, &lower) {
        let decision_line = request_labeled_line(&normalized_request, &["决议", "decision"]);
        let decision_source = decision_line.as_deref().unwrap_or(&normalized_request);
        let title = extract_labeled_value(&normalized_request, &["决议", "decision"])
            .unwrap_or_else(|| "用户需求决议".to_string());
        let decision_effect = parent_line_effect_text(decision_source)
            .unwrap_or_else(|| compact_feature_text.clone());
        let cost = request_cost_value(decision_source).unwrap_or(25);
        out.push_str(&format!(
            "\n# Ingested user request: decision\n决议：{}\n描述：{}\n花费：{}\n效果：{}\n",
            title,
            cleanup_request_value(decision_source),
            cost,
            decision_effect
        ));
    }
    if request_mentions_national_spirit(&normalized_request, &lower) {
        if let Some(replacement) = extract_national_spirit_replacement_request(&normalized_request)
        {
            out.push_str(&format!(
                "\n# Ingested user request: national spirit replacement\n# swap_ideas belongs in intent/compile-intent; feature_cards defines the new national spirit.\n旧民族精神：{}\n新民族精神：{}\n民族精神：{}\n描述：{}\n效果：{}\n",
                replacement.old_name,
                replacement.new_name,
                replacement.new_name,
                compact_feature_text,
                replacement
                    .effect_text
                    .as_deref()
                    .unwrap_or_else(|| normalized_request.trim())
            ));
        } else {
            let spirit_line = request_labeled_line(
                &normalized_request,
                &[
                    "增加民族精神",
                    "新增民族精神",
                    "民族精神",
                    "national spirit",
                    "national idea",
                    "add spirit",
                    "add idea",
                    "spirit",
                    "idea",
                ],
            );
            let spirit_source = spirit_line.as_deref().unwrap_or(&normalized_request);
            let title = extract_labeled_value(
                spirit_source,
                &[
                    "增加民族精神",
                    "新增民族精神",
                    "民族精神",
                    "national spirit",
                    "national idea",
                    "add spirit",
                    "add idea",
                    "spirit",
                    "idea",
                ],
            )
            .unwrap_or_else(|| "用户需求民族精神".to_string());
            let effect = national_spirit_effect_text(&normalized_request, spirit_source, &title)
                .unwrap_or_else(|| compact_feature_text.clone());
            out.push_str(&format!(
                "\n# Ingested user request: national spirit\n民族精神：{}\n描述：{}\n效果：{}\n",
                title,
                cleanup_request_value(spirit_source),
                effect
            ));
        }
    }
    if out.is_empty() {
        out.push_str(&format!(
            "\n# Ingested user request: feature\n决议：用户需求决议\n描述：{}\n效果：{}\n",
            compact_feature_text, compact_feature_text
        ));
    }
    out
}

fn structured_feature_cards_from_user_request(request: &str) -> Option<String> {
    let mut lines = Vec::new();
    let mut feature_context = false;
    let mut saw_feature_header = false;
    let mut saw_structured_field = false;
    for line in request
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
    {
        let lower = line.to_ascii_lowercase();
        if request_line_is_feature_text(line, &lower) {
            lines.push(line.to_string());
            feature_context = true;
            saw_feature_header = true;
            continue;
        }
        if !feature_context {
            continue;
        }
        if request_line_is_focus_text(line, &lower)
            || request_line_is_event_text(line, &lower)
            || request_line_is_dynamic_modifier_start(line, &lower)
            || request_line_is_localisation_text(line, &lower)
        {
            feature_context = false;
            continue;
        }
        if request_line_is_feature_card_field(line, &lower) {
            lines.push(line.to_string());
            saw_structured_field = true;
        }
    }
    if saw_feature_header && saw_structured_field && !lines.is_empty() {
        Some(format!(
            "\n# Ingested user request: structured feature cards\n{}\n",
            lines.join("\n")
        ))
    } else {
        None
    }
}

fn request_line_is_feature_card_field(line: &str, lower: &str) -> bool {
    [
        "ID：",
        "ID:",
        "id：",
        "id:",
        "目标：",
        "目标:",
        "国家：",
        "国家:",
        "分类：",
        "分类:",
        "决议组：",
        "决议组:",
        "描述：",
        "描述:",
        "花费：",
        "花费:",
        "冷却：",
        "冷却:",
        "持续：",
        "持续:",
        "可见：",
        "可见:",
        "显示条件：",
        "显示条件:",
        "可用：",
        "可用:",
        "条件：",
        "条件:",
        "效果：",
        "效果:",
        "llm：",
        "llm:",
        "图标：",
        "图标:",
        "图片：",
        "图片:",
        "移除：",
        "移除:",
    ]
    .iter()
    .any(|prefix| line.starts_with(prefix))
        || lower.starts_with("target:")
        || lower.starts_with("country:")
        || lower.starts_with("category:")
        || lower.starts_with("cost:")
        || lower.starts_with("cooldown:")
        || lower.starts_with("duration:")
        || lower.starts_with("visible:")
        || lower.starts_with("available:")
        || lower.starts_with("effect:")
        || lower.starts_with("llm:")
        || lower.starts_with("icon:")
        || lower.starts_with("picture:")
        || lower.starts_with("remove:")
}

fn model_normalized_feature_cards_from_user_request(
    normalized: &ModelNormalizedIntent,
    request: &str,
) -> Option<String> {
    match normalized.intent_type.as_str() {
        "add_national_spirit" | "add_idea" => {
            let title = normalized.idea_name.as_deref()?;
            let effect = normalized.effects.as_deref().unwrap_or(request.trim());
            Some(format!(
                "\n# Ingested model-normalized request: national spirit\n民族精神：{}\n描述：{}\n效果：{}\n",
                title,
                cleanup_request_value(title),
                cleanup_request_value(effect)
            ))
        }
        "replace_national_spirit" | "replace_idea" | "swap_ideas" => {
            let old_name = normalized.old_idea.as_deref()?;
            let new_name = normalized.new_idea.as_deref()?;
            let effect = normalized.effects.as_deref().unwrap_or(request.trim());
            Some(format!(
                "\n# Ingested model-normalized request: national spirit replacement\n# swap_ideas belongs in intent/compile-intent; feature_cards defines the new national spirit.\n旧民族精神：{}\n新民族精神：{}\n民族精神：{}\n描述：{}\n效果：{}\n",
                old_name,
                new_name,
                new_name,
                cleanup_request_value(new_name),
                cleanup_request_value(effect)
            ))
        }
        _ => None,
    }
}

fn request_labeled_line(text: &str, labels: &[&str]) -> Option<String> {
    text.lines()
        .map(str::trim)
        .find(|line| {
            let lower = line.to_ascii_lowercase();
            labels
                .iter()
                .any(|label| line.contains(label) || lower.contains(&label.to_ascii_lowercase()))
        })
        .map(str::to_string)
}

fn request_cost_value(text: &str) -> Option<i32> {
    let lower = text.to_ascii_lowercase();
    if !(text.contains("花费") || text.contains("政治点") || lower.contains("cost")) {
        return None;
    }
    first_i32_in_text(text)
}

fn first_i32_in_text(text: &str) -> Option<i32> {
    let mut digits = String::new();
    for ch in text.chars() {
        if ch.is_ascii_digit() {
            digits.push(ch);
        } else if !digits.is_empty() {
            break;
        }
    }
    digits.parse::<i32>().ok()
}

fn national_spirit_effect_from_request_line(line: &str, title: &str) -> Option<String> {
    let markers = [
        format!("民族精神：{title}："),
        format!("民族精神:{title}:"),
        format!("增加民族精神：{title}："),
        format!("新增民族精神：{title}："),
        format!("national spirit:{title}:"),
        format!("add spirit:{title}:"),
    ];
    for marker in markers {
        if let Some((_, rest)) = line.split_once(&marker) {
            let effect = cleanup_request_value(rest);
            if !effect.is_empty() {
                return Some(effect);
            }
        }
    }
    parent_line_effect_text(line)
}

fn national_spirit_effect_text(request: &str, source_line: &str, title: &str) -> Option<String> {
    let mut parts = Vec::new();
    if let Some(effect) = national_spirit_effect_from_request_line(source_line, title) {
        parts.push(effect);
    }
    let mut in_target = false;
    for line in request.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            if in_target {
                break;
            }
            continue;
        }
        if trimmed == source_line.trim() {
            in_target = true;
            continue;
        }
        if !in_target {
            continue;
        }
        let lower = trimmed.to_ascii_lowercase();
        if request_line_is_localisation_text(trimmed, &lower)
            || request_line_is_event_text(trimmed, &lower)
            || request_line_is_focus_text(trimmed, &lower)
            || request_mentions_decision(trimmed, &lower)
            || request_line_is_dynamic_modifier_start(trimmed, &lower)
            || request_line_is_national_spirit_label(trimmed, &lower)
        {
            break;
        }
        if request_line_is_feature_effect_continuation(trimmed, &lower)
            || request_line_mentions_dynamic_modifier_value(trimmed, &lower)
        {
            parts.push(trimmed.to_string());
            continue;
        }
        break;
    }
    if parts.is_empty() {
        None
    } else {
        Some(compact_request_line(&parts.join("\n")))
    }
}

fn plain_localisation_entries_from_request(
    request: &str,
    prefix: &str,
) -> BTreeMap<String, String> {
    let mut entries = BTreeMap::new();
    let mut idx = 1usize;
    for line in normalise_work_package_request_lane_lines(request).lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.contains('【') || trimmed.contains('】') {
            continue;
        }
        let Some(value) = plain_localisation_line_value(trimmed) else {
            continue;
        };
        let value = cleanup_request_value(&value);
        if !is_alignment_text_candidate(&value) {
            continue;
        }
        let key = format!(
            "{}_user_loc_{}",
            sanitize_identifier_part(prefix, "mod"),
            idx
        );
        entries.insert(key, value);
        idx += 1;
    }
    entries
}

fn plain_localisation_line_value(line: &str) -> Option<String> {
    for label in ["本地化", "localisation", "localization", "loc"] {
        for sep in ["：", ":"] {
            let needle = format!("{label}{sep}");
            if let Some((_, rest)) = line.split_once(&needle) {
                let value = cleanup_request_value(rest);
                if !value.is_empty() {
                    return Some(value);
                }
            }
        }
    }
    None
}

fn feature_text_from_user_request(request: &str) -> String {
    let mut lines = Vec::new();
    let mut feature_context = false;
    let normalized = normalise_work_package_request_lane_lines(request);
    for line in normalized.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            feature_context = false;
            continue;
        }
        let lower = trimmed.to_ascii_lowercase();
        if request_line_is_feature_text(trimmed, &lower) {
            lines.push(trimmed.to_string());
            feature_context = true;
            continue;
        }
        if feature_context
            && !request_line_is_dynamic_modifier_start(trimmed, &lower)
            && request_line_is_feature_effect_continuation(trimmed, &lower)
        {
            lines.push(trimmed.to_string());
            continue;
        }
        if request_line_is_dynamic_modifier_intent(trimmed, &lower)
            && !request_line_is_feature_text(trimmed, &lower)
        {
            feature_context = false;
            continue;
        }
        if request_line_is_localisation_text(trimmed, &lower)
            || request_line_is_event_text(trimmed, &lower)
            || request_line_is_focus_text(trimmed, &lower)
        {
            feature_context = false;
            continue;
        }
    }
    if lines.is_empty() {
        request.trim().to_string()
    } else {
        lines.join("\n")
    }
}

fn request_line_is_feature_text(line: &str, lower: &str) -> bool {
    line.contains("决议")
        || line.contains("民族精神")
        || line.contains("增加民族精神")
        || lower.contains("decision")
        || lower.contains("national spirit")
        || lower.contains("national idea")
        || lower.contains("add spirit")
        || lower.contains("add idea")
        || lower.contains("spirit:")
        || lower.contains("idea:")
        || lower.contains("spirit：")
        || lower.contains("idea：")
}

fn request_line_is_feature_effect_continuation(line: &str, lower: &str) -> bool {
    !request_line_is_localisation_text(line, lower)
        && !request_line_is_event_text(line, lower)
        && !request_line_is_focus_text(line, lower)
        && (line.contains("效果")
            || line.contains("稳定")
            || line.contains("政治点")
            || line.contains("战争支持")
            || line.contains("建造速度")
            || line.contains("生产效率")
            || lower.contains("effect")
            || lower.contains("stability")
            || lower.contains("political power")
            || lower.contains("war support")
            || line.contains('+')
            || line.contains('-')
            || line.contains('='))
}

fn request_line_is_dynamic_modifier_start(line: &str, lower: &str) -> bool {
    line.contains("动态修正")
        || line.contains("动态修饰")
        || lower.contains("dynamic modifier")
        || lower.contains("dynamic_mod")
        || lower.contains("change_")
        || (!request_line_mentions_non_dynamic_parent(line, lower)
            && request_line_mentions_dynamic_modifier_value(line, lower)
            && (line.contains("的效果") || lower.contains("effect")))
}

fn focus_layout_from_user_request(request: &str, prefix: &str) -> String {
    let normalized = normalise_work_package_request_lane_lines(request);
    let mut layout_lines = Vec::new();
    for line in normalized
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
    {
        let lower = line.to_ascii_lowercase();
        if !request_line_is_focus_text(line, &lower) {
            continue;
        }
        let body = strip_work_package_lane_prefix(line, &["国策", "focus", "Focus"])
            .unwrap_or_else(|| line.to_string());
        if body.contains('|')
            && (body.contains("id =")
                || body.contains("x =")
                || body.contains("y =")
                || body.contains("icon =")
                || body.contains("奖励 =")
                || body.contains("前置 =")
                || body.contains("relative_position_id ="))
        {
            layout_lines.push(body);
        }
    }
    if !layout_lines.is_empty() {
        return format!(
            "\n# Ingested user request: focus\n{}\n",
            layout_lines.join("\n")
        );
    }
    let title = extract_labeled_value(&normalized, &["国策", "focus", "Focus"])
        .unwrap_or_else(|| "用户需求国策".to_string());
    let focus_reward = focus_reward_from_user_request(request);
    format!(
        "\n# Ingested user request: focus\n{} | id = {}_{} | x = 0 | y = 0 | 奖励 = {}\n",
        title,
        prefix,
        ascii_slug(&title),
        compact_request_line(&focus_reward)
    )
}

fn strip_work_package_lane_prefix(line: &str, labels: &[&str]) -> Option<String> {
    let trimmed = line.trim();
    let lower = trimmed.to_ascii_lowercase();
    for label in labels {
        for sep in ["：", ":"] {
            let needle = format!("{label}{sep}");
            let lower_needle = needle.to_ascii_lowercase();
            if lower.starts_with(&lower_needle) {
                return trimmed
                    .get(needle.len()..)
                    .map(cleanup_request_value)
                    .filter(|value| !value.is_empty());
            }
        }
    }
    None
}

fn focus_reward_from_user_request(request: &str) -> String {
    let mut lines = Vec::new();
    let mut focus_context = false;
    let normalized = normalise_work_package_request_lane_lines(request);
    for line in normalized.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            focus_context = false;
            continue;
        }
        let lower = trimmed.to_ascii_lowercase();
        if request_line_is_focus_text(trimmed, &lower) {
            if let Some(effect) = parent_line_effect_text(trimmed) {
                if !effect_is_incomplete_add_marker(&effect) && !effect.contains("民族精神") {
                    lines.push(effect);
                }
            }
            focus_context = true;
            continue;
        }
        if focus_context && request_line_is_focus_reward_continuation(trimmed, &lower) {
            lines.push(trimmed.to_string());
            continue;
        }
        if request_line_is_localisation_text(trimmed, &lower)
            || request_line_is_event_text(trimmed, &lower)
            || request_line_is_feature_text(trimmed, &lower)
            || request_line_is_dynamic_modifier_start(trimmed, &lower)
        {
            focus_context = false;
        }
    }
    if lines.is_empty() {
        "add_political_power = 50".to_string()
    } else {
        lines.join("\n")
    }
}

fn intent_text_from_user_request(request: &str) -> String {
    if model_normalized_intent(request).is_some() {
        return request.trim().to_string();
    }
    let mut lines = Vec::new();
    let mut skip_next_localisation_line = false;
    let mut dynamic_context = false;
    let mut pending_add_national_spirit = false;
    let normalized = normalise_work_package_request_lane_lines(request);
    for line in normalized.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            skip_next_localisation_line = false;
            dynamic_context = false;
            pending_add_national_spirit = false;
            continue;
        }
        let lower = trimmed.to_ascii_lowercase();
        if skip_next_localisation_line {
            skip_next_localisation_line = false;
            continue;
        }
        if dynamic_context && request_line_is_dynamic_modifier_continuation(trimmed, &lower) {
            continue;
        }
        if pending_add_national_spirit && request_line_is_national_spirit_label(trimmed, &lower) {
            lines.push(format!("增加{}", trimmed));
            pending_add_national_spirit = false;
            dynamic_context = false;
            continue;
        }
        pending_add_national_spirit = false;
        if request_line_is_localisation_text(trimmed, &lower) || trimmed.contains('【') {
            skip_next_localisation_line = localisation_label_expects_continuation(trimmed);
            dynamic_context = false;
            continue;
        }
        if request_line_is_dynamic_modifier_start(trimmed, &lower) {
            dynamic_context = true;
            continue;
        }
        if request_line_is_focus_text(trimmed, &lower) || request_mentions_decision(trimmed, &lower)
        {
            if let Some(effect) = parent_line_effect_text(trimmed) {
                if effect_is_incomplete_add_marker(&effect) {
                    pending_add_national_spirit = true;
                } else if !effect.trim().is_empty() {
                    lines.push(effect);
                }
            }
            continue;
        }
        if request_line_is_intent_effect_text(trimmed, &lower) {
            dynamic_context = false;
            lines.push(trimmed.to_string());
        }
    }
    if lines.is_empty() {
        request.trim().to_string()
    } else {
        lines.join("\n")
    }
}

fn request_line_is_intent_effect_text(line: &str, lower: &str) -> bool {
    line.contains("效果")
        || line.contains("奖励")
        || line.contains("替换")
        || line.contains("换为")
        || line.contains("增加")
        || line.contains("移除")
        || line.contains("稳定")
        || line.contains("政治点")
        || line.contains("战争支持")
        || lower.contains("effect")
        || lower.contains("reward")
        || lower.contains("replace")
        || lower.contains("swap")
        || lower.contains("stability")
        || lower.contains("political power")
        || lower.contains("war support")
        || line.contains('+')
        || line.contains('-')
        || line.contains('=')
}

fn parent_line_effect_text(line: &str) -> Option<String> {
    for marker in [
        "效果：",
        "效果:",
        "效果为",
        "效果",
        "reward:",
        "reward：",
        "effect:",
        "effect：",
    ] {
        if let Some((_, rest)) = line.split_once(marker) {
            let effect = cleanup_request_value(rest);
            if !effect.is_empty() {
                return Some(effect);
            }
        }
    }
    None
}

fn effect_is_incomplete_add_marker(effect: &str) -> bool {
    matches!(
        effect.trim(),
        "增加" | "新增" | "添加" | "获得" | "add" | "Add"
    )
}

fn request_line_is_national_spirit_label(line: &str, lower: &str) -> bool {
    line.contains("民族精神")
        || lower.contains("national spirit")
        || lower.contains("national idea")
}

fn request_line_is_dynamic_modifier_continuation(line: &str, lower: &str) -> bool {
    request_line_mentions_dynamic_modifier_value(line, lower)
        || lower.contains("custom_effect_tooltip")
        || lower.contains("set_temp_variable")
        || lower.contains("add_to_variable")
        || lower.contains("add_dynamic_modifier")
        || lower.contains("remove_dynamic_modifier")
        || lower.contains("has_dynamic_modifier")
        || lower.contains("change_")
        || line.contains("调用协议")
}

fn request_line_is_focus_reward_continuation(line: &str, lower: &str) -> bool {
    !request_line_is_localisation_text(line, lower)
        && !request_line_is_event_text(line, lower)
        && !request_line_is_dynamic_modifier_start(line, lower)
        && (line.contains("效果")
            || line.contains("奖励")
            || line.contains("增加")
            || line.contains("移除")
            || line.contains("替换")
            || lower.contains("effect")
            || lower.contains("reward")
            || lower.contains("add ")
            || lower.contains("remove ")
            || line.contains('+')
            || line.contains('-')
            || line.contains('='))
}

fn request_line_is_event_text(line: &str, lower: &str) -> bool {
    line.contains("事件") || lower.contains("event")
}

fn request_line_is_event_title_text(line: &str, lower: &str) -> bool {
    line.contains("事件：")
        || line.contains("事件:")
        || line.contains("事件链：")
        || line.contains("事件链:")
        || lower.contains("event:")
        || lower.contains("event chain:")
}

fn request_line_is_focus_text(line: &str, lower: &str) -> bool {
    line.contains("国策") || lower.contains("focus")
}

#[derive(Clone, Debug)]
struct UserEventOptionDirective {
    key: String,
    title: String,
    effect: Option<String>,
    condition: Option<String>,
    tooltip: Option<String>,
    effect_preview: Option<String>,
    hidden_effect: Option<String>,
    ai_chance: Option<String>,
    follow_up: Option<String>,
    delay: Option<String>,
}

impl UserEventOptionDirective {
    fn new(key: &str) -> Self {
        Self {
            key: key.to_string(),
            title: "继续".to_string(),
            effect: None,
            condition: None,
            tooltip: None,
            effect_preview: None,
            hidden_effect: None,
            ai_chance: None,
            follow_up: None,
            delay: None,
        }
    }
}

pub(crate) fn event_cards_from_user_request(request: &str, namespace: &str) -> String {
    let normalized_request = normalise_work_package_request_lane_lines(request);
    let mut titles = extract_event_chain_titles(&normalized_request);
    if titles.len() == 1 {
        let follow_up = if titles[0] == "用户需求事件" {
            "用户需求后续事件".to_string()
        } else {
            format!("{}后续", titles[0])
        };
        push_unique_clean_title(&mut titles, &follow_up);
    }
    let description = event_description_from_user_request(&normalized_request);
    let event_type = event_labeled_value(&normalized_request, &["类型", "type"])
        .unwrap_or_else(|| "country_event".to_string());
    let picture = event_labeled_value(&normalized_request, &["图片", "picture"]);
    let trigger = event_labeled_value(&normalized_request, &["触发", "trigger"]);
    let explicit_event_key = event_labeled_value(&normalized_request, &["事件键", "event_key"]);
    let effective_namespace = event_labeled_value(&normalized_request, &["命名空间", "namespace"])
        .unwrap_or_else(|| namespace.to_string());
    let mut option_directives = event_option_directives_from_user_request(&normalized_request);
    if option_directives.is_empty() {
        option_directives.push(UserEventOptionDirective {
            key: "A".to_string(),
            title: "继续".to_string(),
            effect: None,
            condition: None,
            tooltip: None,
            effect_preview: None,
            hidden_effect: None,
            ai_chance: None,
            follow_up: None,
            delay: None,
        });
    }
    let mut out = String::from("\n# Ingested user request: event chain\n");
    for (idx, title) in titles.iter().enumerate() {
        let event_key = if idx == 0 {
            explicit_event_key
                .as_deref()
                .map(cleanup_request_value)
                .filter(|value| !value.is_empty())
                .unwrap_or_else(|| ascii_slug(title))
        } else {
            ascii_slug(title)
        };
        out.push_str(&format!(
            "事件键：{}\n事件：{}\n类型：{}\n命名空间：{}\n标题：{}\n描述：{}\n",
            event_key,
            title,
            event_type,
            effective_namespace.as_str(),
            title,
            if idx == 0 {
                description.as_str()
            } else {
                title.as_str()
            }
        ));
        if let Some(picture) = picture.as_deref() {
            out.push_str(&format!("图片：{}\n", picture));
        }
        if let Some(trigger) = trigger.as_deref() {
            out.push_str(&format!("触发：{}\n", trigger));
        }
        if idx == 0 {
            if let Some(value) = event_labeled_value(
                &normalized_request,
                &["立即效果", "事件立即效果", "immediate"],
            ) {
                out.push_str(&format!(
                    "立即效果：{}\n",
                    event_effect_from_user_text(&value)
                ));
            }
            if let Some(value) =
                event_labeled_value(&normalized_request, &["收尾效果", "after_effect"])
            {
                out.push_str(&format!(
                    "收尾效果：{}\n",
                    event_effect_from_user_text(&value)
                ));
            }
            if let Some(value) = event_labeled_value(
                &normalized_request,
                &["收尾隐藏效果", "事件后隐藏效果", "after_hidden_effect"],
            ) {
                out.push_str(&format!(
                    "收尾隐藏效果：{}\n",
                    event_effect_from_user_text(&value)
                ));
            }
        }
        if idx == 0 {
            for option in &option_directives {
                out.push_str(&format!("选项{}：{}\n", option.key, option.title));
                if let Some(condition) = option.condition.as_deref() {
                    out.push_str(&format!("选项{}条件：{}\n", option.key, condition));
                }
                if let Some(tooltip) = option.tooltip.as_deref() {
                    out.push_str(&format!("提示{}：{}\n", option.key, tooltip));
                }
                if let Some(effect_preview) = option.effect_preview.as_deref() {
                    out.push_str(&format!(
                        "效果预览{}：{}\n",
                        option.key,
                        event_effect_from_user_text(effect_preview)
                    ));
                }
                if let Some(effect) = option.effect.as_deref() {
                    out.push_str(&format!("效果{}：{}\n", option.key, effect));
                }
                if let Some(hidden_effect) = option.hidden_effect.as_deref() {
                    out.push_str(&format!(
                        "隐藏效果{}：{}\n",
                        option.key,
                        event_effect_from_user_text(hidden_effect)
                    ));
                }
                if let Some(ai_chance) = option.ai_chance.as_deref() {
                    out.push_str(&format!("AI权重{}：{}\n", option.key, ai_chance));
                }
                if let Some(follow_up) = option
                    .follow_up
                    .as_deref()
                    .or_else(|| titles.get(1).map(String::as_str))
                {
                    out.push_str(&format!("后续事件{}：{}\n", option.key, follow_up));
                    out.push_str(&format!(
                        "延迟{}：{}\n",
                        option.key,
                        option.delay.as_deref().unwrap_or("1")
                    ));
                }
            }
        } else {
            out.push_str("选项A：继续\n");
            if let Some(next_title) = titles.get(idx + 1) {
                out.push_str(&format!("后续事件A：{}\n延迟A：1\n", next_title));
            }
        }
        out.push('\n');
    }
    out
}

fn event_option_directives_from_user_request(request: &str) -> Vec<UserEventOptionDirective> {
    let mut options: BTreeMap<String, UserEventOptionDirective> = BTreeMap::new();
    for line in request
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
    {
        if let Some((key, title)) = split_lettered_labeled_value(line, "选项", "option") {
            let entry = options
                .entry(key.clone())
                .or_insert_with(|| UserEventOptionDirective {
                    key: key.clone(),
                    title: "继续".to_string(),
                    effect: None,
                    condition: None,
                    tooltip: None,
                    effect_preview: None,
                    hidden_effect: None,
                    ai_chance: None,
                    follow_up: None,
                    delay: None,
                });
            entry.title = cleanup_request_value(&title);
            continue;
        }
        if let Some((key, effect)) = split_lettered_labeled_value(line, "效果", "effect") {
            let entry = options
                .entry(key.clone())
                .or_insert_with(|| UserEventOptionDirective {
                    key: key.clone(),
                    title: "继续".to_string(),
                    effect: None,
                    condition: None,
                    tooltip: None,
                    effect_preview: None,
                    hidden_effect: None,
                    ai_chance: None,
                    follow_up: None,
                    delay: None,
                });
            entry.effect = Some(event_effect_from_user_text(&effect));
            continue;
        }
        if let Some((key, condition)) =
            split_chinese_option_middle_labeled_value(line, &["条件", "触发条件", "可见条件"])
                .or_else(|| split_lettered_labeled_value(line, "选项条件", "option condition"))
                .or_else(|| split_lettered_labeled_value(line, "选项触发条件", "option trigger"))
                .or_else(|| split_lettered_labeled_value(line, "条件", "condition"))
        {
            let entry = options
                .entry(key.clone())
                .or_insert_with(|| UserEventOptionDirective::new(&key));
            entry.condition = Some(cleanup_request_value(&condition));
            continue;
        }
        if let Some((key, tooltip)) = split_lettered_labeled_value(line, "提示", "tooltip") {
            let entry = options
                .entry(key.clone())
                .or_insert_with(|| UserEventOptionDirective::new(&key));
            entry.tooltip = Some(cleanup_request_value(&tooltip));
            continue;
        }
        if let Some((key, preview)) =
            split_lettered_labeled_value(line, "效果预览", "effect preview")
                .or_else(|| split_lettered_labeled_value(line, "效果提示", "effect tooltip"))
        {
            let entry = options
                .entry(key.clone())
                .or_insert_with(|| UserEventOptionDirective::new(&key));
            entry.effect_preview = Some(cleanup_request_value(&preview));
            continue;
        }
        if let Some((key, hidden)) = split_lettered_labeled_value(line, "隐藏效果", "hidden effect")
        {
            let entry = options
                .entry(key.clone())
                .or_insert_with(|| UserEventOptionDirective::new(&key));
            entry.hidden_effect = Some(cleanup_request_value(&hidden));
            continue;
        }
        if let Some((key, ai_chance)) = split_lettered_labeled_value(line, "AI权重", "ai chance")
            .or_else(|| split_lettered_labeled_value(line, "ai权重", "ai"))
        {
            let entry = options
                .entry(key.clone())
                .or_insert_with(|| UserEventOptionDirective::new(&key));
            entry.ai_chance = Some(cleanup_request_value(&ai_chance));
            continue;
        }
        if let Some((key, follow_up)) = split_lettered_labeled_value(line, "后续事件", "next event")
        {
            let entry = options
                .entry(key.clone())
                .or_insert_with(|| UserEventOptionDirective {
                    key: key.clone(),
                    title: "继续".to_string(),
                    effect: None,
                    condition: None,
                    tooltip: None,
                    effect_preview: None,
                    hidden_effect: None,
                    ai_chance: None,
                    follow_up: None,
                    delay: None,
                });
            entry.follow_up = Some(cleanup_request_value(&follow_up));
            continue;
        }
        if let Some((key, delay)) = split_lettered_labeled_value(line, "延迟", "delay") {
            let entry = options
                .entry(key.clone())
                .or_insert_with(|| UserEventOptionDirective {
                    key: key.clone(),
                    title: "继续".to_string(),
                    effect: None,
                    condition: None,
                    tooltip: None,
                    effect_preview: None,
                    hidden_effect: None,
                    ai_chance: None,
                    follow_up: None,
                    delay: None,
                });
            entry.delay = Some(cleanup_request_value(&delay));
        }
    }
    options.into_values().collect()
}

fn split_lettered_labeled_value(
    line: &str,
    chinese_label: &str,
    english_label: &str,
) -> Option<(String, String)> {
    for sep in ["：", ":"] {
        let marker = format!("{chinese_label}{sep}");
        if let Some(rest) = line.trim_start().strip_prefix(&marker) {
            return Some(("A".to_string(), rest.trim().to_string()));
        }
    }
    let after_chinese = line.strip_prefix(chinese_label).or_else(|| {
        let lower = line.to_ascii_lowercase();
        lower
            .strip_prefix(english_label)
            .and_then(|_| line.get(english_label.len()..))
    })?;
    let after_chinese = after_chinese.trim_start();
    let mut chars = after_chinese.chars();
    let key_ch = chars.next()?;
    if !key_ch.is_ascii_alphanumeric() {
        return None;
    }
    let rest = chars.as_str().trim_start();
    let rest = rest
        .strip_prefix('：')
        .or_else(|| rest.strip_prefix(':'))?
        .trim();
    Some((key_ch.to_ascii_uppercase().to_string(), rest.to_string()))
}

fn split_chinese_option_middle_labeled_value(
    line: &str,
    tails: &[&str],
) -> Option<(String, String)> {
    let rest = line.trim_start().strip_prefix("选项")?;
    let mut chars = rest.chars();
    let key_ch = chars.next()?;
    if !key_ch.is_ascii_alphanumeric() {
        return None;
    }
    let rest = chars.as_str();
    for tail in tails {
        for sep in ["：", ":"] {
            let marker = format!("{tail}{sep}");
            if let Some(value) = rest.strip_prefix(&marker) {
                return Some((
                    key_ch.to_ascii_uppercase().to_string(),
                    value.trim().to_string(),
                ));
            }
        }
    }
    None
}

fn event_labeled_value(text: &str, labels: &[&str]) -> Option<String> {
    text.lines()
        .find_map(|line| split_labeled_value(line.trim(), labels))
        .map(cleanup_request_value)
        .filter(|value| !value.is_empty())
}

fn event_effect_from_user_text(text: &str) -> String {
    let cleaned = cleanup_request_value(text);
    if cleaned.contains('=') {
        return cleaned;
    }
    let lower = cleaned.to_ascii_lowercase();
    if cleaned.contains("政治点")
        || cleaned.contains("政治力量")
        || lower.contains("political power")
    {
        if let Some(value) = signed_number_text(&cleaned) {
            return format!("add_political_power = {value}");
        }
    }
    if cleaned.contains("稳定") || lower.contains("stability") {
        if let Some(value) = signed_percent_or_decimal_text(&cleaned) {
            return format!("add_stability = {value}");
        }
    }
    if cleaned.contains("战争支持") || cleaned.contains("战争支援") || lower.contains("war support")
    {
        if let Some(value) = signed_percent_or_decimal_text(&cleaned) {
            return format!("add_war_support = {value}");
        }
    }
    cleaned
}

fn signed_number_text(text: &str) -> Option<String> {
    let mut sign = "";
    let mut digits = String::new();
    for ch in text.chars() {
        if (ch == '+' || ch == '-') && digits.is_empty() {
            sign = if ch == '-' { "-" } else { "" };
            continue;
        }
        if ch.is_ascii_digit() {
            digits.push(ch);
            continue;
        }
        if !digits.is_empty() {
            break;
        }
    }
    (!digits.is_empty()).then(|| format!("{sign}{digits}"))
}

fn signed_percent_or_decimal_text(text: &str) -> Option<String> {
    let sign = if text.contains('-') { -1.0 } else { 1.0 };
    let mut number = String::new();
    let mut seen_digit = false;
    for ch in text.chars() {
        if ch.is_ascii_digit() || (ch == '.' && seen_digit && !number.contains('.')) {
            seen_digit = true;
            number.push(ch);
            continue;
        }
        if seen_digit {
            break;
        }
    }
    let mut value = number.parse::<f64>().ok()? * sign;
    if text.contains('%') || text.contains('％') {
        value /= 100.0;
    }
    Some(
        format!("{value:.4}")
            .trim_end_matches('0')
            .trim_end_matches('.')
            .to_string(),
    )
}

fn event_description_from_user_request(request: &str) -> String {
    let mut include_next_plain_line = false;
    let mut collected = Vec::new();
    let mut collecting_description = false;
    let normalized = normalise_work_package_request_lane_lines(request);
    for line in normalized.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            if collecting_description {
                break;
            }
            include_next_plain_line = false;
            continue;
        }
        let lower = trimmed.to_ascii_lowercase();
        if collecting_description {
            if event_description_continuation_stopper(trimmed, &lower) {
                break;
            }
            collected.push(trimmed.to_string());
            continue;
        }
        if include_next_plain_line {
            if !event_description_continuation_stopper(trimmed, &lower) {
                collected.push(trimmed.to_string());
                collecting_description = true;
                continue;
            }
            include_next_plain_line = false;
        }
        if let Some(value) = event_description_line_value(trimmed) {
            if value.is_empty() {
                include_next_plain_line = true;
            } else {
                collected.push(value.trim().to_string());
                collecting_description = true;
            }
        }
    }
    if !collected.is_empty() {
        return collected.join("\n");
    }
    request.trim().to_string()
}

fn event_description_continuation_stopper(line: &str, lower: &str) -> bool {
    request_line_is_feature_text(line, lower)
        || request_line_is_focus_text(line, lower)
        || request_line_is_dynamic_modifier_start(line, lower)
        || request_line_is_event_title_text(line, lower)
        || event_description_field_label(
            line,
            &[
                "事件键",
                "event_key",
                "类型",
                "type",
                "命名空间",
                "namespace",
                "标题",
                "title",
                "图片",
                "picture",
                "触发",
                "trigger",
                "选项",
                "option",
                "效果",
                "effect",
                "后续事件",
                "next_event",
                "延迟",
                "delay",
                "立即效果",
                "immediate",
                "收尾效果",
                "after_effect",
                "收尾隐藏效果",
                "after_hidden_effect",
                "提示",
                "tooltip",
                "AI权重",
                "ai_chance",
            ],
        )
}

fn event_description_field_label(line: &str, labels: &[&str]) -> bool {
    let lower = line.to_ascii_lowercase();
    labels.iter().any(|label| {
        let label = label.to_ascii_lowercase();
        if ["：", ":"]
            .iter()
            .any(|sep| lower.starts_with(&format!("{label}{sep}")))
        {
            return true;
        }
        let Some(rest) = lower.strip_prefix(&label) else {
            return false;
        };
        let Some(sep_idx) = rest.find(['：', ':']) else {
            return false;
        };
        let suffix = &rest[..sep_idx];
        !suffix.is_empty()
            && suffix.len() <= 16
            && suffix
                .chars()
                .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | ' '))
    })
}

fn event_description_line_value(line: &str) -> Option<String> {
    for label in [
        "事件文案",
        "文案",
        "描述",
        "event text",
        "event desc",
        "desc",
    ] {
        for sep in ["：", ":"] {
            let needle = format!("{label}{sep}");
            if let Some((_, rest)) = line.split_once(&needle) {
                return Some(rest.trim().to_string());
            }
        }
    }
    None
}

fn extract_event_chain_titles(request: &str) -> Vec<String> {
    let mut titles = Vec::new();
    for line in request.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        if let Some(rest) = split_event_chain_line(trimmed) {
            for title in split_event_chain_titles(rest) {
                push_unique_clean_title(&mut titles, &title);
            }
            continue;
        }
        if let Some(title) = split_numbered_event_title(trimmed) {
            push_unique_clean_title(&mut titles, title);
            continue;
        }
        if let Some(title) = split_labeled_value(trimmed, &["事件", "后续事件", "后续事件A"])
        {
            push_unique_clean_title(&mut titles, title);
        }
    }
    if titles.is_empty() {
        titles.push(
            extract_labeled_value(request, &["事件"]).unwrap_or_else(|| "用户需求事件".to_string()),
        );
    }
    titles
}

fn split_event_chain_line(line: &str) -> Option<&str> {
    line.split_once("事件链：")
        .or_else(|| line.split_once("事件链:"))
        .map(|(_, rest)| rest.trim())
}

fn split_event_chain_titles(rest: &str) -> Vec<String> {
    let normalized = rest.replace("->", "→").replace("=>", "→");
    normalized
        .split(&['→', '>', '、', ',', '，', ';', '；'][..])
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .map(str::to_string)
        .collect()
}

fn split_numbered_event_title(line: &str) -> Option<&str> {
    let trimmed = line.trim_start_matches("事件");
    if trimmed == line {
        return None;
    }
    let trimmed = trimmed.trim_start_matches(|ch: char| {
        ch.is_ascii_digit()
            || matches!(
                ch,
                '一' | '二' | '三' | '四' | '五' | '六' | '七' | '八' | '九' | '十'
            )
    });
    trimmed
        .strip_prefix('：')
        .or_else(|| trimmed.strip_prefix(':'))
        .map(str::trim)
}

fn split_labeled_value<'a>(line: &'a str, labels: &[&str]) -> Option<&'a str> {
    labels.iter().find_map(|label| {
        line.split_once(&format!("{label}："))
            .or_else(|| line.split_once(&format!("{label}:")))
            .map(|(_, rest)| rest.trim())
    })
}

fn push_unique_clean_title(titles: &mut Vec<String>, title: &str) {
    let title = cleanup_request_value(title);
    if title.is_empty() || title.contains("文案") {
        return;
    }
    if !titles.iter().any(|existing| existing == &title) {
        titles.push(title);
    }
}

struct NationalSpiritReplacementRequest {
    old_name: String,
    new_name: String,
    effect_text: Option<String>,
}

fn extract_national_spirit_replacement_request(
    text: &str,
) -> Option<NationalSpiritReplacementRequest> {
    let explicit_old = extract_labeled_value(text, &["旧民族精神", "原民族精神", "旧idea"]);
    let explicit_new = extract_labeled_value(text, &["新民族精神", "目标民族精神", "新idea"]);
    if let (Some(old_name), Some(new_name)) = (explicit_old, explicit_new) {
        return Some(NationalSpiritReplacementRequest {
            old_name,
            new_name,
            effect_text: extract_replacement_effect_text(text),
        });
    }

    let after_label = text
        .split_once("民族精神：")
        .or_else(|| text.split_once("民族精神:"))
        .map(|(_, rest)| rest.trim())?;
    let (old_name, rest) = after_label
        .split_once("替换为")
        .or_else(|| after_label.split_once("换为"))?;
    let old_name = cleanup_request_value(old_name);
    let (new_name, effect_text) = split_replacement_target_and_effect(rest);
    if old_name.is_empty() || new_name.is_empty() {
        return None;
    }
    Some(NationalSpiritReplacementRequest {
        old_name,
        new_name,
        effect_text,
    })
}

fn split_replacement_target_and_effect(rest: &str) -> (String, Option<String>) {
    for marker in ["效果为", "效果：", "效果:", "效果"] {
        if let Some((name, effect)) = rest.split_once(marker) {
            let name = cleanup_request_value(name);
            let effect = cleanup_request_value(effect);
            return (name, (!effect.is_empty()).then_some(effect));
        }
    }
    (cleanup_request_value(rest), None)
}

fn extract_replacement_effect_text(text: &str) -> Option<String> {
    for marker in ["效果为", "效果：", "效果:", "效果"] {
        if let Some((_, effect)) = text.split_once(marker) {
            let effect = cleanup_request_value(effect);
            if !effect.is_empty() {
                return Some(effect);
            }
        }
    }
    None
}

fn cleanup_request_value(value: &str) -> String {
    value
        .trim()
        .trim_matches(['，', ',', '。', ';', '；', ':', '：'])
        .trim()
        .to_string()
}

fn extract_labeled_value(text: &str, labels: &[&str]) -> Option<String> {
    for label in labels {
        for sep in ["：", ":"] {
            if let Some(rest) = split_once_labeled_rest(text, label, sep) {
                let value = rest
                    .lines()
                    .next()
                    .unwrap_or("")
                    .split(['，', ',', '。', ';', '；', '：', ':'])
                    .next()
                    .unwrap_or("")
                    .trim();
                let value = cleanup_labeled_value(value);
                if !value.is_empty() {
                    return Some(value);
                }
            }
        }
    }
    None
}

fn split_once_labeled_rest<'a>(text: &'a str, label: &str, sep: &str) -> Option<&'a str> {
    let needle = format!("{label}{sep}");
    if let Some((_, rest)) = text.split_once(&needle) {
        return Some(rest);
    }
    let lower_text = text.to_ascii_lowercase();
    let lower_needle = needle.to_ascii_lowercase();
    lower_text
        .find(&lower_needle)
        .and_then(|idx| text.get(idx + needle.len()..))
}

fn cleanup_labeled_value(value: &str) -> String {
    let value = cleanup_request_value(value);
    let lower = value.to_ascii_lowercase();
    for marker in [
        " 花费",
        "花费",
        " cost",
        " costs",
        "cost",
        "costs",
        " 的效果为",
        " 的效果",
        " 效果为",
        " 效果",
        " 奖励",
        "效果为",
        "效果",
        "奖励",
        " effects",
        " effect",
        " reward",
        "effects",
        "effect",
        "reward",
    ] {
        if let Some(idx) = lower.find(marker) {
            return cleanup_request_value(&value[..idx]);
        }
    }
    value
}

fn compact_request_line(text: &str) -> String {
    text.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>()
        .join("；")
}

fn ascii_slug(text: &str) -> String {
    let mut out = String::new();
    for ch in text.chars() {
        if ch.is_ascii_alphanumeric() {
            out.push(ch.to_ascii_lowercase());
        } else if ch.is_ascii_whitespace() || ch == '_' || ch == '-' {
            if !out.ends_with('_') {
                out.push('_');
            }
        }
    }
    let out = out.trim_matches('_').to_string();
    if out.is_empty() {
        "user_focus".to_string()
    } else {
        out
    }
}

fn write_work_package_run_input_templates(
    package: &WorkPackage,
    blueprint: &LargeModBlueprint,
    output_dir: &Path,
) -> Result<Vec<WorkPackageRunInputTemplate>, String> {
    let input_dir = output_dir.join("inputs");
    fs::create_dir_all(&input_dir).map_err(|e| format!("create {}: {e}", input_dir.display()))?;
    let templates = vec![
        WorkPackageRunInputTemplate {
            kind: "style_context",
            path: input_dir.join("style_context.md"),
            required: false,
            writer: "work-package-style-context",
        },
        WorkPackageRunInputTemplate {
            kind: "focus_layout",
            path: input_dir.join("focus_layout.txt"),
            required: true,
            writer: "apply-focus-layout",
        },
        WorkPackageRunInputTemplate {
            kind: "event_cards",
            path: input_dir.join("event_cards.txt"),
            required: true,
            writer: "apply-event-cards",
        },
        WorkPackageRunInputTemplate {
            kind: "feature_cards",
            path: input_dir.join("feature_cards.txt"),
            required: true,
            writer: "apply-feature-cards",
        },
        WorkPackageRunInputTemplate {
            kind: "intent",
            path: input_dir.join("intent.txt"),
            required: true,
            writer: "author-intent",
        },
        WorkPackageRunInputTemplate {
            kind: "dynamic_modifier_intent",
            path: input_dir.join("dynamic_modifier_intent.txt"),
            required: false,
            writer: "plan-dynamic-modifier-change",
        },
        WorkPackageRunInputTemplate {
            kind: "localisation_placeholders",
            path: input_dir.join("localisation_placeholders.txt"),
            required: true,
            writer: "author-placeholder-plan",
        },
        WorkPackageRunInputTemplate {
            kind: "translated_localisation",
            path: input_dir.join("translated_l_simp_chinese.yml"),
            required: false,
            writer: "translate-localisation --apply",
        },
    ];
    for template in &templates {
        let text = work_package_run_input_template_text(template.kind, package, blueprint);
        write_if_missing(&template.path, text.as_bytes())?;
    }
    Ok(templates)
}

fn work_package_run_input_template_text(
    kind: &str,
    package: &WorkPackage,
    blueprint: &LargeModBlueprint,
) -> String {
    let token = package_token(package);
    let tag = package_tag(package).unwrap_or_else(|| "TAG".to_string());
    let prefix = format!("{}_{}", tag.to_ascii_lowercase(), token);
    match kind {
        "focus_layout" => format!(
            "# hoi4skill.work_package_input.focus_layout.v1\n# package: {}\n# Fill this with structured focus layout; Rust writer emits Clausewitz.\n开局整顿 | id = {prefix}_opening | x = 0 | y = 0 | 奖励 = 政治点数 +50\n路线分歧 | id = {prefix}_route_split | x = -1 | y = 1 | 前置 = {prefix}_opening | 奖励 = 稳定度 +5%\n制度巩固 | id = {prefix}_institutional_reform | x = 1 | y = 1 | 前置 = {prefix}_opening | 奖励 = 战争支持度 +5%\n",
            package.id
        ),
        "event_cards" => format!(
            "# hoi4skill.work_package_input.event_cards.v1\n# package: {}\n事件：开局政治会议\n类型：country_event\n标题：政治会议召开\n描述：各派代表已经抵达首都，新的路线争论将决定国家命运。\n选项：维持现状\n效果：政治点数 +25\n选项：推动改革\n效果：稳定度 +3%\n",
            package.id
        ),
        "feature_cards" => format!(
            "# hoi4skill.work_package_input.feature_cards.v1\n# package: {}\n决议：召开地方整顿会议\n描述：地方派系必须重新接受中央协调。\n花费：25\n效果：稳定度 +2%\n\n民族精神：临时政治妥协\n描述：各派暂时停止公开争斗，但深层矛盾仍在积累。\n效果：稳定度 +5%\n",
            package.id
        ),
        "intent" => format!(
            "# hoi4skill.work_package_input.intent.v1\n# One natural-language effect per line. CLI compiles and rejects unindexed syntax.\n{}：战争正当化 = -10%\n新增民族精神：临时政治妥协，稳定度 +5%\n",
            blueprint.acronym
        ),
        "dynamic_modifier_intent" => {
            "# hoi4skill.work_package_input.dynamic_modifier_intent.v1\n# Use only for indexed dynamic modifiers; do not describe national spirits here.\n中国制造 的效果 建造速度 +10%\n生产效率上限 +0.05\n".to_string()
        }
        "localisation_placeholders" => format!(
            "# hoi4skill.work_package_input.localisation_placeholders.v1\n# Use user-visible prose with tokens; unresolved tokens require questions, not invention.\n【红色：【{tag}国旗】【{tag}领导人】】宣布新的政治路线已经开始执行。\n"
        ),
        "translated_localisation" => {
            "l_simp_chinese:\n # Paste reviewed translated localisation here before running translate-localisation --apply.\n".to_string()
        }
        "style_context" => "# hoi4skill.work_package_input.style_context.v1\n# Optional. Generate with:\n# hoi4skill work-package-style-context --style-mod <local style mod> --output style_context.md\n# Use this for style density, cadence, and structure only. Do not copy source prose.\n".to_string(),
        _ => String::new(),
    }
}

fn work_package_run_json(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    packages: &[WorkPackage],
    blueprint_path: &Path,
    mod_root: &Path,
    output_dir: &Path,
    input_templates: &[WorkPackageRunInputTemplate],
    map: &ArgMap,
) -> Result<String, String> {
    let root = mod_root.display().to_string();
    let package_token = package_token(package);
    let tag = package_tag(package);
    let namespace = package_namespace(package, blueprint);
    let start_state = work_package_start_state(package, packages, Some(mod_root));
    let game_root = value(map, "game-root")
        .map(str::to_string)
        .unwrap_or_else(|| "<HOI4 root>".to_string());
    let mod_paths = repeated_values(map, "mod-path")
        .iter()
        .map(|path| path.to_string())
        .collect::<Vec<_>>();
    let style_mods = repeated_values(map, "style-mod")
        .iter()
        .map(|path| path.to_string())
        .collect::<Vec<_>>();
    let request = value(map, "request").unwrap_or("");
    let changed_file = value(map, "changed-file")
        .map(str::to_string)
        .unwrap_or_else(|| {
            mod_root
                .join(".hoi4skill")
                .join(format!("changed_{}.txt", package.id))
                .display()
                .to_string()
        });
    let text_source = value(map, "text-source")
        .or_else(|| value(map, "input"))
        .map(str::to_string)
        .unwrap_or_else(|| "<user request or authoring source>".to_string());
    let authoring_dir = output_dir.join("authoring");
    let lanes =
        work_package_run_content_lanes(package, tag.as_deref(), &namespace, &root, output_dir);
    let evidence_commands = work_package_run_evidence_commands(
        package,
        &root,
        &game_root,
        &mod_paths,
        &changed_file,
        &text_source,
    );
    let writer_commands = work_package_run_writer_commands(
        package,
        &root,
        &game_root,
        &mod_paths,
        tag.as_deref(),
        output_dir,
        &style_mods,
    );
    let gate_commands = work_package_run_gate_commands(
        package,
        &root,
        &game_root,
        &mod_paths,
        &changed_file,
        &text_source,
    );
    let artifacts = work_package_run_artifacts(package, &root, output_dir);
    let input_template_json = input_templates
        .iter()
        .map(WorkPackageRunInputTemplate::to_json)
        .collect::<Vec<_>>();
    let stop_conditions = work_package_run_stop_conditions();
    let can_author = start_state.blocked_by.is_empty();
    let requires_game_root = !value(map, "game-root")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false);

    Ok(format!(
        "{{\n  \"schema\": \"hoi4skill.work_package_run.v1\",\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"blueprint\": {},\n  \"output_dir\": {},\n  \"request\": {},\n  \"game_root\": {},\n  \"mod_paths\": {},\n  \"style_mods\": {},\n  \"package\": {{\n    \"id\": {},\n    \"kind\": {},\n    \"title\": {},\n    \"token\": {},\n    \"tag\": {},\n    \"namespace\": {},\n    \"state\": {},\n    \"can_author\": {},\n    \"blocked_by\": {}\n  }},\n  \"authoring_pack\": {{\n    \"dir\": {},\n    \"start\": {},\n    \"plan\": {},\n    \"context\": {},\n    \"assets\": {},\n    \"manifest\": {}\n  }},\n  \"input_templates\": [{}],\n  \"content_lanes\": [{}],\n  \"ai_output_contract\": {},\n  \"evidence_commands\": {},\n  \"writer_commands\": {},\n  \"gate_commands\": {},\n  \"artifacts\": [{}],\n  \"safety\": {{\n    \"final_code_allowed\": false,\n    \"requires_game_root_before_final_code\": {},\n    \"requires_strict_code_index\": true,\n    \"requires_text_alignment\": true,\n    \"requires_boundary_gate\": true,\n    \"requires_release_gate\": true,\n    \"blocked_until_writer_outputs_exist\": true\n  }},\n  \"stop_conditions\": {}\n}}\n",
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&root),
        json_str(&blueprint_path.display().to_string()),
        json_str(&output_dir.display().to_string()),
        json_str(request),
        json_str(&game_root),
        json_array(&mod_paths),
        json_array(&style_mods),
        json_str(&package.id),
        json_str(&package.kind),
        json_str(&package.title),
        json_str(&package_token),
        json_optional_str(tag.as_deref()),
        json_str(&namespace),
        json_str(&start_state.state),
        json_bool(can_author),
        json_array(&start_state.blocked_by),
        json_str(&authoring_dir.display().to_string()),
        json_str(&authoring_dir.join("start.md").display().to_string()),
        json_str(&authoring_dir.join("plan.json").display().to_string()),
        json_str(&authoring_dir.join("context.md").display().to_string()),
        json_str(&authoring_dir.join("assets.md").display().to_string()),
        json_str(&authoring_dir.join("manifest.json").display().to_string()),
        input_template_json.join(",\n    "),
        lanes.join(",\n    "),
        work_package_run_ai_output_contract_json(),
        json_array(&evidence_commands),
        json_array(&writer_commands),
        json_array(&gate_commands),
        artifacts.join(",\n    "),
        json_bool(requires_game_root),
        json_array(&stop_conditions),
    ))
}

fn work_package_run_content_lanes(
    package: &WorkPackage,
    tag: Option<&str>,
    namespace: &str,
    root: &str,
    output_dir: &Path,
) -> Vec<String> {
    let tag = tag.unwrap_or("<TAG>");
    let prefix = format!("{}_{}", tag.to_ascii_lowercase(), package_token(package));
    let inputs = output_dir.join("inputs");
    [
        (
            "style_context",
            inputs.join("style_context.md"),
            "safe style profile from user-selected local mods; structure and cadence only",
            "hoi4skill work-package-style-context --style-mod <local style mod>".to_string(),
            "anti-copy style context, built-in event templates, focus/idea/event density profile",
        ),
        (
            "national_focus",
            inputs.join("focus_layout.txt"),
            "structured focus layout cards",
            format!("hoi4skill apply-focus-layout --tag {tag} --prefix {prefix} --final-check"),
            "focus ids, prerequisites, rewards, localisation titles and descriptions",
        ),
        (
            "event_chain",
            inputs.join("event_cards.txt"),
            "event cards with options, triggers, effects, pictures, localisation",
            format!("hoi4skill apply-event-cards --namespace {namespace} --final-check"),
            "event ids, namespace reservations, options, descriptions, follow-up links",
        ),
        (
            "decisions",
            inputs.join("feature_cards.txt"),
            "feature cards for decisions and categories",
            format!("hoi4skill apply-feature-cards --tag {tag} --prefix {prefix} --final-check"),
            "decision category, visible/available/remove/effect blocks, AI weights",
        ),
        (
            "national_spirits",
            inputs.join("intent.txt"),
            "natural-language author intent for focus/event/decision effects, ideas, localisation, and dynamic modifiers",
            format!("hoi4skill author-intent --tag {tag} --prefix {prefix} --execute --final-check"),
            "Rust-routed authoring through focus/event/decision writers, add_ideas/remove_ideas/swap_ideas, and idea modifiers",
        ),
        (
            "dynamic_modifiers",
            inputs.join("dynamic_modifier_intent.txt"),
            "dynamic modifier change intent plus scripted_effect reuse plan",
            format!(
                "hoi4skill plan-dynamic-modifier-change --game-root <HOI4 root> --output {}",
                work_package_run_report_path(root, "dynamic_modifier_change_plan.json")
            ),
            "scripted_effect protocol, tooltip, temp variables, no national-spirit misuse",
        ),
        (
            "localisation",
            inputs.join("localisation_placeholders.txt"),
            "player-visible text and token placeholders",
            "hoi4skill author-placeholder-plan --game-root <HOI4 root>".to_string(),
            "Chinese localisation keys, icons, flags, leaders, color tokens, text alignment",
        ),
    ]
    .into_iter()
    .map(|(kind, input, model_input, writer, final_gate)| {
        format!(
            "{{\"kind\": {}, \"input\": {}, \"model_input\": {}, \"writer_or_checker\": {}, \"final_gate\": {}}}",
            json_str(kind),
            json_str(&input.display().to_string()),
            json_str(model_input),
            json_str(&writer),
            json_str(final_gate)
        )
    })
    .collect()
}

fn work_package_run_ai_output_contract_json() -> String {
    let allowed = vec![
        "natural-language intent".to_string(),
        "structured focus layout cards".to_string(),
        "event cards".to_string(),
        "feature cards for decisions, ideas, and reusable effects".to_string(),
        "style context from user-selected local mods".to_string(),
        "localisation text with explicit tokens".to_string(),
    ];
    let forbidden = vec![
        "raw Clausewitz code emitted directly by the model".to_string(),
        "unindexed effects, triggers, modifiers, sprites, pictures, technologies, resources, or tags".to_string(),
        "dynamic modifiers represented as national spirits".to_string(),
        "English localisation or extra systems unless the literal user request authorizes them".to_string(),
        "placeholder ids, TODO script, invented tags, invented icons, or invented leader tokens".to_string(),
    ];
    format!(
        "{{\"schema\": {}, \"model_final_code_allowed\": false, \"rust_writer_required\": true, \"allowed_outputs\": {}, \"forbidden_outputs\": {}}}",
        json_str("hoi4skill.ai_output_contract.v1"),
        json_array(&allowed),
        json_array(&forbidden),
    )
}

fn work_package_run_evidence_commands(
    package: &WorkPackage,
    root: &str,
    game_root: &str,
    mod_paths: &[String],
    changed_file: &str,
    text_source: &str,
) -> Vec<String> {
    let namespace = package.id.replace('-', "_");
    let mod_path_args = work_package_run_mod_path_args(mod_paths);
    let report = |name: String| work_package_run_report_path(root, &name);
    vec![
        format!(
            "hoi4skill detect-hoi4-path --hoi4-path {game_root} --output {}",
            report("hoi4_path.json".to_string())
        ),
        format!(
            "hoi4skill build-mod-index {root} --output {}",
            report("mod_index.json".to_string())
        ),
        format!(
            "hoi4skill code-catalog --game-root {game_root}{mod_path_args} --output {}",
            report("code_catalog.json".to_string())
        ),
        format!(
            "hoi4skill feature-context {root} --output {}",
            report(format!("feature_context_{}.md", package.id))
        ),
        format!(
            "hoi4skill reserve-id {root} --kind event --namespace {namespace} --output {}",
            report(format!("reserve_{}.json", package.id))
        ),
        format!(
            "hoi4skill check-work-package-boundary --mod-root {root} --package {} --changed-file {changed_file} --strict-names --fail-on-violation --output {}",
            package.id,
            report(format!("boundary_{}.json", package.id))
        ),
        format!(
            "hoi4skill check-text-alignment --mod-root {root} --input {text_source} --output {}",
            report("text_alignment.json".to_string())
        ),
    ]
}

fn work_package_run_writer_commands(
    package: &WorkPackage,
    root: &str,
    game_root: &str,
    mod_paths: &[String],
    tag: Option<&str>,
    output_dir: &Path,
    style_mods: &[String],
) -> Vec<String> {
    let tag = tag.unwrap_or("<TAG>");
    let prefix = format!("{}_{}", tag.to_ascii_lowercase(), package_token(package));
    let mod_path_args = work_package_run_mod_path_args(mod_paths);
    let inputs = output_dir.join("inputs");
    let focus_input = inputs.join("focus_layout.txt").display().to_string();
    let event_input = inputs.join("event_cards.txt").display().to_string();
    let feature_input = inputs.join("feature_cards.txt").display().to_string();
    let intent_input = inputs.join("intent.txt").display().to_string();
    let dynamic_input = inputs
        .join("dynamic_modifier_intent.txt")
        .display()
        .to_string();
    let placeholders_input = inputs
        .join("localisation_placeholders.txt")
        .display()
        .to_string();
    let translated_input = inputs
        .join("translated_l_simp_chinese.yml")
        .display()
        .to_string();
    let style_output = inputs.join("style_context.md").display().to_string();
    let report = |name: String| work_package_run_report_path(root, &name);
    let style_mod_args = if style_mods.is_empty() {
        " --style-mod <local style mod>".to_string()
    } else {
        style_mods
            .iter()
            .map(|path| format!(" --style-mod {path}"))
            .collect::<Vec<_>>()
            .join("")
    };
    vec![
        format!("hoi4skill work-package-style-context{style_mod_args} --language all --template auto --output {style_output}"),
        format!("hoi4skill author-intent --input {intent_input} --execute --mod-root {root} --tag {tag} --prefix {prefix} --game-root {game_root}{mod_path_args} --final-check --output {}", report(format!("author_intent_{}.json", package.id))),
        format!("hoi4skill compile-intent --input {intent_input} --kind auto --tag {tag} --prefix {prefix} --game-root {game_root}{mod_path_args} --strict-code-index --require-final-code --output {}", report(format!("compile_intent_{}.json", package.id))),
        format!("hoi4skill apply-focus-layout --input {focus_input} --mod-root {root} --tag {tag} --prefix {prefix} --game-root {game_root}{mod_path_args} --final-check --output {}", report(format!("apply_focus_{}.json", package.id))),
        format!("hoi4skill apply-event-cards --input {event_input} --mod-root {root} --tag {tag} --prefix {prefix} --game-root {game_root}{mod_path_args} --final-check --output {}", report(format!("apply_events_{}.json", package.id))),
        format!("hoi4skill apply-feature-cards --input {feature_input} --mod-root {root} --tag {tag} --prefix {prefix} --game-root {game_root}{mod_path_args} --final-check --output {}", report(format!("apply_features_{}.json", package.id))),
        format!("hoi4skill plan-dynamic-modifier-change --input {dynamic_input} --game-root {game_root}{mod_path_args} --output {}", report(format!("dynamic_modifier_change_plan_{}.json", package.id))),
        format!("hoi4skill author-placeholder-plan --input {placeholders_input} --game-root {game_root}{mod_path_args} --output {}", report(format!("placeholder_plan_{}.json", package.id))),
        format!("hoi4skill translate-localisation --mod-root {root} --from english --to simp_chinese --translated-input {translated_input} --apply --report {}", report(format!("translation_apply_{}.json", package.id))),
    ]
}

fn work_package_run_gate_commands(
    package: &WorkPackage,
    root: &str,
    game_root: &str,
    mod_paths: &[String],
    changed_file: &str,
    text_source: &str,
) -> Vec<String> {
    let mod_path_args = work_package_run_mod_path_args(mod_paths);
    let report = |name: String| work_package_run_report_path(root, &name);
    vec![
        format!("hoi4skill validate {root} --game-root {game_root}{mod_path_args} --strict-code-index --changed-only --changed-file {changed_file} --output {}", report(format!("validation_{}.json", package.id))),
        format!("hoi4skill validate-repair-context {root} --game-root {game_root}{mod_path_args} --changed-only --changed-file {changed_file} --output {}", report(format!("validation_repair_context_{}.json", package.id))),
        format!(
            "hoi4skill large-mod-ai-output-insurance --mod-root {root} --package {} --input <failed_output.md> --game-root {game_root}{mod_path_args} --output {} --markdown-output {}",
            package.id,
            report(format!("ai_output_insurance_{}.json", package.id)),
            report(format!("ai_output_insurance_{}.md", package.id))
        ),
        format!("hoi4skill loc-audit {root} --output {}", report("loc_audit.json".to_string())),
        format!("hoi4skill check-text-alignment --mod-root {root} --input {text_source} --output {}", report("text_alignment.json".to_string())),
        format!("hoi4skill gfx-audit {root} --output {}", report("gfx_audit.json".to_string())),
        format!("hoi4skill logic-audit {root} --output {}", report("logic_audit.json".to_string())),
        format!("hoi4skill work-package-status --mod-root {root} --package {} --output {}", package.id, report(format!("status_{}.json", package.id))),
        format!("hoi4skill work-package-readiness --mod-root {root} --package {} --output {}", package.id, report(format!("readiness_{}.json", package.id))),
        format!("hoi4skill work-package-handoff --mod-root {root} --package {} --output {}", package.id, report(format!("handoff_{}.md", package.id))),
        format!("hoi4skill work-package-merge-gate --mod-root {root} --package {} --output {}", package.id, report(format!("merge_gate_{}.json", package.id))),
        format!("hoi4skill large-mod-capability-audit --mod-root {root} --package {} --output {}", package.id, report(format!("capability_{}.json", package.id))),
        format!("hoi4skill large-mod-release-gate --mod-root {root} --output {}", report("release_gate.json".to_string())),
    ]
}

fn work_package_run_mod_path_args(mod_paths: &[String]) -> String {
    mod_paths
        .iter()
        .map(|path| format!(" --mod-path {path}"))
        .collect::<Vec<_>>()
        .join("")
}

fn work_package_run_report_path(root: &str, file_name: &str) -> String {
    let root = root.trim_end_matches(|ch| ch == '/' || ch == '\\');
    format!("{root}/.hoi4skill/{file_name}")
}

fn work_package_run_artifacts(package: &WorkPackage, root: &str, output_dir: &Path) -> Vec<String> {
    [
        ("run_manifest", output_dir.join("run.json")),
        (
            "authoring_start",
            output_dir.join("authoring").join("start.md"),
        ),
        (
            "authoring_plan",
            output_dir.join("authoring").join("plan.json"),
        ),
        (
            "authoring_context",
            output_dir.join("authoring").join("context.md"),
        ),
        (
            "authoring_assets",
            output_dir.join("authoring").join("assets.md"),
        ),
        (
            "style_context",
            output_dir.join("inputs").join("style_context.md"),
        ),
        (
            "package_boundary",
            PathBuf::from(work_package_run_report_path(
                root,
                &format!("boundary_{}.json", package.id),
            )),
        ),
        (
            "package_status",
            PathBuf::from(work_package_run_report_path(
                root,
                &format!("status_{}.json", package.id),
            )),
        ),
        (
            "package_validation",
            PathBuf::from(work_package_run_report_path(
                root,
                &format!("validation_{}.json", package.id),
            )),
        ),
        (
            "package_handoff",
            PathBuf::from(work_package_run_report_path(
                root,
                &format!("handoff_{}.md", package.id),
            )),
        ),
        (
            "release_gate",
            PathBuf::from(work_package_run_report_path(root, "release_gate.json")),
        ),
    ]
    .into_iter()
    .map(|(kind, path)| {
        format!(
            "{{\"kind\": {}, \"path\": {}}}",
            json_str(kind),
            json_str(&path.display().to_string())
        )
    })
    .collect()
}

fn work_package_run_stop_conditions() -> Vec<String> {
    vec![
        "Stop if package.state is blocked_by_dependencies or can_author is false.".to_string(),
        "Stop if detect-hoi4-path cannot prove a local HOI4 game root before final code.".to_string(),
        "Stop if any writer command reports draft output, missing code-index evidence, or safety blockers.".to_string(),
        "Stop if dynamic modifier intent is routed to a national spirit instead of scripted_effect/dynamic modifier protocol.".to_string(),
        "Stop if localisation token lookup cannot resolve a user-visible icon, flag, leader, cosmetic tag, or color token; ask the user instead of inventing it.".to_string(),
        "Stop if check-text-alignment misses user-provided player-visible text.".to_string(),
        "Stop if boundary, validation, logic, loc, gfx, merge, playtest, regression, or release gate reports needs_review.".to_string(),
    ]
}

struct WorkPackageRunExecution {
    ok: bool,
    report: String,
    repair_bundle: Option<PathBuf>,
}

struct WorkPackageRunRetrievedRepairContext {
    status: String,
    markdown_path: PathBuf,
    json_path: PathBuf,
    markdown: String,
}

pub(crate) struct WorkPackageRunStep {
    pub(crate) kind: String,
    pub(crate) name: String,
    pub(crate) command: String,
    pub(crate) status: String,
    pub(crate) error: Option<String>,
}

#[derive(Clone)]
pub(crate) struct WorkPackageRunFileSnapshot {
    files: BTreeMap<String, Vec<u8>>,
}

fn execute_work_package_run(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    packages: &[WorkPackage],
    mod_root: &Path,
    output_dir: &Path,
    input_templates: &[WorkPackageRunInputTemplate],
    map: &ArgMap,
) -> Result<WorkPackageRunExecution, String> {
    let mut steps = Vec::new();
    let game_root = value(map, "game-root").map(str::to_string);
    let start_state = work_package_start_state(package, packages, Some(mod_root));
    if !start_state.blocked_by.is_empty() && !map.flags.contains("allow-blocked") {
        let error = format!(
            "package is blocked by dependency package(s): {}",
            start_state.blocked_by.join(", ")
        );
        steps.push(WorkPackageRunStep {
            kind: "preflight".to_string(),
            name: "dependency_gate".to_string(),
            command: "work_package_start_state".to_string(),
            status: "blocked".to_string(),
            error: Some(error.clone()),
        });
        return finish_failed_work_package_run(
            blueprint,
            package,
            mod_root,
            output_dir,
            game_root.as_deref(),
            &steps,
            &error,
            map,
        );
    }
    let Some(game_root) = game_root
        .as_deref()
        .filter(|value| !value.trim().is_empty())
    else {
        let error = "run-work-package --execute requires --game-root before writer execution";
        steps.push(WorkPackageRunStep {
            kind: "preflight".to_string(),
            name: "game_root_gate".to_string(),
            command: "require --game-root".to_string(),
            status: "blocked".to_string(),
            error: Some(error.to_string()),
        });
        return finish_failed_work_package_run(
            blueprint, package, mod_root, output_dir, None, &steps, error, map,
        );
    };
    for template in input_templates.iter().filter(|template| template.required) {
        if !template.path.exists() {
            let error = format!(
                "required input template is missing: {}",
                template.path.display()
            );
            steps.push(WorkPackageRunStep {
                kind: "preflight".to_string(),
                name: format!("input_template_{}", template.kind),
                command: template.path.display().to_string(),
                status: "missing".to_string(),
                error: Some(error.clone()),
            });
            return finish_failed_work_package_run(
                blueprint,
                package,
                mod_root,
                output_dir,
                Some(game_root),
                &steps,
                &error,
                map,
            );
        }
    }

    let tag = package_tag(package).unwrap_or_else(|| "TAG".to_string());
    let prefix = format!("{}_{}", tag.to_ascii_lowercase(), package_token(package));
    let mod_path_args = work_package_execute_mod_path_args(map);
    let inputs = output_dir.join("inputs");
    let report_dir = output_dir.join("execution");
    fs::create_dir_all(&report_dir).map_err(|e| format!("create {}: {e}", report_dir.display()))?;
    let style_mods = repeated_values(map, "style-mod");
    if !style_mods.is_empty() {
        let mut args = Vec::new();
        for style_mod in &style_mods {
            args.push("--style-mod".to_string());
            args.push(style_mod.to_string());
        }
        args.extend([
            "--language".to_string(),
            "all".to_string(),
            "--template".to_string(),
            "auto".to_string(),
            "--output".to_string(),
            inputs.join("style_context.md").display().to_string(),
        ]);
        let command_text = format!("hoi4skill work-package-style-context {}", args.join(" "));
        match cmd_work_package_style_context(&args) {
            Ok(()) => steps.push(WorkPackageRunStep {
                kind: "pre_writer".to_string(),
                name: "style_context".to_string(),
                command: command_text,
                status: "ok".to_string(),
                error: None,
            }),
            Err(err) => {
                steps.push(WorkPackageRunStep {
                    kind: "pre_writer".to_string(),
                    name: "style_context".to_string(),
                    command: command_text,
                    status: "failed".to_string(),
                    error: Some(err.clone()),
                });
                return finish_failed_work_package_run(
                    blueprint,
                    package,
                    mod_root,
                    output_dir,
                    Some(game_root),
                    &steps,
                    &err,
                    map,
                );
            }
        }
    }
    let before_snapshot = snapshot_work_package_allowed_files(mod_root, package)?;
    let mut writer_steps = vec![
        (
            "author_intent",
            "author-intent",
            vec![
                "--input".to_string(),
                inputs.join("intent.txt").display().to_string(),
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--tag".to_string(),
                tag.clone(),
                "--prefix".to_string(),
                prefix.clone(),
                "--game-root".to_string(),
                game_root.to_string(),
                "--final-check".to_string(),
                "--output".to_string(),
                report_dir.join("author_intent.json").display().to_string(),
            ],
            cmd_author_intent as fn(&[String]) -> Result<(), String>,
        ),
        (
            "compile_intent",
            "compile-intent",
            vec![
                "--input".to_string(),
                inputs.join("intent.txt").display().to_string(),
                "--kind".to_string(),
                "auto".to_string(),
                "--tag".to_string(),
                tag.clone(),
                "--prefix".to_string(),
                prefix.clone(),
                "--game-root".to_string(),
                game_root.to_string(),
                "--strict-code-index".to_string(),
                "--require-final-code".to_string(),
                "--output".to_string(),
                report_dir.join("compile_intent.json").display().to_string(),
            ],
            cmd_compile_intent as fn(&[String]) -> Result<(), String>,
        ),
        (
            "apply_focus_layout",
            "apply-focus-layout",
            vec![
                "--input".to_string(),
                inputs.join("focus_layout.txt").display().to_string(),
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--tag".to_string(),
                tag.clone(),
                "--prefix".to_string(),
                prefix.clone(),
                "--game-root".to_string(),
                game_root.to_string(),
                "--final-check".to_string(),
                "--output".to_string(),
                report_dir
                    .join("apply_focus_layout.json")
                    .display()
                    .to_string(),
            ],
            cmd_apply_focus_layout as fn(&[String]) -> Result<(), String>,
        ),
        (
            "apply_event_cards",
            "apply-event-cards",
            vec![
                "--input".to_string(),
                inputs.join("event_cards.txt").display().to_string(),
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--tag".to_string(),
                tag.clone(),
                "--prefix".to_string(),
                prefix.clone(),
                "--game-root".to_string(),
                game_root.to_string(),
                "--final-check".to_string(),
                "--output".to_string(),
                report_dir
                    .join("apply_event_cards.json")
                    .display()
                    .to_string(),
            ],
            cmd_apply_event_cards as fn(&[String]) -> Result<(), String>,
        ),
        (
            "apply_feature_cards",
            "apply-feature-cards",
            vec![
                "--input".to_string(),
                inputs.join("feature_cards.txt").display().to_string(),
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--tag".to_string(),
                tag.clone(),
                "--prefix".to_string(),
                prefix.clone(),
                "--game-root".to_string(),
                game_root.to_string(),
                "--final-check".to_string(),
                "--output".to_string(),
                report_dir
                    .join("apply_feature_cards.json")
                    .display()
                    .to_string(),
            ],
            cmd_apply_feature_cards as fn(&[String]) -> Result<(), String>,
        ),
        (
            "dynamic_modifier_change",
            "plan-dynamic-modifier-change",
            vec![
                "--input".to_string(),
                inputs
                    .join("dynamic_modifier_intent.txt")
                    .display()
                    .to_string(),
                "--execute".to_string(),
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--tag".to_string(),
                tag.clone(),
                "--prefix".to_string(),
                prefix.clone(),
                "--game-root".to_string(),
                game_root.to_string(),
                "--final-check".to_string(),
                "--output".to_string(),
                report_dir
                    .join("dynamic_modifier_change_plan.json")
                    .display()
                    .to_string(),
            ],
            cmd_plan_dynamic_modifier_change as fn(&[String]) -> Result<(), String>,
        ),
    ];
    if map.flags.contains("apply-localisation") {
        writer_steps.push((
            "translate_localisation_apply",
            "translate-localisation",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--from".to_string(),
                "english".to_string(),
                "--to".to_string(),
                "simp_chinese".to_string(),
                "--translated-input".to_string(),
                inputs
                    .join("translated_l_simp_chinese.yml")
                    .display()
                    .to_string(),
                "--apply".to_string(),
                "--report".to_string(),
                report_dir
                    .join("translation_apply.json")
                    .display()
                    .to_string(),
            ],
            cmd_translate_localisation as fn(&[String]) -> Result<(), String>,
        ));
    }
    for (_, _, args, _) in &mut writer_steps {
        args.extend(mod_path_args.clone());
    }
    let mut placeholder_preflight_done = false;
    for (name, command, args, runner) in writer_steps {
        if !placeholder_preflight_done && is_work_package_mutating_writer(name) {
            let placeholder_preflight_text =
                work_package_placeholder_preflight_input(input_templates)?;
            let placeholder_preflight_input = report_dir.join("placeholder_preflight_input.txt");
            fs::write(&placeholder_preflight_input, &placeholder_preflight_text)
                .map_err(|e| format!("write {}: {e}", placeholder_preflight_input.display()))?;
            let mut placeholder_preflight_args = vec![
                "--input".to_string(),
                placeholder_preflight_input.display().to_string(),
                "--game-root".to_string(),
                game_root.to_string(),
                "--output".to_string(),
                report_dir
                    .join("placeholder_plan.json")
                    .display()
                    .to_string(),
            ];
            placeholder_preflight_args.extend(mod_path_args.clone());
            let placeholder_preflight_command = format!(
                "hoi4skill author-placeholder-plan {}",
                placeholder_preflight_args.join(" ")
            );
            match cmd_author_placeholder_plan(&placeholder_preflight_args) {
                Ok(()) => steps.push(WorkPackageRunStep {
                    kind: "pre_writer".to_string(),
                    name: "placeholder_plan".to_string(),
                    command: placeholder_preflight_command,
                    status: "ok".to_string(),
                    error: None,
                }),
                Err(err) => {
                    steps.push(WorkPackageRunStep {
                        kind: "pre_writer".to_string(),
                        name: "placeholder_plan".to_string(),
                        command: placeholder_preflight_command,
                        status: "failed".to_string(),
                        error: Some(err.clone()),
                    });
                    return finish_failed_work_package_run(
                        blueprint,
                        package,
                        mod_root,
                        output_dir,
                        Some(game_root),
                        &steps,
                        &err,
                        map,
                    );
                }
            }
            placeholder_preflight_done = true;
        }
        let command_text = format!("hoi4skill {command} {}", args.join(" "));
        match runner(&args) {
            Ok(()) => steps.push(WorkPackageRunStep {
                kind: "writer".to_string(),
                name: name.to_string(),
                command: command_text,
                status: "ok".to_string(),
                error: None,
            }),
            Err(err) => {
                if is_non_blocking_work_package_writer(name) {
                    steps.push(WorkPackageRunStep {
                        kind: "writer_audit".to_string(),
                        name: name.to_string(),
                        command: command_text,
                        status: "needs_review".to_string(),
                        error: Some(err),
                    });
                    continue;
                }
                steps.push(WorkPackageRunStep {
                    kind: "writer".to_string(),
                    name: name.to_string(),
                    command: command_text,
                    status: "failed".to_string(),
                    error: Some(err.clone()),
                });
                return finish_failed_work_package_run(
                    blueprint,
                    package,
                    mod_root,
                    output_dir,
                    Some(game_root),
                    &steps,
                    &err,
                    map,
                );
            }
        }
    }
    let plain_localisation_entries =
        plain_localisation_entries_from_request(value(map, "request").unwrap_or_default(), &prefix);
    if !plain_localisation_entries.is_empty() {
        let loc_path = target_localisation_path(mod_root, &tag);
        let command_text = format!(
            "hoi4skill apply-plain-localisation --mod-root {} --tag {} --prefix {} --request <author request>",
            mod_root.display(),
            tag,
            prefix
        );
        match append_localisation_entries(&loc_path, &plain_localisation_entries) {
            Ok(_) => steps.push(WorkPackageRunStep {
                kind: "writer".to_string(),
                name: "apply_plain_localisation".to_string(),
                command: command_text,
                status: "ok".to_string(),
                error: None,
            }),
            Err(err) => {
                steps.push(WorkPackageRunStep {
                    kind: "writer".to_string(),
                    name: "apply_plain_localisation".to_string(),
                    command: command_text,
                    status: "failed".to_string(),
                    error: Some(err.clone()),
                });
                return finish_failed_work_package_run(
                    blueprint,
                    package,
                    mod_root,
                    output_dir,
                    Some(game_root),
                    &steps,
                    &err,
                    map,
                );
            }
        }
    }
    let changed_paths = diff_work_package_allowed_files(mod_root, package, &before_snapshot)?;
    let changed_file_path = write_work_package_run_changed_file(mod_root, package, &changed_paths)?;
    steps.push(WorkPackageRunStep {
        kind: "post_gate".to_string(),
        name: "changed_file".to_string(),
        command: changed_file_path.display().to_string(),
        status: "ok".to_string(),
        error: None,
    });
    if let Err(err) = run_work_package_post_gates(
        package,
        mod_root,
        output_dir,
        &changed_file_path,
        &mut steps,
    ) {
        return finish_failed_work_package_run(
            blueprint,
            package,
            mod_root,
            output_dir,
            Some(game_root),
            &steps,
            &err,
            map,
        );
    }
    if let Err(err) = run_work_package_success_evidence(
        package,
        mod_root,
        output_dir,
        &changed_file_path,
        &mut steps,
        map,
    ) {
        return finish_failed_work_package_run(
            blueprint,
            package,
            mod_root,
            output_dir,
            Some(game_root),
            &steps,
            &err,
            map,
        );
    }
    let report = work_package_run_execution_report_json(
        blueprint,
        package,
        mod_root,
        output_dir,
        Some(game_root),
        "ok",
        &steps,
        None,
        None,
    );
    Ok(WorkPackageRunExecution {
        ok: true,
        report,
        repair_bundle: None,
    })
}

fn is_non_blocking_work_package_writer(name: &str) -> bool {
    matches!(name, "author_intent" | "compile_intent")
}

fn is_work_package_mutating_writer(name: &str) -> bool {
    !is_non_blocking_work_package_writer(name)
}

fn work_package_execute_mod_path_args(map: &ArgMap) -> Vec<String> {
    repeated_values(map, "mod-path")
        .into_iter()
        .flat_map(|path| ["--mod-path".to_string(), path.to_string()])
        .collect()
}

pub(crate) fn snapshot_work_package_allowed_files(
    mod_root: &Path,
    package: &WorkPackage,
) -> Result<WorkPackageRunFileSnapshot, String> {
    let mut files = BTreeMap::new();
    for prefix in work_package_boundary_allowed_prefixes(package) {
        let root = mod_root.join(&prefix);
        if !root.exists() {
            continue;
        }
        collect_work_package_snapshot_files(mod_root, &root, &mut files)?;
    }
    Ok(WorkPackageRunFileSnapshot { files })
}

fn collect_work_package_snapshot_files(
    mod_root: &Path,
    root: &Path,
    files: &mut BTreeMap<String, Vec<u8>>,
) -> Result<(), String> {
    if root.is_file() {
        let rel = slash_path(root.strip_prefix(mod_root).unwrap_or(root));
        if rel.starts_with(".hoi4skill/") {
            return Ok(());
        }
        let bytes = fs::read(root).map_err(|e| format!("read {}: {e}", root.display()))?;
        files.insert(rel, bytes);
        return Ok(());
    }
    if !root.is_dir() {
        return Ok(());
    }
    for entry in fs::read_dir(root).map_err(|e| format!("read {}: {e}", root.display()))? {
        let entry = entry.map_err(|e| format!("read {}: {e}", root.display()))?;
        collect_work_package_snapshot_files(mod_root, &entry.path(), files)?;
    }
    Ok(())
}

pub(crate) fn diff_work_package_allowed_files(
    mod_root: &Path,
    package: &WorkPackage,
    before: &WorkPackageRunFileSnapshot,
) -> Result<Vec<String>, String> {
    let after = snapshot_work_package_allowed_files(mod_root, package)?;
    let mut changed = Vec::new();
    for (path, bytes) in &after.files {
        if before.files.get(path) != Some(bytes) {
            changed.push(path.clone());
        }
    }
    for path in before.files.keys() {
        if !after.files.contains_key(path) {
            changed.push(path.clone());
        }
    }
    changed.sort();
    changed.dedup();
    Ok(changed)
}

pub(crate) fn write_work_package_run_changed_file(
    mod_root: &Path,
    package: &WorkPackage,
    changed_paths: &[String],
) -> Result<PathBuf, String> {
    let path = mod_root
        .join(".hoi4skill")
        .join(format!("changed_{}.txt", package.id));
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
    }
    let mut text = changed_paths.join("\n");
    if !text.is_empty() {
        text.push('\n');
    }
    fs::write(&path, text).map_err(|e| format!("write {}: {e}", path.display()))?;
    Ok(path)
}

fn run_work_package_post_gates(
    package: &WorkPackage,
    mod_root: &Path,
    output_dir: &Path,
    changed_file_path: &Path,
    steps: &mut Vec<WorkPackageRunStep>,
) -> Result<(), String> {
    let post_dir = output_dir.join("post_gates");
    fs::create_dir_all(&post_dir).map_err(|e| format!("create {}: {e}", post_dir.display()))?;
    let gates: Vec<(&str, &str, Vec<String>, fn(&[String]) -> Result<(), String>)> = vec![
        (
            "boundary_gate",
            "check-work-package-boundary",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--package".to_string(),
                package.id.clone(),
                "--changed-file".to_string(),
                changed_file_path.display().to_string(),
                "--strict-names".to_string(),
                "--fail-on-violation".to_string(),
                "--output".to_string(),
                mod_root
                    .join(".hoi4skill")
                    .join(format!("boundary_{}.json", package.id))
                    .display()
                    .to_string(),
            ],
            cmd_check_work_package_boundary as fn(&[String]) -> Result<(), String>,
        ),
        (
            "package_status",
            "work-package-status",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--package".to_string(),
                package.id.clone(),
                "--output".to_string(),
                mod_root
                    .join(".hoi4skill")
                    .join(format!("status_{}.json", package.id))
                    .display()
                    .to_string(),
            ],
            cmd_work_package_status as fn(&[String]) -> Result<(), String>,
        ),
        (
            "package_readiness",
            "work-package-readiness",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--package".to_string(),
                package.id.clone(),
                "--output".to_string(),
                mod_root
                    .join(".hoi4skill")
                    .join(format!("readiness_{}.json", package.id))
                    .display()
                    .to_string(),
            ],
            cmd_work_package_readiness as fn(&[String]) -> Result<(), String>,
        ),
        (
            "package_handoff",
            "work-package-handoff",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--package".to_string(),
                package.id.clone(),
                "--output".to_string(),
                mod_root
                    .join(".hoi4skill")
                    .join(format!("handoff_{}.md", package.id))
                    .display()
                    .to_string(),
            ],
            cmd_work_package_handoff as fn(&[String]) -> Result<(), String>,
        ),
    ];
    for (name, command, args, runner) in gates {
        let command_text = format!("hoi4skill {command} {}", args.join(" "));
        match runner(&args) {
            Ok(()) => steps.push(WorkPackageRunStep {
                kind: "post_gate".to_string(),
                name: name.to_string(),
                command: command_text,
                status: "ok".to_string(),
                error: None,
            }),
            Err(err) => {
                steps.push(WorkPackageRunStep {
                    kind: "post_gate".to_string(),
                    name: name.to_string(),
                    command: command_text,
                    status: "failed".to_string(),
                    error: Some(err.clone()),
                });
                return Err(err);
            }
        }
    }
    let summary_path = post_dir.join("post_gates.json");
    let summary = work_package_run_steps_json("hoi4skill.work_package_post_gates.v1", steps);
    fs::write(&summary_path, summary)
        .map_err(|e| format!("write {}: {e}", summary_path.display()))?;
    Ok(())
}

pub(crate) fn run_work_package_success_evidence(
    package: &WorkPackage,
    mod_root: &Path,
    output_dir: &Path,
    changed_file_path: &Path,
    steps: &mut Vec<WorkPackageRunStep>,
    map: &ArgMap,
) -> Result<(), String> {
    let evidence_dir = output_dir.join("evidence");
    fs::create_dir_all(&evidence_dir)
        .map_err(|e| format!("create {}: {e}", evidence_dir.display()))?;
    let playtest_report = mod_root
        .join(".hoi4skill")
        .join(format!("playtest_{}.json", package.id));
    let playtest_plan = mod_root.join(".hoi4skill").join("playtest_plan.json");
    let playtest_gate = mod_root.join(".hoi4skill").join("playtest_gate.json");
    let package_text_alignment = mod_root
        .join(".hoi4skill")
        .join(format!("text_alignment_{}.json", package.id));
    let package_validation = mod_root
        .join(".hoi4skill")
        .join(format!("validation_{}.json", package.id));
    let package_content_audit = mod_root
        .join(".hoi4skill")
        .join(format!("content_audit_{}.json", package.id));
    let package_sample_acceptance = mod_root
        .join(".hoi4skill")
        .join(format!("sample_acceptance_{}.json", package.id));
    let content_audit = mod_root.join(".hoi4skill").join("content_audit.json");
    let evidence_pack = mod_root.join(".hoi4skill").join("evidence_pack.json");
    let review_brief = mod_root.join(".hoi4skill").join("review_brief.md");
    let release_gate = mod_root.join(".hoi4skill").join("release_gate.json");
    let run_manifest = output_dir.join("run.json");
    let expected_texts =
        author_request_alignment_expectations(value(map, "request").unwrap_or_default());
    if !expected_texts.is_empty() {
        let mut text_alignment_args = vec![
            "--mod-root".to_string(),
            mod_root.display().to_string(),
            "--output".to_string(),
            package_text_alignment.display().to_string(),
        ];
        for text in &expected_texts {
            text_alignment_args.push("--expect-text".to_string());
            text_alignment_args.push(text.clone());
        }
        let command_text = format!(
            "hoi4skill check-text-alignment {}",
            text_alignment_args.join(" ")
        );
        match cmd_check_text_alignment(&text_alignment_args) {
            Ok(()) => steps.push(WorkPackageRunStep {
                kind: "evidence".to_string(),
                name: "package_text_alignment".to_string(),
                command: command_text,
                status: "ok".to_string(),
                error: None,
            }),
            Err(err) => {
                steps.push(WorkPackageRunStep {
                    kind: "evidence".to_string(),
                    name: "package_text_alignment".to_string(),
                    command: command_text,
                    status: "failed".to_string(),
                    error: Some(err.clone()),
                });
                return Err(err);
            }
        }
    }

    let changed_paths = read_changed_paths_file(changed_file_path)?;
    if value(map, "game-root").is_none() {
        steps.push(WorkPackageRunStep {
            kind: "evidence".to_string(),
            name: "package_validation".to_string(),
            command: format!(
                "hoi4skill validate {} --game-root <missing>",
                mod_root.display()
            ),
            status: "skipped".to_string(),
            error: None,
        });
    } else if !changed_paths.is_empty() {
        let mut validation_args = vec![
            mod_root.display().to_string(),
            "--game-root".to_string(),
            require_value(map, "game-root")?.to_string(),
            "--strict-code-index".to_string(),
            "--changed-only".to_string(),
            "--output".to_string(),
            package_validation.display().to_string(),
        ];
        for mod_path in repeated_values(map, "mod-path") {
            validation_args.push("--mod-path".to_string());
            validation_args.push(mod_path.to_string());
        }
        for changed in &changed_paths {
            validation_args.push("--changed".to_string());
            validation_args.push(changed.clone());
        }
        for text in &expected_texts {
            validation_args.push("--expect-text".to_string());
            validation_args.push(text.clone());
        }
        let command_text = format!("hoi4skill validate {}", validation_args.join(" "));
        match cmd_validate(&validation_args) {
            Ok(()) => steps.push(WorkPackageRunStep {
                kind: "evidence".to_string(),
                name: "package_validation".to_string(),
                command: command_text,
                status: "ok".to_string(),
                error: None,
            }),
            Err(err) => {
                steps.push(WorkPackageRunStep {
                    kind: "evidence".to_string(),
                    name: "package_validation".to_string(),
                    command: command_text,
                    status: "failed".to_string(),
                    error: Some(err.clone()),
                });
                return Err(err);
            }
        }
    } else {
        steps.push(WorkPackageRunStep {
            kind: "evidence".to_string(),
            name: "package_validation".to_string(),
            command: format!(
                "hoi4skill validate {} --changed-only <no changed files>",
                mod_root.display()
            ),
            status: "skipped".to_string(),
            error: None,
        });
    }

    let args_and_runners: Vec<(&str, &str, Vec<String>, fn(&[String]) -> Result<(), String>)> = vec![
        (
            "playtest_report_skeleton",
            "work-package-playtest-report",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--package".to_string(),
                package.id.clone(),
                "--result".to_string(),
                "needs_review".to_string(),
                "--summary".to_string(),
                "auto-generated after writer execution; launch HOI4 and verify focus/event/decision/national-spirit/dynamic-modifier/localisation loop before marking passed".to_string(),
                "--finding".to_string(),
                "manual in-game playtest not completed".to_string(),
                "--evidence".to_string(),
                run_manifest.display().to_string(),
                "--evidence".to_string(),
                changed_file_path.display().to_string(),
                "--output".to_string(),
                playtest_report.display().to_string(),
            ],
            cmd_work_package_playtest_report as fn(&[String]) -> Result<(), String>,
        ),
        (
            "playtest_plan",
            "large-mod-playtest-plan",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--output".to_string(),
                playtest_plan.display().to_string(),
            ],
            cmd_large_mod_playtest_plan as fn(&[String]) -> Result<(), String>,
        ),
        (
            "playtest_gate",
            "large-mod-playtest-gate",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--output".to_string(),
                playtest_gate.display().to_string(),
            ],
            cmd_large_mod_playtest_gate as fn(&[String]) -> Result<(), String>,
        ),
        (
            "package_content_audit",
            "large-mod-content-audit",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--package".to_string(),
                package.id.clone(),
                "--output".to_string(),
                package_content_audit.display().to_string(),
            ],
            cmd_large_mod_content_audit as fn(&[String]) -> Result<(), String>,
        ),
        (
            "content_audit",
            "large-mod-content-audit",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--output".to_string(),
                content_audit.display().to_string(),
            ],
            cmd_large_mod_content_audit as fn(&[String]) -> Result<(), String>,
        ),
        (
            "package_sample_acceptance",
            "large-mod-sample-acceptance",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--package".to_string(),
                package.id.clone(),
                "--check-written".to_string(),
                "--require-accepted".to_string(),
                "--output".to_string(),
                package_sample_acceptance.display().to_string(),
            ],
            cmd_large_mod_sample_acceptance as fn(&[String]) -> Result<(), String>,
        ),
        (
            "evidence_pack",
            "large-mod-evidence-pack",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--output".to_string(),
                evidence_pack.display().to_string(),
            ],
            cmd_large_mod_evidence_pack as fn(&[String]) -> Result<(), String>,
        ),
        (
            "review_brief",
            "large-mod-review-brief",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--output".to_string(),
                review_brief.display().to_string(),
            ],
            cmd_large_mod_review_brief as fn(&[String]) -> Result<(), String>,
        ),
        (
            "release_gate_snapshot",
            "large-mod-release-gate",
            vec![
                "--mod-root".to_string(),
                mod_root.display().to_string(),
                "--output".to_string(),
                release_gate.display().to_string(),
            ],
            cmd_large_mod_release_gate as fn(&[String]) -> Result<(), String>,
        ),
    ];
    for (name, command, args, runner) in args_and_runners {
        let command_text = format!("hoi4skill {command} {}", args.join(" "));
        match runner(&args) {
            Ok(()) => steps.push(WorkPackageRunStep {
                kind: "evidence".to_string(),
                name: name.to_string(),
                command: command_text,
                status: "ok".to_string(),
                error: None,
            }),
            Err(err) => {
                steps.push(WorkPackageRunStep {
                    kind: "evidence".to_string(),
                    name: name.to_string(),
                    command: command_text,
                    status: "failed".to_string(),
                    error: Some(err.clone()),
                });
                return Err(err);
            }
        }
    }
    let summary_path = evidence_dir.join("evidence_steps.json");
    let summary = work_package_run_steps_json("hoi4skill.work_package_success_evidence.v1", steps);
    fs::write(&summary_path, summary)
        .map_err(|e| format!("write {}: {e}", summary_path.display()))?;
    if map.flags.contains("require-playtest-pass") {
        return Err(
            "run-work-package generated a needs_review playtest skeleton; rerun after real in-game playtest evidence is attached".to_string(),
        );
    }
    Ok(())
}

pub(crate) fn read_changed_paths_file(path: &Path) -> Result<Vec<String>, String> {
    let text = read_utf8_lossy(path)?;
    Ok(text
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(str::to_string)
        .collect())
}

fn author_request_alignment_expectations(request: &str) -> Vec<String> {
    let mut out = Vec::new();
    for labels in [
        &["国策", "focus"][..],
        &["事件", "事件文案", "event text", "event"][..],
        &["决议", "decision"][..],
        &[
            "增加民族精神",
            "新增民族精神",
            "民族精神",
            "national spirit",
            "national idea",
        ][..],
        &["本地化", "localisation", "localization"][..],
    ] {
        if let Some(value) = extract_labeled_value(request, labels) {
            push_unique_alignment_expectation(&mut out, &value);
        }
    }
    let event_desc = event_description_from_user_request(request);
    if event_desc != request.trim() {
        push_unique_alignment_expectation(&mut out, &event_desc);
    }
    for title in extract_event_chain_titles(request) {
        if title != "用户需求事件" {
            push_unique_alignment_expectation(&mut out, &title);
        }
    }
    out
}

fn push_unique_alignment_expectation(out: &mut Vec<String>, value: &str) {
    let value = cleanup_labeled_value(value);
    if !is_alignment_text_candidate(&value) {
        return;
    }
    let key = normalize_text_for_alignment(&value);
    if key.is_empty()
        || out
            .iter()
            .any(|existing| normalize_text_for_alignment(existing) == key)
    {
        return;
    }
    out.push(value);
}

fn finish_failed_work_package_run(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    mod_root: &Path,
    output_dir: &Path,
    game_root: Option<&str>,
    steps: &[WorkPackageRunStep],
    error: &str,
    map: &ArgMap,
) -> Result<WorkPackageRunExecution, String> {
    let repair_bundle = write_work_package_run_repair_bundle(
        blueprint, package, mod_root, output_dir, game_root, steps, error, map,
    )?;
    let report = work_package_run_execution_report_json(
        blueprint,
        package,
        mod_root,
        output_dir,
        game_root,
        "failed",
        steps,
        Some(error),
        Some(&repair_bundle),
    );
    Ok(WorkPackageRunExecution {
        ok: false,
        report,
        repair_bundle: Some(repair_bundle),
    })
}

fn write_work_package_run_repair_bundle(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    mod_root: &Path,
    output_dir: &Path,
    game_root: Option<&str>,
    steps: &[WorkPackageRunStep],
    error: &str,
    map: &ArgMap,
) -> Result<PathBuf, String> {
    let repair_dir = mod_root
        .join(".hoi4skill")
        .join(format!("repair_bundle_{}", package.id));
    fs::create_dir_all(&repair_dir).map_err(|e| format!("create {}: {e}", repair_dir.display()))?;
    let failed_output_path = repair_dir.join("failed_output.md");
    let repair_prompt_path = repair_dir.join("repair_prompt.md");
    let input_repair_prompt_path = repair_dir.join("input_repair_prompt.md");
    let repair_bundle_path = repair_dir.join("repair_bundle.json");
    let failed_output = work_package_run_failed_output_markdown(
        blueprint, package, mod_root, output_dir, game_root, steps, error,
    );
    fs::write(&failed_output_path, &failed_output)
        .map_err(|e| format!("write {}: {e}", failed_output_path.display()))?;
    let retrieved_context = write_work_package_run_retrieved_repair_context(
        package,
        mod_root,
        output_dir,
        &repair_dir,
        game_root,
        steps,
        error,
        map,
    )?;
    let edit_context_path = output_dir.join("authoring").join("context.md");
    let edit_context = read_utf8_lossy(&edit_context_path).unwrap_or_else(|_| {
        format!(
            "# Work Package {}\n\nNo authoring context was available.",
            package.id
        )
    });
    let failed_output_input = (failed_output_path.clone(), failed_output.clone());
    let retrieved_context_input = (
        retrieved_context.markdown_path.clone(),
        retrieved_context.markdown.clone(),
    );
    let repair_prompt = render_ai_repair_prompt(
        value(map, "request"),
        &edit_context_path,
        &edit_context,
        Some(&retrieved_context_input),
        Some(&failed_output_input),
        80_000,
        40_000,
        40_000,
    );
    fs::write(&repair_prompt_path, repair_prompt)
        .map_err(|e| format!("write {}: {e}", repair_prompt_path.display()))?;
    let input_repair_prompt = work_package_input_repair_prompt_markdown(
        package,
        mod_root,
        output_dir,
        game_root,
        &failed_output_path,
        &retrieved_context.markdown_path,
        &repair_bundle_path,
        value(map, "request"),
    );
    fs::write(&input_repair_prompt_path, input_repair_prompt)
        .map_err(|e| format!("write {}: {e}", input_repair_prompt_path.display()))?;
    let artifacts = [
        ("failed_output_pack", failed_output_path.clone()),
        (
            "retrieved_code_context",
            retrieved_context.markdown_path.clone(),
        ),
        (
            "retrieved_code_context_json",
            retrieved_context.json_path.clone(),
        ),
        ("ai_repair_prompt", repair_prompt_path.clone()),
        ("input_repair_prompt", input_repair_prompt_path.clone()),
        ("run_manifest", output_dir.join("run.json")),
        ("execution_report", output_dir.join("execution_report.json")),
    ]
    .into_iter()
    .map(|(name, path)| {
        format!(
            "{{\"name\": {}, \"path\": {}}}",
            json_str(name),
            json_str(&path.display().to_string())
        )
    })
    .collect::<Vec<_>>()
    .join(", ");
    let next_commands = vec![
        format!(
            "hoi4skill apply-work-package-repair --repair-bundle {} --input <ai_repair_inputs.md> --execute --game-root <HOI4 root>",
            repair_bundle_path.display()
        ),
        format!(
            "hoi4skill run-work-package --mod-root {} --package {} --execute --game-root <HOI4 root>",
            mod_root.display(),
            package.id
        ),
        format!(
            "hoi4skill large-mod-release-gate --mod-root {} --output {}",
            mod_root.display(),
            work_package_run_report_path(&mod_root.display().to_string(), "release_gate.json")
        ),
    ];
    let bundle = format!(
        "{{\n  \"schema\": \"hoi4skill.ai_repair_bundle.v1\",\n  \"status\": \"repair_prompt_ready\",\n  \"validation_ok\": false,\n  \"mod_root\": {},\n  \"game_root\": {},\n  \"output_dir\": {},\n  \"package\": {},\n  \"source\": \"run-work-package\",\n  \"retrieval_status\": {},\n  \"artifacts\": [{}],\n  \"next_commands\": {}\n}}\n",
        json_str(&mod_root.display().to_string()),
        json_optional_str(game_root),
        json_str(&repair_dir.display().to_string()),
        json_str(&package.id),
        json_str(&retrieved_context.status),
        artifacts,
        json_array(&next_commands),
    );
    fs::write(&repair_bundle_path, bundle)
        .map_err(|e| format!("write {}: {e}", repair_bundle_path.display()))?;
    Ok(repair_bundle_path)
}

fn work_package_input_repair_prompt_markdown(
    package: &WorkPackage,
    mod_root: &Path,
    output_dir: &Path,
    game_root: Option<&str>,
    failed_output_path: &Path,
    retrieved_context_path: &Path,
    repair_bundle_path: &Path,
    request: Option<&str>,
) -> String {
    let mut out = String::new();
    out.push_str("# Work Package Input Repair Prompt\n\n");
    out.push_str("- schema: `hoi4skill.work_package_input_repair_prompt.v1`\n");
    out.push_str(&format!("- package: `{}`\n", package.id));
    out.push_str(&format!("- mod_root: `{}`\n", mod_root.display()));
    out.push_str(&format!("- output_dir: `{}`\n", output_dir.display()));
    out.push_str(&format!(
        "- game_root: `{}`\n",
        game_root.unwrap_or("<missing>")
    ));
    if let Some(request) = request {
        out.push_str(&format!(
            "- user_request: `{}`\n",
            truncate_chars(&request.replace('`', "'"), 500)
        ));
    }
    out.push_str(&format!(
        "- failed_output: `{}`\n",
        failed_output_path.display()
    ));
    out.push_str(&format!(
        "- retrieved_code_context: `{}`\n",
        retrieved_context_path.display()
    ));
    out.push_str("\n## Task\n\n");
    out.push_str("Repair the work-package input templates only. Return only fenced blocks whose info string starts with `hoi4skill-input:` and one of the allowed kinds below. Do not output diffs, final Clausewitz files, file paths, prose outside fenced blocks, or changes to `common/`, `events/`, `localisation/`, `interface/`, or any other final mod directory.\n");
    out.push_str("\n## Allowed Output Blocks\n\n");
    for kind in work_package_repair_input_kinds() {
        out.push_str(&format!(
            "- ```hoi4skill-input:{kind}``` writes `{}`\n",
            work_package_repair_input_filename(kind)
        ));
    }
    out.push_str("\n## Apply Command\n\n");
    out.push_str(&markdown_fence(
        "powershell",
        &format!(
            "hoi4skill apply-work-package-repair --repair-bundle \"{}\" --input \"<ai_repair_inputs.md>\" --execute --game-root \"<HOI4 root>\"",
            repair_bundle_path.display()
        ),
    ));
    let evidence_answers_path = mod_root
        .join(".hoi4skill")
        .join(format!("context_evidence_answers_{}.md", package.id));
    if let Ok(answers) = read_utf8_lossy(&evidence_answers_path) {
        out.push_str("\n## User Context Evidence Answers\n\n");
        out.push_str("- status: `recorded_not_verified`\n");
        out.push_str("- rule: Use these answers as hints only; verify symbols against local HOI4/dependency indexes before final output.\n\n");
        out.push_str(&markdown_fence(
            "markdown",
            &truncate_chars(&answers, 12_000),
        ));
    }
    let style_context_path = output_dir.join("inputs").join("style_context.md");
    out.push_str("\n## Style Context\n\n");
    out.push_str(&format!("- path: `{}`\n", style_context_path.display()));
    out.push_str("- rule: Apply this style context to repaired focus, event, idea, intent, and localisation inputs for cadence and density only.\n");
    out.push_str("- rule: Do not copy source prose, titles, option text, named jokes, or worldbuilding from style mods.\n\n");
    match read_utf8_lossy(&style_context_path) {
        Ok(text) => out.push_str(&markdown_fence(
            "markdown",
            &truncate_chars(&text, 16_000),
        )),
        Err(_) => out.push_str(
            "- No style context file exists yet; use the built-in templates and user request only.\n",
        ),
    }
    out.push_str("\n## Current Input Templates\n\n");
    let input_dir = output_dir.join("inputs");
    for kind in work_package_repair_input_kinds() {
        let filename = work_package_repair_input_filename(kind);
        let path = input_dir.join(filename);
        out.push_str(&format!("### `{kind}` -> `{}`\n\n", path.display()));
        match read_utf8_lossy(&path) {
            Ok(text) => out.push_str(&markdown_fence(
                &format!("hoi4skill-input:{kind}"),
                &truncate_chars(&text, 12_000),
            )),
            Err(_) => out.push_str("- Missing current input file; emit a complete replacement block only if this kind is needed.\n"),
        }
        out.push('\n');
    }
    out.push_str("\n## Stop Rules\n\n");
    out.push_str("- If the retrieved context lacks a required symbol, dynamic modifier helper, sprite, tag, leader, or localisation token, ask for evidence in plain text instead of inventing a block.\n");
    out.push_str("- Dynamic modifier requests belong in `dynamic_modifier_intent`, not `feature_cards`, unless the user explicitly asked for a national spirit.\n");
    out.push_str("- National spirit creation or replacement belongs in `feature_cards`/`intent`; use writer-owned structured text, not raw final files.\n");
    out.push_str("- Localisation icons, colors, flags, leaders, and cosmetic tag aliases belong in `localisation_placeholders`; unresolved tokens must remain questions, not guessed keys.\n");
    out
}

fn work_package_repair_input_kinds() -> &'static [&'static str] {
    &[
        "focus_layout",
        "event_cards",
        "feature_cards",
        "intent",
        "dynamic_modifier_intent",
        "localisation_placeholders",
        "translated_localisation",
    ]
}

fn write_work_package_run_retrieved_repair_context(
    package: &WorkPackage,
    mod_root: &Path,
    output_dir: &Path,
    repair_dir: &Path,
    game_root: Option<&str>,
    steps: &[WorkPackageRunStep],
    error: &str,
    map: &ArgMap,
) -> Result<WorkPackageRunRetrievedRepairContext, String> {
    let markdown_path = repair_dir.join("retrieved_code_context.md");
    let json_path = repair_dir.join("retrieved_code_context.json");
    let queries = work_package_run_repair_queries(package, output_dir, steps, error, map);
    let context = build_work_package_run_retrieved_repair_context(
        package, mod_root, game_root, &queries, map,
    );
    fs::write(&markdown_path, &context.markdown)
        .map_err(|e| format!("write {}: {e}", markdown_path.display()))?;
    fs::write(&json_path, &context.json)
        .map_err(|e| format!("write {}: {e}", json_path.display()))?;
    Ok(WorkPackageRunRetrievedRepairContext {
        status: context.status,
        markdown_path,
        json_path,
        markdown: context.markdown,
    })
}

struct WorkPackageRunRetrievedRepairPayload {
    status: String,
    markdown: String,
    json: String,
}

fn build_work_package_run_retrieved_repair_context(
    package: &WorkPackage,
    mod_root: &Path,
    game_root: Option<&str>,
    queries: &[String],
    map: &ArgMap,
) -> WorkPackageRunRetrievedRepairPayload {
    let Some(game_root) = game_root.filter(|value| !value.trim().is_empty()) else {
        return work_package_run_retrieved_repair_unavailable(
            package,
            mod_root,
            None,
            queries,
            "missing_game_root",
            "No --game-root was available, so local HOI4 code retrieval was not possible.",
        );
    };
    let game_root_path = match normalize_path(game_root) {
        Ok(path) => path,
        Err(err) => {
            return work_package_run_retrieved_repair_unavailable(
                package,
                mod_root,
                Some(game_root),
                queries,
                "unavailable",
                &format!("Could not normalize --game-root: {err}"),
            );
        }
    };
    let dependency_roots = match dependency_mod_roots(map) {
        Ok(paths) => paths,
        Err(err) => {
            return work_package_run_retrieved_repair_unavailable(
                package,
                mod_root,
                Some(game_root),
                queries,
                "unavailable",
                &format!("Could not resolve --mod-path dependencies: {err}"),
            );
        }
    };
    let index = match build_game_index_with_mod_paths(&game_root_path, &dependency_roots) {
        Ok(index) => index,
        Err(err) => {
            return work_package_run_retrieved_repair_unavailable(
                package,
                mod_root,
                Some(game_root),
                queries,
                "unavailable",
                &format!("Could not build local strict code index: {err}"),
            );
        }
    };
    let library_path = value(map, "code-library")
        .map(normalize_path)
        .transpose()
        .ok()
        .flatten();
    let libraries = match ensure_clausewitz_libraries(&game_root_path, &[], library_path.as_deref())
    {
        Ok(libraries) => libraries,
        Err(_) => Vec::new(),
    };
    let mut symbols = Vec::new();
    push_exact_indexed_symbols_from_queries(&mut symbols, &index, queries);
    for query in queries.iter().take(10) {
        for symbol in related_code_symbol_matches(&index, query, None, 6) {
            if !symbols.iter().any(|existing: &CodeSymbolMatch| {
                existing.category == symbol.category
                    && existing.kind == symbol.kind
                    && existing.symbol == symbol.symbol
            }) {
                symbols.push(symbol);
            }
            if symbols.len() >= 30 {
                break;
            }
        }
        if symbols.len() >= 30 {
            break;
        }
    }
    let mut examples = Vec::new();
    if !libraries.is_empty() {
        for query in queries.iter().take(8) {
            if let Ok(found) = query_clausewitz_libraries(&libraries, query, None, 3) {
                for example in found {
                    if !examples.iter().any(|existing: &ClausewitzExample| {
                        existing.system == example.system
                            && existing.symbol == example.symbol
                            && existing.source == example.source
                    }) {
                        examples.push(example);
                    }
                    if examples.len() >= 12 {
                        break;
                    }
                }
            }
            if examples.len() >= 12 {
                break;
            }
        }
    }
    let status = if symbols.is_empty() && examples.is_empty() {
        "no_matches"
    } else {
        "ok"
    };
    let markdown = work_package_run_retrieved_repair_markdown(
        package,
        mod_root,
        Some(game_root),
        status,
        queries,
        &symbols,
        &examples,
        None,
    );
    let json = work_package_run_retrieved_repair_json(
        package,
        mod_root,
        Some(game_root),
        status,
        queries,
        &symbols,
        &examples,
        None,
    );
    WorkPackageRunRetrievedRepairPayload {
        status: status.to_string(),
        markdown,
        json,
    }
}

fn push_exact_indexed_symbols_from_queries(
    out: &mut Vec<CodeSymbolMatch>,
    index: &GameIndex,
    queries: &[String],
) {
    for query in queries.iter().take(40) {
        for symbol in backtick_code_symbols(query) {
            for matched in code_symbol_matches(index, &symbol, None) {
                if !out.iter().any(|existing| {
                    existing.category == matched.category
                        && existing.kind == matched.kind
                        && existing.symbol == matched.symbol
                }) {
                    out.push(matched);
                }
                if out.len() >= 30 {
                    return;
                }
            }
        }
    }
}

fn backtick_code_symbols(text: &str) -> Vec<String> {
    let mut rest = text;
    let mut out = Vec::new();
    while let Some(start) = rest.find('`') {
        rest = &rest[start + 1..];
        let Some(end) = rest.find('`') else {
            break;
        };
        let symbol = rest[..end].trim();
        if author_intent_workflow_code_symbol_like(symbol)
            && !out.iter().any(|existing| existing == symbol)
        {
            out.push(symbol.to_string());
        }
        rest = &rest[end + 1..];
    }
    out
}

fn work_package_run_retrieved_repair_unavailable(
    package: &WorkPackage,
    mod_root: &Path,
    game_root: Option<&str>,
    queries: &[String],
    status: &str,
    reason: &str,
) -> WorkPackageRunRetrievedRepairPayload {
    let markdown = work_package_run_retrieved_repair_markdown(
        package,
        mod_root,
        game_root,
        status,
        queries,
        &[],
        &[],
        Some(reason),
    );
    let json = work_package_run_retrieved_repair_json(
        package,
        mod_root,
        game_root,
        status,
        queries,
        &[],
        &[],
        Some(reason),
    );
    WorkPackageRunRetrievedRepairPayload {
        status: status.to_string(),
        markdown,
        json,
    }
}

fn work_package_run_repair_queries(
    package: &WorkPackage,
    output_dir: &Path,
    steps: &[WorkPackageRunStep],
    error: &str,
    map: &ArgMap,
) -> Vec<String> {
    let mut queries = Vec::new();
    push_work_package_repair_query(&mut queries, &package.title);
    push_work_package_repair_query(&mut queries, error);
    if let Some(request) = value(map, "request") {
        push_work_package_repair_query(&mut queries, request);
    }
    for step in steps {
        push_work_package_repair_query(&mut queries, &step.name);
        push_work_package_repair_query(&mut queries, &step.command);
        if let Some(error) = &step.error {
            push_work_package_repair_query(&mut queries, error);
        }
    }
    let inputs = output_dir.join("inputs");
    for name in [
        "intent.txt",
        "focus_layout.txt",
        "event_cards.txt",
        "feature_cards.txt",
        "dynamic_modifier_intent.txt",
        "localisation_placeholders.txt",
    ] {
        if let Ok(text) = read_utf8_lossy(&inputs.join(name)) {
            for line in text.lines() {
                push_work_package_repair_query(&mut queries, line);
            }
        }
    }
    queries.truncate(40);
    queries
}

pub(crate) fn ai_output_insurance_queries(
    package: &WorkPackage,
    source: &str,
    map: &ArgMap,
) -> Vec<String> {
    let mut queries = Vec::new();
    push_work_package_repair_query(&mut queries, &package.title);
    if let Some(request) = value(map, "request") {
        push_work_package_repair_query(&mut queries, request);
    }
    let analysis = analyze_large_mod_ai_output_insurance_source(source);
    if analysis.direct_clausewitz_code {
        push_work_package_repair_query(&mut queries, "compile-intent strict-code-index");
        push_work_package_repair_query(&mut queries, "structured work package inputs");
    }
    if analysis.dynamic_modifier_as_national_spirit {
        push_work_package_repair_query(&mut queries, "dynamic modifier scripted_effect protocol");
        push_work_package_repair_query(&mut queries, "custom_effect_tooltip set_temp_variable");
        push_work_package_repair_query(&mut queries, "add_dynamic_modifier dynamic_modifier");
    }
    if ai_output_mentions_localisation_placeholder_or_icon(source) {
        push_work_package_repair_query(&mut queries, "localisation placeholders icon spriteType");
        push_work_package_repair_query(&mut queries, "author-placeholder-plan localisation");
    }
    for line in source.lines() {
        for query in ai_output_insurance_error_queries(line) {
            push_work_package_repair_query(&mut queries, &query);
        }
        push_work_package_repair_query(&mut queries, line);
        for token in ai_output_insurance_code_tokens(line) {
            push_work_package_repair_query(&mut queries, &token);
        }
    }
    queries.truncate(60);
    queries
}

fn ai_output_insurance_error_queries(line: &str) -> Vec<String> {
    let mut queries = Vec::new();
    for (needle, kind) in [
        ("unknown effect `", "effect"),
        ("unknown trigger `", "trigger"),
        ("unknown modifier `", "modifier"),
        ("unindexed effect `", "effect"),
        ("unindexed trigger `", "trigger"),
        ("unindexed modifier `", "modifier"),
        ("unindexed icon `", "resource_id"),
        ("unknown icon `", "resource_id"),
        ("unindexed country scope `", "country_tag"),
        ("unknown country tag `", "country_tag"),
        ("unknown idea `", "idea"),
        ("unindexed idea `", "idea"),
        ("event picture `", "event_picture"),
        ("unknown event picture `", "event_picture"),
    ] {
        for symbol in extract_backtick_symbols_after(line, needle) {
            push_ai_output_error_query(&mut queries, kind, &symbol);
        }
    }
    for (needle, kind) in [
        ("unknown effect ", "effect"),
        ("unknown trigger ", "trigger"),
        ("unknown modifier ", "modifier"),
        ("unindexed effect ", "effect"),
        ("unindexed trigger ", "trigger"),
        ("unindexed modifier ", "modifier"),
    ] {
        if let Some(symbol) = extract_identifier_after(line, needle) {
            push_ai_output_error_query(&mut queries, kind, &symbol);
        }
    }
    queries
}

fn extract_backtick_symbols_after(line: &str, needle: &str) -> Vec<String> {
    let lower = line.to_ascii_lowercase();
    let needle_lower = needle.to_ascii_lowercase();
    let mut offset = 0usize;
    let mut symbols = Vec::new();
    while let Some(idx) = lower[offset..].find(&needle_lower) {
        let start = offset + idx + needle.len();
        let Some(rest) = line.get(start..) else {
            break;
        };
        let Some(end) = rest.find('`') else {
            break;
        };
        let symbol = rest[..end].trim();
        if !symbol.is_empty() && !symbols.iter().any(|existing| existing == symbol) {
            symbols.push(symbol.to_string());
        }
        offset = start + end + 1;
        if symbols.len() >= 8 {
            break;
        }
    }
    symbols
}

fn extract_identifier_after(line: &str, needle: &str) -> Option<String> {
    let lower = line.to_ascii_lowercase();
    let needle_lower = needle.to_ascii_lowercase();
    let idx = lower.find(&needle_lower)?;
    let start = idx + needle.len();
    let rest = line.get(start..)?.trim_start();
    let symbol = rest
        .trim_start_matches(['`', '\'', '"'])
        .split(|ch: char| !(ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '-' | '@')))
        .next()
        .unwrap_or("")
        .trim_matches(['`', '\'', '"']);
    (!symbol.is_empty()).then(|| symbol.to_string())
}

fn push_ai_output_error_query(out: &mut Vec<String>, kind: &str, symbol: &str) {
    let symbol = symbol.trim();
    if symbol.is_empty() {
        return;
    }
    for query in [
        symbol.to_string(),
        format!("{kind} {symbol}"),
        format!("check-code-symbol {kind} {symbol}"),
    ] {
        if !out.iter().any(|existing| existing == &query) {
            out.push(query);
        }
    }
}

fn ai_output_insurance_code_tokens(line: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    for raw in
        line.split(|ch: char| !(ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '-' | '@')))
    {
        let token = raw
            .trim_matches(|ch: char| matches!(ch, '_' | '.' | '-' | '@'))
            .trim();
        if token.len() < 3 {
            continue;
        }
        let looks_like_code = token.contains('_')
            || token.contains('.')
            || token.starts_with("GFX")
            || token.chars().all(|ch| ch.is_ascii_uppercase());
        if looks_like_code && !tokens.iter().any(|existing| existing == token) {
            tokens.push(token.to_string());
        }
        if tokens.len() >= 20 {
            break;
        }
    }
    tokens
}

struct LargeModAiOutputInsuranceAnalysis {
    direct_clausewitz_code: bool,
    dynamic_modifier_as_national_spirit: bool,
    suspicious_code_tokens: Vec<String>,
}

impl LargeModAiOutputInsuranceAnalysis {
    fn blocking_count(&self) -> usize {
        usize::from(self.direct_clausewitz_code)
            + usize::from(self.dynamic_modifier_as_national_spirit)
            + usize::from(!self.suspicious_code_tokens.is_empty())
    }

    fn to_json(&self) -> String {
        let mut findings = Vec::new();
        if self.direct_clausewitz_code {
            findings.push(
                "ai_output_contains_direct_clausewitz_code_use_structured_inputs".to_string(),
            );
        }
        if self.dynamic_modifier_as_national_spirit {
            findings.push(
                "dynamic_modifier_appears_routed_through_add_ideas_or_national_spirit".to_string(),
            );
        }
        if !self.suspicious_code_tokens.is_empty() {
            findings.push("suspicious_code_tokens_require_indexed_writer_validation".to_string());
        }
        format!(
            "{{\"direct_clausewitz_code\": {}, \"dynamic_modifier_as_national_spirit\": {}, \"suspicious_code_tokens\": {}, \"blocking_count\": {}, \"findings\": {}}}",
            json_bool(self.direct_clausewitz_code),
            json_bool(self.dynamic_modifier_as_national_spirit),
            json_array(&self.suspicious_code_tokens),
            self.blocking_count(),
            json_array(&findings),
        )
    }
}

fn analyze_large_mod_ai_output_insurance_source(source: &str) -> LargeModAiOutputInsuranceAnalysis {
    let direct_clausewitz_code = source
        .lines()
        .any(ai_output_line_looks_like_clausewitz_code);
    let dynamic_modifier_as_national_spirit = ai_output_mentions_dynamic_modifier(source)
        && source
            .lines()
            .any(|line| line.contains("add_ideas") || line.contains("swap_ideas"));
    let mut suspicious_code_tokens = Vec::new();
    for line in source.lines() {
        for token in ai_output_insurance_code_tokens(line) {
            if !suspicious_code_tokens
                .iter()
                .any(|existing| existing == &token)
            {
                suspicious_code_tokens.push(token);
            }
            if suspicious_code_tokens.len() >= 30 {
                break;
            }
        }
        if suspicious_code_tokens.len() >= 30 {
            break;
        }
    }
    LargeModAiOutputInsuranceAnalysis {
        direct_clausewitz_code,
        dynamic_modifier_as_national_spirit,
        suspicious_code_tokens,
    }
}

fn ai_output_line_looks_like_clausewitz_code(line: &str) -> bool {
    let trimmed = line.trim();
    if trimmed.is_empty() || trimmed.starts_with('#') {
        return false;
    }
    trimmed.contains(" = {")
        || trimmed.ends_with("= {")
        || trimmed.starts_with("country_event =")
        || trimmed.starts_with("news_event =")
        || trimmed.starts_with("state_event =")
        || trimmed.starts_with("option =")
        || trimmed.starts_with("completion_reward =")
        || trimmed.starts_with("available =")
        || trimmed.starts_with("visible =")
        || trimmed.starts_with("complete_effect =")
}

fn ai_output_mentions_dynamic_modifier(source: &str) -> bool {
    let lower = source.to_ascii_lowercase();
    lower.contains("dynamic_modifier")
        || lower.contains("dynamic modifier")
        || source.contains("动态修正")
        || source.contains("动态修饰")
        || source.contains("的效果")
}

fn ai_output_mentions_localisation_placeholder_or_icon(source: &str) -> bool {
    let lower = source.to_ascii_lowercase();
    source.contains('【')
        || source.contains('§')
        || lower.contains("localisation")
        || lower.contains("localization")
        || lower.contains("sprite")
        || lower.contains("spriteType")
        || lower.contains("gfx_")
        || lower.contains("icon")
        || lower.contains("flag")
        || source.contains("图标")
        || source.contains("国旗")
        || source.contains("本地化")
}

fn large_mod_ai_output_insurance_repair_plan_json(
    analysis: &LargeModAiOutputInsuranceAnalysis,
    mod_root: &Path,
    package: &WorkPackage,
    game_root: Option<&str>,
    source: &str,
    queries: &[String],
) -> String {
    let mut steps = Vec::new();
    let root = mod_root.display().to_string();
    let game = game_root.unwrap_or("<HOI4 root>");
    if analysis.direct_clausewitz_code {
        steps.push(format!(
            "{{\"id\": \"direct_clausewitz_code\", \"severity\": \"blocking\", \"required_route\": \"convert intent to writer-owned inputs before final script output\", \"forbidden_fallback\": \"do not paste AI Clausewitz directly into final mod files\", \"commands\": {}}}",
            json_array(&vec![
                format!("hoi4skill compile-intent --kind auto --game-root {game} --strict-code-index --text <natural-language-effect>"),
                format!("hoi4skill run-work-package --mod-root {root} --package {} --game-root {game} --execute", package.id),
            ])
        ));
    }
    if analysis.dynamic_modifier_as_national_spirit {
        steps.push(format!(
            "{{\"id\": \"dynamic_modifier_as_national_spirit\", \"severity\": \"blocking\", \"required_route\": \"regenerate dynamic_modifier_intent and use verified dynamic modifier/scripted_effect protocol\", \"forbidden_fallback\": \"do not replace add_dynamic_modifier/scripted_effect protocol with add_ideas, remove_ideas, has_idea, or swap_ideas\", \"commands\": {}}}",
            json_array(&vec![
                format!("hoi4skill plan-dynamic-modifier-change --mod-path {root} --game-root {game} --strict-code-index --text <dynamic modifier intent>"),
                format!("hoi4skill large-mod-ai-output-insurance --mod-root {root} --package {} --input <failed_output.md> --game-root {game}", package.id),
            ])
        ));
    }
    if !analysis.suspicious_code_tokens.is_empty() {
        let mut commands = Vec::new();
        for token in analysis.suspicious_code_tokens.iter().take(8) {
            commands.push(format!(
                "hoi4skill check-code-symbol --game-root {game} --mod-path {root} --symbol {token}"
            ));
        }
        steps.push(format!(
            "{{\"id\": \"suspicious_code_tokens\", \"severity\": \"blocking\", \"required_route\": \"verify every symbol through strict code index or semantic candidates before writer rerun\", \"forbidden_fallback\": \"do not silently rename, drop, or invent unindexed effects, triggers, ideas, sprites, tags, or modifiers\", \"symbols\": {}, \"commands\": {}}}",
            json_array(&analysis.suspicious_code_tokens.iter().take(20).cloned().collect::<Vec<_>>()),
            json_array(&commands)
        ));
    }
    if ai_output_mentions_localisation_placeholder_or_icon(source) {
        steps.push(format!(
            "{{\"id\": \"localisation_placeholder_or_icon\", \"severity\": \"review\", \"required_route\": \"route icons, flags, colour codes, leaders, country aliases, and cosmetic tags through localisation_placeholders plus strict validation\", \"forbidden_fallback\": \"do not invent spriteType, cosmetic tag, country tag, scripted localisation, or icon aliases when local evidence is missing\", \"commands\": {}}}",
            json_array(&vec![
                format!("hoi4skill author-placeholder-plan --mod-root {root} --game-root {game} --text <localisation prose>"),
                format!("hoi4skill check-text-alignment --mod-root {root} --input <user request>"),
            ])
        ));
    }
    if steps.is_empty() {
        steps.push(format!(
            "{{\"id\": \"no_blocking_pattern_detected\", \"severity\": \"review\", \"required_route\": \"still use retrieved local evidence and writer-owned inputs before accepting the output\", \"forbidden_fallback\": \"do not treat no pattern match as permission to bypass validate --strict-code-index\", \"queries\": {}}}",
            json_array(&queries.iter().take(20).cloned().collect::<Vec<_>>())
        ));
    }
    format!("[{}]", steps.join(", "))
}

fn large_mod_ai_output_insurance_repair_plan_markdown(
    analysis: &LargeModAiOutputInsuranceAnalysis,
    mod_root: &Path,
    package: &WorkPackage,
    game_root: Option<&str>,
    source: &str,
) -> String {
    let mut out = String::new();
    let root = mod_root.display();
    let game = game_root.unwrap_or("<HOI4 root>");
    out.push_str("## Repair Plan\n\n");
    if analysis.direct_clausewitz_code {
        out.push_str("- `direct_clausewitz_code`: convert prose/effects through `compile-intent --strict-code-index` or package inputs; do not paste AI Clausewitz into final files.\n");
    }
    if analysis.dynamic_modifier_as_national_spirit {
        out.push_str("- `dynamic_modifier_as_national_spirit`: regenerate `dynamic_modifier_intent.txt`; use `plan-dynamic-modifier-change` and verified `custom_effect_tooltip`/variable/scripted-effect protocol, not `add_ideas` or `swap_ideas`.\n");
    }
    if !analysis.suspicious_code_tokens.is_empty() {
        out.push_str("- `suspicious_code_tokens`: run `check-code-symbol` or semantic lookup for every listed token before rerunning writers.\n");
    }
    if ai_output_mentions_localisation_placeholder_or_icon(source) {
        out.push_str("- `localisation_placeholder_or_icon`: route prose through `localisation_placeholders.txt` and `author-placeholder-plan`; ask the user when local icon, flag, cosmetic tag, or scripted localisation evidence is missing.\n");
    }
    if analysis.blocking_count() == 0
        && !ai_output_mentions_localisation_placeholder_or_icon(source)
    {
        out.push_str("- `review`: use retrieved evidence and writer-owned inputs; final output still needs strict validation.\n");
    }
    out.push_str(&format!(
        "- rerun: `hoi4skill run-work-package --mod-root {root} --package {} --execute --game-root {game}`\n\n",
        package.id
    ));
    out
}

fn large_mod_ai_output_insurance_json(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    mod_root: &Path,
    game_root: Option<&str>,
    source: &str,
    queries: &[String],
    payload: &WorkPackageRunRetrievedRepairPayload,
) -> String {
    let retrieval_ok = payload.status == "ok";
    let analysis = analyze_large_mod_ai_output_insurance_source(source);
    let repair_plan = large_mod_ai_output_insurance_repair_plan_json(
        &analysis, mod_root, package, game_root, source, queries,
    );
    let source_line_count = source
        .lines()
        .filter(|line| !line.trim().is_empty())
        .count();
    let next_commands = vec![
        format!(
            "hoi4skill large-mod-ai-output-insurance --mod-root {} --package {} --input <failed_output.md> --game-root <HOI4 root> --output .hoi4skill/ai_output_insurance_{}.json --markdown-output .hoi4skill/ai_output_insurance_{}.md",
            mod_root.display(),
            package.id,
            package.id,
            package.id
        ),
        format!(
            "hoi4skill apply-work-package-repair --repair-bundle {}/.hoi4skill/repair_bundle_{} --input <ai_repair_inputs.md> --execute --game-root <HOI4 root>",
            mod_root.display(),
            package.id
        ),
        format!(
            "hoi4skill run-work-package --mod-root {} --package {} --execute --game-root <HOI4 root>",
            mod_root.display(),
            package.id
        ),
    ];
    format!(
        "{{\n  \"schema\": \"hoi4skill.ai_output_insurance.v1\",\n  \"status\": {},\n  \"retrieval_ok\": {},\n  \"mod\": {},\n  \"acronym\": {},\n  \"mod_root\": {},\n  \"game_root\": {},\n  \"package\": {},\n  \"source_line_count\": {},\n  \"query_count\": {},\n  \"queries\": {},\n  \"analysis\": {},\n  \"repair_plan\": {},\n  \"retrieved_context\": {},\n  \"next_commands\": {},\n  \"stop_conditions\": {}\n}}\n",
        json_str(&payload.status),
        json_bool(retrieval_ok),
        json_str(&blueprint.name),
        json_str(&blueprint.acronym),
        json_str(&mod_root.display().to_string()),
        json_optional_str(game_root),
        json_str(&package.id),
        source_line_count,
        queries.len(),
        json_array(&queries.iter().take(60).cloned().collect::<Vec<_>>()),
        analysis.to_json(),
        repair_plan,
        payload.json,
        json_array(&next_commands),
        json_array(&large_mod_ai_output_insurance_stop_conditions()),
    )
}

fn large_mod_ai_output_insurance_markdown(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    mod_root: &Path,
    game_root: Option<&str>,
    source: &str,
    payload: &WorkPackageRunRetrievedRepairPayload,
) -> String {
    let mut out = String::new();
    out.push_str("# AI Output Insurance\n\n");
    out.push_str("- schema: `hoi4skill.ai_output_insurance.v1`\n");
    out.push_str(&format!("- status: `{}`\n", payload.status));
    out.push_str(&format!("- mod: `{}`\n", blueprint.name));
    out.push_str(&format!("- package: `{}`\n", package.id));
    out.push_str(&format!("- mod_root: `{}`\n", mod_root.display()));
    out.push_str(&format!(
        "- game_root: `{}`\n",
        game_root.unwrap_or("<missing>")
    ));
    out.push_str("- rule: use this as repair context for structured inputs only; Rust writers still assemble final Clausewitz.\n");
    out.push_str("- rule: if retrieval status is not `ok`, ask for evidence or rerun with a valid game/dependency root before writing final code.\n\n");
    let analysis = analyze_large_mod_ai_output_insurance_source(source);
    out.push_str("## Blocking Analysis\n\n");
    out.push_str(&format!(
        "- direct_clausewitz_code: `{}`\n",
        analysis.direct_clausewitz_code
    ));
    out.push_str(&format!(
        "- dynamic_modifier_as_national_spirit: `{}`\n",
        analysis.dynamic_modifier_as_national_spirit
    ));
    out.push_str(&format!(
        "- blocking_count: `{}`\n",
        analysis.blocking_count()
    ));
    if !analysis.suspicious_code_tokens.is_empty() {
        out.push_str(&format!(
            "- suspicious_code_tokens: `{}`\n",
            analysis.suspicious_code_tokens.join(", ")
        ));
    }
    out.push('\n');
    out.push_str(&large_mod_ai_output_insurance_repair_plan_markdown(
        &analysis, mod_root, package, game_root, source,
    ));
    out.push_str("## Suspect AI Output\n\n");
    out.push_str(&markdown_fence("text", &truncate_chars(source, 20_000)));
    out.push_str("\n## Retrieved Local Evidence\n\n");
    out.push_str(&payload.markdown);
    out
}

fn large_mod_ai_output_insurance_stop_conditions() -> Vec<String> {
    vec![
        "Do not apply AI output directly to final mod files; repair structured work-package inputs and rerun Rust writers.".to_string(),
        "If retrieval_ok is false, missing, or ambiguous, ask for the missing HOI4 install/dependency/symbol evidence instead of inventing code.".to_string(),
        "If the AI output used dynamic modifiers as national spirits, regenerate dynamic_modifier_intent or verified scripted-effect protocol inputs instead.".to_string(),
        "If the AI output contains unknown localisation icons, flags, cosmetic tags, or scripted localisation scopes, route them through localisation_placeholders and strict validation.".to_string(),
    ]
}

fn push_work_package_repair_query(out: &mut Vec<String>, raw: &str) {
    let mut text = raw.trim();
    if text.is_empty() || text.starts_with('#') {
        return;
    }
    if let Some((_, after)) = text.split_once("error:") {
        text = after.trim();
    }
    let text = text
        .trim_matches('`')
        .replace(['\r', '\n', '\t'], " ")
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    let text = truncate_chars(&text, 260);
    if text.len() < 3 {
        return;
    }
    if !out.iter().any(|existing| existing == &text) {
        out.push(text);
    }
}

fn work_package_run_retrieved_repair_markdown(
    package: &WorkPackage,
    mod_root: &Path,
    game_root: Option<&str>,
    status: &str,
    queries: &[String],
    symbols: &[CodeSymbolMatch],
    examples: &[ClausewitzExample],
    reason: Option<&str>,
) -> String {
    let mut out = String::new();
    out.push_str("# Retrieved Repair Code Context\n\n");
    out.push_str("- schema: `hoi4skill.work_package_retrieved_repair_context.v1`\n");
    out.push_str(&format!("- status: `{status}`\n"));
    out.push_str(&format!("- package: `{}`\n", package.id));
    out.push_str(&format!("- mod_root: `{}`\n", mod_root.display()));
    out.push_str(&format!(
        "- game_root: `{}`\n",
        game_root.unwrap_or("<missing>")
    ));
    if let Some(reason) = reason {
        out.push_str(&format!(
            "- retrieval_error: `{}`\n",
            reason.replace('`', "'")
        ));
    }
    out.push_str("- rule: use these local examples and symbols only to repair structured inputs; Rust writers still emit final Clausewitz.\n");
    out.push_str("- rule: if no matching symbol or example exists, stop and ask for evidence instead of inventing syntax, IDs, sprites, or modifiers.\n\n");
    out.push_str("## Queries\n\n");
    for query in queries.iter().take(20) {
        out.push_str(&format!("- `{}`\n", query.replace('`', "'")));
    }
    out.push_str("\n## Related Indexed Symbols\n\n");
    if symbols.is_empty() {
        out.push_str("- No related indexed symbols were found.\n");
    } else {
        for symbol in symbols.iter().take(30) {
            out.push_str(&format!(
                "- `{}` / `{}`: `{}`\n",
                symbol.category, symbol.kind, symbol.symbol
            ));
        }
    }
    out.push_str("\n## Retrieved Clausewitz Examples\n\n");
    if examples.is_empty() {
        out.push_str("- No local Clausewitz examples were retrieved.\n");
    } else {
        for example in examples.iter().take(12) {
            out.push_str(&format!(
                "### {} `{}`\n\n- source: `{}`\n\n",
                example.system,
                example.symbol,
                example.source.replace('`', "'")
            ));
            out.push_str(&markdown_fence(
                "hoi4",
                &truncate_chars(&example.code, 8_000),
            ));
            out.push('\n');
        }
    }
    out
}

fn work_package_run_retrieved_repair_json(
    package: &WorkPackage,
    mod_root: &Path,
    game_root: Option<&str>,
    status: &str,
    queries: &[String],
    symbols: &[CodeSymbolMatch],
    examples: &[ClausewitzExample],
    reason: Option<&str>,
) -> String {
    let symbol_json = symbols
        .iter()
        .take(30)
        .map(|symbol| {
            format!(
                "{{\"category\": {}, \"kind\": {}, \"symbol\": {}}}",
                json_str(symbol.category),
                json_str(symbol.kind),
                json_str(&symbol.symbol)
            )
        })
        .collect::<Vec<_>>()
        .join(", ");
    let example_json = examples
        .iter()
        .take(12)
        .map(|example| {
            format!(
                "{{\"system\": {}, \"symbol\": {}, \"source\": {}, \"code\": {}}}",
                json_str(&example.system),
                json_str(&example.symbol),
                json_str(&example.source),
                json_str(&truncate_chars(&example.code, 8_000))
            )
        })
        .collect::<Vec<_>>()
        .join(", ");
    format!(
        "{{\n  \"schema\": \"hoi4skill.work_package_retrieved_repair_context.v1\",\n  \"status\": {},\n  \"package\": {},\n  \"mod_root\": {},\n  \"game_root\": {},\n  \"retrieval_error\": {},\n  \"queries\": {},\n  \"related_symbols\": [{}],\n  \"examples\": [{}],\n  \"anti_hallucination_rule\": {}\n}}\n",
        json_str(status),
        json_str(&package.id),
        json_str(&mod_root.display().to_string()),
        json_optional_str(game_root),
        json_optional_str(reason),
        json_array(&queries.iter().take(40).cloned().collect::<Vec<_>>()),
        symbol_json,
        example_json,
        json_str("If status is not ok or no related local evidence exists, fail generation or ask the user instead of inventing HOI4 code.")
    )
}

fn work_package_run_failed_output_markdown(
    blueprint: &LargeModBlueprint,
    package: &WorkPackage,
    mod_root: &Path,
    output_dir: &Path,
    game_root: Option<&str>,
    steps: &[WorkPackageRunStep],
    error: &str,
) -> String {
    let mut out = String::new();
    out.push_str("# Work Package Run Failed Output\n\n");
    out.push_str("- schema: `hoi4skill.work_package_run_failed_output.v1`\n");
    out.push_str(&format!("- mod: `{}`\n", blueprint.name));
    out.push_str(&format!("- package: `{}`\n", package.id));
    out.push_str(&format!("- mod_root: `{}`\n", mod_root.display()));
    out.push_str(&format!(
        "- game_root: `{}`\n",
        game_root.unwrap_or("<missing>")
    ));
    out.push_str(&format!("- output_dir: `{}`\n", output_dir.display()));
    out.push_str("\n## Blocking Error\n\n");
    out.push_str("```text\n");
    out.push_str(error);
    out.push_str("\n```\n\n");
    out.push_str("## Steps\n\n");
    for step in steps {
        out.push_str(&format!("- `{}`: `{}`\n", step.name, step.status));
        out.push_str(&format!("  command: `{}`\n", step.command));
        if let Some(error) = &step.error {
            out.push_str("  error:\n");
            out.push_str("  ```text\n");
            for line in error.lines() {
                out.push_str("  ");
                out.push_str(line);
                out.push('\n');
            }
            out.push_str("  ```\n");
        }
    }
    out.push_str("\n## Repair Rules\n\n");
    out.push_str("- Fix only the listed failed step or its required input template.\n");
    out.push_str("- Do not bypass Rust writers by emitting raw Clausewitz code.\n");
    out.push_str("- Keep dynamic modifiers on the scripted_effect/dynamic modifier path, not as national spirits.\n");
    out.push_str("- Rerun `run-work-package --execute` after repair.\n");
    out
}

